// === PART 5: FORMAT DETECTION & TEST BLOCK FINDER ======================

function detectFormat(data) {
  // A Scale Score column only exists on STAAR exports
  for (var hr = 1; hr <= 2 && hr < data.length; hr++) {
    var headerRow = data[hr] || [];
    for (var c = 0; c < headerRow.length; c++) {
      if (cellStr(headerRow[c]).toLowerCase() === "scale score") return "STAAR";
    }
  }
  // Benchmark exports alternate student row / blank row. Find the real first
  // student row before testing that pattern -- some exports carry an extra TEK
  // row, which shifts the data down and used to break this check.
  var demo = detectDemoCols(data);
  var start = DATA_START_ROW - 1;
  while (start < data.length) {
    var probe = cellStr(data[start][demo.name]);
    if (probe !== "" && probe.toLowerCase() !== "student name") break;
    start++;
  }
  // EVERY probed pair must be blank-on-the-second-row, not just two of eight.
  //
  // This used to be `blankCount >= 2`, and an alternating layout is not the only
  // thing that produces blank rows: EXPORT_SPEC.md REQUIRES absentees to appear
  // as blank rows ("an absent student must appear as a blank row, not be
  // missing"), so the spec mandates the exact condition the old threshold read
  // as proof. Two absentees landing at odd offsets declared a STAAR export a
  // "Benchmark", set rowStep = 2, and skipped every other row -- measured at 18
  // pupils in, 10 parsed, with no warning anywhere.
  //
  // A genuine alternating export is blank on EVERY second row, structurally, so
  // demanding all of them costs nothing real and scattered absentees can no
  // longer trip it. `checked >= 3` stops a two-row tab deciding on one pair.
  var blankCount = 0, checked = 0;
  for (var r = start; r + 1 < data.length && checked < 8; r += 2, checked++) {
    if (cellStr(data[r + 1][demo.name]) === "") blankCount++;
  }
  var alternating = (checked >= 3 && blankCount === checked);
  if (alternating) {
    console.log("detectFormat: alternating student/blank layout on this tab (" +
                blankCount + " of " + checked + " probed pairs) -- reading every other row.");
  }
  return alternating ? "Benchmark" : "STAAR";
}

function findTestBlocks(sheetName, data, format, tekMap) {
  var blocks = [];
  var totalCols = data[0] ? data[0].length : 0;
  if (!data[1]) return blocks;

  // Every test block is anchored by an "All Responses" header.
  var arCols = [];
  for (var c = 1; c < totalCols; c++) {
    if (String(data[1][c] || "").trim().toLowerCase() === "all responses") arCols.push(c);
  }
  // COMBINED tests push that header down one row
  if (data[2]) {
    for (var c2 = 1; c2 < totalCols; c2++) {
      if (String(data[2][c2] || "").trim().toLowerCase() === "all responses" &&
          arCols.indexOf(c2) === -1) arCols.push(c2);
    }
  }
  arCols.sort(function (a, b) { return a - b; });

  for (var bi = 0; bi < arCols.length; bi++) {
    var arCol  = arCols[bi];
    var nextAR = bi + 1 < arCols.length ? arCols[bi + 1] : totalCols;

    // Test title sits in row 0, at or to the left of the anchor. Scan all the
    // way to column 0 -- when an export has no Economic Disadvantage column the
    // first anchor lands left of DEMO_COLS, and stopping there found no title
    // at all, so the first test was named "Test 1".
    var testTitle = "";
    for (var tc = arCol; tc >= 0; tc--) {
      var tv = cellStr(data[0][tc]);
      if (tv !== "") { testTitle = tv; break; }
    }
    if (!testTitle) testTitle = "Test " + (bi + 1);

    var headerOffset = 1;
    if (String(data[1][arCol] || "").trim().toLowerCase() !== "all responses") headerOffset = 2;

    var qNumRow = headerOffset + 1;
    var tekRow  = headerOffset + 4;

    var rawScoreCol = -1, scaleScoreCol = -1, dateTakenCol = -1;
    var instructorCol = -1, sectionCol = -1, courseCol = -1, periodCol = -1;
    // Recorded so Needed_Info can say which key columns a pull actually carries.
    var rawCol = -1, bandCols = 0;
    // Midlo Headers 2.0 adds these. Prev-year columns are the ones that let a
    // pupil who transferred in be growth-scored at all.
    var scoreCodeCol = -1, stateIdCol = -1, snapSchoolCol = -1, snapDistCol = -1;
    var prevScaleCol = -1, prevGradeCol = -1, prevProgCol = -1;
    // WHERE THE QUESTIONS END, worked out from the block's own shape rather
    // than from a header label.
    //
    // This used to key on finding "Raw Score", and the Midlo header files store
    // that cell as a bare number -- the shared-string index, with its text
    // marker lost -- so the label read as absent and the boundary fell off the
    // end of the block, swallowing the whole trailer as question columns.
    //
    // A question column is one that carries a NUMBER in the question-number row
    // and a WORD in the grading row ("Correct/Incorrect", "Partial (0-1-2)").
    // Trailer columns carry neither. That holds whatever the headers say, and
    // whatever order the trailer is in.
    var gradingRow = headerOffset + 2;
    var lastQCol = -1;
    for (var qs2 = arCol; qs2 < nextAR; qs2++) {
      var qn2 = String((data[qNumRow] || [])[qs2] || "").trim();
      var gr2 = String((data[gradingRow] || [])[qs2] || "").trim();
      if (qn2 !== "" && !isNaN(Number(qn2)) && gr2 !== "" && isNaN(Number(gr2))) lastQCol = qs2;
    }
    var summaryStart = (lastQCol >= 0) ? lastQCol + 1 : nextAR - 1;

    for (var sc = arCol + 1; sc < nextAR; sc++) {
      var label = trailerLabelAt(data, headerOffset, sc);
      if (label === "raw score")   { rawScoreCol = sc; rawCol = sc; }
      if (label === "scale score") scaleScoreCol = sc;
      if (label === "date taken")  dateTakenCol  = sc;
      if (label === "current instructor") instructorCol = sc;
      if (label === "current section")    sectionCol    = sc;
      if (label === "current course")     courseCol     = sc;
      if (label === "current period")     periodCol     = sc;
      if (isBandLabel(label, "approaches") || isBandLabel(label, "meets") ||
          isBandLabel(label, "masters")) bandCols++;
      if (label === "score code") scoreCodeCol = sc;
      if (label.indexOf("unique student id") !== -1) stateIdCol = sc;
      if (label.indexOf("school snapshot") === 0)   snapSchoolCol = sc;
      if (label.indexOf("district snapshot") === 0) snapDistCol   = sc;
      if (label.indexOf("prev year scale score") === 0)    prevScaleCol = sc;
      if (label.indexOf("prev year tested grade") === 0)   prevGradeCol = sc;
      if (label.indexOf("prev year staar progress") === 0) prevProgCol  = sc;
    }

    // Count questions -- Q1 sometimes shares the anchor column
    var qCount = 0, qStartCol = arCol;
    if (data[qNumRow]) {
      for (var qc = arCol; qc < summaryStart; qc++) {
        var qv = String(data[qNumRow][qc] || "").trim();
        if (qv !== "" && !isNaN(Number(qv))) {
          qCount++;
          if (qCount === 1) qStartCol = qc;
        }
      }
    }

    // Most common Date Taken across students becomes the auto-date
    var autoDate = "";
    if (dateTakenCol >= 0) {
      var dateCounts = {};
      var rowStep = format === "Benchmark" ? 2 : 1;
      var dateStart = DATA_START_ROW - 1;
      while (dateStart < data.length) {
        var nm = String(data[dateStart][COL_NAME] || "").trim();
        if (nm !== "" && nm.toLowerCase() !== "student name") break;
        dateStart++;
      }
      for (var dr = dateStart; dr < data.length; dr += rowStep) {
        var dv = data[dr] ? String(data[dr][dateTakenCol] || "").trim() : "";
        if (dv && dv !== "-") dateCounts[dv] = (dateCounts[dv] || 0) + 1;
      }
      var bestCount = 0;
      for (var dk in dateCounts) {
        if (dateCounts[dk] > bestCount) { bestCount = dateCounts[dk]; autoDate = dk; }
      }
    }

    // No Date Taken column at all -- the Midlo layout drops it, which left every
    // test unordered and forced the Order column to be typed in by hand. The
    // title carries the month and year, and STAAR runs in one window per year,
    // so a synthesised first-of-month date sorts correctly even though it is
    // not the true administration date.
    if (!autoDate) autoDate = dateFromTestTitle(testTitle);

    var block = {
      sheetName: sheetName, testName: testTitle,
      startCol: arCol, questionStartCol: qStartCol, questionCount: qCount,
      summaryStartCol: summaryStart, dateTakenCol: dateTakenCol,
      scalScoreCol: scaleScoreCol, autoDate: autoDate,
      instructorCol: instructorCol, sectionCol: sectionCol, courseCol: courseCol,
      periodCol: periodCol,
      order: 0, include: true, buildViews: false,
      testType: detectTestType(testTitle),
      language: detectLanguage(testTitle),
      subject: detectSubjectFromName(testTitle),
      // KEPT SEPARATELY, and this is load-bearing. resolveBlockSubjects runs
      // more than once in a run -- once so the Config can show its guesses,
      // once before anything is built -- and it WRITES to blk.subject. A second
      // pass reading blk.subject as evidence would see its own answer from the
      // first pass and label every guess "the test name", which is how a guess
      // stops looking like a guess. This field only ever holds what the TITLE
      // said, so the ladder gives the same answer however often it is run.
      subjectTitle: detectSubjectFromName(testTitle),
      rawScoreCol: rawCol, bandColCount: bandCols,
      scoreCodeCol: scoreCodeCol, stateIdCol: stateIdCol,
      snapSchoolCol: snapSchoolCol, snapDistCol: snapDistCol,
      prevScaleCol: prevScaleCol, prevGradeCol: prevGradeCol, prevProgCol: prevProgCol,
      isCombined: false, hasTEKRow: false
    };

    if (data[tekRow]) {
      for (var kc = qStartCol; kc < summaryStart; kc++) {
        var kv = String(data[tekRow][kc] || "").trim();
        if (kv && kv !== "()" && kv !== "-") { block.hasTEKRow = true; break; }
      }
    }
    blocks.push(block);
  }
  return blocks;
}


// === PART 6: CONFIG WRITER =============================================
/**
 * Builds the Config tab.
 *
 * Apps Script advantage over the Excel version: instead of asking teachers to
 * TYPE "Yes"/"No" (which caused silent failures when someone typed "yes " or
 * "Y"), every choice cell here gets a real dropdown via data validation.
 * You physically cannot enter an invalid value.
 *
 * Layout is 10 columns wide. Column 10 is deliberately empty so long
 * instruction text has somewhere to overflow.
 */
// 11, not 10: the Test Registry now says WHERE each subject came from. A
// guessed subject that looks identical to a certain one is how a wrong subject
// survives unnoticed.
var CFG_COLS = 11;

function writeConfig(ss, sheetInfos, allBlocks, anyMissingDates, mapSheetNames, teacherCensus) {
  var sheet = getOrCreate(ss, "Config");
  var g = new Grid(CFG_COLS);

  // Remember where the dropdown cells land so we can attach validation later.
  var dd = { mode: 0, combine: 0, sheetInc: null, mapInc: null,
             testInc: null, testBV: null, testSubj: null,
             teacherInc: null, viewInc: null };

  // -- Title + status banner -------------------------------------------
  g.header("MULTI-TEST ANALYZER  \u2014  CONFIG", C.hdr, C.hdrTxt, 14, CFG_COLS, 34);
  // The run control, said once and said loudly. Apps Script cannot put a live
  // button in a cell from script alone, so the menu is the button and this is
  // the sign pointing at it.
  g.header("\u25b6   WHEN YOU ARE READY:  menu  STAAR Analyzer  \u25b8  Run Analysis"
    + "        (progress appears in the bottom-right corner; teacher tabs are built first, "
    + "so you can start reading while the rest finishes)",
    "#1b5e20", "#ffffff", 12, CFG_COLS, 30);

  if (anyMissingDates) {
    g.header("ACTION REQUIRED: Some tests had no Date Taken \u2014 their Order cells are blank. "
      + "Tests with dates were auto-ordered. Fill in the blank Order cells to fit those tests "
      + "into the sequence, then run again.  |  Give two tests the SAME Order number to combine them.",
      C.alert, C.alertTxt, 10, CFG_COLS, 46);
  } else {
    g.header("Dates were found for all tests \u2014 Order has been pre-filled. "
      + "Review, adjust if needed, set Include to No to skip a test, then run again.",
      "#1b5e20", "#ffffff", 10, CFG_COLS, 36, false);
  }
  g.row(8);

  // -- Section 0b: Teacher Filter --------------------------------------
  // The one control that decides how big a run is. Put every test you own in
  // the workbook and narrow the RUN here instead: tick a teacher and only their
  // pupils are analysed, along with every test those pupils have ever taken.
  // Nothing is deleted, so tomorrow's 6th-grade dig is three clicks away.
  //
  // No ticks at all means everybody, so a first run behaves exactly as before
  // and nobody has to untick forty teachers to look at two.
  var tNames = [];
  for (var tn in (teacherCensus || {})) tNames.push(tn);
  tNames.sort(function (a, b) {
    return a < b ? -1 : a > b ? 1 : 0;                     // plain alphabetical
  });

  if (tNames.length > 0) {
    g.header("TEACHER FILTER  \u2014  tick who you want in this run",
      "#263238", "#ffffff", 12, CFG_COLS, 26);
    g.header("Leave every box in Run? unticked to run EVERYBODY. Tick one or more and only those "
      + "teachers' students are pulled \u2014 with every test those students have ever taken, "
      + "whatever year it came from.   |   "
      + "SUBJECTS decide which tabs a teacher gets. They are pre-ticked from the export: a subject "
      + "is ticked when at least a quarter of that teacher's pupils sit it, which keeps a stray row "
      + "or two from earning somebody a second, near-empty tab. \"What we found\" is the raw count "
      + "behind each tick, so you can argue with it. A teacher with TWO subjects ticked gets one tab "
      + "per subject; untick one and they get a single tab. Untick all four and we fall back to "
      + "whatever the export says.",
      C.warn, "#000000", 9, CFG_COLS, 46, false);

    var subjHdr = [];
    for (var sh0 = 0; sh0 < CFG_SUBJECTS.length; sh0++) subjHdr.push(CFG_SUBJECTS[sh0].label);
    g.headerRow(["Run?", "Teacher", "Class Periods", "Students"]
                  .concat(subjHdr).concat(["What we found"]));
    var tStart = g.v.length;
    for (var ti = 0; ti < tNames.length; ti++) {
      var ent = teacherCensus[tNames[ti]];
      var tbg = ti % 2 === 0 ? C.white : C.zebra;
      g.row(21);
      g.set(0, "", { bg: C.edit });                       // checkbox goes here
      g.set(1, tNames[ti], { bg: tbg, bold: true });
      g.set(2, teacherPeriodLabel(ent), { bg: tbg, fg: "#555555", align: "center" });
      g.set(3, Object.keys(ent.students).length, { bg: tbg, align: "center" });
      for (var sc0 = 0; sc0 < CFG_SUBJECTS.length; sc0++) {
        g.set(4 + sc0, "", { bg: C.edit });               // one checkbox per subject
      }
      g.set(4 + CFG_SUBJECTS.length, teacherSubjectSummary(ent),
            { bg: tbg, fg: "#555555", size: 9 });
    }
    dd.teacherInc = { r: tStart, n: tNames.length, c: 0 };
    dd.teacherSubj = { r: tStart, n: tNames.length, c: 4, w: CFG_SUBJECTS.length,
                       names: tNames, census: teacherCensus };
    g.row(8);
  }

  // -- Section 0c: Views to build --------------------------------------
  g.header("VIEWS TO BUILD  \u2014  untick what you do not need; fewer views, faster run",
    "#263238", "#ffffff", 12, CFG_COLS, 26);
  g.header("Untick a view to skip building it. The per-teacher tabs are the point of the tool; "
    + "Data_Check is the tab that says whether to trust the rest.",
    C.sectionBg, "#000000", 9, CFG_COLS, 30, false);
  g.headerRow(["Run?", "View", "What it covers"]);
  var vStart = g.v.length;
  for (var vi2 = 0; vi2 < VIEW_CATALOGUE.length; vi2++) {
    var vc = VIEW_CATALOGUE[vi2];
    var vbg = vi2 % 2 === 0 ? C.white : C.zebra;
    g.row(20);
    g.set(0, "", { bg: C.edit });
    g.set(1, vc.label, { bg: vbg, bold: true });
    g.set(2, (vc.everyTest ? "EVERY TEST" + (vc.note ? "  -  " : "") : "") + vc.note,
          { bg: vc.everyTest ? C.warn : vbg, fg: "#555555", size: 9 });
  }
  dd.viewInc = { r: vStart, n: VIEW_CATALOGUE.length, c: 0 };
  g.row(8);

  // -- Section 0d: PLC content -----------------------------------------
  g.header("PLC CONTENT  \u2014  what each class period shows",
    "#263238", "#ffffff", 12, CFG_COLS, 26);
  g.header("LEFT SIDE: each class period gets ONE TEK table, built from the newest STAAR its pupils "
    + "sat.  |  RIGHT SIDE: every paper the period sat, one column each, a band per pupil; the "
    + "number below caps how many columns show per subject, newest kept.  |  A test still has to "
    + "be Include? = Yes in the Test Registry, and a paper nobody in a group sat is never shown.",
    C.warn, "#000000", 9, CFG_COLS, 40, false);
  // WHICH paper each subject's TEK tables are built from. One table per class
  // period, so this is the whole choice: the newest paper the class sat, or a
  // named one when you want to go back to a particular test.
  // TYPE FIRST, THEN TEST. One choice for the whole run: pick STAAR and every
  // teacher tab is built from that subject's STAAR, whatever benchmarks the
  // workbook also holds. Without this, a DCB most of the class had sat took the
  // single table slot and the tab quietly answered a different question.
  var byType = {}, pbSorted = allBlocks.slice().sort(function (a, b) { return (b.order || 0) - (a.order || 0); });
  for (var pb = 0; pb < pbSorted.length; pb++) {
    var pbName = String(pbSorted[pb].testName || "").trim();
    if (!pbName) continue;
    var pbType = pbSorted[pb].testType || detectTestType(pbName);
    if (!byType[pbType]) byType[pbType] = [];
    if (byType[pbType].indexOf(pbName) === -1) byType[pbType].push(pbName);
  }
  var typesHere = [];
  for (var tk3 = 0; tk3 < TEST_TYPES.length; tk3++) {
    if (TEST_TYPES[tk3] !== "MAP" && byType[TEST_TYPES[tk3]]) typesHere.push(TEST_TYPES[tk3]);
  }
  if (typesHere.length === 0) typesHere = [PLC_TYPE_DEFAULT];

  var allPapers = [];
  for (var at = 0; at < typesHere.length; at++) {
    var lst = byType[typesHere[at]] || [];
    for (var ap2 = 0; ap2 < lst.length; ap2++) {
      if (allPapers.indexOf(lst[ap2]) === -1) allPapers.push(lst[ap2]);
    }
  }
  var paperRow = g.row(20);
  g.set(0, PLC_PAPER_ROW_LABEL, { bg: C.sectionBg, bold: true });
  g.set(1, PLC_PAPER_AUTO, { bg: C.edit, bold: true, align: "center" });
  g.set(2, "\u2190  Leave it on \"" + PLC_PAPER_AUTO + "\" and each class gets the newest paper of "
        + "that type IT actually sat. Name a test to go back to a particular one -- a class that "
        + "never sat it is told so on its own table rather than shown something else.",
        { bg: C.sectionBg, fg: "#555555", wrap: true });
  dd.plcPaper = { r: paperRow, opts: [PLC_PAPER_AUTO].concat(allPapers) };

  var tlRow = g.row(22);
  g.set(0, "Timeline checkpoints to show  (strip, RIGHT side)", { bg: C.sectionBg, bold: true });
  g.set(1, String(PLC_CONTENT_DEFAULT.timelineMax), { bg: C.edit, bold: true, align: "center" });
  g.set(2, "\u2190  papers per subject on the strip, newest kept.  All = every paper the period sat",
        { bg: C.sectionBg, fg: "#555555" });
  dd.plcTlMax = tlRow;
  g.row(8);

  // -- Section 1: Sheet Registry ---------------------------------------
  g.header("SHEET REGISTRY  \u2014  rename Group Label only if you want to", C.subHdr, C.subTxt, 11, CFG_COLS, 26);
  g.header("Leave Group Label as the tab name and the run names the tab itself, from what is on it: "
           + "the subject of its papers and the grade those students are in NOW, read from the "
           + "newest paper moved on a grade per school year. That is why a tab "
           + "called \"Sheet1 (3)\" comes out as \"Math 7\" on every campus view while this cell still "
           + "says Sheet1 (3).   |   Type a name here and it is used exactly as typed, for good: "
           + "a name somebody chose is never overridden.",
           C.warn, "#000000", 9, CFG_COLS, 30, false);

  dd.combine = g.row(22);
  g.set(0, "Treat all sheets as one group?", { bg: C.sectionBg, bold: true });
  g.set(1, "No", { bg: C.edit, bold: true, align: "center" });
  g.set(2, "\u2190  Yes merges every class into one combined section", { bg: C.sectionBg, fg: "#555555" });

  g.headerRow(["Sheet Name", "Group Label", "Format Detected", "Include?"]);
  var sheetIncStart = g.v.length; // 0-based index of first data row
  for (var i = 0; i < sheetInfos.length; i++) {
    var si = sheetInfos[i];
    var bg = i % 2 === 0 ? C.white : C.zebra;
    g.row(20);
    g.set(0, si.sheetName,  { bg: bg });
    g.set(1, si.groupLabel, { bg: bg });
    g.set(2, si.format,     { bg: bg, fg: "#555555", align: "center" });
    g.set(3, si.include ? "Yes" : "No", { bg: C.edit, align: "center" });
  }
  dd.sheetInc = { r: sheetIncStart, n: sheetInfos.length, c: 3 };
  g.row(8);

  // -- Section 2: Test Registry ----------------------------------------
  g.header("TEST REGISTRY  \u2014  set Order and Include for each test",
    C.subHdr, C.subTxt, 11, CFG_COLS, 26);
  g.header("Give two tests the SAME Order number to COMBINE them into one column - use this only "
    + "for two versions of ONE paper, such as the English and Spanish forms.  |  "
    + "Subject is auto-detected \u2014 fill in any blank yellow Subject cell.  |  "
    + "Every tab is treated as a STAAR paper.",
    C.warn, "#000000", 9, CFG_COLS, 40, false);

  g.headerRow(["Sheet", "Test Name", "Auto-Date", "Order", "Include?",
               "Language", "Questions", "Subject", "Subject set by"]);

  var testStart = g.v.length;
  for (var bi2 = 0; bi2 < allBlocks.length; bi2++) {
    var b    = allBlocks[bi2];
    var rbg  = bi2 % 2 === 0 ? C.white : C.zebra;
    var subj = b.subject || "";
    g.row(20);
    g.set(0, b.sheetName, { bg: rbg });
    g.set(1, b.testName,  { bg: rbg });
    g.set(2, b.autoDate,  { bg: rbg, fg: "#555555", align: "center" });
    g.set(3, b.order > 0 ? String(b.order) : "", { bg: C.edit, bold: true, align: "center" });
    g.set(4, b.include ? "Yes" : "No", { bg: C.edit, align: "center" });
    g.set(5, b.language, { bg: rbg, fg: b.language === "Spanish" ? C.spanishTxt : "#000000", align: "center" });
    g.set(6, String(b.questionCount), { bg: rbg, fg: "#555555", align: "center" });
    // A GUESS LOOKS DIFFERENT FROM AN ANSWER. Certain subjects sit on the row
    // colour; anything inferred is on the edit yellow with its source beside
    // it, and an unresolved one is the red "Unknown subject" you have to pick.
    var srcFrom = b.subjectFrom || "";
    var guessed = !!b.subjectGuess;
    var shown = subj || SUBJECT_UNKNOWN;
    g.set(7, shown, { bg: (!subj || guessed) ? C.edit : rbg,
                      fg: !subj ? "#b71c1c" : "#000000", bold: !subj || guessed,
                      align: "center" });
    if (!subj && b.subjectSuggest) {
      g.note(7, "Nothing could identify this paper's subject.\n\n"
             + "Closest match from its TEK codes: " + b.subjectSuggest + " -- but the codes it "
             + "uses belong to several subjects, so that is a coin toss rather than a reading.\n\n"
             + "Pick the right one from the dropdown.");
    }
    g.set(8, subjectFromLabel(srcFrom), {
      bg: !subj ? "#ffcdd2" : guessed ? C.warn : rbg,
      fg: "#555555", size: 9, align: "center" });
  }
  dd.testInc  = { r: testStart, n: allBlocks.length, c: 4 };
  dd.testSubj = { r: testStart, n: allBlocks.length, c: 7 };
  g.row(8);

  // -- One write -------------------------------------------------------
  g.flush(sheet, [300, 230, 120, 80, 90, 90, 90, 130, 150]);

  // -- Dropdowns (one call per range) ----------------------------------
  var yesNo   = SpreadsheetApp.newDataValidation()
                  .requireValueInList(["Yes", "No"], true).setAllowInvalid(false).build();
  // "Unknown subject" is IN the list on purpose. A blank cell reads as "not
  // filled in yet"; this reads as "the tool could not tell and is asking".
  var subjRule = SpreadsheetApp.newDataValidation()
                  .requireValueInList(["Math", "ELA", "Science", "History", SUBJECT_UNKNOWN], true)
                  .setAllowInvalid(true).build();

  sheet.getRange(dd.combine + 1, 2).setDataValidation(yesNo);
  if (dd.sheetInc && dd.sheetInc.n > 0) {
    sheet.getRange(dd.sheetInc.r + 1, dd.sheetInc.c + 1, dd.sheetInc.n, 1).setDataValidation(yesNo);
  }
  // Real checkboxes, written in one batched call. If this Sheets version will
  // not take them, fall back to a Yes/No dropdown rather than losing the whole
  // Config write over a formatting quirk.
  if (dd.plcTlMax) {
    // "All" sits alongside the numbers rather than being a separate tick: it is
    // the same question -- how many -- and a blank cell must not mean nothing.
    if (dd.plcPaper) {
      // allowInvalid: a pick that names a paper no longer in the workbook must
      // not block the cell -- the run falls back to the newest of the type and
      // says so on the table itself.
      sheet.getRange(dd.plcPaper.r + 1, 2).setDataValidation(
        SpreadsheetApp.newDataValidation()
          .requireValueInList(dd.plcPaper.opts, true).setAllowInvalid(true).build());
    }
    var tlOpts = ["All"];
    for (var tl = 2; tl <= 12; tl++) tlOpts.push(String(tl));
    sheet.getRange(dd.plcTlMax + 1, 2).setDataValidation(
      SpreadsheetApp.newDataValidation()
        .requireValueInList(tlOpts, true).setAllowInvalid(false).build());
  }

  if (dd.viewInc && dd.viewInc.n > 0) {
    var vRng = sheet.getRange(dd.viewInc.r + 1, dd.viewInc.c + 1, dd.viewInc.n, 1);
    try {
      vRng.setNumberFormat("General");
      vRng.insertCheckboxes();
      // Views default on; a switch that regroups the data defaults off, so
      // rebuilding Config never silently changes how a teacher's tab is cut.
      var vv = [];
      for (var vq = 0; vq < dd.viewInc.n; vq++) {
        vv.push([VIEW_CATALOGUE[vq] && VIEW_CATALOGUE[vq].defaultOff ? false : true]);
      }
      vRng.setValues(vv);
    } catch (e2) {
      vRng.setDataValidation(yesNo);
      var vv2 = [];
      for (var vq2 = 0; vq2 < dd.viewInc.n; vq2++) {
        vv2.push([VIEW_CATALOGUE[vq2] && VIEW_CATALOGUE[vq2].defaultOff ? "No" : "Yes"]);
      }
      vRng.setValues(vv2);
    }
  }
  if (dd.teacherInc && dd.teacherInc.n > 0) {
    var tRng = sheet.getRange(dd.teacherInc.r + 1, dd.teacherInc.c + 1, dd.teacherInc.n, 1);
    try {
      tRng.setNumberFormat("General");     // Grid stamps "@" on everything
      tRng.insertCheckboxes();
    } catch (e) {
      tRng.setDataValidation(yesNo);
      var tv = [];
      for (var tq = 0; tq < dd.teacherInc.n; tq++) tv.push(["No"]);
      tRng.setValues(tv);
    }
  }
  // The subject grid: one checkbox per subject per teacher, pre-ticked from
  // the export. Written as one range, one setValues, not a cell at a time.
  if (dd.teacherSubj && dd.teacherSubj.n > 0) {
    var sRng = sheet.getRange(dd.teacherSubj.r + 1, dd.teacherSubj.c + 1,
                              dd.teacherSubj.n, dd.teacherSubj.w);
    var sVals = [];
    for (var sr = 0; sr < dd.teacherSubj.n; sr++) {
      var sEnt = dd.teacherSubj.census[dd.teacherSubj.names[sr]], rowv = [];
      for (var sk = 0; sk < CFG_SUBJECTS.length; sk++) {
        rowv.push(teacherSubjectTicked(sEnt, CFG_SUBJECTS[sk].key));
      }
      sVals.push(rowv);
    }
    try {
      sRng.setNumberFormat("General");
      sRng.insertCheckboxes();
      sRng.setValues(sVals);
    } catch (e3) {
      sRng.setDataValidation(yesNo);
      var sv2 = [];
      for (var sr2 = 0; sr2 < sVals.length; sr2++) {
        var rr2 = [];
        for (var sc2 = 0; sc2 < sVals[sr2].length; sc2++) rr2.push(sVals[sr2][sc2] ? "Yes" : "No");
        sv2.push(rr2);
      }
      sRng.setValues(sv2);
    }
  }
  if (dd.testInc && dd.testInc.n > 0) {
    sheet.getRange(dd.testInc.r + 1, dd.testInc.c + 1, dd.testInc.n, 1).setDataValidation(yesNo);
    sheet.getRange(dd.testSubj.r + 1, dd.testSubj.c + 1, dd.testSubj.n, 1).setDataValidation(subjRule);
  }

  sheet.setFrozenRows(1);
  ss.setActiveSheet(sheet);
  console.log("Config written \u2014 " + allBlocks.length + " tests across " + sheetInfos.length + " data sheets.");
}


// === PART 7: CONFIG READERS ============================================
// All readers share one cached read of the Config tab -- reading it once and
// passing the array around avoids re-fetching the same data five times.

function getConfigValues(ss) {
  var sheet = ss.getSheetByName("Config");
  if (!sheet) return null;
  return sheet.getDataRange().getValues();
}

/**
 * Every section heading on the Config tab, lower case, in sheet order.
 *
 * ONE list. Each reader opens on its own heading and closes on any other, so a
 * section added later cannot be forgotten by a reader that predates it --
 * which is exactly how readViewToggles came to run on past PLC CONTENT and
 * only stopped by luck, because that section's note happens to say "Registry".
 */
var CFG_SECTIONS = [
  "teacher filter", "views to build", "plc content",
  "sheet registry", "test registry"
];

/**
 * Does this row START the named section?
 *
 * ANCHORED, and that is the whole point. Matching a heading anywhere in the
 * cell reads instruction notes as headings, because notes legitimately name
 * other sections: the Test Registry note explains what Type does "in PLC
 * CONTENT", and the PLC CONTENT note says a test must still be included "in
 * the Test Registry".
 *
 * That cost a live run. The Test Registry note sits directly above the test
 * rows, so being read as a PLC CONTENT heading closed the registry before a
 * single test was parsed. Every Order came back 0, the script decided the
 * Config was incomplete, and it sat on the Config tab with nothing to say.
 *
 * Headings are written by g.header() and always begin with the section name.
 * Notes never do.
 */
function isCfgSection(lowerCol0, name) {
  return lowerCol0.indexOf(name) === 0;
}

/** True when this row starts any section OTHER than `except`. */
function isOtherCfgSection(lowerCol0, except) {
  for (var i = 0; i < CFG_SECTIONS.length; i++) {
    if (CFG_SECTIONS[i] === except) continue;
    if (isCfgSection(lowerCol0, CFG_SECTIONS[i])) return true;
  }
  return false;
}

function readCombineSheets(cfg) {
  if (!cfg) return false;
  for (var r = 0; r < cfg.length; r++) {
    if (String(cfg[r][0] || "").trim().toLowerCase() === "treat all sheets as one group?") {
      return String(cfg[r][1] || "").trim().toLowerCase() === "yes";
    }
  }
  return false;
}


/**
 * Which views a run may build. Order matches the Config tab.
 *
 * `everyTest` marks the views that walk the WHOLE workbook regardless of what
 * is ticked under Build Views -- they are why a single-teacher run still took
 * minutes. Untick those and a teacher-focused run does only the work it needs.
 *
 * THE DEFAULTS ARE WHAT MIDLO ACTUALLY USES, set 2026-09-22 from Austin's own
 * account of a year's use, not from what the tool can do. On by default:
 * the per-teacher tabs, Data_Check, naming pupils with no data, and the three
 * MAP views. Off by default: Mastery_Flow / Campus_Summary / Equity_Trend,
 * Strand_Timeline, TEK_Offenders, Strand_Analysis, Gemini_Summary and
 * Student_Trajectory -- all built, all still one tick away, none of them used
 * enough to be worth the minutes they cost on every run.
 *
 * A default that is OFF is not a judgement on the view. It is a judgement on
 * what a run should cost when nobody has been asked.
 */
var VIEW_CATALOGUE = [
  { key: "plcsection", label: "Per-teacher tabs, one block per class section",
    note: "one tab per teacher; each Current Section gets its newest STAAR ranked by TEK on the "
        + "left and every paper the class sat as a band strip on the right", everyTest: false },
  { key: "growthmx",   label: "Growth_Matrix + Growth_Students",
    note: "campus 6x6 growth grid, each number clickable through to the pupils",
    everyTest: false },
  { key: "datacheck",  label: "Data_Check",
    note: "cheap, and the tab that says whether to trust the rest", everyTest: false },
  { key: "rostercheck", label: "Name pupils with no data on the paper",
    note: "in each PLC section, list who is on the roster but has no result - and why",
    everyTest: false }
];

/**
 * Set by a menu item that builds ONE tab, and cleared the moment it is done.
 *
 * A single-view run still has to scan, parse and merge -- that work is cheap
 * and shared. What it skips is the per-teacher tabs, which measured out at 85%
 * of a full run. Overriding here rather than inside runAnalysis keeps one
 * definition of what a view toggle means.
 */
var VIEW_FORCE = null;


/**
 * True only while the comparison menu item runs: every row height and banner
 * merge is then sent the old way, one call each. See Grid.prototype.flush.
 */
var ROW_SIZING_CLASSIC = false;

/**
 * Which views this run should build. No Config, or none recognised = build all.
 *
 * The override is applied HERE rather than inside the reader, because the
 * reader returns early when there is no Config at all -- and a single-view run
 * on a workbook whose Config has not been built yet is exactly when the
 * override matters most.
 */
function readViewToggles(cfg) {
  var on = readViewTogglesRaw(cfg);
  if (VIEW_FORCE) {
    for (var i = 0; i < VIEW_CATALOGUE.length; i++) {
      on[VIEW_CATALOGUE[i].key] = !!VIEW_FORCE[VIEW_CATALOGUE[i].key];
    }
  }
  return on;
}

function readViewTogglesRaw(cfg) {
  var on = {}, i;
  // Views default ON so a missing Config row never silently drops a tab. A
  // switch that CHANGES how data is grouped is the opposite: it must default
  // off, or upgrading the script would regroup every teacher's tab unasked.
  for (i = 0; i < VIEW_CATALOGUE.length; i++) {
    on[VIEW_CATALOGUE[i].key] = VIEW_CATALOGUE[i].defaultOff ? false : true;
  }
  if (!cfg) return on;

  var inViews = false, sawAny = false;
  for (var r = 0; r < cfg.length; r++) {
    var c0 = String(cfg[r][0] || "").trim().toLowerCase();
    var c1 = String(cfg[r][1] || "").trim();
    if (isCfgSection(c0, "views to build")) { inViews = true; continue; }
    if (!inViews) continue;
    if (isOtherCfgSection(c0, "views to build")) { inViews = false; continue; }
    if (!c1 || c0 === "run?") continue;
    for (i = 0; i < VIEW_CATALOGUE.length; i++) {
      if (VIEW_CATALOGUE[i].label === c1) { on[VIEW_CATALOGUE[i].key] = isTicked(cfg[r][0]); sawAny = true; }
    }
  }
  if (!sawAny) {
    for (i = 0; i < VIEW_CATALOGUE.length; i++) {
      on[VIEW_CATALOGUE[i].key] = VIEW_CATALOGUE[i].defaultOff ? false : true;
    }
  }
  return on;
}

/** A ticked checkbox, a "Yes", or neither. Blank counts as unticked. */
function isTicked(v) {
  if (v === true)  return true;
  if (v === false) return false;
  var t = String(v === null || v === undefined ? "" : v).trim().toLowerCase();
  return t === "yes" || t === "true";
}


/**
 * Which teachers this run covers.
 *
 * Returns null when the answer is "everybody", so callers skip filtering
 * entirely rather than testing a map that would let everyone through anyway.
 * No ticks means everybody: a fresh Config behaves exactly as it did before the
 * filter existed, and nobody has to untick forty teachers to look at two.
 */
function readTeacherFilter(cfg) {
  if (!cfg) return null;
  var inTeachers = false, picked = {}, n = 0;

  for (var r = 0; r < cfg.length; r++) {
    var c1 = String(cfg[r][1] || "").trim();
    var lo0 = String(cfg[r][0] || "").trim().toLowerCase();

    if (isCfgSection(lo0, "teacher filter")) { inTeachers = true; continue; }
    if (!inTeachers) continue;

    // Any following section header closes the block.
    // Every other section header closes this block. Miss one and the rows below
    // it are read as teachers -- the VIEWS TO BUILD checkboxes default to
    // ticked, so they would have become nine phantom "teachers" that match no
    // pupil, and the run would have come out empty.
    if (isOtherCfgSection(lo0, "teacher filter")) { inTeachers = false; continue; }
    if (lo0 === "run?" || c1 === "" || c1.toLowerCase() === "teacher") continue;

    if (isTicked(cfg[r][0])) { picked[c1] = true; n++; }
  }

  return n > 0 ? picked : null;
}

/**
 * How much of each source a PLC tab shows.
 *
 * Returns the defaults untouched when there is no Config or the block is
 * missing, so an older Config keeps working -- the run does not stop because a
 * section it has never seen is absent.
 */
function readPLCContent(cfg) {
  var out = {
    tables:   { STAAR: 1, Benchmark: 0, DCB: 1, MAP: 0 },
    timeline: { STAAR: true, Benchmark: true, DCB: false, MAP: true },
    paper:    {},
    timelineMax: PLC_CONTENT_DEFAULT.timelineMax,
    found: false
  };
  if (!cfg) return out;
  var inPLC = false;
  for (var r = 0; r < cfg.length; r++) {
    var lo = String(cfg[r][0] || "").trim().toLowerCase();
    if (isCfgSection(lo, "plc content")) { inPLC = true; out.found = true; continue; }
    if (!inPLC) continue;
    if (isOtherCfgSection(lo, "plc content")) break;
    if (lo.indexOf(PLC_PAPER_ROW_LABEL.toLowerCase()) === 0) {
      var wsub = lo.indexOf("--") !== -1 ? String(cfg[r][0]).split("--").pop().trim() : "";
      var wval = String(cfg[r][1] || "").trim();
      for (var wk = 0; wk < CFG_SUBJECTS.length; wk++) {
        if (CFG_SUBJECTS[wk].label.toLowerCase() !== wsub.toLowerCase()) continue;
        if (wval && wval.toLowerCase() !== PLC_PAPER_AUTO.toLowerCase()) out.paper[CFG_SUBJECTS[wk].key] = wval;
      }
      continue;
    }
    if (lo.indexOf("timeline checkpoints") === 0) {
      var tv = String(cfg[r][1] || "").trim();
      if (tv.toLowerCase() === "all") out.timelineMax = 0;
      else {
        var tn = parseInt(tv, 10);
        if (!isNaN(tn) && tn > 0) out.timelineMax = tn;
      }
    }
  }
  return out;
}

/** Applies the teacher's Config choices back onto the detected sheets/blocks. */
function readConfig(cfg, sheetInfos, allBlocks) {
  if (!cfg) return false;
  var inSheetReg = false, inTestReg = false;

  for (var r = 0; r < cfg.length; r++) {
    var col0 = String(cfg[r][0] || "").trim();
    var lower = col0.toLowerCase();

    if (isCfgSection(lower, "sheet registry")) { inSheetReg = true;  inTestReg = false; continue; }
    if (isCfgSection(lower, "test registry"))  { inTestReg  = true;  inSheetReg = false; continue; }
    if (isCfgSection(lower, "plc content")) { inTestReg = false; inSheetReg = false; continue; }
    // skip note / header rows
    if (lower === "sheet name" || lower === "sheet" || col0 === "") continue;
    if (lower.indexOf("action required") !== -1 || lower.indexOf("dates were found") !== -1) continue;
    if (lower.indexOf("give two tests") !== -1 || lower.indexOf("treat all sheets") === 0) continue;

    if (inSheetReg) {
      for (var si = 0; si < sheetInfos.length; si++) {
        if (sheetInfos[si].sheetName === col0) {
          var lbl = String(cfg[r][1] || "").trim();
          if (lbl) sheetInfos[si].groupLabel = lbl;
          sheetInfos[si].include = String(cfg[r][3] || "Yes").trim().toLowerCase() !== "no";
          break;
        }
      }
    }

    if (inTestReg) {
      var rowSheet = col0;
      var rowTest  = String(cfg[r][1] || "").trim();
      if (!rowSheet && !rowTest) continue;
      var autoDateStr = String(cfg[r][2] || "").trim();
      var orderStr    = String(cfg[r][3] || "").trim();
      var includeStr  = String(cfg[r][4] || "Yes").trim().toLowerCase();
      var langStr     = String(cfg[r][5] || "").trim();
      var subjStr     = String(cfg[r][7] || "").trim();
      var srcStr      = String(cfg[r][8] || "").trim();

      for (var bi = 0; bi < allBlocks.length; bi++) {
        if (allBlocks[bi].sheetName === rowSheet && allBlocks[bi].testName === rowTest) {
          allBlocks[bi].order      = orderStr !== "" ? (parseInt(orderStr, 10) || 0) : 0;
          allBlocks[bi].include    = includeStr !== "no";
          if (langStr) allBlocks[bi].language = langStr;
          if (autoDateStr) allBlocks[bi].autoDate = autoDateStr;
          // The Subject dropdown allows free text, so "Reading" or "ELAR" typed
          // over it must still land on the one spelling every subject
          // comparison uses. Unrecognised text is kept as typed rather than
          // dropped, so it shows up in the Config as what it is.
          // A SUBJECT IS ONLY "MANUAL" WHEN A PERSON PUT IT THERE.
          //
          // Every Subject cell is written by the run, so the value alone says
          // nothing about who chose it. The "Subject set by" cell beside it is
          // the marker: the writer fills it in, and a teacher changing the
          // subject does not touch it. So a cell holding a real subject whose
          // source still reads COULD NOT TELL, or already reads "you chose it",
          // is a hand pick -- and hand picks outrank every detection rung and
          // survive a Config rebuild.
          var picked = detectSubjectFromName(subjStr) || subjStr;
          var wasChosen = /you chose it|COULD NOT TELL/i.test(srcStr);
          if (subjStr && subjStr !== SUBJECT_UNKNOWN &&
              subjStr.toLowerCase() !== "unknown") {
            allBlocks[bi].subject = picked;
            if (wasChosen) allBlocks[bi].subjectManual = picked;
          }
          break;
        }
      }
    }
  }
  return true;
}


/**
 * Reads every non-reserved tab once and returns everything downstream needs.
 * One getDataRange().getValues() per tab -- the values are cached and reused,
 * never re-read.
 */
/**
 * Who teaches whom, gathered before anything heavy runs.
 *
 * Reads only the Current Instructor / Section / Course columns -- three cells
 * per pupil per block, not the answer grid -- so the Config tab can offer a
 * teacher list without paying for a full parse first.
 *
 * Keyed on Local ID so a pupil appearing in eight years of test blocks is
 * counted once. A pupil with no instructor anywhere is collected under
 * NO_TEACHER so they can be included or dropped deliberately rather than
 * vanishing silently.
 */
var NO_TEACHER = "(No instructor listed)";

/**
 * The subjects a teacher can be given a tab for. The Config says ELAR because
 * that is what the district calls it; everything inside says ELA.
 */
var CFG_SUBJECTS = [
  { key: "Math",    label: "Math" },
  { key: "ELA",     label: "ELAR" },
  { key: "Science", label: "Science" },
  { key: "History", label: "History" }
];

/**
 * How many DISTINCT pupils put this teacher in this subject.
 */
function teacherSubjectCount(entry, subject) {
  var m = entry && entry.subjects ? entry.subjects[subject] : null;
  return m ? Object.keys(m).length : 0;
}

/**
 * Should this subject be ticked for this teacher when the Config is written?
 *
 * A SHARE, not a count. A maths teacher with 120 maths pupils and three whose
 * English block happens to name them is 2% English, and ticking it earned them
 * a second, near-empty English tab -- which is exactly what the user reported.
 * A special education teacher with 20 maths and 18 English is plainly both.
 * Small classes still qualify because the test is proportional.
 */
var CFG_SUBJECT_SHARE = 0.25;
function teacherSubjectTicked(entry, subject) {
  var total = entry && entry.students ? Object.keys(entry.students).length : 0;
  if (!total) return false;
  var n = teacherSubjectCount(entry, subject);
  if (n === 0) return false;
  return (n / total) >= CFG_SUBJECT_SHARE;
}

/** "Math 120, ELAR 3" -- what we saw, so a tick can be argued with. */
function teacherSubjectSummary(entry) {
  var out = [];
  for (var i = 0; i < CFG_SUBJECTS.length; i++) {
    var n = teacherSubjectCount(entry, CFG_SUBJECTS[i].key);
    if (n > 0) out.push(CFG_SUBJECTS[i].label + " " + n);
  }
  return out.join(", ");
}

function collectTeachers(data, blocks, census, pupilIndex) {
  var demo = detectDemoCols(data);
  var startRow = DATA_START_ROW - 1;
  while (startRow < data.length) {
    var probe = cellStr(data[startRow][demo.name]);
    if (probe !== "" && probe.toLowerCase() !== "student name") break;
    startRow++;
  }

  for (var r = startRow; r < data.length; r++) {
    var row = data[r];
    if (!row) continue;
    var name = cellStr(row[demo.name]);
    if (!name) continue;
    var key = cellStr(row[demo.id]) || name;

    // Take the value from the NEWEST paper, matching what parseStudents() does.
    // Reading the first non-empty block instead gave the Config census a
    // different answer from the views whenever these columns disagree between
    // blocks -- which they demonstrably do -- and the two totals then differ
    // for no visible reason. Every instructor seen is kept so the diagnostics
    // can report how many pupils are ambiguous.
    var teacher = "", section = "", course = "", period = "", bestKey = "";
    var seenT = {}, nSeenT = 0;
    for (var bi = 0; bi < blocks.length; bi++) {
      var b = blocks[bi];
      var t  = b.instructorCol >= 0 ? cellStr(row[b.instructorCol]) : "";
      var s2 = b.sectionCol    >= 0 ? cellStr(row[b.sectionCol])    : "";
      var c2 = b.courseCol     >= 0 ? cellStr(row[b.courseCol])     : "";
      var p2 = b.periodCol     >= 0 ? cellStr(row[b.periodCol])     : "";
      if (t === "-")  t  = "";
      if (s2 === "-") s2 = "";
      if (c2 === "-") c2 = "";
      if (p2 === "-") p2 = "";
      if (t && !seenT[t]) { seenT[t] = true; nSeenT++; }
      // NOT `key` -- that name already holds this pupil's Local ID a few lines
      // up, and `var` is function-scoped, so reusing it overwrote the id with a
      // date and every pupil collapsed into one census entry.
      var bkey = dateToSortKey(b.autoDate);
      if ((t || s2 || c2 || p2) && bkey >= bestKey) {
        bestKey = bkey;
        if (t)  teacher = t;
        if (s2) section = s2;
        if (c2) course  = c2;
        if (p2) period  = p2;
      }
    }
    // Older exports carry Course + Period instead of a single Section.
    if (!section && course) section = course;
    if (!teacher) teacher = NO_TEACHER;

    if (!census[teacher]) {
      census[teacher] = { students: {}, sections: {}, courses: {}, periods: {},
                          rows: 0, subjects: {} };
    }
    if (!census[teacher].subjects) census[teacher].subjects = {};
    if (!census[teacher].periods) census[teacher].periods = {};
    if (period) census[teacher].periods[period] = true;
    census[teacher].rows++;                       // rows minus distinct = shared Local IDs
    census[teacher].students[key] = true;
    // Which SUBJECTS this teacher is named on, and for how many DISTINCT
    // pupils. The count is what stops a single stray row -- one pupil whose
    // English block happens to name the maths teacher -- from declaring that
    // teacher an English teacher and earning them a second tab.
    for (var bs = 0; bs < blocks.length; bs++) {
      var bsub = blocks[bs].subject;
      if (!bsub || blocks[bs].instructorCol < 0) continue;
      var bwho = cellStr(row[blocks[bs].instructorCol]);
      if (!bwho || bwho === "-" || bwho !== teacher) continue;
      if (!census[teacher].subjects[bsub]) census[teacher].subjects[bsub] = {};
      census[teacher].subjects[bsub][key] = true;
    }
    if (section) census[teacher].sections[section] = true;
    if (course)  census[teacher].courses[course]   = true;

    if (pupilIndex) {
      pupilIndex[key] = { teacher: teacher, section: section,
                          instructorsSeen: nSeenT, hasSection: section ? 1 : 0 };
    }
  }
}

/** Grade a teacher is currently teaching, from their course names. "" if unclear. */
/**
 * The class periods this teacher holds, listed rather than counted.
 *
 * Replaced a "Sections" count and a "Grade(s)" column. Neither survived contact
 * with the real data: a teacher can hold several sections in one period, so the
 * section count did not describe anything a teacher recognises, and the grade
 * was derived from course names that do not reliably carry one.
 */
function teacherPeriodLabel(entry) {
  var ps = Object.keys((entry && entry.periods) || {});
  if (ps.length === 0) return "";
  ps.sort(function (a, b) {
    var na = parseInt(String(a).replace(/\D/g, ""), 10);
    var nb = parseInt(String(b).replace(/\D/g, ""), 10);
    if (!isNaN(na) && !isNaN(nb) && na !== nb) return na - nb;
    return String(a) < String(b) ? -1 : String(a) > String(b) ? 1 : 0;
  });
  return ps.join(", ");
}


/**
 * WHICH COLUMNS ACTUALLY NEED THEIR FILL READ.
 *
 * The first version read `rng.getBackgrounds()` over the whole data range of
 * every test tab -- 1.6 million hex strings on Austin's workbook -- and the run
 * died on the six-minute ceiling. Measured on that same export, only **43 of
 * 2,427 question columns** contain a cell whose credit depends on the fill.
 * That is **1% of the payload**. Every Math paper needs none at all.
 *
 * A cell needs its fill only where the TEXT cannot settle it:
 *   - a marked multi-select with no x/y ("+A,C"), where green means full and
 *     orange means part;
 *   - an x/y that OVERFLOWS a ceiling the grading row stated, where the colour
 *     decides instead of the numbers.
 * Plain multiple choice, bare numbers and a fitting x/y are settled by the text
 * and the fill is never consulted, so reading it is pure cost.
 *
 * DELIBERATELY CONSERVATIVE. Anything this does not recognise counts as needing
 * the fill, because a column wrongly skipped changes a score silently, while a
 * column wrongly read costs only time.
 */
function columnsNeedingFill(data, blocks) {
  var need = {}, bi, c, r;
  for (bi = 0; bi < blocks.length; bi++) {
    var blk = blocks[bi];
    if (!blk.include && blk.order === 0) { /* still scan: Config may include it later */ }
    var arRow = cellStr(data[1] ? data[1][blk.startCol] : "").toLowerCase() === "all responses" ? 1 : 2;
    var qNumRow = arRow + 1, gradingRow = arRow + 2;
    for (c = blk.questionStartCol; c < blk.summaryStartCol; c++) {
      var numStr = cellStr(data[qNumRow] ? data[qNumRow][c] : "");
      if (!numStr || isNaN(Number(numStr))) continue;
      var grading = cellStr(data[gradingRow] ? data[gradingRow][c] : "");
      var stated  = gradingStatesCeiling(grading);
      var pts     = gradingMaxPts(grading);
      for (r = DATA_START_ROW - 1; r < data.length; r++) {
        if (cellNeedsFill(cellStr((data[r] || [])[c]), stated, pts)) { need[c] = true; break; }
      }
    }
  }
  var out = [];
  for (var k in need) out.push(parseInt(k, 10));
  out.sort(function (a, b) { return a - b; });
  return out;
}

/** Mirrors scoreCell's branch order exactly. Unknown shapes return TRUE. */
function cellNeedsFill(raw, stated, pts) {
  var t = String(raw === null || raw === undefined ? "" : raw).trim();
  if (t === "" || t === "-" || t.charAt(0) === "#") return false;
  var v = (t.length > 1 && t.charAt(0) === "=") ? t.substring(1) : t;
  if (v.charAt(0) === "+" && v.length === 2 && /[A-J]/.test(v.charAt(1))) return false;
  if (v.charAt(0) !== "+" && v.length === 1 && /[A-J]/.test(v))           return false;
  var stripped = v.charAt(0) === "+" ? v.substring(1) : v;
  var slash = stripped.match(/(\d+)\/(\d+)\s*$/);
  if (slash) {
    var possible = parseInt(slash[2], 10);
    if (possible > 0) return !(!stated || possible <= pts);   // only an overflow needs it
    return true;
  }
  if (/^\d+$/.test(stripped)) return false;                   // bare number: text settles it
  return true;                                                 // multi-select, or unrecognised
}

function scanWorkbook(ss) {
  var tekMap     = buildTEKMap();
  var sheets     = ss.getSheets();
  var sheetInfos = [], allBlocks = [], mapSheetNames = [], cache = {}, formulaCache = {};
  // THE CELL COLOUR IS PART OF THE DATA. Read only where it can change a score -- see
  // columnsNeedingFill. Ported from the master 2026-10-06.
  var bgCache = {};
  var teacherCensus = {}, pupilIndex = {};

  for (var i = 0; i < sheets.length; i++) {
    var sh   = sheets[i];
    var name = sh.getName();
    if (isReservedSheet(name)) continue;
    if (sh.getLastRow() < 2 || sh.getLastColumn() < 2) continue;

    var rng  = sh.getDataRange();
    var data = rng.getValues();
    // Either MAP layout. Without the wide check the NWEA CSV falls through to
    // findTestBlocks and is parsed as a question-level test export.
    var format = detectFormat(data);
    var blocks = findTestBlocks(name, data, format, tekMap);
    if (blocks.length === 0) continue;

    collectTeachers(data, blocks, teacherCensus, pupilIndex);
    sheetInfos.push({ sheetName: name, groupLabel: name, format: format, include: true });
    for (var b = 0; b < blocks.length; b++) allBlocks.push(blocks[b]);
    cache[name] = data;
    // Eduphoria stores correct answers as formulas ("=+A"); getValues() shows an
    // error for those cells, so keep the formula text alongside the values.
    formulaCache[name] = rng.getFormulas();
    // ONLY THE COLUMNS THAT NEED IT. Reading every fill on every tab is what
    // put the run past the six-minute ceiling: 1.6M hex strings for the 1% of
    // them that change a score. One narrow read per needed column, and a tab
    // that needs none -- every Math paper -- pays nothing at all.
    //
    // Never fatal: a tab whose fills cannot be read scores on text alone,
    // exactly as every run before 2026-09-24 did.
    try {
      var needCols = columnsNeedingFill(data, blocks);
      if (needCols.length) {
        var byCol = {}, nRows = data.length;
        // ONE READ PER RUN OF COLUMNS, NOT ONE PER COLUMN.
        //
        // Measured live on 2026-09-25: 124 single-column reads cost 71.7s, a
        // flat 0.58s each almost regardless of how tall the column was. The
        // cost is the round trip, not the data -- so the fix is to make fewer
        // of them, not smaller ones. Needed columns are usually clustered (a
        // paper's constructed-response items sit together), so the runs are
        // few and each one is a single call.
        //
        // The gap between two runs is what stops this collapsing back into
        // "read the whole sheet", which is what blew the time limit on
        // 2026-09-24: 1.6M hex strings for the 1% that change a score. A gap
        // of 24 columns or less is cheaper to swallow than to pay another
        // round trip for; anything wider stays a separate read.
        var runs = [], GAP = 24;
        for (var nc = 0; nc < needCols.length; nc++) {
          var last = runs.length ? runs[runs.length - 1] : null;
          if (last && needCols[nc] - last.to <= GAP) last.to = needCols[nc];
          else runs.push({ from: needCols[nc], to: needCols[nc] });
        }
        for (var ru = 0; ru < runs.length; ru++) {
          var span = runs[ru].to - runs[ru].from + 1;
          var grid = sh.getRange(1, runs[ru].from + 1, nRows, span).getBackgrounds();
          for (var wc = 0; wc < needCols.length; wc++) {
            var col = needCols[wc];
            if (col < runs[ru].from || col > runs[ru].to) continue;
            var flat = [], off = col - runs[ru].from;
            for (var rr = 0; rr < grid.length; rr++) flat.push(grid[rr][off]);
            byCol[col] = flat;
          }
        }
        bgCache[name] = { byCol: byCol };
        RUN_TRACE.at("fills read", name + ": " + needCols.length + " column(s) in "
                     + runs.length + " read(s)");
      }
    }
    catch (eBg) { console.log("Cell colours unread on a tab; scoring falls back to text."); }
  }
  return { sheetInfos: sheetInfos, allBlocks: allBlocks, mapSheetNames: mapSheetNames,
           cache: cache, formulaCache: formulaCache, bgCache: bgCache, tekMap: tekMap,
           teacherCensus: teacherCensus, pupilIndex: pupilIndex };
}

/**
 * Numbers the tests 1..N in date order. Undated blocks stay 0.
 *
 * One order per distinct TEST, not per block. The same paper given to three
 * classes on three tabs is ONE test; numbering those blocks 6, 7 and 8 split
 * its pupils into three separate cohorts, so a section of fifteen appeared as
 * five and most of the class vanished from the per-teacher view. Blocks sharing
 * an order are merged by buildMergedTests(), which is exactly what is wanted.
 */
/**
 * A paper's identity, ignoring language.
 *
 * "May 2026 STAAR Mathematics Spanish, Grade 5" and the English form are the
 * SAME paper: same blueprint, same TEKs, same question numbers, sat by pupils
 * sitting in the same room. Grade 5 offers a Spanish form, so one section
 * routinely spans both -- treating them as separate tests dropped every Spanish
 * tester out of their own teacher's tab.
 */
function testIdentity(title) {
  return String(title)
    .replace(/\s*spanish\s*/i, " ")
    .replace(/\s+([,;])/g, "$1")     // "Mathematics , Grade 5" -> "Mathematics, Grade 5"
    .replace(/\s+/g, " ")
    .trim().toLowerCase();
}

function autoOrderBlocks(allBlocks) {
  var byTest = {}, names = [], i;
  for (i = 0; i < allBlocks.length; i++) {
    var b = allBlocks[i];
    if (!b.autoDate) continue;
    var id = testIdentity(b.testName);
    if (!byTest[id]) { byTest[id] = []; names.push(id); }
    byTest[id].push(b);
  }
  names.sort(function (x, y) {
    var kx = dateToSortKey(byTest[x][0].autoDate), ky = dateToSortKey(byTest[y][0].autoDate);
    if (kx !== ky) return kx < ky ? -1 : 1;
    return x < y ? -1 : x > y ? 1 : 0;
  });
  for (var o = 0; o < names.length; o++) {
    var grp = byTest[names[o]];
    for (var g = 0; g < grp.length; g++) grp[g].order = o + 1;
  }

  // Dated tests are now numbered 1..names.length. Everything WITHOUT a date
  // goes after them, newest-last, grouped so two forms of one paper still share
  // an Order. Leaving these at 0 is what used to stop the run dead.
  var next = names.length + 1, undated = {}, uNames = [];
  for (var u = 0; u < allBlocks.length; u++) {
    if (allBlocks[u].autoDate) continue;
    var uid = testIdentity(allBlocks[u].testName);
    if (!undated[uid]) { undated[uid] = []; uNames.push(uid); }
    undated[uid].push(allBlocks[u]);
  }
  uNames.sort();
  for (var un = 0; un < uNames.length; un++) {
    var ug = undated[uNames[un]];
    for (var ui = 0; ui < ug.length; ui++) ug[ui].order = next;
    next++;
  }

  return uNames.length > 0;                    // true = some had no date
}

/**
 * Give an Order to anything still sitting at zero, and say what was touched.
 *
 * A blank Order used to end the run. It no longer does: a test with no date is
 * placed after the dated ones and the run is allowed to continue, with the
 * teacher told which tests were placed for them. Position is a guess, and a
 * wrong guess only misorders a column -- stopping the whole run was the worse
 * failure by a wide margin.
 */
function fillMissingOrders(allBlocks) {
  var maxOrder = 0, i;
  for (i = 0; i < allBlocks.length; i++) {
    if (allBlocks[i].order > maxOrder) maxOrder = allBlocks[i].order;
  }
  var assigned = [], byId = {};
  for (i = 0; i < allBlocks.length; i++) {
    var b = allBlocks[i];
    if (!b.include || b.order > 0) continue;
    var id = testIdentity(b.testName);
    // Two forms of one paper keep a shared Order, exactly as autoOrderBlocks
    // does -- otherwise the Spanish form becomes a separate column.
    if (byId[id] === undefined) { byId[id] = ++maxOrder; assigned.push({ name: b.testName, order: byId[id] }); }
    b.order = byId[id];
  }
  return assigned;
}


// === PART 9: MAIN ======================================================

/**
 * A breadcrumb trail through a run.
 *
 * Apps Script gives a stack trace when something throws, but says nothing at
 * all when a run ENDS EARLY on purpose -- and that is the failure that actually
 * costs a morning: the tool returns to the Config tab with no error, and there
 * is no way from the sheet to tell a missed cell from a bug.
 *
 * So every stage announces itself here. Whatever happens, the last thing
 * recorded is the furthest point reached, and RUN_TRACE.report() turns it into
 * something that can be read down a phone or pasted into a message.
 */
var RUN_TRACE = {
  stages: [], notes: [], t0: 0,

  start: function () { this.stages = []; this.notes = []; this.t0 = new Date().getTime(); },

  /** Record reaching a stage. Cheap -- no sheet writes, no flushes. */
  at: function (stage, detail) {
    this.stages.push({
      stage: stage,
      detail: detail === undefined ? "" : String(detail),
      ms: new Date().getTime() - this.t0
    });
    console.log("[trace] " + stage + (detail ? "  --  " + detail : ""));
  },

  /** Record something suspicious that did NOT stop the run. */
  note: function (what) {
    this.notes.push(String(what));
    console.log("[note] " + what);
  },

  furthest: function () {
    return this.stages.length ? this.stages[this.stages.length - 1].stage : "(nothing ran)";
  },

  /** The trail as text, oldest first, for an alert or a message to me. */
  report: function () {
    var out = [];
    for (var i = 0; i < this.stages.length; i++) {
      out.push("  " + (i + 1) + ". " + this.stages[i].stage
               + (this.stages[i].detail ? "  --  " + this.stages[i].detail : "")
               + "   [" + this.stages[i].ms + "ms]");
    }
    var txt = "RUN TRACE  (furthest point: " + this.furthest() + ")\n" + out.join("\n");
    if (this.notes.length) txt += "\n\nUNEXPECTED:\n  \u2022 " + this.notes.join("\n  \u2022 ");
    return txt;
  }
};

/**
 * What the Config reader actually saw, checked against what the writer wrote.
 *
 * This is the check that would have caught the PLC CONTENT collision in
 * seconds. It does not ask "is the Config filled in", it asks "did every
 * section READ BACK". A section the writer emitted and the reader cannot find
 * means the section machinery is broken, not that a teacher missed a cell --
 * and those two need very different responses.
 */
function auditConfigSections(cfg) {
  var found = {}, rows = {}, i;
  for (i = 0; i < CFG_SECTIONS.length; i++) { found[CFG_SECTIONS[i]] = false; rows[CFG_SECTIONS[i]] = -1; }
  if (!cfg) return { found: found, missing: CFG_SECTIONS.slice(), rows: rows };

  for (var r = 0; r < cfg.length; r++) {
    var lo = String(cfg[r][0] || "").trim().toLowerCase();
    if (!lo) continue;
    for (i = 0; i < CFG_SECTIONS.length; i++) {
      if (!found[CFG_SECTIONS[i]] && isCfgSection(lo, CFG_SECTIONS[i])) {
        found[CFG_SECTIONS[i]] = true; rows[CFG_SECTIONS[i]] = r + 1;
      }
    }
  }
  var missing = [];
  for (i = 0; i < CFG_SECTIONS.length; i++) if (!found[CFG_SECTIONS[i]]) missing.push(CFG_SECTIONS[i]);
  return { found: found, missing: missing, rows: rows };
}

/**
 * One row per run, appended, never cleared: the Run_Log tab.
 *
 * A dialog is gone the moment it is clicked and Data_Check is rebuilt every
 * run, so "it built 12 tabs last time and 16 this time" had no evidence
 * behind it. This keeps the numbers that decide a tab, run after run, so two
 * runs can be compared by name. Teacher names only; never a pupil.
 */
function appendRunLog(ss, outcome) {
  // Public build: no Run_Log tab. The five named tabs are the whole promise.
  return;
}

/**
 * The entry point. All it does is run the analysis and make sure that if
 * anything throws, the trail up to that point is put in front of the person
 * running it rather than buried in the execution log.
 *
 * The error is re-thrown afterwards so Apps Script still records the real stack
 * trace -- the dialog is for the teacher, the log is for me.
 */
function runAnalysis() {
  RUN_TRACE.start();
  RUN_TRACE.at("start");
  try {
    runAnalysisInner();
  } catch (err) {
    var where = RUN_TRACE.furthest();
    console.log("FAILED after: " + where);
    console.log(RUN_TRACE.report());
    try { appendRunLog(SpreadsheetApp.getActiveSpreadsheet(), "FAILED after " + where + ": "
                       + (err && err.message ? err.message : String(err))); } catch (e3) {}
    try {
      SpreadsheetApp.getUi().alert(
        "Run failed after: " + where,
        "The error was:\n  " + (err && err.message ? err.message : String(err)) + "\n\n"
        + RUN_TRACE.report()
        + "\n\nSend this whole message on and it says exactly how far the run got.",
        SpreadsheetApp.getUi().ButtonSet.OK);
    } catch (e2) { /* no UI (triggered run) -- the log above still has it */ }
    throw err;
  }
}

function runAnalysisInner() {
  resetFlatCache();
  var ss  = SpreadsheetApp.getActiveSpreadsheet();
  var ui  = SpreadsheetApp.getUi();
  var t0  = new Date().getTime();

  PROGRESS.note(ss, "Looking at the tabs in this workbook ...");
  var scan = scanWorkbook(ss);
  RUN_TRACE.at("scanned workbook",
    scan.sheetInfos.length + " data sheet(s), " + scan.allBlocks.length + " test block(s), "
    + scan.mapSheetNames.length + " MAP sheet(s)");
  // A missing Student Name column is the one failure that looks like success:
  // parseStudents skips every row without a name, so the run completes, every
  // tab builds, and not one pupil is in any of them. Catch it up front.
  var noNameSheets = [];
  for (var nsi = 0; nsi < scan.sheetInfos.length; nsi++) {
    var nsName = scan.sheetInfos[nsi].sheetName;
    if (!scan.sheetInfos[nsi].include) continue;
    var nsData = scan.cache && scan.cache[nsName];
    if (!nsData) continue;
    var foundName = false;
    for (var nr = 0; nr < Math.min(5, nsData.length) && !foundName; nr++) {
      for (var nc = 0; nc < Math.min(12, (nsData[nr] || []).length); nc++) {
        if (cellStr(nsData[nr][nc]).toLowerCase() === "student name") { foundName = true; break; }
      }
    }
    if (!foundName) noNameSheets.push(nsName);
  }
  if (noNameSheets.length > 0 && noNameSheets.length === scan.sheetInfos.length) {
    ui.alert("No Student Name column found",
      "These sheets have no \"Student Name\" header:\n\n  " + noNameSheets.join("\n  ") +
      "\n\nEvery row is keyed on that column, so the run would finish with zero " +
      "pupils and no error. Add the column to the export and pull again.",
      ui.ButtonSet.OK);
    return;
  }

  if (scan.allBlocks.length === 0) {
    ui.alert("No test data found",
      "Paste an Eduphoria export into a tab, then run this again.\n\n"
      + "The script looks for an \"All Responses\" header to find each test.",
      ui.ButtonSet.OK);
    return;
  }

  // -- Does a usable Config already exist? -------------------------------
  var cfg = getConfigValues(ss);
  RUN_TRACE.at("read Config", cfg ? (cfg.length + " rows") : "NO Config tab");

  // Which sections did the reader actually find? A section the writer emits
  // but the reader cannot see is a bug in the section machinery, and it stays
  // silent unless something goes looking for it.
  if (cfg) {
    var audit = auditConfigSections(cfg);
    RUN_TRACE.at("Config sections",
      (CFG_SECTIONS.length - audit.missing.length) + " of " + CFG_SECTIONS.length + " found");
    for (var am = 0; am < audit.missing.length; am++) {
      // MAP sections are written only when a MAP tab is present, so their
      // absence is normal and must not be reported as a fault.
      if (audit.missing[am].indexOf("map") === 0) continue;
      RUN_TRACE.note("Config section not found by the reader: " + audit.missing[am].toUpperCase());
    }
  }

  var configComplete = false, missing = [];
  if (cfg) {
    readConfig(cfg, scan.sheetInfos, scan.allBlocks);
    configComplete = true;

    // A blank Order no longer stops the run. It is filled in, and the teacher
    // is told and asked -- because they may well have already checked it, and
    // being sent back to Config to retype something the script could work out
    // for itself cost a morning once.
    missing = fillMissingOrders(scan.allBlocks);
    if (missing.length) {
      var lines = [];
      for (var mi = 0; mi < missing.length; mi++) {
        lines.push("  \u2022 " + missing[mi].name + "   \u2192  Order " + missing[mi].order);
      }
      RUN_TRACE.note(missing.length + " test(s) had no Order; auto-assigned: "
                     + lines.join(" | "));
      var go = ui.alert(
        "Auto-assigned Order on " + missing.length + " test(s)",
        "These tests are included but had no Date Taken, so no Order. They have "
        + "been placed AFTER the dated tests, in this sequence:\n\n"
        + lines.join("\n")
        + "\n\nOrder only sets left-to-right position on the timeline and which "
        + "paper counts as most recent. If that sequence is right, or you have "
        + "already checked it, continue.\n\n"
        + "YES  =  run now with the order above\n"
        + "NO   =  stop, so you can set Order yourself on the Config tab",
        ui.ButtonSet.YES_NO);
      if (go !== ui.Button.YES) {
        RUN_TRACE.at("stopped -- auto-assigned Order declined");
        console.log(RUN_TRACE.report());
        return;
      }
      RUN_TRACE.at("auto-assigned Order accepted", missing.length + " test(s)");
    }
    RUN_TRACE.at("applied Config",
      scan.allBlocks.length + " block(s), " + missing.length + " auto-assigned");
  }

  // -- PHASE 1: build the Config and stop --------------------------------
  if (!configComplete) {
    var anyMissingDates = autoOrderBlocks(scan.allBlocks);
    // THE CONFIG DOES THE GUESSING, so the guessing has to happen first.
    // Subjects used to be resolved inside buildAllViews, which is phase TWO --
    // so the Config a teacher reviews carried whatever the test title happened
    // to say and nothing else, and the papers that needed a hand pick were
    // exactly the ones it stayed silent about. Resolving here means the Config
    // arrives with its best answer, where it came from, and an explicit
    // "Unknown subject" on anything it could not work out.
    var cfgMaps = buildSubjectTEKMaps();
    resolveBlockSubjects(scan.allBlocks, scan.cache, cfgMaps, readSubjectMemory());
    writeConfig(ss, scan.sheetInfos, scan.allBlocks, anyMissingDates, scan.mapSheetNames,
                scan.teacherCensus);
    // Say WHY, on screen. This used to stop with no explanation on the tab
    // itself, so a Config that looked completely filled in gave a teacher no
    // way to tell whether they had missed a cell or the script had a bug.
    // Reaching here means there was no readable Config at all. A blank Order no
    // longer lands here -- fillMissingOrders() handles that and asks instead.
    var whyStopped = cfg
      ? "STOPPED BECAUSE: the Config tab exists but could not be read.\n\n"
      : "First run \u2014 Config has just been created.\n\n";
    RUN_TRACE.at("stopped at Config");
    console.log(RUN_TRACE.report());
    appendRunLog(ss, "Config written");
    ui.alert("Config ready \u2014 review it, then run again",
      whyStopped +
      RUN_TRACE.report() + "\n\n" +
      (anyMissingDates
        ? "Some tests had no Date Taken, so their Order cells are blank.\n"
          + "Tests WITH dates were auto-numbered for you. Fill in the blank Order\n"
          + "cells to slot the remaining tests into the sequence.\n\n"
        : "Every test had a date, so Order has been filled in for you.\n\n")
      + "On the Config tab:\n"
      + "  \u2022 TEACHER FILTER \u2014 tick the teachers you want in this run.\n"
      + "    Leave every box unticked to run everybody.\n"
      + "  \u2022 Include? \u2014 set to No to skip a test\n"
      + "  \u2022 Same Order number on two tests combines them\n\n"
      + "Then run STAAR Analyzer \u25b8 Run Analysis again.",
      ui.ButtonSet.OK);
    return;
  }

  // -- PHASE 2: build the views ------------------------------------------
  var runMode       = "Both";
  var combineSheets = readCombineSheets(cfg);
  var allExcluded   = {};
  if (combineSheets) console.log("Combine sheets: ON");

  // Resolve subjects BEFORE anything is built, so the dialog below is asked
  // while stopping is still cheap -- not after eighteen teacher tabs.
  var runMaps = buildSubjectTEKMaps();
  var runManual = readSubjectMemory();
  for (var rm = 0; rm < scan.allBlocks.length; rm++) {
    if (scan.allBlocks[rm].subjectManual) {
      runManual[scan.allBlocks[rm].testName] = scan.allBlocks[rm].subjectManual;
    }
  }
  resolveBlockSubjects(scan.allBlocks, scan.cache, runMaps, runManual);
  writeSubjectMemory(runManual);
  if (!confirmGuessedSubjects(ui)) {
    RUN_TRACE.at("stopped -- subject needs setting");
    console.log(RUN_TRACE.report());
    appendRunLog(ss, "stopped: subject needs setting");
    return;
  }

  PLC_TABS_BUILT = {}; PLC_NO_TAB = []; PLC_TICKED_N = 0; RUN_STATS = { students: 0, tests: 0 };
  buildAllViews(ss, scan, runMode, combineSheets, allExcluded, cfg);
  appendRunLog(ss, "views built");

  console.log("Finished in " + ((new Date().getTime() - t0) / 1000).toFixed(1) + "s");
}

/** Wipes the Config tab so the next run rebuilds it from scratch. */
function rebuildConfig() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var ui = SpreadsheetApp.getUi();
  var sheet = ss.getSheetByName("Config");
  if (sheet) ss.deleteSheet(sheet);
  ui.alert("Config cleared",
    "Run STAAR Analyzer \u25b8 Run Analysis to rebuild it from your current tabs.",
    ui.ButtonSet.OK);
}


// === PART 10: QUESTION & STUDENT PARSING ===============================

/**
 * Every TEK code on one block, read from the TEK row alone.
 *
 * Exists so a block's SUBJECT can be resolved BEFORE parseQuestions() runs.
 * parseQuestions needs the subject to pick the right TEK map, and the subject
 * used to be worked out from the questions -- which meant it was worked out
 * AFTER they had already been filed. Reading one row of cells is cheap; the
 * alternative was parsing every block twice.
 */
function blockTEKList(block, data) {
  var arRow = String(data[1] ? data[1][block.startCol] : "").trim().toLowerCase() === "all responses" ? 1 : 2;
  var qNumRow = arRow + 1, tekRow = arRow + 4;
  var dual = hasDualCodeRow(block, data, arRow);
  var out = [];
  for (var c = block.questionStartCol; c < block.summaryStartCol; c++) {
    var numStr = cellStr(data[qNumRow] ? data[qNumRow][c] : "");
    if (!numStr || isNaN(Number(numStr))) continue;
    out.push(normalizeTEK(cellStr(data[tekRow] ? data[tekRow][c] : "")));
    // The dual-code row is often the MORE distinctive of the two -- an
    // 8th grade Social Studies paper carries its content TEKs on row one and
    // 8.29.x, the social-studies-skills block, underneath. Leaving it out cost
    // exactly the codes that identify the subject.
    if (dual) out.push(normalizeTEK(cellStr(data[tekRow + 1] ? data[tekRow + 1][c] : "")));
  }
  return out;
}

/**
 * Does this block carry a SECOND TEK row -- a dual-coded paper?
 *
 * A question can assess two standards at once, and Eduphoria writes the second
 * directly under the first. That row sits exactly where the first pupil row
 * would be, so it is identified by what it holds rather than by position: no
 * name in the name column, and TEK-shaped values under the question columns.
 * parseStudents already skips it, because it skips any row with no name.
 */
function hasDualCodeRow(block, data, arRow) {
  var tekRow = arRow + 4, row = data[tekRow + 1];
  if (!row) return false;
  var demo = detectDemoCols(data);
  if (cellStr(row[demo.name]) !== "") return false;      // a pupil row, not a TEK row
  var hits = 0;
  for (var c = block.questionStartCol; c < block.summaryStartCol; c++) {
    var v = cellStr(row[c]);
    if (!v || v === "-" || v === "()") continue;
    if (normalizeTEK(v)) hits++;
  }
  return hits > 0;
}

/**
 * Resolve every included block's subject to a REGISTRY subject, in place.
 *
 * Handles both ways the old code went wrong:
 *   - block.subject unset (the test title names no subject), and
 *   - block.subject set to something that is not a registry key, which
 *     readConfig() can do via `detectSubjectFromName(subjStr) || subjStr`
 *     -- a free-text Config entry like "Literacy Block" is truthy, so the old
 *     code treated the subject as KNOWN while subjectTEKMaps[it] was undefined.
 * Both used to reach the flat all-subjects map. Returns the number of blocks it
 * could not resolve.
 */
/**
 * The reporting-category row, read as a SUBJECT.
 *
 * Eduphoria writes its own category tag on the row above the TEKs: "M1" on a
 * maths paper, "R1" on reading, "SC1" on science, "History 2" on social
 * studies. That is a direct statement of subject by the system that built the
 * test, and it beats anything inferred from TEK codes -- which are namespaced
 * per subject and therefore ambiguous by construction.
 *
 * Deliberately conservative. A bare "S1" is NOT read as Science: S could be
 * anything, and a wrong subject is the one failure this whole ladder exists to
 * avoid. Unrecognised tags return "" and the next rung takes over.
 */
var CATEGORY_TAG_SUBJECT = [
  { re: /^(hist|ss|soc)/i,          subject: "History" },
  { re: /^(sci|sc\s*\d)/i,           subject: "Science" },
  { re: /^(math|m\s*\d)/i,           subject: "Math" },
  { re: /^(elar?|rla|read|r\s*\d|w\s*\d)/i, subject: "ELA" }
];

function subjectFromCategoryTag(tag) {
  var t = cellStr(tag).trim();
  if (!t || t === "()" || t === "-") return "";
  for (var i = 0; i < CATEGORY_TAG_SUBJECT.length; i++) {
    if (CATEGORY_TAG_SUBJECT[i].re.test(t)) return CATEGORY_TAG_SUBJECT[i].subject;
  }
  return "";
}

/** Every category tag on one block, for the rung above. */
function blockCategoryTags(block, data) {
  var arRow = String(data[1] ? data[1][block.startCol] : "").trim().toLowerCase() === "all responses" ? 1 : 2;
  var mpRow = arRow + 3, out = [];
  for (var c = block.questionStartCol; c < block.summaryStartCol; c++) {
    var v = cellStr(data[mpRow] ? data[mpRow][c] : "");
    if (v && v !== "()" && v !== "-") out.push(v);
  }
  return out;
}

/**
 * Subject from a block's TEK codes, weighting each code by how DISCRIMINATING
 * it is rather than counting hits.
 *
 * A plain tally is worthless here: 37 codes exist in all four subjects, so a
 * nine-question CFA using only those scores 9-9-9-9 and the winner is whichever
 * subject happens to be registered first -- which is Math, always. Weighting a
 * code by 1/(subjects that own it) means a code unique to Social Studies counts
 * four times what a four-way code does.
 *
 * Returns { subject, decisive, scores }. `decisive` is the honest part: a
 * result that only just edged ahead is offered as a guess, not as an answer.
 */
function weightedSubjectFromTEKs(codes) {
  var reg = subjectRegistry(), scores = {}, i, r;
  for (i = 0; i < codes.length; i++) {
    if (!codes[i]) continue;
    var owners = [];
    for (r = 0; r < reg.length; r++) if (reg[r].tekSet[codes[i]]) owners.push(reg[r].subject);
    if (!owners.length) continue;
    var w = 1 / owners.length;
    for (r = 0; r < owners.length; r++) scores[owners[r]] = (scores[owners[r]] || 0) + w;
  }
  var best = "", bn = 0, second = 0;
  for (var k in scores) {
    if (scores[k] > bn) { second = bn; bn = scores[k]; best = k; }
    else if (scores[k] > second) second = scores[k];
  }
  // Clear of the runner-up by half again, and standing on more than one
  // unshared code's worth of evidence. Below that it is a coin toss wearing a
  // decimal point.
  var decisive = !!best && bn >= 1.5 && bn >= second * 1.5;
  return { subject: best, decisive: decisive, scores: scores };
}

/**
 * Every block's subject, worked out and LABELLED WITH WHERE IT CAME FROM.
 *
 * The ladder, strongest first. Anything below the third rung is a GUESS, and
 * the Config says so on its face rather than presenting it as fact:
 *
 *   1. manual     a subject chosen by hand on the Config tab. Never overridden.
 *   2. title      the test name says it ("... ELAR", "Math 6").
 *   3. tag        Eduphoria's own category tag on the paper (SC1, History 2).
 *   4. TEKs       weighted code tally, and only when it is decisive.
 *   5. teacher    this instructor teaches one subject on papers we are sure of.
 *   6. tab        every other block on the tab agrees, and none contradicts.
 *   7. unknown    nothing answered. The Config offers a dropdown.
 *
 * Why TEKs outrank the teacher: a decisive code tally is evidence from the
 * paper itself, while the teacher is evidence about the person holding it. A
 * teacher who picks up one section of another subject would otherwise drag
 * every one of their papers with them.
 */
/**
 * What the Subject cell says when nothing could identify the paper.
 *
 * A WORD, not a blank. A blank cell reads as "nobody has filled this in yet";
 * this reads as "the tool looked and could not tell, so it is asking you".
 * It is in the dropdown so it can be seen and replaced rather than typed over.
 */
var SUBJECT_UNKNOWN = "Unknown subject";

/** Plain English for the Config's "Subject set by" column. */
/**
 * The dialog you have to click through when a subject was guessed.
 *
 * A guess that looks like an answer is how a class ends up planning against
 * another subject's standards. So a run that had to infer ANY subject says so
 * on screen, by name, and will not proceed until it is acknowledged -- and a
 * run with an "Unknown subject" still on the Config refuses outright, because
 * a paper with no subject files its questions under no reporting category and
 * every TEK table on it would be blank.
 *
 * Returns true when the run may continue.
 */
function confirmGuessedSubjects(ui) {
  var guessed = [], unknown = [], i;
  for (i = 0; i < SUBJECT_RESOLUTION.length; i++) {
    var r = SUBJECT_RESOLUTION[i];
    if (r.from === "unknown") unknown.push(r);
    else if (r.guess) guessed.push(r);
  }
  if (!guessed.length && !unknown.length) return true;

  function lines(list, withSubject) {
    var L = [];
    for (var j = 0; j < list.length && j < 12; j++) {
      L.push("  \u2022 " + list[j].testName
             + (withSubject ? "\n        read as " + list[j].subject
                              + "  (" + subjectFromLabel(list[j].from) + ")" : ""));
    }
    if (list.length > 12) L.push("  ...and " + (list.length - 12) + " more");
    return L.join("\n");
  }

  if (unknown.length) {
    ui.alert("Set the subject on " + unknown.length + " test(s) before running",
      "These papers carry no subject the tool can read, and it will not guess "
      + "at one:\n\n" + lines(unknown, false)
      + "\n\nOn the Config tab, TEST REGISTRY, the Subject column shows "
      + "\"" + SUBJECT_UNKNOWN + "\" on each of them. Pick the right subject "
      + "from the dropdown and run again.\n\n"
      + "WHY IT CANNOT GUESS: a TEKS code is not unique to a subject. \"7.6.B\" "
      + "is a real standard in Maths, Reading, Science AND Social Studies, "
      + "meaning four different things. A short paper using only codes like "
      + "that carries no subject information at all.\n\n"
      + "Your pick is remembered, including through Rebuild Config.",
      ui.ButtonSet.OK);
    return false;
  }

  var go = ui.alert("The subject was GUESSED on " + guessed.length + " test(s)",
    "The run can continue, but check these before anyone plans from them:\n\n"
    + lines(guessed, true)
    + "\n\nA wrong subject does not look wrong. The tab still builds, the "
    + "numbers still add up, and the TEKs are filed under another subject's "
    + "reporting categories.\n\n"
    + "To correct one: Config tab, TEST REGISTRY, change the Subject cell. Your "
    + "choice outranks every guess and is remembered.\n\n"
    + "YES  =  run with the subjects above\n"
    + "NO   =  stop, so you can set them yourself",
    ui.ButtonSet.YES_NO);
  return go === ui.Button.YES;
}

function subjectFromLabel(from) {
  if (from === "manual")  return "you chose it";
  if (from === "title")   return "the test name";
  if (from === "tag")     return "the paper's own category tag";
  if (from === "TEKs")    return "GUESS -- its TEK codes";
  if (from === "teacher") return "GUESS -- this teacher's subject";
  if (from === "tab")     return "GUESS -- the rest of this tab";
  if (from === "unknown") return "COULD NOT TELL -- please pick";
  return "";
}

/**
 * Subjects chosen by hand, remembered across a Config rebuild.
 *
 * Rebuild Config deletes the tab, which would throw away every subject that
 * had to be picked by hand -- and those are exactly the papers detection
 * cannot do on its own, so they would need picking again after every rebuild.
 * While iterating on the code that is many times a day.
 *
 * Stored per spreadsheet, keyed on the test NAME, because the Order number is
 * reassigned on every run. Failing to read or write them is never fatal: a
 * forgotten pick costs a re-pick, and stopping the run would cost the run.
 */
var SUBJECT_MEMORY_KEY = "STAAR_ANALYZER_SUBJECT_PICKS";

function readSubjectMemory() {
  try {
    var raw = PropertiesService.getDocumentProperties().getProperty(SUBJECT_MEMORY_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) { return {}; }
}

function writeSubjectMemory(map) {
  try {
    PropertiesService.getDocumentProperties()
      .setProperty(SUBJECT_MEMORY_KEY, JSON.stringify(map || {}));
  } catch (e) { console.log("Subject picks not saved: " + (e && e.message ? e.message : e)); }
}

/** Menu: forget every remembered pick, for a genuinely clean slate. */
function forgetSubjectPicks() {
  var ui = SpreadsheetApp.getUi();
  var n = 0;
  for (var k in readSubjectMemory()) n++;
  writeSubjectMemory({});
  ui.alert("Subject picks cleared",
    n + " remembered subject(s) forgotten. The next run detects every paper from scratch.",
    ui.ButtonSet.OK);
}

var SUBJECT_RESOLUTION = [];

function resolveBlockSubjects(allBlocks, cache, subjectTEKMaps, manualSubjects) {
  var i, blk, unresolved = 0;
  SUBJECT_RESOLUTION = [];
  manualSubjects = manualSubjects || {};

  function known(sub) { return !!(sub && subjectTEKMaps[sub]); }
  function settle(b, sub, from, guess) {
    b.subject = sub;
    b.subjectFrom = from;
    b.subjectGuess = !!guess;
  }

  var live = [];
  for (i = 0; i < allBlocks.length; i++) {
    if (allBlocks[i].include && allBlocks[i].order !== 0) live.push(allBlocks[i]);
  }

  // -- rungs 1 to 4, which are the ones that can stand alone ---------------
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    var manual = manualSubjects[blk.testName];
    if (known(manual)) { settle(blk, manual, "manual", false); continue; }
    if (known(blk.subjectTitle)) { settle(blk, blk.subjectTitle, "title", false); continue; }

    var data = cache[blk.sheetName];
    if (!data) { blk.subjectFrom = ""; continue; }

    var tags = blockCategoryTags(blk, data), tagSub = "";
    for (var t = 0; t < tags.length && !tagSub; t++) tagSub = subjectFromCategoryTag(tags[t]);
    if (known(tagSub)) { settle(blk, tagSub, "tag", false); continue; }

    var w = weightedSubjectFromTEKs(blockTEKList(blk, data));
    blk.__tekGuess = w;                         // kept for rung 5's fallback
    if (w.decisive && known(w.subject)) { settle(blk, w.subject, "TEKs", true); continue; }
    blk.subject = "";                           // clear a Config subject we cannot honour
    blk.subjectFrom = "";
  }

  // -- rung 5: what does this instructor teach, on papers we are sure of? --
  var byTeacher = {};
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    if (blk.subjectGuess || !blk.subjectFrom || blk.instructorCol < 0) continue;
    var d1 = cache[blk.sheetName];
    if (!d1) continue;
    var seen = {};
    for (var r1 = DATA_START_ROW - 1; r1 < d1.length; r1++) {
      var who = cellStr((d1[r1] || [])[blk.instructorCol]);
      if (!who || who === "-" || seen[who]) continue;
      seen[who] = true;
      (byTeacher[who] = byTeacher[who] || {})[blk.subject] = true;
    }
  }
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    if (blk.subjectFrom) continue;
    var d2 = cache[blk.sheetName];
    if (!d2 || blk.instructorCol < 0) continue;
    var subs = {}, n = 0, seen2 = {};
    for (var r2 = DATA_START_ROW - 1; r2 < d2.length; r2++) {
      var who2 = cellStr((d2[r2] || [])[blk.instructorCol]);
      if (!who2 || who2 === "-" || seen2[who2]) continue;
      seen2[who2] = true;
      for (var sub in (byTeacher[who2] || {})) { if (!subs[sub]) { subs[sub] = true; n++; } }
    }
    // Only when EVERY teacher on the paper is a one-subject teacher and they
    // all teach the same one. Two subjects between them says nothing.
    if (n === 1) { for (var only in subs) settle(blk, only, "teacher", true); }
  }

  // -- rung 6: the rest of the tab, where nothing on it disagrees ----------
  var byTab = {};
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    if (!blk.subjectFrom) continue;
    (byTab[blk.sheetName] = byTab[blk.sheetName] || {})[blk.subject] = true;
  }
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    if (blk.subjectFrom) continue;
    var tabSubs = byTab[blk.sheetName] || {}, keys = [];
    for (var ts in tabSubs) keys.push(ts);
    if (keys.length === 1) settle(blk, keys[0], "tab", true);
  }

  // -- rung 7: nothing answered -------------------------------------------
  for (i = 0; i < live.length; i++) {
    blk = live[i];
    if (!blk.subjectFrom) {
      blk.subject = "";
      blk.subjectFrom = "unknown";
      blk.subjectGuess = true;
      blk.subjectUnresolved = true;
      unresolved++;
      // Last resort for the Config's own suggestion: the indecisive tally.
      // Offered as a starting point in the dropdown, never applied.
      blk.subjectSuggest = (blk.__tekGuess && blk.__tekGuess.subject) || "";
    }
    SUBJECT_RESOLUTION.push({
      testName: blk.testName, sheetName: blk.sheetName,
      subject: blk.subject, from: blk.subjectFrom,
      guess: !!blk.subjectGuess, suggest: blk.subjectSuggest || ""
    });
  }
  return unresolved;
}

function parseQuestions(block, data, tekMap, subjectTEKMaps) {
  var questions = [];
  var arRow = String(data[1] ? data[1][block.startCol] : "").trim().toLowerCase() === "all responses" ? 1 : 2;
  var qNumRow = arRow + 1, gradingRow = arRow + 2, mpRow = arRow + 3, tekRow = arRow + 4;
  var dualRow = hasDualCodeRow(block, data, arRow);

  for (var c = block.questionStartCol; c < block.summaryStartCol; c++) {
    var numStr = cellStr(data[qNumRow] ? data[qNumRow][c] : "");
    if (!numStr || isNaN(Number(numStr))) continue;

    var tekRaw = cellStr(data[tekRow] ? data[tekRow][c] : "");
    var tek    = normalizeTEK(tekRaw);
    // DUAL CODING. A question can assess two standards, and both are real: a
    // pupil who missed it missed both, so it counts FULLY under each in the TEK
    // table and appears on both reteach lists. The consequence, stated because
    // it looks like a bug otherwise: points summed across TEKs then exceed the
    // paper's own total. That is correct for standards-based reporting.
    var tek2Raw = dualRow ? cellStr(data[tekRow + 1] ? data[tekRow + 1][c] : "") : "";
    var tek2    = normalizeTEK(tek2Raw);
    if (tek2 === tek) tek2 = "";                    // coded twice with one code

    // NO FALLBACK TO THE FLAT MAP. It used to read `else tekInfo = tekMap[tek]`
    // whenever the subject was unresolved, and buildAllViews resolved subjects
    // AFTER this ran, so that branch fired routinely rather than rarely.
    // buildTEKMap() is flat and last-write-wins across a registration order of
    // Math, ELA, Science, History -- 128 codes are owned by more than one
    // subject (95 by two, 30 by three, 3 by four), so History quietly took the
    // shared ones. Measured: a paper titled "May 2026 Unit Assessment, Grade 8"
    // rendered its TEKs as "Colonization" and "American Revolution".
    //
    // Now the subject is resolved before this runs (resolveBlockSubjects), and
    // if it still cannot be resolved the question carries NO reporting category
    // and raises subjectConflict -- the canary CLAUDE.md has always named and
    // which, until 2026-09-22, existed only in prose. Wrong and confident is
    // worse than blank and flagged.
    var subjMap = block.subject ? subjectTEKMaps[block.subject] : undefined;
    var tekInfo, subjectConflict = false;
    if (!tek)         tekInfo = undefined;
    else if (subjMap) tekInfo = subjMap[tek];
    else            { tekInfo = undefined; subjectConflict = true; }

    var grading = cellStr(data[gradingRow] ? data[gradingRow][c] : "");
    var maxPts  = gradingMaxPts(grading);

    var strand    = tekInfo ? tekInfo.strand    : "";
    var gradeNum  = tekInfo ? tekInfo.gradeNum  : 0;
    var gradeBand = tekInfo ? tekInfo.gradeBand : "";

    // A Math code the table has never seen still files correctly, because the
    // strand is derivable from the code itself. 34 Math TEKs that appear on
    // real papers are missing from TEK_DATA -- 5.3.L, 5.4.F and 5.4.H show up
    // ten times each -- and every one of them was landing in "Other Standards".
    // This also covers Algebra 1, which TEK_DATA doesn't carry at all.
    if (!strand && tek && block.subject === "Math" && USE_DERIVED_MATH_STRANDS) {
      strand = strandForTEK(tek);
      if (strand) {
        gradeNum  = gradeNumFromTEK(tek);
        gradeBand = gradeBandFromTEK(tek);
      }
    }
    // The same idea for ELA, from a different source. ELA_DATA carries no
    // roman-numeral sub-standards -- 4.11.D.iii, 5.11.D.vii and their kin are
    // real codes on real papers -- but ELA_TEK_RC_MAP does, and its reporting
    // category IS the ELA strand ("Reading" / "Writing"). Falling back to it
    // rescues those questions from "Other Standards", where they carried no
    // strand, no reporting category and no state figure.
    // A named strand from TEA's own Snapshot wording beats the coarse
    // Reading/Writing fallback below, which cannot be matched to a MAP goal.
    if (!strand && tek && block.subject === "ELA") {
      strand = elaStrandForTEK(tek);
      if (strand && !gradeNum) gradeNum = gradeNumFromTEK(tek);
    }
    if (!strand && tek && block.subject === "ELA") {
      var rcInfo = ELA_TEK_RC_MAP[tek];
      // A sub-standard the map has never seen rolls up to its parent letter:
      // 5.11.D.vii is part of 5.11.D and belongs in whatever strand that does.
      if (!rcInfo) {
        var upTo = elaParentTEK(tek);
        if (upTo) rcInfo = ELA_TEK_RC_MAP[upTo];
      }
      if (rcInfo && rcInfo.rcName) {
        strand = rcInfo.rcName;
        if (!gradeNum) gradeNum = gradeNumFromTEK(tek);
      }
    }
    if (!strand) strand = tek ? "Other Standards" : "";

    questions.push({
      colIndex: c, number: parseInt(numStr, 10),
      grading: grading, mp: cellStr(data[mpRow] ? data[mpRow][c] : ""),
      tek: tek, assessed: assessedTag(tekRaw), maxPts: maxPts,
      tek2: tek2, assessed2: tek2 ? assessedTag(tek2Raw) : "",
      strand: strand, gradeNum: gradeNum, gradeBand: gradeBand,
      subjectConflict: subjectConflict
    });
  }
  return questions;
}

/**
 * Reads every student row on one tab.
 *
 * Note on formulaData: Eduphoria encodes a correct answer as a formula ("=+A").
 * getValues() returns an error for those cells, so we read getFormulas() too and
 * prefer the formula text whenever it is present.
 */
function parseStudents(sheetName, data, format, blocks, blockQuestions, studentMap, formulaData,
                       teacherFilter, bgs) {
  var rowStep = format === "Benchmark" ? 2 : 1;
  var totalRows = data.length;
  var demo = detectDemoCols(data);

  var startRow = DATA_START_ROW - 1;
  while (startRow < totalRows) {
    var probe = cellStr(data[startRow][demo.name]);
    if (probe !== "" && probe.toLowerCase() !== "student name") break;
    startRow++;
  }

  var seenThisSheet = {}, dupIds = 0;

  for (var r = startRow; r < totalRows; r += rowStep) {
    var row = data[r];
    if (!row) continue;
    var name = cellStr(row[demo.name]);
    if (!name) continue;

    // Teacher filter, applied before any scoring work. Reading three cells to
    // decide whether to skip a pupil is far cheaper than parsing their answers
    // across every test block and discarding the result afterwards.
    if (teacherFilter) {
      // Keep the pupil if ANY block names a ticked teacher. This used to test
      // the FIRST block that carried an instructor -- the oldest paper -- and
      // "Current Instructor" on an old block is whoever had the pupil back
      // then. A teacher new to the campus this year had every pupil dropped
      // here and got no tab, while the Config census, built from the NEWEST
      // block, still listed them: 16 ticked, 12 tabs. The filter exists only
      // to save parsing time, so being generous costs nothing.
      var keep = false, sawAny = false;
      for (var tb = 0; tb < blocks.length && !keep; tb++) {
        if (blocks[tb].instructorCol < 0) continue;
        var tv = cellStr(row[blocks[tb].instructorCol]);
        if (tv && tv !== "-") { sawAny = true; if (teacherFilter[tv]) keep = true; }
      }
      if (!sawAny && teacherFilter[NO_TEACHER]) keep = true;
      if (!keep) continue;
    }

    var localId = cellStr(row[demo.id]);
    // Two rows in ONE export sharing a Local ID are two different pupils -- an
    // export has one row per pupil. Merging them let the second row's scores
    // overwrite the first's for every block. Cross-SHEET joining on Local ID is
    // untouched; only a repeat within this tab is split apart.
    var baseKey = localId || name;
    var seenN   = seenThisSheet[baseKey] || 0;
    seenThisSheet[baseKey] = seenN + 1;
    var key = seenN === 0 ? baseKey : baseKey + "#" + seenN;
    if (seenN > 0) dupIds++;
    if (!studentMap[key]) {
      studentMap[key] = {
        // The SPLIT key, not just the Local ID. Two rows on one tab sharing a
        // Local ID are two different pupils and become "id" and "id#1" -- but
        // that suffix used to live only in studentMap's key, never on the
        // record, so every downstream join keyed on localId collapsed them
        // back together. Carrying it here is what lets MAP attachment and the
        // held-out fold tell them apart.
        idKey: key,
        localId: localId, name: name,
        sped:      demo.sped      >= 0 ? cellStr(row[demo.sped])      : "",
        econDis:   demo.econDis   >= 0 ? cellStr(row[demo.econDis])   : "",
        eb:        demo.eb        >= 0 ? cellStr(row[demo.eb])        : "",
        ethnicity: demo.ethnicity >= 0 ? cellStr(row[demo.ethnicity]) : "",
        // Every OTHER student group the export happens to carry, by registry
        // key. Absent columns leave no key, which is how the campus tab tells
        // "nobody in this group" apart from "we never pulled that column".
        groups: readDemoGroups(demo, row),
        testScores: {}
      };
    }
    var student = studentMap[key];

    for (var bi = 0; bi < blocks.length; bi++) {
      var block = blocks[bi];
      if (!block.include || block.order === 0) continue;
      var questions = blockQuestions[block.testName] || [];

      // STAAR marks a not-taken test with "-" in every answer cell
      var tookTest = true;
      if (format === "STAAR") {
        var allDash = true;
        for (var qd = 0; qd < questions.length && allDash; qd++) {
          var dv = cellStr(row[questions[qd].colIndex]);
          if (dv !== "-" && dv !== "") allDash = false;
        }
        if (allDash && questions.length > 0) tookTest = false;
      }

      var scores = [], maxPtsActual = [], ambiguousIdx = [], choices = [];
      var formulaRow = formulaData ? formulaData[r] : null;
      for (var qi = 0; qi < questions.length; qi++) {
        var col = questions[qi].colIndex;
        // Eduphoria writes a correct answer as a formula ("=+A"); a wrong answer
        // and a partial-credit score are plain values. Read the formula text when
        // there is one, otherwise the value -- and never with `|| ""`, which would
        // swallow a legitimate score of 0.
        var rawVal = row[col];
        var fv = formulaRow ? cellStr(formulaRow[col]) : "";
        var v;
        if (typeof rawVal === "number") {
          // Partial-credit items are stored as "=+1" / "=+2", which is just unary
          // plus -- the computed value IS the score, so it must win over the text.
          v = String(rawVal);
        } else {
          v = fv !== "" ? fv : cellStr(rawVal);
        }
        // Sparse: only the columns whose fill can change a score were read.
        var bgCol = (bgs && bgs.byCol) ? bgs.byCol[col] : null;
        // `col`, NOT questionStartCol + qi. parseQuestions skips any column in
        // the span whose question-number cell is blank, so the two expressions
        // part company on the first such column and every fill after it is read
        // one column to the left -- landing on a real green or red belonging to
        // a neighbouring item. Silent, and it looks like clean output. True of
        // no block in today's export, which is why it was invisible.
        var s = scoreCell(v, questions[qi].maxPts,
                          bgCol ? bgCol[r] : null,
                          questions[qi].grading);
        scores.push(s.earned);
        choices.push(s.choice || "");
        maxPtsActual.push(s.possible > 0 ? s.possible : questions[qi].maxPts);
        if (s.ambiguous) ambiguousIdx.push(qi);
      }
      // Technology-enhanced items report their own point total -- take the max seen
      for (var qm = 0; qm < questions.length; qm++) {
        if (maxPtsActual[qm] > questions[qm].maxPts) questions[qm].maxPts = maxPtsActual[qm];
      }

      var arRow = cellStr(data[1][block.startCol]).toLowerCase() === "all responses" ? 1 : 2;
      // choices[] parallels scores[]: "" for anything that is not a single
      // multiple-choice letter (griddables, technology-enhanced, unattempted).
      var rawScore = 0, scaleScore = 0, pctScore = 0;
      // Whether the export CARRIES a raw score, which is not the same question
      // as whether this pupil scored zero. Midlo Headers 2.0 drops the column,
      // and conflating the two excluded every pupil from growth.
      var hasRawScore = block.rawScoreCol >= 0;
      var scoreCode = "", stateId = "", snapSchool = "", snapDist = "";
      var prevScale = "", prevGrade = "", prevProgress = "";
      var approaches = "", meets = "", masters = "", dateTaken = "";
      // A local Eduphoria benchmark has no Approaches/Meets/Masters columns.
      // masteryLevel() answers "Below" to three blanks, which would report an
      // entire class as Below Approaches on a test that never had bands.
      var hasBands = false;
      var instructor = "", section = "", course = "", period = "";
      var endCol = bi + 1 < blocks.length ? blocks[bi + 1].startCol : data[0].length;

      for (var sc = block.summaryStartCol; sc < endCol; sc++) {
        var label = cellStr(data[arRow][sc]).toLowerCase();
        var val   = cellStr(row[sc]);
        if (label === "raw score")   rawScore   = parseFloat(val) || 0;
        if (label === "scale score") scaleScore = parseFloat(val) || 0;
        if (label.indexOf("percent") !== -1) {
          var p = parseFloat(val.replace("%", "")) || 0;
          // exports write this either as 64.71 or as the fraction 0.6471
          pctScore = (p > 0 && p <= 1 && val.indexOf("%") === -1) ? p * 100 : p;
        }
        // THREE trailer columns contain the word "approaches":
        //   "Approaches Grade Level (TX)"                  <- the real flag
        //   "Approaches Low"                               <- band split, arrives "No"
        //   "Passing Standard for Approaches Grade Level"  <- arrives "N/A"
        // The loop runs left to right, so a loose match sets the real flag and
        // then two later columns wipe it. Every pupil who had reached Approaches
        // but not Meets was being reported as Below Approaches, in class totals,
        // Mastery_Flow, Campus_Summary, Equity_Trend and the trajectory alike.
        // The earlier guard only excluded "high", which this export never says.
        if (isBandLabel(label, "approaches")) {
          hasBands = true;
          approaches = val.toLowerCase() === "yes" ? "Yes" : "";
        }
        if (isBandLabel(label, "meets")) {
          hasBands = true;
          meets = val.toLowerCase() === "yes" ? "Yes" : "";
        }
        if (isBandLabel(label, "masters")) {
          hasBands = true;
          masters = val.toLowerCase() === "yes" ? "Yes" : "";
        }
        if (label === "date taken") dateTaken = (val !== "-") ? val : "";
        if (label === "score code") scoreCode = val;
        if (label.indexOf("unique student id") !== -1) stateId = val;
        if (label.indexOf("school snapshot") === 0)   snapSchool = val;
        if (label.indexOf("district snapshot") === 0) snapDist   = val;
        if (label.indexOf("prev year scale score") === 0)    prevScale    = val;
        if (label.indexOf("prev year tested grade") === 0)   prevGrade    = val;
        if (label.indexOf("prev year staar progress") === 0) prevProgress = val;

        // Who has this pupil NOW, and in which class. These describe the
        // student's present placement, not who taught the tested year -- a
        // Grade 7 result sits beside a Grade 8 course. Right for deciding who
        // reteaches; wrong for crediting growth. See DECISIONS.md.
        if (label === "current instructor") instructor = (val !== "-") ? val : "";
        if (label === "current section")    section    = (val !== "-") ? val : "";
        if (label === "current course")     course     = (val !== "-") ? val : "";
        if (label === "current period")     period     = (val !== "-") ? val : "";
      }

      // Older exports carry Course + Period instead of a single Section.
      if (!section) {
        section = course && period ? (course + " - " + period) : (course || period);
      }

      // -- Reconcile against Eduphoria's own Raw Score --------------------
      // A multi-select cell like "+A,B" cannot say whether the student got the
      // item fully or partly right -- the "+" only means "partly or fully".
      // Eduphoria already resolved it when it computed Raw Score, so when our
      // total falls short we hand the difference to those ambiguous cells.
      // Our own total BEFORE any reconciliation. Kept so Data_Check can compare
      // it against Eduphoria's Raw Score as a genuinely independent figure --
      // after reconciliation the two are forced to agree on ambiguous items, so
      // comparing the post-adjustment total would be checking our own homework.
      var preRecon = 0;
      for (var pc = 0; pc < scores.length; pc++) preRecon += scores[pc] || 0;

      if (tookTest && rawScore > 0 && ambiguousIdx.length > 0) {
        var computed = preRecon;
        var diff = rawScore - computed;
        for (var ai = 0; ai < ambiguousIdx.length && diff > 0; ai++) {
          var idx  = ambiguousIdx[ai];
          var room = (maxPtsActual[idx] || 1) - scores[idx];
          if (room <= 0) continue;
          var give = Math.min(room, diff);
          scores[idx] += give;
          diff -= give;
        }
      }

      student.testScores[String(block.order) + "|" + block.sheetName + "|" + block.testName] = {
        sheetName: sheetName, testName: block.testName, order: block.order,
        language: block.language, rawScore: rawScore, scaleScore: scaleScore,
        pctScore: pctScore, approaches: approaches, meets: meets, masters: masters,
        dateTaken: dateTaken, scores: scores, choices: choices,
        questions: questions, tookTest: tookTest,
        hasBands: hasBands, hasRawScore: hasRawScore,
        scoreCode: scoreCode, stateId: stateId,
        snapSchool: snapSchool, snapDist: snapDist,
        prevScale: prevScale, prevGrade: prevGrade, prevProgress: prevProgress,
        instructor: instructor, section: section,
        period: period, course: course,
        preRecon: preRecon, ambiguousCount: ambiguousIdx.length
      };

      // Placement is recorded PER SUBJECT as well as overall.
      //
      // A pupil has a maths teacher AND an English teacher, and they are not
      // the same person. Keeping one instructor per pupil meant that with two
      // subjects loaded the newer paper won and the pupil was filed under one
      // teacher for both -- so an English teacher's period came out half empty,
      // strangers appeared in it, and the group was handed a paper nobody in it
      // had sat. Subject is the missing dimension.
      //
      // A GUESSED SUBJECT MUST NOT OUTRANK A SETTLED ONE, whatever the order, and a paper that
      // names no teacher cannot claim the slot. Teacher, section and period move TOGETHER: as
      // three separate `if`s, a newer paper naming a teacher but no period installed the new
      // teacher over the old period -- a class that does not exist. An empty slot takes anyone;
      // a settled subject beats a guessed one; within the same confidence the newer paper wins.
      // Ported from the master 2026-10-06.
      if (block.subject) {
        if (!student.placeBySubject) student.placeBySubject = {};
        var pbs = student.placeBySubject[block.subject];
        if (!pbs) { pbs = student.placeBySubject[block.subject] = { order: -1, guess: true }; }
        var thisGuess = !!block.subjectGuess;
        var haveIns  = !!pbs.instructor;
        var thisIns  = !!instructor;
        var better = (!haveIns && thisIns)                            // empty slot: anyone
                  || (thisIns && pbs.guess && !thisGuess)             // settled beats guessed
                  || (thisIns && pbs.guess === thisGuess && block.order >= pbs.order);
        if (better) {
          pbs.order      = block.order;
          pbs.guess      = thisGuess;
          pbs.instructor = instructor;
          pbs.section    = section;
          pbs.period     = period;
        }
      }

      // Promote to the student, taking the value from the MOST RECENT paper.
      //
      // These columns are labelled "Current", but they do not all agree: one
      // pupil in the sample carries "Math 6 Advanced - Period 5" on one block,
      // "Math 6 - Period 7" on another and "Math 8 - Period 5" on a third. So
      // there is no single "current" value to read -- the newest paper is the
      // best proxy for where the pupil sits today, and picking it consistently
      // matters more than which rule we pick, because every view has to agree.
      if (instructor && (student.__instrOrder === undefined || block.order >= student.__instrOrder)) {
        student.instructor  = instructor;
        student.__instrOrder = block.order;
      }
      if (section && (student.__secOrder === undefined || block.order >= student.__secOrder)) {
        student.section  = section;
        student.__secOrder = block.order;
      }
      // Period is kept separately from section because they are not the same
      // thing: a teacher can hold several sections in one class period, and it
      // is the period they actually stand in front of.
      if (period && (student.__perOrder === undefined || block.order >= student.__perOrder)) {
        student.period  = period;
        student.__perOrder = block.order;
      }
    }
  }

  if (dupIds > 0) {
    console.log("parseStudents: " + sheetName + " \u2014 " + dupIds +
      " row(s) repeated a Local ID already used on this tab and were kept separate.");
  }
}

function buildMergedTests(allBlocks) {
  var orderMap = {};
  for (var bi = 0; bi < allBlocks.length; bi++) {
    var b = allBlocks[bi];
    if (!b.include || b.order === 0) continue;
    if (!orderMap[b.order]) orderMap[b.order] = [];
    orderMap[b.order].push(b);
  }
  var orderNums = Object.keys(orderMap).map(function (k) { return parseInt(k, 10); });
  orderNums.sort(function (a, b) { return a - b; });

  var merged = [];
  for (var oi = 0; oi < orderNums.length; oi++) {
    var blocks = orderMap[orderNums[oi]];
    // Deduplicate: the same paper sitting on three class tabs is three blocks
    // with one name, and joining them blindly gave "Grade 7 + Grade 7 + Grade 7".
    // Genuinely different papers combined by hand still show both names.
    var names = [], seenName = {};
    for (var ni = 0; ni < blocks.length; ni++) {
      var nm = blocks[ni].testName;
      if (!seenName[nm]) { seenName[nm] = true; names.push(nm); }
    }
    var label = names.join(" + ");

    var date = blocks[0].autoDate;
    for (var di = 1; di < blocks.length; di++) {
      if (blocks[di].autoDate && blocks[di].autoDate < date) date = blocks[di].autoDate;
    }
    var anyBuildViews = false;
    for (var vi = 0; vi < blocks.length; vi++) {
      if (blocks[vi].buildViews) { anyBuildViews = true; break; }
    }
    // State percentages describe STAAR items. A local benchmark or CBA asks
    // different questions about the same TEK, so comparing it with a STAAR
    // state figure is not a gap -- it is two different tests. Views fall back
    // to "All others" for anything that is not a STAAR paper.
    var isSTAAR = true;                           // public build: every paper is a STAAR paper
    // The type comes off the blocks, not the label, so a Config override is
    // honoured. Blocks combined under one Order are one paper; if they disagree
    // the STAAR reading wins, because a STAAR form merged with anything is
    // still the STAAR that counts for growth.
    var mType = "";
    for (var ty = 0; ty < blocks.length; ty++) {
      var bt = blocks[ty].testType || detectTestType(blocks[ty].testName);
      if (bt === "STAAR") { mType = "STAAR"; break; }
      if (!mType) mType = bt;
    }
    merged.push({
      order: orderNums[oi], label: label, date: date, blocks: blocks,
      questions: [], subject: blocks[0].subject || "", buildViews: anyBuildViews,
      isSTAAR: isSTAAR, testType: mType || (isSTAAR ? "STAAR" : "Benchmark")
    });
  }
  return merged;
}


// === PART 11: SHARED VIEW HELPERS ======================================

function shortEB(eb) {
  if (!eb) return "";
  var lower = String(eb).toLowerCase();
  if (lower.indexOf("currently") !== -1) return "EB";
  if (lower.indexOf("non") !== -1) return "Non-EB";
  return String(eb).split(" ")[0];
}


function priorityLabelEx(classPct, statePct) {
  if (statePct !== null && statePct !== undefined) {
    var delta = Math.round(classPct * 100) - statePct;
    if (delta >= 15)  return { label: "Commend & Extend" };
    if (delta >= 6)   return { label: "Solid Mastery" };
    if (delta >= -5)  return { label: "The Bubble (Monitor)" };
    if (delta >= -14) return { label: "Strategic Reteach" };
    return { label: "URGENT RETEACH" };
  }
  if (classPct < 0.50) return { label: "Urgent re-teach (no state avg)" };
  if (classPct < 0.70) return { label: "Re-teach needed (no state avg)" };
  if (classPct < 0.85) return { label: "Review / reinforce (no state avg)" };
  return { label: "Strong (no state avg)" };
}


function calcAdjMaxPtsEx(qs, exclNums) {
  var adj = 0;
  for (var qi = 0; qi < qs.length; qi++) {
    if (exclNums.indexOf(qs[qi].number) === -1) adj += qs[qi].maxPts;
  }
  return adj;
}


function yearFromDate(dateStr) {
  if (!dateStr) return 0;
  // A date-formatted cell comes back from getValues() as a Date, not a string.
  if (dateStr instanceof Date) {
    var dy = dateStr.getFullYear();
    return isNaN(dy) ? 0 : dy;
  }
  var str = String(dateStr).trim();
  var parts = str.split("/");
  if (parts.length === 3) {
    var yr = parseInt(parts[2], 10);
    if (!isNaN(yr)) return yr < 100 ? 2000 + yr : yr;
  }
  // ISO ("2026-05-01"), or a year sitting anywhere in the text.
  var m = str.match(/(19|20)\d{2}/);
  return m ? parseInt(m[0], 10) : 0;
}

/** Shared lookup for the three state-average getters. field = "pct" | "q" | "year" */
function _stateTEKLookup(tek, subject, testYear, field, lang) {
  if (!tek) return null;
  for (var ri = 0; ri < subjectRegistry().length; ri++) {
    if (subject && subjectRegistry()[ri].subject !== subject) continue;

    // A Spanish-form pupil sat the SAME items as everyone else -- for Grade 5
    // Maths all 172 match one for one, same question numbers, same TEKs -- but
    // a different population sits that paper and scores lower on 99% of items
    // (mean 15 points at Grade 5). Ranking survives translation almost intact,
    // so the English figures put the right TEKs in the right order; it is the
    // SIZE of the gap that misleads. Prefer the Spanish figures when we hold
    // them, and fall back to English rather than showing nothing.
    var tables = [];
    if (lang === "Spanish" && subjectRegistry()[ri].stateTEKAvgES) {
      tables.push({ tbl: subjectRegistry()[ri].stateTEKAvgES, es: true });
    }
    tables.push({ tbl: subjectRegistry()[ri].stateTEKAvg, es: false });

    for (var tb = 0; tb < tables.length; tb++) {
      var entry = tables[tb].tbl[tek];
      if (entry === undefined) continue;
      if (field === "es") return tables[tb].es;

      if (typeof entry === "number") {
        if (field === "pct")  return entry;
        // A flat number is a MULTI-YEAR BLEND, not that year's state result.
        // Maths and ELA were both stored this way until 31 Aug 2026; both are
        // now year-keyed from the lead4ward PDFs, so this branch should no
        // longer fire for them. It stays because returning the test's own year
        // here would fabricate a match, making a blended figure read as if TEA
        // had published it for that paper.
        if (field === "year") return null;
        if (field === "src")  return STATE_SRC_BLEND;
        return null;
      }
      if (typeof entry !== "object") continue;

      var years = Object.keys(entry).map(function (k) { return parseInt(k, 10); })
                                    .filter(function (y) { return !isNaN(y); });
      if (years.length === 0) continue;
      var pick;
      if (testYear) {
        if (entry[testYear]) { pick = testYear; }
        else {
          // STAAR was redesigned for 2022-23 and the state mean fell about ten
          // points overnight. Falling back across that line reintroduces exactly
          // the bias the year-keyed table was built to remove -- a 2023 paper
          // judged against a 2022 figure looks ten points worse than it is. So
          // prefer a year on the same side of the redesign, and only cross when
          // there is genuinely nothing else. When it does cross, the "vs" column
          // shows the year it used, so it stays visible.
          var sameEra = [];
          for (var e = 0; e < years.length; e++) {
            if ((years[e] >= STAAR_REDESIGN_YEAR) === (testYear >= STAAR_REDESIGN_YEAR)) {
              sameEra.push(years[e]);
            }
          }
          var pool = sameEra.length ? sameEra : years;
          pick = pool[0];
          for (var i2 = 1; i2 < pool.length; i2++) {
            if (Math.abs(pool[i2] - testYear) < Math.abs(pick - testYear)) pick = pool[i2];
          }
        }
      } else {
        pick = Math.max.apply(null, years);
      }
      if (!entry[pick]) continue;
      if (field === "year") return pick;
      if (field === "src")  return String(pick);
      // A TEK tested by several items in one year has no single question number,
      // so `q` is absent by design. Return null, not undefined -- a view checking
      // `!== null` would otherwise print "Qundefined".
      var v = entry[pick][field];
      return (v === undefined) ? null : v;
    }
    return null;
  }
  return null;
}

/**
 * Where a state figure came from: a specific year ("2025") or the multi-year
 * blend. Anything shown to a teacher next to a state percentage should say
 * which, because the two mean very different things.
 */
var STATE_SRC_BLEND = "2015-25 avg";

/**
 * The year STAAR was redesigned. State percent correct dropped roughly ten
 * points across it, so figures either side are not measuring the same test.
 */
var STAAR_REDESIGN_YEAR = 2023;


/**
 * School Progress, Part A: Academic Growth -- the transition table.
 * Rows are the PRIOR year's band, columns the CURRENT year's, both in
 * ENHANCED_BANDS order. Values are the points TEA awards per assessment.
 *
 * Source: TEA Accountability Rating System Manual, Chapter 3, "Part A:
 * Academic Growth: Annual Growth Points (STAAR)".
 *
 * Read it and the pattern is plain: move up a band and you earn 1; stay put and
 * you earn 1/2, except at the bottom (staying Did Not Meet Low earns nothing)
 * and at the top (staying Meets or Masters earns a full point); go backwards
 * and you earn 0.
 */
var GROWTH_TABLE = [
  /* prior dnmL    */ [0,   1,   1,   1,   1, 1],
  /* prior dnmH    */ [0, 0.5,   1,   1,   1, 1],
  /* prior appL    */ [0,   0, 0.5,   1,   1, 1],
  /* prior appH    */ [0,   0,   0, 0.5,   1, 1],
  /* prior meets   */ [0,   0,   0,   0,   1, 1],
  /* prior masters */ [0,   0,   0,   0,   0, 1]
];

/** Points for one assessment, or null when either band is unknown. */
function growthPointsFor(priorBand, currentBand) {
  var pi = ENHANCED_BANDS.indexOf(priorBand);
  var ci = ENHANCED_BANDS.indexOf(currentBand);
  if (pi < 0 || ci < 0) return null;
  return GROWTH_TABLE[pi][ci];
}

/**
 * Accelerated Learning: was Did Not Meet last year, reached Approaches or above
 * this year. TEA counts these separately and weights them 0.25 on top of the
 * annual growth points.
 */
function isAcceleratedLearning(priorBand, currentBand) {
  if (priorBand !== "dnmL" && priorBand !== "dnmH") return false;
  return ENHANCED_BANDS.indexOf(currentBand) >= ENHANCED_BANDS.indexOf("appL");
}

/**
 * The cut-table grade label for a test -- "6", "A", "E1" -- taken from the TEK
 * codes on its own questions rather than from the title, because the title is
 * free text and the TEKs are not. Most common prefix wins.
 */
function cutGradeLabelFor(qs) {
  var tally = {}, best = "", bestN = 0;
  for (var i = 0; i < qs.length; i++) {
    var t = qs[i].tek;
    if (!t) continue;
    var pre = String(t).split(".")[0];
    if (!pre) continue;
    tally[pre] = (tally[pre] || 0) + 1;
    if (tally[pre] > bestN) { bestN = tally[pre]; best = pre; }
  }
  return best;
}

/**
 * Growth for one pupil between two papers.
 *
 * Returns { points, accelerated, prior, current, reason }. `points` is null
 * whenever TEA would not score the pupil, and `reason` says which rule stopped
 * it -- because "no prior test on file" and "earned zero" are the same number in
 * a total and completely different facts about a child. The pupils who cannot
 * be scored are the ones moving into the district, so they must stay nameable.
 *
 * The rules are TEA's, from Chapter 3:
 *   - consecutive years, prior immediately before current
 *   - the grade must INCREASE; the same grade twice is not evaluated
 *   - a raw score of zero is excluded outright
 *   - the same subject either side
 *   - a language change between years is fine and still counts
 */
function growthBetween(prior, current) {
  var out = { points: null, accelerated: false, prior: "", current: "", reason: "" };
  if (!prior || !prior.tookTest) { out.reason = "no prior-year STAAR in this workbook"; return out; }
  if (!current || !current.tookTest) { out.reason = "no current-year result"; return out; }
  if (current.year !== prior.year + 1) {
    out.reason = "prior paper is " + prior.year + ", not the year before " + current.year;
    return out;
  }
  if (prior.subject !== current.subject) { out.reason = "different subject"; return out; }
  // Only exclude on a zero raw score when the export actually CARRIES one.
  // Midlo Headers 2.0 has no Raw Score column, so rawScore defaults to 0 for
  // everybody -- and this rule excluded every pupil in the district from growth
  // while reporting a reason that sounded like a fact about the child.
  if ((prior.hasRawScore && Number(prior.rawScore) === 0) ||
      (current.hasRawScore && Number(current.rawScore) === 0)) {
    out.reason = "raw score of zero is excluded from growth"; return out;
  }
  // TEA excludes score codes A (Absent) and O (Other) from growth. Eduphoria
  // can write the WORD instead of the letter -- the live export writes "Score"
  // for S -- and matching only the letter let a test marked "Other" into the
  // growth TEA excludes. Both forms now; a first-letter test would be too loose.
  var badCode = function (c) {
    c = String(c || "").trim().toUpperCase();
    return c === "A" || c === "O" || c.indexOf("ABSENT") === 0 || c.indexOf("OTHER") === 0;
  };
  if (badCode(prior.scoreCode) || badCode(current.scoreCode)) {
    out.reason = "score code " + (badCode(prior.scoreCode) ? prior.scoreCode : current.scoreCode)
               + " is excluded from growth by TEA";
    return out;
  }
  var pg = GRADE_ORDER.indexOf(prior.gradeLabel), cg = GRADE_ORDER.indexOf(current.gradeLabel);
  if (pg < 0 || cg < 0) { out.reason = "grade not recognised for a cut table"; return out; }
  if (cg <= pg) { out.reason = "same or lower grade level - not evaluated for growth"; return out; }

  // A missing band has two very different causes, and reporting both as "no cut
  // table" sent people looking for a TEA file when the real problem was a blank
  // scale score on the pupil's own record. Separate them.
  function bandFail(rec, which) {
    var sc = parseFloat(rec.scaleScore);
    if (!sc || isNaN(sc)) {
      return "no scale score on the " + which + " paper (" + rec.gradeLabel + " "
           + rec.subject + " " + rec.year + ")";
    }
    if (!hasEnhancedCuts(rec.gradeLabel, rec.subject, rec.language, rec.year)) {
      return "no TEA cut table loaded for " + rec.gradeLabel + " " + rec.subject
           + " " + rec.year;
    }
    return "scale score " + sc + " falls below every band for " + rec.gradeLabel
         + " " + rec.subject + " " + rec.year;
  }
  out.prior   = enhancedBandOf(prior.scaleScore,   prior.gradeLabel,   prior.subject,   prior.language,   prior.year);
  out.current = enhancedBandOf(current.scaleScore, current.gradeLabel, current.subject, current.language, current.year);
  if (!out.prior)   { out.reason = bandFail(prior,   "prior-year"); return out; }
  if (!out.current) { out.reason = bandFail(current, "current-year"); return out; }

  out.points = growthPointsFor(out.prior, out.current);
  out.accelerated = isAcceleratedLearning(out.prior, out.current);
  return out;
}

/** Grade labels in the order a pupil moves through them. */
var GRADE_ORDER = ["3", "4", "5", "6", "7", "8", "E1", "A", "E2"];

/** The six enhanced bands, weakest first. Order is load-bearing: the growth
 *  table is indexed by it, and banding walks it upwards. */
var ENHANCED_BANDS = ["dnmL", "dnmH", "appL", "appH", "meets", "masters"];

// Low/High leads the label. A teacher scanning a column of these is sorting on
// "which half of the band", so that word has to be the one their eye lands on
// first -- "Low Approaches" and "High Approaches" separate at a glance in a way
// that "Approaches Low" and "Approaches High" do not.
var ENHANCED_BAND_NAMES = {
  dnmL: "Low Did Not Meet",  dnmH: "High Did Not Meet",
  appL: "Low Approaches",    appH: "High Approaches",
  meets: "Meets",            masters: "Masters"
};

/** Short form for a grid cell. */
var ENHANCED_BAND_SHORT = {
  dnmL: "Low DNM", dnmH: "High DNM", appL: "Low App",
  appH: "High App", meets: "Meets", masters: "Masters"
};

// The band colour ramp lives with the palette at the top of the file, because
// it is the single source the palette itself is built from. See BAND_RAMP.

/**
 * Which cut table applies: "6|Math|EN".
 * Grade is the label TEA uses, not a number -- "A" for Algebra I, "E1"/"E2" for
 * the English EOCs -- because those have their own cut tables.
 */
function enhancedCutKey(gradeLabel, subject, language) {
  if (!gradeLabel || !subject) return "";
  return gradeLabel + "|" + subject + "|" + (language === "Spanish" ? "ES" : "EN");
}

/**
 * The enhanced band a scale score falls in, or "" when we cannot say.
 *
 * Banding is by LOWER BOUND, walking upwards, because TEA's published ranges
 * leave gaps between bands -- scale scores are discrete, so a value can sit in
 * no printed range while still clearly belonging to the band beneath it.
 *
 * Returns "" rather than guessing when there is no cut table for that year,
 * grade and subject. A missing band has to stay visible: it means no growth
 * score for that pupil, which is also what TEA does.
 */
function enhancedBandOf(scaleScore, gradeLabel, subject, language, year) {
  var sc = parseFloat(scaleScore);
  if (!sc || isNaN(sc)) return "";
  var byYear = ENHANCED_CUTS[String(year)];
  if (!byYear) return "";
  var row = byYear[enhancedCutKey(gradeLabel, subject, language)];
  // Spanish cuts exist only for grades 3-5 RLA; everyone else falls back to the
  // English table, which is the same paper for them.
  if (!row && language === "Spanish") row = byYear[enhancedCutKey(gradeLabel, subject, "")];
  if (!row) return "";
  var band = "";
  for (var i = 0; i < ENHANCED_BANDS.length; i++) {
    var b = ENHANCED_BANDS[i];
    if (row[b] !== undefined && sc >= row[b]) band = b;
  }
  return band;
}

/** Is there a cut table at all for this year/grade/subject? */
function hasEnhancedCuts(gradeLabel, subject, language, year) {
  var byYear = ENHANCED_CUTS[String(year)];
  if (!byYear) return false;
  return !!(byYear[enhancedCutKey(gradeLabel, subject, language)] ||
            byYear[enhancedCutKey(gradeLabel, subject, "")]);
}

/**
 * What this TEK was a grade below and becomes a grade above.
 * -> { prev: [codes], next: [codes] }; empty arrays when the chart shows none,
 * which is a real answer rather than missing data.
 */
/**
 * Does this workbook hold TEA's vertical alignment chart for a subject AT ALL?
 *
 * Its own function because two callers need the answer WITHOUT a TEK code in hand -- the column
 * heading that explains a blank column, and getVerticalAlignmentEx itself. Asking the latter with
 * an empty code returned haveChart:false for every subject, because it bails on a falsy code
 * before it ever looks at a chart, so the heading note fired on Math and ELA too.
 *
 * Measured 2026-09-27: Math 315 codes, ELA 376, Science 0, History 0. The zero ones hold a
 * vertAlign OBJECT with nothing in it, which is why the presence of the object proves nothing and
 * this counts keys.
 */
function haveVertAlignChart(subject) {
  var reg = subjectRegistry();
  for (var ri = 0; ri < reg.length; ri++) {
    if (subject && reg[ri].subject !== subject) continue;
    if (reg[ri].vertAlign) {
      for (var probe in reg[ri].vertAlign) return true;
    }
  }
  return false;
}

function getVerticalAlignmentEx(tek, subject) {
  var out = { prev: [], next: [], haveChart: haveVertAlignChart(subject) };
  if (!tek) return out;
  for (var ri = 0; ri < subjectRegistry().length; ri++) {
    var entry = subjectRegistry()[ri];
    if (subject && entry.subject !== subject) continue;
    var e = entry.vertAlign && entry.vertAlign[tek];
    if (!e) continue;
    if (e.p) out.prev = String(e.p).split(",");
    if (e.n) out.next = String(e.n).split(",");
    return out;
  }
  return out;
}

/**
 * "Last year, same students": this group against the standard this TEK grows
 * out of, on their own last STAAR.
 *
 * Deliberately NOT last year's pupils in this grade -- those are different
 * children, and the question a teacher is asking is whether THIS group moved.
 * The two standards are different questions and can differ in difficulty, so
 * the cell is a direction, not a like-for-like gap, and the hover note says so.
 *
 * "New TEK" means TEA's vertical alignment chart shows nothing earlier that
 * leads into this standard -- a real answer, not missing data.
 */
function lastYearTEKCell(prevRef, nowMatched, tek, subject, classPct) {
  var out = { text: "", note: "", bg: null, fg: null };
  // A BLANK CELL IS THE ONE THING THIS COLUMN MUST NOT DO.
  //
  // Austin, 2026-09-27: "I just was unsure of what you put on there since it was blank." He was
  // looking at a whole column of empty cells with the reason hidden in a hover note nobody
  // thinks to hover. Every state of this cell now READS, and the note is the detail rather than
  // the only answer.
  // THE CHART IS CHECKED FIRST, and the order matters.
  //
  // It used to test for a prior STAAR before testing whether we hold a chart at all. Science is
  // tested only in grades 5 and 8, so a Science table usually has no prior STAAR either -- and it
  // was handed the "no earlier STAAR" wording, whose note ends "Load that STAAR export into this
  // workbook and the column fills in." That is a promise the tool cannot keep: with no vertical
  // alignment chart for Science, loading every STAAR export ever written would change nothing.
  // The missing chart is the binding reason, so it is the one reported.
  var va = getVerticalAlignmentEx(tek, subject);
  if (!va.haveChart) {
    out.text = "no chart yet";
    out.fg   = "#555555";
    out.note = "This workbook holds no vertical alignment chart for "
             + (subject ? subject : "this subject") + ", so there is nothing to look up -- the "
             + "gap is in the tool, not in your class.\n\nMath and ELA have TEA's chart loaded. "
             + "Science and History do not yet, so this column cannot answer for them.";
    return out;
  }
  if (!prevRef || !prevRef.test) {
    out.text = "no earlier STAAR";
    out.fg   = "#555555";
    out.note = "None of the pupils in this class has an earlier STAAR in this subject in this "
             + "workbook, so there is nothing to compare with.\n\nGrade 3 is the first STAAR year, "
             + "so a grade-3 class always reads this. Otherwise the earlier papers are not loaded, or "
             + "the class is new to the campus. This column needs the same children on TWO papers: "
             + "the one this table is built from, and a STAAR from a previous year in the same "
             + "subject. Load that export into this workbook and the column fills in.";
    return out;
  }
  if (!va.prev.length) {
    out.text = "New TEK";
    out.fg   = "#555555";
    out.note = "TEA's vertical alignment chart shows no earlier standard leading into " + tek
             + ", so there is nothing these students sat last year to compare it with.";
    return out;
  }
  // "NOBODY HERE SAT IT" IS NOT "IT WAS NOT ON THE TEST", and the cell used to say the second
  // when it meant the first.
  //
  // prevYearStatsFor hands back { test: best, stats: {}, n: 0 } when none of the pupils in front
  // of you has a row on that paper -- a class of arrivals, or a paper from before they were at
  // this campus. An empty stats map then pooled to possible === 0 and the cell read
  // "7.9.B / not on that test", whose note says the standard "was not assessed on
  // May 2026 STAAR Mathematics, Grade 7". That is a claim about the STATE TEST, and it was
  // false: the standard was on it, these children were not.
  if (!prevRef.n) {
    out.text = "nobody here sat it";
    out.fg   = "#555555";
    out.note = "Not one pupil in this class has a result on " + prevRef.test.label
             + ", so there is nobody to compare.\n\nThat is the answer for a class of pupils new "
             + "to the campus, or for a paper sat before they got here. It says nothing about "
             + "whether the standard was on that test.";
    return out;
  }
  var earned = 0, possible = 0, codes = [];
  for (var i = 0; i < va.prev.length; i++) {
    var st = prevRef.stats[va.prev[i]];
    if (!st || !st.possible) continue;
    earned += st.earned; possible += st.possible; codes.push(va.prev[i]);
  }
  if (!possible) {
    out.text = va.prev.join(", ") + "\nnot on that test";
    out.fg   = "#555555";
    out.note = "The standard this one grows out of (" + va.prev.join(", ") + ") was not assessed on "
             + prevRef.test.label + ", so there is no figure to compare with.";
    return out;
  }
  var nowInfo = nowMatched ? nowMatched[tek] : null;
  if (!nowInfo || !nowInfo.possible) {
    out.text = codes.join(", ") + "\n" + Math.round(earned / possible * 100) + "% then";
    out.fg   = "#555555";
    out.note = "None of the students who sat " + prevRef.test.label + " has a score on " + tek
             + " here, so there is nothing to compare their " + Math.round(earned / possible * 100)
             + "% with.";
    return out;
  }
  var then  = Math.round(earned / possible * 100);
  var now   = Math.round(nowInfo.earned / nowInfo.possible * 100);
  var delta = now - then;
  out.text = codes.join(", ") + "  " + then + "% \u2192 " + now + "%\n"
           + (delta > 0 ? "+" : "") + delta + "%   (" + prevRef.n + ")";
  out.bg   = delta > 0 ? C.strandGood : (delta < 0 ? C.strandBad : C.strandMid);
  out.note = "The " + prevRef.n + " student(s) in this period who also sat " + prevRef.test.label
           + ": " + then + "% on " + codes.join(", ") + " then, " + now + "% on " + tek + " now, "
           + (delta > 0 ? "+" : "") + delta + " points.\n\n"
           + "Both figures are those same students, so anyone who arrived since is in neither. "
           + "The whole period is at " + classPct + "% on " + tek + ".\n\n"
           + "The two standards are different questions and can differ in difficulty, so read this "
           + "as a direction, not a like-for-like gap.";
  return out;
}

/** One cell's worth: "<- 4.3.F   -> 6.3.A", with a dash where there is none. */
function verticalAlignmentLabel(tek, subject) {
  var a = getVerticalAlignmentEx(tek, subject);
  if (!a.prev.length && !a.next.length) return "";
  return "<- " + (a.prev.join(", ") || "\u2013") +
         "   -> " + (a.next.join(", ") || "\u2013");
}

function getStateTEKSrcEx(tek, subject, testYear, lang) { return _stateTEKLookup(tek, subject, testYear, "src",  lang); }
function getStateTEKPctEx(tek, subject, testYear, lang)  { return _stateTEKLookup(tek, subject, testYear, "pct",  lang); }

/**
 * How many STAAR items this TEK carried in the year the figure came from.
 *
 * This is the "is it worth my time" number. A TEK ranked weakest is not
 * automatically the best use of a reteach: one worth four items on the real
 * test beats one worth a single item, however bad the percentage looks.
 * The count has been in the state tables all along and nothing read it.
 */
function getStateTEKNEx(tek, subject, testYear, lang)    { return _stateTEKLookup(tek, subject, testYear, "n",    lang); }

/** True when the figure returned came from the Spanish-form table. */
function getStateTEKIsESEx(tek, subject, testYear, lang) { return _stateTEKLookup(tek, subject, testYear, "es",   lang) === true; }


function primaryQuestionsEx(mt, blockQuestions) {
  if (mt.blocks.length > 0 && blockQuestions[mt.blocks[0].testName]) {
    return blockQuestions[mt.blocks[0].testName];
  }
  return mt.questions;
}

function getExclNumsEx(mt, allExcluded) {
  if (mt.blocks.length === 0) return [];
  var exclMap = allExcluded[mt.blocks[0].testName] || {};
  var nums = [];
  for (var k in exclMap) { if (exclMap[k]) nums.push(parseInt(k, 10)); }
  return nums;
}

/**
 * Flattened rows for a paper, computed ONCE per run.
 *
 * This is the most expensive function in the project and it was being redone
 * from scratch at fifteen call sites, several of them inside a loop over every
 * test. Each call walks every pupil, allocates an Object.keys array for each,
 * and aligns answers with a nested scan -- O(pupils x questions^2). At 600
 * pupils and 40 questions that is roughly a million comparisons PER CALL, and
 * a run with six tests and the trend views on made dozens of them.
 *
 * Keyed on the paper's order, which identifies a merged test uniquely. Safe
 * because allStudents, blockQuestions and allExcluded are all read once per run
 * and never change while views are being built. If that ever stops being true,
 * this cache has to be keyed on them too.
 *
 * The PLC keeps its own flatByOrder cache and stamps __grp onto these rows.
 * That is harmless: no other view reads __grp, and the PLC reassigns it rather
 * than reading it back.
 */
var FLAT_CACHE = {};

function resetFlatCache() { FLAT_CACHE = {}; }

/**
 * Where a pupil sits FOR ONE SUBJECT: teacher, section and period.
 *
 * Falls back to the pupil-level values when that subject was never seen, so a
 * single-subject run behaves exactly as it always did.
 */
/**
 * Where a pupil sits, for one subject.
 *
 * `strict` matters and is what the per-subject rosters must pass. Without it
 * the function falls back to the pupil-level instructor, which is taken from
 * the NEWEST paper of ANY subject -- so a pupil whose maths export carried no
 * Current Instructor inherited their ENGLISH teacher for maths, and that
 * teacher then acquired a maths group, a maths paper on their strip and a
 * maths TEK table. An English teacher seeing maths tests on the right is
 * exactly that. When a subject is named, only that subject's own placement
 * may answer; no placement means no teacher for that subject, which lands
 * the pupil under "(No instructor listed)" where it can be seen and fixed.
 *
 * The loose form stays for single-subject runs and for callers with no
 * subject in hand, where the rollup IS the answer.
 */
function placementFor(student, subject, strict) {
  var pbs = (student && student.placeBySubject) || null;
  var p = (pbs && subject) ? pbs[subject] : null;
  if (strict && subject) {
    if (p && p.instructor) return { instructor: p.instructor, section: p.section || "", period: p.period || "" };
    // Nothing recorded for THIS subject. Borrow from the pupil-level rollup
    // only when no subject has a placement at all -- an export with no
    // Current Instructor anywhere, where the rollup is equally uninformative
    // and equally harmless. If some OTHER subject does have one, refusing to
    // borrow is the entire point: that is how an English teacher was handed a
    // maths roster. The pupil lands under "(No instructor listed)" for this
    // subject, visible in Data_Check rather than silently misattributed.
    var anyOther = false;
    for (var k in (pbs || {})) { if (pbs[k] && pbs[k].instructor) { anyOther = true; break; } }
    if (anyOther) return { instructor: "", section: (p && p.section) || "", period: (p && p.period) || "" };
  }
  return {
    instructor: (p && p.instructor) || (student && student.instructor) || "",
    section:    (p && p.section)    || (student && student.section)    || "",
    period:     (p && p.period)     || (student && student.period)     || ""
  };
}

function flattenStudentsForTest(mt, allStudents, blockQuestions, allExcluded) {
  var ck = "o" + mt.order;
  if (FLAT_CACHE.hasOwnProperty(ck)) return FLAT_CACHE[ck];
  var out = flattenStudentsForTestUncached(mt, allStudents, blockQuestions, allExcluded);
  FLAT_CACHE[ck] = out;
  return out;
}

function flattenStudentsForTestUncached(mt, allStudents, blockQuestions, allExcluded) {
  var qs        = primaryQuestionsEx(mt, blockQuestions);
  var exclNums  = getExclNumsEx(mt, allExcluded);
  var adjMaxPts = calcAdjMaxPtsEx(qs, exclNums);
  var results   = [];

  for (var si = 0; si < allStudents.length; si++) {
    var student = allStudents[si];
    // A pupil can hold SEVERAL records under one order, because English and
    // Spanish forms of the same paper are merged onto a single order on
    // purpose. Whoever sat the Spanish form has an empty English record beside
    // their real one. Taking the first match and stopping meant that if the
    // empty record happened to come first the pupil was dropped from the whole
    // view -- silently, and only for Spanish-form pupils. Prefer a record they
    // actually sat.
    var testResult = null;
    var keys = Object.keys(student.testScores);
    for (var ki = 0; ki < keys.length; ki++) {
      var cand = student.testScores[keys[ki]];
      if (cand.order !== mt.order) continue;
      if (!testResult) testResult = cand;
      if (cand.tookTest) { testResult = cand; break; }
    }
    if (!testResult || !testResult.tookTest) continue;

    // Align this student's answers to the primary question list by question number
    // Choices are aligned alongside scores, by question NUMBER like everything
    // else here -- two forms of a paper can order their columns differently, and
    // a distractor tally built on column position would mix up the options.
    var aligned = [], alignedChoices = [];
    for (var qi = 0; qi < qs.length; qi++) {
      var found = false;
      for (var q2 = 0; q2 < testResult.questions.length; q2++) {
        if (testResult.questions[q2].number === qs[qi].number) {
          aligned.push(testResult.scores[q2]);
          alignedChoices.push(testResult.choices ? (testResult.choices[q2] || "") : "");
          found = true; break;
        }
      }
      if (!found) { aligned.push(0); alignedChoices.push(""); }
    }

    var adjScore = 0;
    for (var qa = 0; qa < qs.length; qa++) {
      if (exclNums.indexOf(qs[qa].number) === -1) adjScore += aligned[qa] || 0;
    }

    results.push({
      name: student.name, localId: student.localId,
      choices: alignedChoices,
      sped: student.sped, econDis: student.econDis,
      eb: student.eb, ethnicity: student.ethnicity,
      // Every other group column the export carried (504 and the rest, by registry key), so the
      // Support Groups table can read them off the same record it already uses.
      groups: student.groups || {},
      rawScore: testResult.rawScore, adjScore: adjScore,
      pctScore: testResult.pctScore,
      adjPctScore: adjMaxPts > 0 ? adjScore / adjMaxPts : 0,
      approaches: testResult.approaches, meets: testResult.meets,
      masters: testResult.masters, scores: aligned, tookTest: testResult.tookTest,
      // Which FORM this pupil sat. English and Spanish STAAR are the same
      // items in the same order, so the two are comparable question by
      // question -- but not against the same benchmark.
      language: testResult.language || "",
      // The pupil-level value, NOT this block's. Grouping has to be stable
      // across tests: using the per-block value meant a pupil sat in one
      // section on the Grade 5 flatten and another on the Grade 6 flatten, so a
      // section matched nobody and emptied itself without a word.
      // The paper's OWN Current Instructor wins over the pupil-level rollup.
      // The rollup is a single value across every subject; this record belongs
      // to one paper in one subject, and that is the teacher who taught it.
      instructor: testResult.instructor || student.instructor || "",
      section:    testResult.section    || student.section    || "",
      period:     testResult.period     || student.period     || ""
    });
  }
  return results;
}


/** Values-only tab writer: pads ragged rows, keeps real numbers numeric. */
function writeRows(sheet, rows) {
  if (!rows.length) return;
  var numCols = 0;
  for (var r = 0; r < rows.length; r++) if (rows[r].length > numCols) numCols = rows[r].length;
  if (numCols === 0) return;

  var padded = [], fmts = [];
  for (var p = 0; p < rows.length; p++) {
    var prow = [], frow = [];
    for (var c = 0; c < numCols; c++) {
      var v = c < rows[p].length ? rows[p][c] : "";
      prow.push(v);
      frow.push((typeof v === "number" && isFinite(v))
                ? ((v === Math.round(v)) ? "0" : "0.0")
                : "@");
    }
    padded.push(prow); fmts.push(frow);
  }
  var rng = sheet.getRange(1, 1, padded.length, numCols);
  rng.setNumberFormats(fmts);
  rng.setValues(padded);
}


// === PART 13: PHASE 2 ORCHESTRATOR =====================================

function buildAllViews(ss, scan, runMode, combineSheets, allExcluded, cfg) {
  var t0 = new Date().getTime();
  var subjectTEKMaps = buildSubjectTEKMaps();
  var blockQuestions = {};
  var teacherFilter  = readTeacherFilter(cfg);
  var viewsOn        = readViewToggles(cfg);
  var plcContent     = readPLCContent(cfg);
  var skipped        = [];
  for (var vk = 0; vk < VIEW_CATALOGUE.length; vk++) {
    if (!viewsOn[VIEW_CATALOGUE[vk].key]) skipped.push(VIEW_CATALOGUE[vk].label);
  }
  if (skipped.length) console.log("Views skipped by Config: " + skipped.join(" | "));
  if (teacherFilter) {
    var picked = [];
    for (var pk in teacherFilter) picked.push(pk);
    console.log("Teacher filter ON - " + picked.length + " teacher(s): " + picked.join(" | "));
  }

  // Questions for every included block, then the subject of any block whose
  // title did not name one, from the TEKs on the paper.
  for (var bi = 0; bi < scan.allBlocks.length; bi++) {
    var block = scan.allBlocks[bi];
    if (!block.include || block.order === 0) continue;
    var data = scan.cache[block.sheetName];
    if (!data) continue;
    blockQuestions[block.testName] = parseQuestions(block, data, scan.tekMap, subjectTEKMaps);
  }
  for (var bf = 0; bf < scan.allBlocks.length; bf++) {
    var blk = scan.allBlocks[bf];
    if (blk.subject) continue;
    var bqs = blockQuestions[blk.testName] || [];
    var tekList = [];
    for (var qf = 0; qf < bqs.length; qf++) tekList.push(bqs[qf].tek || "");
    var subjT = detectSubjectFromTEKList(tekList);
    if (subjT) blk.subject = subjT;
  }

  // Every pupil, parsed once.
  var studentMap = {};
  for (var si = 0; si < scan.sheetInfos.length; si++) {
    var info = scan.sheetInfos[si];
    if (!info.include) continue;
    var sdata = scan.cache[info.sheetName];
    if (!sdata) continue;
    var sheetBlocks = [];
    for (var sb = 0; sb < scan.allBlocks.length; sb++) {
      if (scan.allBlocks[sb].sheetName === info.sheetName) sheetBlocks.push(scan.allBlocks[sb]);
    }
    parseStudents(info.sheetName, sdata, info.format, sheetBlocks,
                  blockQuestions, studentMap, scan.formulaCache[info.sheetName],
                  teacherFilter, scan.bgCache ? scan.bgCache[info.sheetName] : null);
  }
  var allStudents = [];
  for (var k in studentMap) allStudents.push(studentMap[k]);
  console.log("Students parsed: " + allStudents.length);
  RUN_STATS.students = allStudents.length;

  // Merge the forms of each paper, attach questions, drop papers nobody sat.
  var mergedTests = buildMergedTests(scan.allBlocks);
  for (var mi = 0; mi < mergedTests.length; mi++) {
    var allMQ = [];
    for (var mb = 0; mb < mergedTests[mi].blocks.length; mb++) {
      var bq = blockQuestions[mergedTests[mi].blocks[mb].testName] || [];
      for (var qq = 0; qq < bq.length; qq++) allMQ.push(bq[qq]);
    }
    mergedTests[mi].questions = allMQ;
  }
  var keptTests = [];
  for (var mk = 0; mk < mergedTests.length; mk++) {
    var anyTook = false;
    for (var sk = 0; sk < allStudents.length && !anyTook; sk++) {
      var tkeys = Object.keys(allStudents[sk].testScores);
      for (var tk2 = 0; tk2 < tkeys.length; tk2++) {
        var res2 = allStudents[sk].testScores[tkeys[tk2]];
        if (res2.order === mergedTests[mk].order && res2.tookTest) { anyTook = true; break; }
      }
    }
    if (anyTook) keptTests.push(mergedTests[mk]);
  }
  if (keptTests.length !== mergedTests.length) {
    console.log("Skipped " + (mergedTests.length - keptTests.length) +
                " test(s) with no pupils in this run.");
  }
  mergedTests = keptTests;
  console.log("Merged tests: " + mergedTests.length);
  RUN_STATS.tests = mergedTests.length;
  if (mergedTests.length === 0) return;

  // The paper Data_Check reconciles against: the newest one anybody sat.
  var viewTargets = [];
  for (var fb = mergedTests.length - 1; fb >= 0; fb--) {
    if (flattenStudentsForTest(mergedTests[fb], allStudents, blockQuestions, allExcluded).length > 0) {
      viewTargets.push(mergedTests[fb]);
      break;
    }
  }
  if (viewTargets.length === 0) viewTargets.push(mergedTests[mergedTests.length - 1]);

  RUN_TRACE.at("Needed_Info");
  generateNeededInfo(ss, scan, mergedTests);

  if (viewsOn.growthmx !== false) {
    RUN_TRACE.at("Growth_Matrix");
    generateGrowthMatrix(ss, mergedTests, allStudents, blockQuestions);
  }

  var plcSectionTabs = 0, plcTicked = 0, plcNoTab = [];
  if (viewsOn.plcsection) {
    RUN_TRACE.at("PLC by section");
    plcSectionTabs = generatePLCBySection(ss, mergedTests, allStudents, blockQuestions,
                                          allExcluded, viewsOn.rostercheck !== false,
                                          false, plcContent);
    RUN_TRACE.at("PLC done", plcSectionTabs + " tab(s)");
    if (teacherFilter) {
      for (var tk in teacherFilter) {
        if (teacherFilter[tk]) { plcTicked++; if (!PLC_TABS_BUILT[tk]) plcNoTab.push(tk); }
      }
    }
  }
  PLC_TICKED_N = plcTicked;
  PLC_NO_TAB   = plcNoTab.length ? plcNoTabReasons(plcNoTab, allStudents, mergedTests, scan.teacherCensus) : [];
  for (var nr2 = 0; nr2 < PLC_NO_TAB.length; nr2++) {
    RUN_TRACE.note("No PLC tab for " + PLC_NO_TAB[nr2].name + ": " + PLC_NO_TAB[nr2].reason);
  }

  // Data_Check last, so it can report which ticked teachers got no tab and why.
  if (viewsOn.datacheck) {
    RUN_TRACE.at("Data_Check");
    generateDataCheck(ss, mergedTests, allStudents, blockQuestions, allExcluded, scan,
                      viewTargets[0]);
  }

  var dcSheet = ss.getSheetByName("Data_Check");
  if (dcSheet) ss.setActiveSheet(dcSheet);

  var secs = ((new Date().getTime() - t0) / 1000).toFixed(1);
  SpreadsheetApp.getUi().alert(
    "Analysis complete  (" + secs + "s)",
    "Students: " + allStudents.length + "\n" +
    "Tests:    " + mergedTests.length + "\n" +
    (plcSectionTabs ? "Per-teacher PLC tabs: " + plcSectionTabs
       + (plcTicked ? " of " + plcTicked + " ticked" : "") + "\n" : "") +
    (plcNoTab.length ? "NO TAB for " + plcNoTab.length + " ticked teacher(s): " + plcNoTab.join("; ")
       + "\n   Why, by name: Data_Check, section 13.\n" : "") +
    "\nCheck Data_Check before sharing anything, then open your PLC tabs.",
    SpreadsheetApp.getUi().ButtonSet.OK);
}


function mapTermRank(term) {
  if (term === "Fall")   return 1;
  if (term === "Winter") return 2;
  if (term === "Spring") return 3;
  return 0;
}


/**
 * Growth is a DIFFERENT KIND OF THING from a level, so it must not look like
 * one. The RIT cell beside it is a filled block of the STAAR band ramp; this
 * one is coloured TEXT on the ordinary row background. Filled = where they
 * are headed, coloured text = whether they are moving. Two grammars, no
 * chance of reading one as the other.
 *
 * The colour comes from NWEA's own four flags (Yes, Yes-star, No-star, No),
 * because only NWEA knows the standard error behind the star. A literal
 * asterisk-slash would close this comment, hence the spelling.
 * The TEXT is the number of RIT points
 * above or below their target, which is the thing a teacher can act on.
 */
function mapGrowthStyle(call, rowBg) {
  if (call === "met")          return { bg: rowBg, fg: "#1b5e20", bold: true };
  if (call === "met-close")    return { bg: rowBg, fg: "#558b2f", bold: false };
  if (call === "missed-close") return { bg: rowBg, fg: "#b26a00", bold: false };
  if (call === "missed")       return { bg: rowBg, fg: "#b71c1c", bold: true };
  return { bg: rowBg, fg: "#9e9e9e", bold: false };
}

/**
 * What the growth cell says: RIT points above or below NWEA's projection.
 * "+5" beats "Yes" -- it says how much, and the size of the number tells you
 * how close it was, which is what the asterisk was doing badly. Falls back to
 * NWEA's flag where the two growth numbers are missing, and to a dash on a
 * pupil's first term, when there is no target yet.
 */
function mapGrowthText(rec) {
  if (!rec) return "\u2013";
  var o = rec.observedGrowth, p = rec.projectedGrowth;
  if (o !== undefined && p !== undefined && o >= 0 && p >= 0) {
    var d = Math.round(o - p);
    return (d > 0 ? "+" : d < 0 ? "\u2212" : "\u00b1") + Math.abs(d);
  }
  return rec.metProjectedGrowth || "\u2013";
}
/** NWEA's projection text -> the level name the STAAR ramp colours from. */
function mapLevelName(proj) {
  var p = String(proj || "").toLowerCase();
  if (!p) return "";
  if (p.indexOf("master") !== -1)   return "Masters";
  if (p.indexOf("meets") !== -1)    return "Meets";
  if (p.indexOf("approach") !== -1) return "Approaches";
  if (p.indexOf("not meet") !== -1 || p.indexOf("did not") !== -1 || p.indexOf("below") !== -1) return "Below";
  return "";
}

function mapCheckpointYear(rec) {
  var y = yearFromDate(rec.dateTaken);
  if (!y) { var m = String(rec.title || rec.schoolYear || "").match(/(20\d\d)/); y = m ? parseInt(m[1], 10) : 0; }
  return y;
}
/**
 * A checkpoint is one COURSE in one term, not just one term.
 *
 * An 8th grade period is usually one course -- the advanced set sat Algebra 1,
 * everyone else sat Math 6+ -- but where a period holds both, their RITs are
 * from different tests and must not share a column. Splitting on course keeps
 * the common case at one column pair and only widens where it has to.
 */
function mapCheckpointKey(rec) {
  var y = mapCheckpointYear(rec);
  if (!y) return "";
  return (rec.course || rec.subject || "MAP") + "|" + (rec.term || "Term") + " " + y;
}
/** "Math 6+" -> "M6+", "Algebra 1" -> "Alg1": short enough for a 56px column. */
function mapCourseShort(course) {
  var c = String(course || "").trim();
  if (!c) return "MAP";
  if (/^algebra/i.test(c))  return "Alg" + (c.match(/\d/) ? c.match(/\d/)[0] : "");
  if (/^geometry/i.test(c)) return "Geo";
  if (/^science/i.test(c))  return "Sci";
  if (/^math/i.test(c))     return "M" + (c.match(/\d\+?/) ? c.match(/\d\+?/)[0] : "");
  if (/^reading/i.test(c))  return "R" + (c.match(/\d\+?/) ? c.match(/\d\+?/)[0] : "");
  if (/^language/i.test(c)) return "Lang";
  return c.length <= 5 ? c : c.substring(0, 5);
}
/**
 * The SCHOOL year a checkpoint belongs to, which is not its calendar year.
 *
 * Winter and Spring of 2025-26 are sat in January and April 2026, the same
 * calendar year as Fall of 2026-27. Sorting on the calendar year put this
 * autumn's test THIRD, between last year's autumn and last year's winter.
 * The title carries the school year outright ("Fall 2025-2026 NWEA Growth")
 * and that wins; otherwise a winter or spring test belongs to the year before
 * the one it was sat in.
 */
function mapSchoolYear(rec) {
  var m = String(rec.title || rec.schoolYear || "").match(/(20\d\d)\s*-\s*20\d\d/);
  if (m) return parseInt(m[1], 10);
  var y = mapCheckpointYear(rec);
  if (!y) return 0;
  return mapTermRank(rec.term) >= 2 ? y - 1 : y;
}
/**
 * Labelled by the year the pupil actually sat it: F'25, W'26, S'26, F'26.
 * The course is named only when a group holds more than one, so a period that
 * all sat the same test still reads "M MAP F'26".
 *
 * The subject tag is ALWAYS on, even though every tab is one subject now.
 * That is the point: it is a canary. An English tab showing "M MAP F'26" says
 * at a glance that the wrong data is being pulled, which is exactly the fault
 * we have chased twice.
 */
function mapCheckpointLabel(rec, showCourse) {
  var when = (rec.term || "?") + " '" + String(mapCheckpointYear(rec)).slice(2);
  var tag  = subjectTag(rec.subject);
  return (tag ? tag + " " : "") + (showCourse ? mapCourseShort(rec.course) : "MAP") + " " + when;
}
function mapCheckpointSort(rec)  { return String(mapSchoolYear(rec)) + mapTermRank(rec.term) + dateToSortKey(rec.dateTaken); }
/**
 * The MAP checkpoints a group's strip shows: one per term any pupil on the
 * roster sat in this subject, oldest first. Each becomes two columns.
 */
function mapCheckpointsFor(roster, subject) {
  var seen = {}, out = [], courses = {}, nCourses = 0;
  for (var i = 0; i < roster.length; i++) {
    var recs = roster[i].map || [];
    for (var r = 0; r < recs.length; r++) {
      var rec = recs[r];
      if (subject && rec.subject !== subject) continue;
      var key = mapCheckpointKey(rec);
      if (!key) continue;
      var cs = rec.course || rec.subject || "MAP";
      if (!courses[cs]) { courses[cs] = true; nCourses++; }
      if (seen[key]) continue;
      seen[key] = true;
      out.push({ key: key, course: cs, rec: rec, sort: mapCheckpointSort(rec), subject: subject });
    }
  }
  // Course first so each test's terms sit together, then time within a course.
  out.sort(function (a, b) {
    if (a.course !== b.course) return a.course < b.course ? -1 : 1;
    return a.sort < b.sort ? -1 : a.sort > b.sort ? 1 : 0;
  });
  for (var o = 0; o < out.length; o++) out[o].label = mapCheckpointLabel(out[o].rec, nCourses > 1);
  return out;
}
/**
 * The STAAR administration a MAP checkpoint is projecting TOWARDS.
 *
 * Fall 2026-2027 MAP projects the May 2027 STAAR -- the one not sat yet.
 * Naming the target year everywhere is the whole point: a projection read as
 * a result is the most expensive mistake this tab could invite.
 */
function mapProjectionYear(rec) {
  var sy = mapSchoolYear(rec);
  return sy ? sy + 1 : 0;
}

/** Six TEA bands collapsed to the four MAP can speak. */
var FOUR_BANDS = ["Masters", "Meets", "Approaches", "Did Not Meet"];
function fourBandOf(fine, coarse) {
  if (fine === "masters" || coarse === "Masters") return "Masters";
  if (fine === "meets"   || coarse === "Meets")   return "Meets";
  if (fine === "appL" || fine === "appH" || coarse === "Approaches") return "Approaches";
  if (fine === "dnmL" || fine === "dnmH" || coarse === "Below")      return "Did Not Meet";
  return "";
}
function fourBandRampKey(b) {
  return b === "Masters" ? "Masters" : b === "Meets" ? "Meets"
       : b === "Approaches" ? "Approaches" : b === "Did Not Meet" ? "Below" : "";
}

/** A pupil's six-band result on one paper, or "" if they did not sit it. */
function pupilBandOn(full, mt, blockQuestions) {
  var ks = Object.keys(full.testScores || {}), pick = null;
  for (var i = 0; i < ks.length; i++) {
    var r = full.testScores[ks[i]];
    if (r.order !== mt.order) continue;
    if (!pick) pick = r;
    if (r.tookTest) { pick = r; break; }
  }
  if (!pick || !pick.tookTest || pick.hasBands === false) return { fine: "", coarse: "" };
  var coarse = masteryLevel(pick.approaches, pick.meets, pick.masters);
  var fine = enhancedBandOf(pick.scaleScore,
               cutGradeLabelFor(primaryQuestionsEx(mt, blockQuestions)),
               mt.subject, pick.language, yearFromDate(mt.date));
  return { fine: fine, coarse: coarse };
}

/** The newest MAP record a pupil has in a subject, or null. */
function newestMAPFor(full, subject) {
  var recs = (full && full.map) || [], best = null;
  for (var i = 0; i < recs.length; i++) {
    var r = recs[i];
    if (subject && r.subject !== subject) continue;
    if (!best || mapCheckpointSort(r) > mapCheckpointSort(best)) best = r;
  }
  return best;
}

/**
 * HOW MAP'S GOAL AREAS LINE UP WITH WHAT WE GROUP STAAR BY, PER SUBJECT.
 *
 * One table so a new subject, or another district's test line-up, is a data
 * change and not a code change. Each entry says:
 *
 *   groupBy   "rc"     group the STAAR side by reporting category (TEK_RC_MAP)
 *             "strand" group it by TEK strand (the question's own strand)
 *   label     what to call that grouping in the heading
 *   alias     goal-key -> group-key, for wording drift where the two sides
 *             mean the same thing: "Describe & Graph" vs "Describing and
 *             Graphing". Used when one goal maps to exactly one group.
 *   goalTo    goal-key -> [group names], for a genuine one-to-many. Reading
 *             works this way: NWEA built their goals on TEKS strands, so one
 *             goal legitimately spans several of ours.
 *   note      the caveat printed under the block. Say what MAP cannot see.
 *
 * Why the two subjects differ. NWEA built the Texas MATHS goals on TEA's own
 * reporting categories, so those line up one to one. They built the READING
 * goals on the 2017 ELAR TEKS instead, and TEA reports STAAR reading in just
 * two categories, Reading and Writing. So reading is bridged through strand,
 * where the names genuinely correspond, and the block says outright that MAP
 * reading is silent on Composition -- roughly half the STAAR RLA test, and
 * its own MAP test (Growth: Language 2-12 TX) which is not being pulled.
 */
var MAP_GOAL_BRIDGE = {
  Math: {
    groupBy: "rc",
    label: "reporting category",
    note: "MAP's maths goal areas ARE TEA's reporting categories, under NWEA's own wording, "
        + "so these two columns measure the same thing twice.",
    alias: {
      "dataanalysis": "dataanalysisandpersonalfinancialliteracy",
      "numericalrepresentationsandprobability": "numericalrepresentationsandrelationships",
      "describegraphlinearfunctionsequationsinequalities": "describingandgraphinglinearfunctionsequationsandinequalities",
      "writesolvelinearfunctionsequationsinequalities": "writingandsolvinglinearfunctionsequationsandinequalities"
    }
  },
  ELA: {
    groupBy: "strand",
    label: "strand",
    note: "MAP builds its reading goals on the ELAR TEKS, not on TEA's reporting categories, so "
        + "these are matched by STRAND. Read one limit with them: all three MAP reading goals sit "
        + "inside the Reading half of STAAR RLA. MAP reading does not assess Composition, which is "
        + "about half the points on the test; that is a separate MAP test (Language 2-12) and it is "
        + "not in this workbook.",
    goalTo: {
      "foundationallanguageskillsvocabulary": ["Vocabulary", "Foundational Language"],
      "multiplegenres":                        ["Genres", "Literary Elements", "Comprehension", "Response Skills"],
      "authorspurposecraft":                   ["Author's Purpose"]
    }
  }
};

