/**
 * An ELA TEK's strand, from its grade and section.
 *
 * 214 of the 364 ELA codes that appear on real papers carry no strand in
 * ELA_TEK_DATA, and unlike Maths the code cannot be reasoned from: the ELAR
 * TEKS renumber between grade bands. Without this the MAP strand bridge
 * reached 20% of a paper and the rest fell back to the coarse "Reading" and
 * "Writing", which match no MAP goal at all. The table above is read from
 * TEA's own wording in the Snapshots, per grade.
 *
 * Returns "" for a code outside the table, which leaves the existing
 * Reading/Writing fallback exactly as it was.
 */
function elaStrandForTEK(tek) {
  if (typeof ELA_SECTION_STRAND === "undefined") return "";
  var m = String(tek || "").match(/^(\d+|E[12])\.(\d+)/);   // 7.5 and E1.5 alike
  if (!m) return "";
  return ELA_SECTION_STRAND[m[1] + "." + m[2]] || "";
}

/** Squash a goal or category name to a comparable key. */
function rcKey(name, subject) {
  var k = String(name || "").toLowerCase();
  k = k.replace(/^(mathematics|language arts|science|social studies|reading)\s*:\s*/, "");
  k = k.replace(/&/g, "").replace(/\band\b/g, "").replace(/[^a-z]/g, "");
  var cfg = subject ? MAP_GOAL_BRIDGE[subject] : null;
  if (cfg && cfg.alias && cfg.alias[k]) return cfg.alias[k];
  return k;
}

/**
 * group name -> goal key, for one subject. Built from the table above, so the
 * one-to-many entries are authored the readable way (goal -> groups) and
 * inverted here.
 */
function bridgeGroupKeyOf(subject, groupName) {
  var cfg = MAP_GOAL_BRIDGE[subject];
  if (!cfg) return "";
  if (cfg.goalTo) {
    for (var gk in cfg.goalTo) {
      var list = cfg.goalTo[gk];
      for (var i = 0; i < list.length; i++) {
        if (String(list[i]).toLowerCase() === String(groupName).toLowerCase()) return gk;
      }
    }
    return "";
  }
  return rcKey(groupName, subject);
}

/** What this subject groups the STAAR side by: "rc" or "strand". "" = not bridged. */
function bridgeGroupBy(subject) {
  var cfg = MAP_GOAL_BRIDGE[subject];
  return cfg ? cfg.groupBy : "";
}

/**
 * Tutoring groups, cut from MAP GOAL scores rather than from one overall RIT.
 *
 * This is the thing MAP can do that STAAR cannot do until May. A pupil is not
 * one number: they might sit at 228 in Geometry and 202 in Computations, and
 * for a small group those are two different pupils. So for each goal area the
 * period is sorted by its RIT IN THAT GOAL and cut into bands, because a band
 * is a group you can actually teach together -- you cannot run one lesson at
 * 202 and 235.
 *
 * Goals are listed WEAKEST CLASS AVERAGE FIRST, so the skill worth running
 * groups on is at the top.
 *
 * Bands are cut from THIS class, not from a national norm. A teacher pulling
 * four pupils wants their four lowest on that skill; whether those four are
 * nationally average is a different question, answered by the projection
 * block above. NWEA's own adjective rides along for each pupil so the norm is
 * still visible.
 */
function mapTutorBands(n) {
  if (n < 4) return 1;
  if (n < 9) return 2;
  if (n < 21) return 3;
  return 4;
}
var MAP_TUTOR_LABELS = {
  1: ["Whole group"],
  2: ["Needs it most", "Stronger half"],
  3: ["Needs it most", "Middle", "Strongest"],
  4: ["Needs it most", "Lower middle", "Upper middle", "Strongest"]
};

/**
 * One row per pupil in a goal area, sorted low to high, tagged with a band.
 * Returns [] when nobody in the group has a goal score for this subject.
 */
function mapTutorGroups(roster, subject) {
  var byGoal = {}, order = [];
  for (var i = 0; i < roster.length; i++) {
    var rec = newestMAPFor(roster[i], subject);
    if (!rec || !rec.goals) continue;
    for (var gq = 0; gq < rec.goals.length; gq++) {
      var go = rec.goals[gq];
      if (!go.name || !(go.rit > 0)) continue;
      if (!byGoal[go.name]) { byGoal[go.name] = { name: go.name, pupils: [], term: rec.term }; order.push(go.name); }
      byGoal[go.name].pupils.push({ name: roster[i].name, rit: go.rit, adj: go.adjective || "" });
    }
  }
  var out = [];
  for (var o = 0; o < order.length; o++) {
    var G = byGoal[order[o]];
    G.pupils.sort(function (a, b) { return a.rit - b.rit || (a.name < b.name ? -1 : 1); });
    var total = 0;
    for (var p = 0; p < G.pupils.length; p++) total += G.pupils[p].rit;
    G.avg = G.pupils.length ? Math.round(total / G.pupils.length) : 0;
    // Cut into bands of near-equal size, splitting on pupil count rather than
    // on RIT value: a teacher wants four groups of six, not one group of
    // nineteen and three of one.
    var nb = mapTutorBands(G.pupils.length), per = G.pupils.length / nb;
    G.bands = [];
    for (var b = 0; b < nb; b++) {
      var from = Math.round(b * per), to = Math.round((b + 1) * per);
      var slice = G.pupils.slice(from, to);
      if (slice.length === 0) continue;
      G.bands.push({ label: MAP_TUTOR_LABELS[nb][b], pupils: slice,
                     lo: slice[0].rit, hi: slice[slice.length - 1].rit });
    }
    out.push(G);
  }
  // Weakest class average first: the skill worth pulling groups on.
  out.sort(function (a, b) { return a.avg - b.avg; });
  return out;
}

var MAP_KEY_COLS = 3;   // swatch, label, meaning
/**
 * The key, drawn once per tab two columns to the right of the last tracker.
 *
 * A teacher should not have to be told twice what a colour means. Both
 * grammars are shown side by side: a filled block is a projected level, a
 * coloured number is movement against target.
 */
function drawMAPKey(g, row, col, anyMap) {
  var r = row;
  function line(c0, text, opts) { g.setAt(r, c0, text, opts); }
  g.setAt(r, col, "HOW TO READ THE TRACKER", { bg: "#37474f", fg: "#ffffff", bold: true, size: 10 });
  g.setAt(r, col + 1, "", { bg: "#37474f" });
  g.setAt(r, col + 2, "", { bg: "#37474f" });
  r++;
  g.setAt(r, col, "STAAR bands", { bg: C.sectionBg, bold: true, size: 9 });
  g.setAt(r, col + 1, "", { bg: C.sectionBg });
  g.setAt(r, col + 2, "a filled block = where they are headed", { bg: C.sectionBg, size: 9, fg: "#555555" });
  r++;
  var bands = [["Masters", "masters"], ["Meets", "meets"], ["High App", "appH"],
               ["Low App", "appL"], ["High DNM", "dnmH"], ["Low DNM", "dnmL"]];
  for (var b = 0; b < bands.length; b++) {
    g.setAt(r, col,     ENHANCED_BAND_SHORT[bands[b][1]] || bands[b][0],
            { bg: rampBg(bands[b][1], ""), fg: rampFg(bands[b][1], ""), bold: true, align: "center", size: 9 });
    g.setAt(r, col + 1, "", { bg: C.white });
    g.setAt(r, col + 2, b === 0 ? "STAAR band" : "", { bg: C.white, size: 9, fg: "#555555" });
    r++;
  }
  if (!anyMap) return r;
  r++;
  g.setAt(r, col, "MAP growth: vs target", { bg: C.sectionBg, bold: true, size: 9 });
  g.setAt(r, col + 1, "", { bg: C.sectionBg });
  g.setAt(r, col + 2, "a coloured NUMBER = whether they are moving", { bg: C.sectionBg, size: 9, fg: "#555555" });
  r++;
  var gk = [["met", "+5", "beat NWEA's growth target"],
            ["met-close", "+1", "met it, inside the margin (NWEA writes Yes*)"],
            ["missed-close", "\u22121", "just missed, inside the margin (No*)"],
            ["missed", "\u22124", "missed the target"],
            ["", "\u2013", "first term: no target yet, or no MAP"]];
  for (var k = 0; k < gk.length; k++) {
    var st = mapGrowthStyle(gk[k][0], C.white);
    g.setAt(r, col,     gk[k][1], { bg: st.bg, fg: st.fg, bold: st.bold, align: "center", size: 9 });
    g.setAt(r, col + 1, "", { bg: C.white });
    g.setAt(r, col + 2, gk[k][2], { bg: C.white, size: 9, fg: "#555555" });
    r++;
  }
  g.setAt(r, col, "RIT points above or below the growth NWEA projected for this pupil.",
          { bg: C.white, size: 9, fg: "#555555", wrap: true });
  return r;
}

/** yyyymmdd for a checkpoint: Date Taken when it parses, else mid-term of its school year. */
function mapCheckpointDateKey(rec) {
  var k = dateToSortKey(rec.dateTaken);
  if (/^\d{8}$/.test(k)) return k;
  var sy = mapSchoolYear(rec), term = rec.term || "";
  if (!sy) return "99999999";
  if (term === "Winter") return String(sy + 1) + "0115";
  if (term === "Spring") return String(sy + 1) + "0415";
  return String(sy) + "0915";
}

/**
 * The strip's columns in TIME order: STAAR papers and MAP checkpoints
 * interleaved by the date they were sat. May '25 STAAR, then Fall '25 MAP,
 * Winter '26, Spring '26, then May '26 STAAR, then Fall '26 -- the year as
 * the pupil lived it, not "all the STAAR, then all the MAP". Two courses in
 * one term share a date and so stay side by side. Returns { cols, width };
 * each col carries `at`, its offset from the first strip column.
 */
function stripColumnsFor(trajTests, mapCols) {
  // Subject first, THEN date. A teacher on both exports reads Maths as one
  // story and English as another; interleaving them by date alone reads as
  // one story that keeps changing subject. Within a subject, time order.
  var cols = [], i;
  for (i = 0; i < trajTests.length; i++) {
    cols.push({ kind: "staar", mt: trajTests[i], width: 1,
                sort: subjectStripRank(trajTests[i].subject || "") + "|"
                      + dateToSortKey(trajTests[i].date) + "0" });
  }
  for (i = 0; i < mapCols.length; i++) {
    cols.push({ kind: "map", cp: mapCols[i], width: 2,
                sort: subjectStripRank(mapCols[i].subject || mapCols[i].rec.subject || "") + "|"
                      + mapCheckpointDateKey(mapCols[i].rec) + "1" + mapCols[i].course });
  }
  cols.sort(function (a, b) { return a.sort < b.sort ? -1 : a.sort > b.sort ? 1 : 0; });
  var at = 0;
  for (i = 0; i < cols.length; i++) { cols[i].at = at; at += cols[i].width; }
  return { cols: cols, width: at };
}

/** This pupil's record for a checkpoint: same subject, term and year; the latest date if several. */
function mapRecordFor(stu, cp) {
  var recs = (stu && stu.map) || [], best = null;
  for (var r = 0; r < recs.length; r++) {
    var rec = recs[r];
    if (cp.subject && rec.subject !== cp.subject) continue;
    if (mapCheckpointKey(rec) !== cp.key) continue;   // key carries the course
    if (!best || dateToSortKey(rec.dateTaken) > dateToSortKey(best.dateTaken)) best = rec;
  }
  return best;
}


// === PART 29: VIEW -- PLC BY SECTION ====================================
// One tab per teacher. Each tab walks that teacher's class sections in turn and
// ranks the TEKs that section is weakest on.
//
// Why this exists: the campus PLC view answers "what did we all struggle with".
// A teacher planning Tuesday's warm-up needs "what does 3rd period struggle
// with, that 5th period does not" -- reteaching to everyone something only one
// period missed is the expensive mistake this is meant to stop. So every TEK row
// shows the period beside the teacher's other periods and beside all students.

/** "Math 8 [MATH 8] - Current Period: 6" -> 6, so periods list in order. */
function sectionSortKey(name) {
  var m = String(name).match(/(\d+)\s*$/);
  return m ? parseInt(m[1], 10) : 9999;
}

/** A tab name Sheets will accept, unique within `used`. */
function safeTabName(prefix, name, used) {
  var t = String(name || "Unassigned").replace(/[:\\\/\?\*\[\]]/g, " ")
                                      .replace(/\s+/g, " ").trim();
  var base = (prefix + t).substring(0, 95);
  var n = base, i = 2;
  while (used[n]) { n = base.substring(0, 92) + "_" + i; i++; }
  used[n] = true;
  return n;
}

/**
 * earned/possible per TEK across a list of flattened student results.
 * Question indexes are resolved once and reused -- the campus PLC view
 * recomputed them per subgroup, which is what made it slow on a big roster.
 */
function tekStatsForGroup(students, qs, exclNums) {
  var map = {}, order = [];
  for (var qi = 0; qi < qs.length; qi++) {
    if (exclNums.indexOf(qs[qi].number) !== -1) continue;
    // Both codes on a dual-coded question, each getting the question in full.
    // A pupil who missed it missed both standards, so both reteach lists must
    // name them -- which is the whole reason the second code is recorded.
    var codes = [qs[qi].tek];
    if (qs[qi].tek2) codes.push(qs[qi].tek2);
    for (var ci = 0; ci < codes.length; ci++) {
      var tek = codes[ci];
      if (!tek) continue;
      if (!map[tek]) {
        map[tek] = { tek: tek,
                     assessed: (ci === 0 ? qs[qi].assessed : qs[qi].assessed2) || "",
                     strand: qs[qi].strand || "", qNums: [], qIdx: [],
                     earned: 0, possible: 0, dual: 0 };
        order.push(tek);
      }
      if (ci === 1) map[tek].dual++;
      map[tek].qNums.push(qs[qi].number);
      map[tek].qIdx.push(qi);
    }
  }
  for (var oi = 0; oi < order.length; oi++) {
    var info = map[order[oi]];
    for (var si = 0; si < students.length; si++) {
      var s = students[si];
      if (!s.scores || s.scores.length !== qs.length) continue;
      for (var j = 0; j < info.qIdx.length; j++) {
        info.earned   += s.scores[info.qIdx[j]] || 0;
        info.possible += qs[info.qIdx[j]].maxPts;
      }
    }
  }
  return map;
}

/** Pupils in `students` who did not earn full credit on every question of `info`. */
function studentsMissingTEK(students, info, qs) {
  var out = [];
  for (var si = 0; si < students.length; si++) {
    var s = students[si];
    if (!s.scores || s.scores.length !== qs.length) continue;
    for (var j = 0; j < info.qIdx.length; j++) {
      var qi = info.qIdx[j];
      if ((s.scores[qi] || 0) < qs[qi].maxPts) { out.push(s); break; }
    }
  }
  return out;
}


/** Mean adjusted score of a group, as a whole percentage. null if empty. */
function groupAvgPct(list, adjMax) {
  if (!list.length || !adjMax) return null;
  var t = 0;
  for (var i = 0; i < list.length; i++) t += list[i].adjScore;
  return Math.round(t / list.length / adjMax * 100);
}

/** The single weakest TEK for a group, as "6.4.C (23%)". "" if none. */
/**
 * One row per STAAR reporting category for one class, on STAAR alone.
 *
 * Why this exists: the older REPORTING CATEGORY table was a MAP bridge -- goal
 * RITs beside STAAR percentages -- so it ran for Maths only (MAP gives three
 * reading goals and ELA has two categories; three onto two is a guess) and it
 * printed nothing useful without MAP. The presentation build reads no MAP at
 * all, so the room got a category table full of "MAP does not assess this".
 *
 * This is the STAAR-only answer to the same question, and because it never
 * touches MAP it works for EVERY subject, not just Maths.
 *
 * Units, which differ between the fields it reads and are easy to get wrong:
 * secPct / otherPct / allPct are FRACTIONS (earned / possible); statePct is
 * already 0-100. Everything is returned 0-100.
 *
 * Comparison columns are weighted by points possible, not averaged across
 * TEKs. A four-mark TEK should count for more than a one-mark TEK, and a plain
 * mean of percentages would let a single one-mark standard swing the category.
 */
function plcCategoryRollup(rows, subject) {
  var reg = subjectRegistry(), sd = null;
  for (var ri = 0; ri < reg.length; ri++) {
    if (reg[ri].subject === subject) { sd = reg[ri]; break; }
  }
  var rcMap = (sd && sd.tekRCMap) ? sd.tekRCMap : null;

  var agg = {}, order = [];
  for (var r = 0; r < rows.length; r++) {
    var info = rows[r].info;
    if (!info || !info.possible) continue;
    var nm = "";
    if (rcMap) { var rcInf = rcMap[info.tek]; nm = (rcInf && rcInf.rcName) ? rcInf.rcName : ""; }
    // Strand is derived from the code, so it is the honest fallback for a TEK
    // the category table has never seen. "Unmapped" is deliberately visible --
    // a blank bucket would hide a data-quality problem in Eduphoria's TEK
    // strings, which is exactly what CLAUDE.md says not to do.
    if (!nm) nm = info.strand || "";
    if (!nm) nm = "Unmapped";
    if (!agg[nm]) {
      agg[nm] = { name: nm, e: 0, p: 0, q: 0,
                  oW: 0, oP: 0, aW: 0, aP: 0, sW: 0, sP: 0, missing: 0 };
      order.push(nm);
    }
    var a = agg[nm];
    a.e += info.earned;
    a.p += info.possible;
    a.q++;
    if (rows[r].otherPct !== null && rows[r].otherPct !== undefined) {
      a.oW += rows[r].otherPct * info.possible; a.oP += info.possible;
    }
    if (rows[r].allPct !== null && rows[r].allPct !== undefined) {
      a.aW += rows[r].allPct * info.possible;   a.aP += info.possible;
    }
    if (rows[r].statePct !== null && rows[r].statePct !== undefined) {
      a.sW += rows[r].statePct * info.possible; a.sP += info.possible;
    }
    a.missing += (rows[r].missing || []).length;
  }

  var out = [];
  for (var o = 0; o < order.length; o++) {
    var x = agg[order[o]];
    if (!x.p) continue;
    var pct   = Math.round(x.e / x.p * 100);
    var oPct  = x.oP ? Math.round(x.oW / x.oP * 100) : null;
    var aPct  = x.aP ? Math.round(x.aW / x.aP * 100) : null;
    var sPct  = x.sP ? Math.round(x.sW / x.sP) : null;   // already 0-100
    // Same benchmark ladder the per-TEK table uses, for the same reason: a
    // published state figure first, then every other pupil who sat this test,
    // and only then the class's own average, so a lone class still ranks.
    var bench, bSrc;
    if (sPct !== null)      { bench = sPct; bSrc = "State"; }
    else if (aPct !== null) { bench = aPct; bSrc = "All others"; }
    else                    { bench = pct;  bSrc = "Test avg"; }
    out.push({ name: x.name, questions: x.q, pct: pct, otherPct: oPct,
               allPct: aPct, statePct: sPct, benchmark: bench, benchSrc: bSrc,
               gap: bench - pct, missing: x.missing });
  }
  out.sort(function (a, b) {
    if (b.gap !== a.gap) return b.gap - a.gap;   // worst shortfall first
    return a.pct - b.pct;
  });
  return out;
}

/** The sentence beside a category row. STAAR only -- no MAP anywhere in it. */
function plcCategorySay(c) {
  var belowBench = c.gap >= 5;
  // "This Period against My Other Periods is the column that decides what to
  // do": low in both is a whole-class reteach, low in one period only is a
  // warm-up for that period. Same rule as the per-TEK table's guidance.
  var behindOwn = (c.otherPct !== null) && (c.pct <= c.otherPct - 8);
  if (belowBench && behindOwn)  return "weakest in this period  ->  warm-up for this class";
  if (belowBench)               return "low across your periods  ->  reteach";
  if (behindOwn)                return "behind your other periods";
  if (c.gap <= -5)              return "ahead of " + c.benchSrc.toLowerCase();
  return "in line with " + c.benchSrc.toLowerCase();
}

function weakestTEKFor(list, qs, exclNums) {
  if (!list.length) return "";
  var stats = tekStatsForGroup(list, qs, exclNums);
  var worst = "", worstPct = 2;
  for (var k in stats) {
    if (stats[k].possible === 0) continue;
    var p = stats[k].earned / stats[k].possible;
    if (p < worstPct) { worstPct = p; worst = k; }
  }
  return worst ? worst + " (" + Math.round(worstPct * 100) + "%)" : "";
}

/**
 * The student groups on a teacher tab, in a fixed order. Empty groups are dropped.
 *
 * The three service groups, then Section 504, then one row per ethnicity. Austin, 2026-10-12:
 * "add all 504 and ethnicity to be in the version on the teacher's tab. it already reads it."
 * Ethnicity rows follow TEA's own order; any value TEA's list does not name comes after, as
 * written, so nothing an export carries is silently dropped. Every group is shown however small
 * (MIN_GROUP_N = 1) -- a row of one is one child, which is why the tab is for the teacher who
 * already has that child, not for sharing.
 */
var ETHNICITY_ORDER = ["Hispanic/Latino", "White", "Black/African American", "Asian",
                       "American Indian/Alaska Native", "Native Hawaiian/Other Pacific Islander",
                       "Two or More Races"];
function supportGroupsOf(list) {
  var out = [];
  function add(label, f) {
    var g = [];
    for (var i = 0; i < list.length; i++) if (f(list[i])) g.push(list[i]);
    if (g.length) out.push({ label: label, members: g });
  }
  add("Special Ed",         function (s) { return s.sped === "Yes"; });
  add("Emergent Bilingual", function (s) { return shortEB(s.eb) === "EB"; });
  add("Econ Disadvantaged", function (s) { return s.econDis === "Yes"; });
  add("Section 504",        function (s) { return /^(yes|y|true|1)$/i.test(String((s.groups || {}).s504 || "").trim()); });
  var seen = {}, extra = [];
  for (var i = 0; i < list.length; i++) {
    var e = String(list[i].ethnicity || "").trim();
    if (e && !seen[e]) { seen[e] = true; if (ETHNICITY_ORDER.indexOf(e) === -1) extra.push(e); }
  }
  var eth = ETHNICITY_ORDER.concat(extra.sort());
  for (var ei = 0; ei < eth.length; ei++) {
    if (!seen[eth[ei]]) continue;
    (function (val) { add(val, function (s) { return String(s.ethnicity || "").trim() === val; }); })(eth[ei]);
  }
  return out;
}


/** Most papers one PLC group will be split across before we stop. */
/** Growth points expected per pupil. Midlo set this to 1: a class of 18 is
 *  expected to produce 18 points. Overridable per teacher once Config carries
 *  a column for it -- a SpEd-only caseload is not the same expectation. */
var GROWTH_EXPECTED_PER_PUPIL = 1;

// The three sources a class period can be built from. MAP is deliberately
// timeline-only: a TEK table needs question-level data with TEKs on it, and MAP
// has neither -- it reports RIT and goal areas. So MAP can never be a "paper",
// and its Tables cell in Config is locked.
var TEST_TYPES = ["STAAR", "Benchmark", "DCB", "MAP"];

// DCB = district common / curriculum benchmark, the unit tests. A type of its
// own because it is read differently from a BOY/MOY benchmark:
//   - a class period shows ONE table, built from the paper picked in Config
//     (newest by default), so a DCB REPLACES the STAAR table rather than
//     sitting beside it -- one test at a time, which is what a teacher can act
//     on in a PLC meeting;
//   - DCBs stay OFF the strip. The strip is the long view -- STAAR, BOY/MOY
//     and MAP -- and a unit test every few weeks would bury it.
var PLC_CONTENT_DEFAULT = {
  tables:   { STAAR: 1, Benchmark: 0, DCB: 1, MAP: 0 },   // 0 = never used for a TEK table
  timeline: { STAAR: true, Benchmark: true, DCB: false, MAP: true },
  maxTables: 6,
  timelineMax: 5                        // 0 = show every checkpoint
};

var PLC_PAPER_ROW_LABEL = "Which test exactly";
var PLC_PAPER_AUTO      = "Most recent of that type";
var PLC_TYPE_DEFAULT    = "STAAR";

/**
 * Which of the three sources a paper is.
 *
 * Detected from the title, because that is the one thing every export carries.
 * A teacher can override it in the Test Registry -- a district benchmark titled
 * "STAAR Practice" would otherwise be counted against the STAAR allowance and
 * push the real STAAR out of the tab.
 */
function detectTestType(testName) {
  return "STAAR";                                  // public build: every paper is a STAAR paper
}

// 13 = the TEK table A-M. Column C is the vertical alignment, sitting
// immediately right of the TEK it describes.
var PLC_SECTION_COLS = 14;          // the TEK table occupies A-N
var PLC_TRAJ_GAP     = 1;           // blank column M
var PLC_TRAJ_START   = PLC_SECTION_COLS + PLC_TRAJ_GAP;   // trajectory starts at N
var PLC_TABS_BUILT   = {};                                 // teacher -> tab name, last run
var PLC_NO_TAB       = [];                                 // [{name, reason}] ticked teachers without a tab
var PLC_TICKED_N     = 0;                                  // how many teachers were ticked
var RUN_STATS        = { students: 0, tests: 0 };          // set by buildAllViews, read by the run log

/**
 * Say what is happening, while it happens.
 *
 * A four-minute run with a blank screen reads as a hang, and a teacher shown
 * this for the first time will not sit through it twice. toast() is
 * non-blocking -- it drops a note in the bottom-right corner and the script
 * carries on -- so it costs one call against the thousands a run already
 * makes, and it is the whole difference between "it froze" and "it is on tab
 * 7 of 18, about a minute left".
 *
 * step() also flushes. Apps Script batches pending writes, so without one the
 * tabs can all appear at the end in a lump. A flush PER TAB is not the banned
 * pattern: the rule in CLAUDE.md is about flushing inside a per-cell or
 * per-row loop, which is thousands of calls. This is eighteen.
 */
var PROGRESS = {
  ss: null, t0: 0, total: 0, done: 0, label: "",

  begin: function (ss, label, total) {
    this.ss = ss || this.ss; this.t0 = new Date().getTime();
    this.total = total || 0; this.done = 0; this.label = label || "";
    this.say(label + (total ? "  --  0 of " + total : ""));
  },

  /** One unit finished. `what` names it: a teacher, a view. */
  step: function (what) {
    this.done++;
    var msg = this.label + "  --  " + this.done + " of " + this.total;
    if (what) msg += "   " + what;
    var left = this.remaining();
    if (left) msg += "   (about " + left + " left)";
    this.say(msg);
    try { SpreadsheetApp.flush(); } catch (e) {}
  },

  /** A rough estimate from what the run has managed so far. "" until it can tell. */
  remaining: function () {
    if (this.done < 2 || this.done >= this.total) return "";
    var per = (new Date().getTime() - this.t0) / this.done;
    var secs = Math.round(per * (this.total - this.done) / 1000);
    if (secs < 20) return "";
    if (secs < 90) return (Math.round(secs / 10) * 10) + " seconds";
    return (Math.round(secs / 30) / 2) + " minutes";
  },

  /** A stage that is not counted, only announced. */
  note: function (ss, msg) { this.ss = ss || this.ss; this.say(msg); },

  say: function (msg) {
    try { (this.ss || SpreadsheetApp.getActiveSpreadsheet()).toast(msg, "STAAR Analyzer", 30); }
    catch (e) { /* no UI (a triggered run) -- the log still has the trace */ }
  }
};


function bandShort(level) {
  if (level === "Masters")    return "Masters";
  if (level === "Meets")      return "Meets";
  if (level === "Approaches") return "App";
  return "DNM";
}

/** Compact column head for a test: "G7 \u201926", "G5S \u201924". */
/**
 * Short column heading for one paper on the trajectory strip.
 *
 * Carries the SUBJECT. Without it, Grade 7 maths and Grade 7 reading both came
 * out as "G7 '26" and sat side by side on the same strip, indistinguishable --
 * which is the first thing anyone noticed when two subjects were loaded at once.
 */
function trajTestLabel(mt, showSubject) {
  var lab = String(mt.label);
  var gr  = lab.match(/grade\s*(\d+)/i);
  var yr  = lab.match(/20(\d\d)/);
  // "S" in the HEADING only when every form merged into this column is the
  // Spanish one. The English and Spanish forms of a paper share a column, and
  // "G5S" over a column most pupils sat in English read as a Spanish paper.
  // The per-pupil "S" in the cells is what says who sat which form.
  var parts = lab.split(" + "), allES = parts.length > 0;
  for (var pi = 0; pi < parts.length; pi++) if (!/spanish/i.test(parts[pi])) allES = false;
  var sp  = allES ? "S" : "";
  var base = (gr ? "G" + gr[1] + sp : "T" + mt.order) + (yr ? " '" + yr[1] : "");
  if (showSubject === false) return base;
  var tag = subjectTag(mt.subject);
  return tag ? tag + " " + base : base;
}

/** The one-or-two letter tag a column heading wears: M, E, Sci, SS. */
// === PROVENANCE: WHICH TEST A BLOCK WAS BUILT FROM =====================
/**
 * The one mistake this workbook cannot afford is a teacher planning against
 * the WRONG PAPER -- reading a Grade 7 table as though it were their Grade 6
 * class, or an English form as though it were the Spanish one. That has
 * already happened once here, and the cost is not a bad number: it is weeks of
 * intervention aimed at the wrong children.
 *
 * So every block built from a specific test carries a note saying which test.
 * A note rather than a caption, because a caption costs a row on every table
 * and stops being read by the third one, whereas a note is invisible until you
 * distrust a number -- which is exactly the moment you want it.
 *
 * Notes carry IDENTITY ONLY: the title as the workbook has it, the tab it came
 * from, its Order, its date, its type and its forms. Never a score, never a
 * pupil. A note travels with the cell into any sheet these tabs are copied
 * into, so it has to be safe to hand to a teacher.
 */
function provLine(label, value) {
  var pad = "                    ";
  var l = label + ":";
  return "  " + l + pad.slice(0, Math.max(1, 20 - l.length)) + value;
}

/** The tabs and forms behind a merged test, de-duplicated. */
function provBlockFacts(mt) {
  var tabs = {}, langs = {}, tl = [], ll = [], blocks = (mt && mt.blocks) || [];
  for (var i = 0; i < blocks.length; i++) {
    var sn = blocks[i].sheetName;
    if (sn && !tabs[sn]) { tabs[sn] = true; tl.push(sn); }
    var lg = blocks[i].language;
    if (lg && !langs[lg]) { langs[lg] = true; ll.push(lg); }
  }
  return { tabs: tl, langs: ll };
}

/** A STAAR or benchmark paper, as a cell note. */
function testProvenance(mt, opts) {
  var o = opts || {}, f = provBlockFacts(mt), L = [];
  L.push("WHICH TEST THIS IS");
  L.push("");
  L.push("Title, exactly as the workbook has it:");
  L.push("    " + (mt.label || "(untitled)"));
  L.push("");
  L.push(provLine("Read from tab", f.tabs.length ? f.tabs.join(", ") : "(unknown)"));
  L.push(provLine("Order", (mt.order || "?") + "   (lower number = older)"));
  L.push(provLine("Date on the title", mt.date || "(none found)"));
  L.push(provLine("Type", mt.testType || (mt.isSTAAR ? "STAAR" : "Benchmark")));
  L.push(provLine("Subject", mt.subject || "(not detected)"));
  L.push(provLine("Form", f.langs.length ? f.langs.join(" + ") : "English"));
  if (o.grade)     L.push(provLine("Grade on the paper", o.grade));
  if (o.questions) L.push(provLine("Questions scored", o.questions));
  if (o.sat !== undefined && o.of !== undefined) {
    L.push(provLine("Sat by", o.sat + " of the " + o.of + " pupils in this group"));
  }
  if (o.why) { L.push(""); L.push(o.why); }
  L.push("");
  L.push("Not the paper you meant? Order and Include? in the TEST REGISTRY on");
  L.push("the Config tab decide which papers a run uses and which one leads.");
  return L.join("\n");
}

/** A MAP checkpoint, as a cell note. */
function mapProvenance(rec, opts) {
  var o = opts || {}, L = [];
  if (!rec) return "";
  var when = rec.schoolYear ? String(rec.schoolYear)
           : ((rec.term || "?") + " " + (mapCheckpointYear(rec) || "?"));
  L.push("WHICH MAP TEST THIS IS");
  L.push("");
  L.push("Test name, as the export has it:");
  L.push("    " + (rec.testName || rec.title || "(untitled)"));
  L.push("");
  L.push(provLine("Term", when));
  L.push(provLine("School year", mapSchoolYear(rec) ? mapSchoolYear(rec) + "-" + (mapSchoolYear(rec) + 1) : "(unknown)"));
  L.push(provLine("Subject", rec.subject || "(not detected)"));
  L.push(provLine("Course", rec.course || "(none given)"));
  L.push(provLine("Read from tab", rec.sourceSheet || "(unknown)"));
  if (o.grade)             L.push(provLine("Grade", o.grade));
  if (o.pupils !== undefined) L.push(provLine("Pupils with a score", o.pupils));
  L.push("");
  L.push("MAP is joined to a pupil on Local ID where the export carries one, and");
  L.push("on name for the raw NWEA layout. Data_Check reports how many matched.");
  return L.join("\n");
}

/**
 * EVERY test behind a whole tab, numbered, as one note on its banner.
 *
 * The per-block notes answer "what is this table?"; this one answers "did the
 * run pull the right tests at all?" without opening a single block. It is the
 * first thing to read when a tab looks wrong.
 */
function pulledTestsNote(tests, mapCps, heading) {
  var L = [heading || "EVERY TEST BEHIND THIS TAB"], i;
  L.push("");
  L.push("Read this first if anything on the tab looks wrong. If a paper here is");
  L.push("not one you meant to pull, nothing below it is worth reading yet.");
  L.push("");
  if (tests && tests.length) {
    L.push("STAAR PAPERS  (" + tests.length + ")");
    for (i = 0; i < tests.length; i++) {
      var mt = tests[i], f = provBlockFacts(mt);
      L.push("  " + (i + 1) + ".  " + (mt.label || "(untitled)"));
      L.push("      tab " + (f.tabs.length ? f.tabs.join(" + ") : "?")
             + "   |   order " + (mt.order || "?")
             + "   |   " + (mt.date || "no date")
             + "   |   " + (mt.testType || (mt.isSTAAR ? "STAAR" : "Benchmark"))
             + "   |   " + (mt.subject || "?")
             + "   |   " + (f.langs.length ? f.langs.join(" + ") : "English"));
    }
  } else {
    L.push("STAAR PAPERS: none.");
  }
  L.push("");
  if (mapCps && mapCps.length) {
    L.push("MAP CHECKPOINTS  (" + mapCps.length + ")");
    for (i = 0; i < mapCps.length; i++) {
      var r = mapCps[i].rec || mapCps[i];
      var when2 = r.schoolYear ? String(r.schoolYear)
                : ((r.term || "?") + " " + (mapCheckpointYear(r) || "?"));
      L.push("  " + (i + 1) + ".  " + (r.testName || r.title || "(untitled)"));
      L.push("      tab " + (r.sourceSheet || "?")
             + "   |   " + when2
             + "   |   " + (r.subject || "?")
             + "   |   " + (r.course || "no course"));
    }
  } else {

  }
  return L.join("\n");
}

function subjectTag(subject) {
  var sub = subject || "";
  return sub === "Math" ? "M" : sub === "ELA" ? "E"
       : sub === "Science" ? "Sci" : sub === "History" ? "SS" : "";
}

/**
 * The papers a PLC tab's "class over time" strip shows, oldest first.
 *
 * `subjects` is what the tab's teacher teaches. A paper is shown only if its
 * subject is one of them -- a maths-only teacher gets maths columns and nothing
 * else, an English-only teacher gets English, a teacher on both exports gets
 * both. An empty list means there is no subject information (a single-subject
 * run, or papers without a subject tag) and every paper is shown, which is
 * exactly what single-subject runs always did.
 *
 * `cap` is applied PER SUBJECT to the newest end (0 = no cap). Applying it to
 * the merged list dropped the oldest years of every subject as soon as two
 * were loaded -- four years of maths plus four of English is eight papers, and
 * a cap of five kept the newest five, so a strip called "over time" stopped
 * being over time.
 *
 * With more than one subject the columns are grouped by subject, each group
 * oldest first: "M G6 '24  M G7 '25  |  E G6 '24  E G7 '25" reads as two
 * stories side by side, where interleaving by date reads as one story that
 * keeps changing subject.
 */
function trajTestsFor(tests, subjects, cap) {
  var subs = (subjects || []).slice();
  var groups = {}, groupOrder = [];
  for (var i = 0; i < tests.length; i++) {
    var t = tests[i], key = t.subject || "";
    // A paper with NO subject tag (a local benchmark whose title and TEKs
    // named nothing) cannot be attributed to any teacher, so it is shown to
    // all of them, last on the strip. Hiding it silently is the worse harm.
    if (subs.length > 0 && key && subs.indexOf(key) === -1) continue;
    if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
    groups[key].push(t);
  }
  groupOrder.sort(function (a, b) { return subjectStripRank(a) - subjectStripRank(b); });
  var out = [];
  for (var gi = 0; gi < groupOrder.length; gi++) {
    var list = groups[groupOrder[gi]].slice();
    list.sort(function (x, y) { return y.order - x.order; });         // newest first
    if (cap > 0 && list.length > cap) list = list.slice(0, cap);      // drop the OLD end
    list.sort(function (x, y) { return x.order - y.order; });         // back to oldest first
    for (var li = 0; li < list.length; li++) out.push(list[li]);
  }
  return out;
}

/** Fixed left-to-right order for subjects on a strip, so every tab reads the same way. */
var SUBJECT_STRIP_ORDER = ["Math", "ELA", "Science", "History"];
function subjectStripRank(s) {
  var i = SUBJECT_STRIP_ORDER.indexOf(s || "");
  return i === -1 ? SUBJECT_STRIP_ORDER.length : i;
}

/**
 * The papers a GROUP's strip shows: of the teacher's candidate papers, only
 * those at least one pupil on this roster actually sat, then capped per
 * subject through trajTestsFor.
 *
 * A Maths 6 teacher in a workbook that also holds Maths 7 and Maths 8 was
 * getting every maths paper in the run -- "G7 '25  G7 '26  G8 '26" on a class
 * that sat none of them -- and the cap then pushed out the years the class DID
 * sit. The tables already follow this rule ("papers nobody in this group sat
 * are never shown"); the strip now follows it too.
 */
function stripTestsFor(candidates, roster, subjects, cap) {
  var sat = {};
  for (var i = 0; i < roster.length; i++) {
    var ts = (roster[i] && roster[i].testScores) || {}, ks = Object.keys(ts);
    for (var k = 0; k < ks.length; k++) if (ts[ks[k]].tookTest) sat[ts[ks[k]].order] = true;
  }
  var kept = [];
  for (var c = 0; c < candidates.length; c++) if (sat[candidates[c].order]) kept.push(candidates[c]);
  return trajTestsFor(kept, subjects, cap);
}

/** The subjects a teacher has at least one group in, in strip order. */
function teacherSubjectsOf(secSubjectForTeacher) {
  var map = secSubjectForTeacher || {}, keys = Object.keys(map), out = [];
  for (var i = 0; i < keys.length; i++) {
    var sub = map[keys[i]] || "";
    if (sub && out.indexOf(sub) === -1) out.push(sub);
  }
  out.sort(function (a, b) { return subjectStripRank(a) - subjectStripRank(b); });
  return out;
}
/**
 * Why a ticked teacher got no tab, by name, worked out from the parsed records.
 *
 * A tab needs a pupil who (a) sat a paper in a subject and (b) carries this
 * teacher as Current Instructor on the NEWEST paper of that subject. So the
 * answer is one of three: never named on any paper; named only on older papers
 * (those pupils have moved on); or named on the newest paper only by pupils
 * who did not sit it. Teacher names only -- no pupil name or ID is written.
 */
function plcNoTabReasons(names, allStudents, mergedTests, census) {
  // Who survived the teacher filter, by Local ID, so a filter drop can be told
  // apart from a spelling mismatch. The census was taken BEFORE the filter.
  var kept = {};
  for (var ks0 = 0; ks0 < allStudents.length; ks0++) {
    kept[allStudents[ks0].localId || allStudents[ks0].name] = true;
  }
  var newestBySubj = {}, labelByOrder = {}, subjByOrder = {};
  for (var i = 0; i < mergedTests.length; i++) {
    var mt = mergedTests[i], sj = mt.subject || "";
    labelByOrder[mt.order] = mt.label; subjByOrder[mt.order] = sj;
    if (!(sj in newestBySubj) || mt.order > newestBySubj[sj]) newestBySubj[sj] = mt.order;
  }
  var out = [];
  for (var n = 0; n < names.length; n++) {
    var name = names[n], byOrder = {}, onNewest = 0, onNewestSat = 0, total = 0;
    for (var s = 0; s < allStudents.length; s++) {
      var ts = allStudents[s].testScores || {}, ks = Object.keys(ts);
      for (var k = 0; k < ks.length; k++) {
        var r = ts[ks[k]];
        if (String(r.instructor || "").trim() !== name) continue;
        total++;
        if (!byOrder[r.order]) byOrder[r.order] = { n: 0, sat: 0 };
        byOrder[r.order].n++;
        if (r.tookTest) byOrder[r.order].sat++;
        if (newestBySubj[subjByOrder[r.order]] === r.order) {
          onNewest++;
          if (r.tookTest) onNewestSat++;
        }
      }
    }
    var reason;
    var cen = census && census[name] ? census[name] : null;
    var cenN = cen ? Object.keys(cen.students || {}).length : 0, cenKept = 0;
    if (cen) { for (var ck in cen.students) if (kept[ck]) cenKept++; }
    if (cen && cenN > 0 && cenKept === 0) {
      reason = "The Config counted " + cenN + " pupil(s) for this teacher before the run, and the "
             + "teacher filter kept none of them. The tick and the Current Instructor cells do not "
             + "match as text: compare the spelling and spacing on the Config row with the column.";
    } else if (total === 0) {
      reason = "Never appears as Current Instructor on any paper in this workbook. The Config list "
             + "is built from the newest dated block, so look for a spelling or spacing difference "
             + "in that column between blocks."
             + (cen ? " (The Config counted " + cenN + " pupil(s); " + cenKept + " survived the filter.)" : "");
    } else if (onNewest === 0) {
      var parts = [], ords = Object.keys(byOrder).sort(function (a, b) { return b - a; });
      for (var o = 0; o < ords.length; o++) {
        parts.push(labelByOrder[ords[o]] + " (" + byOrder[ords[o]].n + " pupils)");
      }
      reason = "Named only on older papers: " + parts.join("; ") + ". Those pupils have another "
             + "teacher on this year's paper, so there is nothing current to build. Expected for a "
             + "teacher who has changed grade or subject, or left.";
    } else if (onNewestSat === 0) {
      reason = "Named on this year's paper for " + onNewest + " pupil(s), none of whom has a scored "
             + "result on it (absent, not scored, or every answer blank). A tab needs at least one "
             + "scored pupil.";
    } else {
      reason = "Named on this year's paper for " + onNewest + " pupil(s) with results, yet no tab "
             + "was built. Unexpected -- send the Data_Check tab.";
    }
    out.push({ name: name, reason: reason });
  }
  return out;
}

/**
 * lead4ward's public documents for a subject and grade, or null.
 *
 * Keys are "Subject|Grade" as the cut tables use them ("Math|7", "ELA|E1").
 * The Spanish reading form links to the SLAR snapshot where one exists and
 * falls back to the English documents for anything SLAR does not have. The
 * table is in Ref_Lead4ward_Links.gs; a project without that file simply
 * shows no links, it never throws.
 */
function lead4wardLinksFor(subject, gradeLabel, language) {
  if (typeof LEAD4WARD_LINKS === "undefined" || !subject || !gradeLabel) return null;
  var g   = String(gradeLabel).replace(/^0+(?=\d)/, "");
  var en  = LEAD4WARD_LINKS[subject + "|" + g] || null;
  var es  = language === "Spanish" ? (LEAD4WARD_LINKS[subject + "-ES|" + g] || null) : null;
  if (!en && !es) return null;
  en = en || {}; es = es || {};
  return {
    snapshot:   es.snapshot   || en.snapshot   || "",
    vocabulary: es.vocabulary || en.vocabulary || "",
    scaffold:   es.scaffold   || en.scaffold   || ""
  };
}

var L4W_ROW_BG    = "#e8f0fe";   // light blue row, so the links read as links
var L4W_LINK_FG   = "#1155cc";   // Sheets' own link blue
var L4W_LINK_OPTS = { bg: "#e8f0fe", fg: "#1155cc", underline: true, size: 10, fmt: "General" };

/** "8th Grade", "Algebra I", "English I" from a cut-table grade label. */
function l4wGradeName(g) {
  var s = String(g || "");
  if (/^\d+$/.test(s)) {
    var n = parseInt(s, 10);
    var suf = (n % 100 >= 11 && n % 100 <= 13) ? "th"
            : (n % 10 === 1) ? "st" : (n % 10 === 2) ? "nd" : (n % 10 === 3) ? "rd" : "th";
    return n + suf + " Grade";
  }
  var named = { A: "Algebra I", E1: "English I", E2: "English II", B: "Biology", US: "US History" };
  return named[s] || s;
}

/** "8th Grade Math", "4th Grade SLAR", "English I": what the teacher is clicking on. */
function l4wLabel(subject, gradeLabel, language) {
  var g = String(gradeLabel || "");
  if (!/^\d+$/.test(g)) return l4wGradeName(g);           // course names carry the subject
  var subj = subject === "History" ? "Social Studies" : (subject || "");
  if (subject === "ELA" && language === "Spanish") subj = "SLAR";
  return (l4wGradeName(g) + " " + subj).trim();
}

/**
 * TEA's released test for a paper, or null: the online form, the answer key,
 * and TEA's item rationales. Keyed like the cut tables. A Spanish cohort gets
 * the Spanish form where TEA released one and the English set otherwise. A
 * project without Ref_Released_Tests.gs gets no links and never throws.
 */
function releasedTestFor(year, gradeLabel, subject, language) {
  if (typeof RELEASED_TESTS === "undefined" || !year || !gradeLabel || !subject) return null;
  var g = String(gradeLabel).replace(/^0+(?=\d)/, "");
  var en = RELEASED_TESTS[year + "|" + g + "|" + subject + "|EN"] || null;
  var es = language === "Spanish" ? (RELEASED_TESTS[year + "|" + g + "|" + subject + "|ES"] || null) : null;
  if (!en && !es) return null;
  en = en || {}; es = es || {};
  return { form: es.form || en.form || "", key: es.key || en.key || "",
           rationale: es.rationale || en.rationale || "" };
}

/** A HYPERLINK formula. Write it with fmt: "General" or Grid's text format keeps it as text. */
function l4wLink(url, label) {
  return '=HYPERLINK("' + String(url).replace(/"/g, '""') + '","'
         + String(label).replace(/"/g, '""') + '")';
}
var PLC_PULL_TEK_LIMIT = 5;   // name pupils for the five weakest TEKs per period

/**
 * Split a period by the language form each pupil actually sat.
 *
 * English and Spanish STAAR are the SAME items in the same order -- for Grade 5
 * Maths all 172 line up one for one, same question numbers, same TEKs -- so the
 * two cohorts are comparable question by question. What is not comparable is
 * the benchmark: the pupils who sit the Spanish paper score lower on 99% of
 * items, by about 13 points. Averaging the two together hides both groups at
 * once, so they are reported one under the other instead.
 *
 * Returns a single cohort when a period is all one form, which is the usual
 * case and leaves those tabs exactly as they were.
 */
function cohortsByForm(pupils) {
  var en = [], es = [];
  for (var i = 0; i < pupils.length; i++) {
    if (pupils[i].language === "Spanish") es.push(pupils[i]); else en.push(pupils[i]);
  }
  if (es.length === 0) return [{ lang: "",        pupils: en }];
  if (en.length === 0) return [{ lang: "Spanish", pupils: es }];
  return [{ lang: "", pupils: en }, { lang: "Spanish", pupils: es }];
}

/** "May 2026 STAAR Grade 6  +  Unit 3 Benchmark" for a header line. */
function paperListLabel(papers) {
  var out = [];
  for (var i = 0; i < papers.length; i++) out.push(papers[i].label);
  return out.join("   +   ");
}

/** Pupils from `list` who sat the same form as `lang`. */
function sameForm(list, lang) {
  var out = [];
  for (var i = 0; i < list.length; i++) {
    if ((list[i].language === "Spanish" ? "Spanish" : "") === lang) out.push(list[i]);
  }
  return out;
}


var NI_COLS = 5;


var GM_COLS = 9;

/**
 * Campus growth, cell by cell: who moved from which band to which.
 *
 * One entry per pupil PER SUBJECT, because that is TEA's own denominator --
 * "10 or more assessments with academic growth outcomes, combined across RLA
 * and mathematics". A pupil with both subjects counts twice, as they do in the
 * state's figure.
 *
 * The current paper is the NEWEST that pupil sat in that subject, and the prior
 * is the year before it. Not the paper any particular class is working from --
 * this is the campus view.
 */
function computeCampusGrowth(mergedTests, allStudents, blockQuestions) {
  var yearBy = {}, gradeBy = {}, subjBy = {}, labelBy = {};
  for (var i = 0; i < mergedTests.length; i++) {
    var mt = mergedTests[i];
    yearBy[mt.order]  = yearFromDate(mt.date);
    gradeBy[mt.order] = cutGradeLabelFor(primaryQuestionsEx(mt, blockQuestions));
    subjBy[mt.order]  = mt.subject || "";
    labelBy[mt.order] = mt.label;
  }
  var cells = {}, notScored = [], scored = 0, points = 0, accel = 0;

  for (var si = 0; si < allStudents.length; si++) {
    var stu = allStudents[si];
    var keys = Object.keys(stu.testScores);

    // newest paper per subject
    var newest = {};
    for (var k = 0; k < keys.length; k++) {
      var r = stu.testScores[keys[k]];
      if (!r.tookTest) continue;
      var sub = subjBy[r.order] || "";
      if (!sub || !yearBy[r.order]) continue;
      if (!newest[sub] || yearBy[r.order] > yearBy[newest[sub].order]) newest[sub] = r;
    }

    for (var sub2 in newest) {
      var cur = newest[sub2], curYear = yearBy[cur.order], prior = null;
      for (var k2 = 0; k2 < keys.length; k2++) {
        var r2 = stu.testScores[keys[k2]];
        if (!r2.tookTest || subjBy[r2.order] !== sub2) continue;
        if (yearBy[r2.order] === curYear - 1) { prior = r2; break; }
      }
      function shape(rec) {
        if (!rec) return null;
        return { tookTest: rec.tookTest, year: yearBy[rec.order],
                 gradeLabel: gradeBy[rec.order], subject: subjBy[rec.order],
                 scaleScore: rec.scaleScore, rawScore: rec.rawScore,
                 hasRawScore: rec.hasRawScore, scoreCode: rec.scoreCode,
                 language: rec.language };
      }
      var g = growthBetween(shape(prior), shape(cur));
      var entry = {
        name: stu.name, stu: stu, subject: sub2,
        grade: gradeBy[cur.order] || "?", period: stu.period || "",
        instructor: stu.instructor || "", curLabel: labelBy[cur.order],
        prior: g.prior, current: g.current, points: g.points,
        accelerated: g.accelerated, reason: g.reason
      };
      if (g.points === null) { notScored.push(entry); continue; }
      var key = g.prior + ">" + g.current;
      if (!cells[key]) cells[key] = [];
      cells[key].push(entry);
      scored++;
      points += g.points;
      if (g.accelerated) accel++;
    }
  }
  return { cells: cells, notScored: notScored, scored: scored,
           points: points, accelerated: accel };
}

/** Total points one cell is worth per assessment, bonus included. */
function cellPoints(priorBand, currentBand) {
  var base = growthPointsFor(priorBand, currentBand);
  if (base === null) return null;
  return base + (isAcceleratedLearning(priorBand, currentBand) ? 0.25 : 0);
}

/** Colour a cell by what it is worth, not by how many are in it. */
function cellPointBg(v) {
  if (v === null) return C.white;
  if (v >= 1.25) return "#1b5e20";
  if (v >= 1)    return C.strandGood;
  if (v >= 0.5)  return C.strandMid;
  return C.strandBad;
}
function cellPointFg(v) { return (v !== null && v >= 1.25) ? "#ffffff" : "#000000"; }

/**
 * Growth_Matrix and Growth_Students.
 *
 * 36 cells, and a tab each would be 36 tabs nobody can navigate. Instead every
 * pupil is written ONCE to Growth_Students, ordered by matrix cell, then by
 * grade, then by surname -- so each cell of the matrix is a contiguous block
 * with a known first row, and the matrix links straight to it.
 */
/**
 * The slice of a growth result belonging to one subject, or all of it.
 *
 * Pupils are NOT recounted or recomputed here -- the same entries are simply
 * partitioned, so the subject matrices always add up to the combined one.
 * Passing "" gives everything back.
 */
function growthSubset(G, subj) {
  var out = { cells: {}, notScored: [], scored: 0, points: 0, accelerated: 0 };
  for (var k in G.cells) {
    var keep = [];
    for (var i = 0; i < G.cells[k].length; i++) {
      var e = G.cells[k][i];
      if (subj && e.subject !== subj) continue;
      keep.push(e);
      out.scored++;
      out.points += e.points;
      if (e.accelerated) out.accelerated++;
    }
    if (keep.length) out.cells[k] = keep;
  }
  for (var m = 0; m < G.notScored.length; m++) {
    if (subj && G.notScored[m].subject !== subj) continue;
    out.notScored.push(G.notScored[m]);
  }
  return out;
}

/**
 * Which subjects actually earned growth in this run, in a stable order.
 *
 * Only subjects with a SCORED entry appear. Science and Social Studies cannot
 * reach this list: TEA evaluates growth for RLA and mathematics only, and
 * those papers are years apart in any case, so they fail the consecutive-year
 * rule before subject ever comes into it.
 */
function growthSubjects(G) {
  var seen = {}, out = [];
  for (var k in G.cells) {
    for (var i = 0; i < G.cells[k].length; i++) {
      var sub = G.cells[k][i].subject;
      if (sub && !seen[sub]) { seen[sub] = true; out.push(sub); }
    }
  }
  out.sort();
  return out;
}

function generateGrowthMatrix(ss, mergedTests, allStudents, blockQuestions) {
  var G = computeCampusGrowth(mergedTests, allStudents, blockQuestions);
  if (G.scored === 0 && G.notScored.length === 0) return false;

  var B = ENHANCED_BANDS;
  var trajTests = mergedTests.slice().sort(function (a, b) { return a.order - b.order; });

  // ---- pupils tab first: we need each block's row number for the links -----
  var stuSheet = getOrCreate(ss, "Growth_Students");
  var SW = 9 + trajTests.length;
  var gs = new Grid(SW);
  gs.header("GROWTH STUDENTS  --  who is in each cell of the matrix", C.hdr, C.hdrTxt, 14, SW, 30);
  gs.header("Every pupil appears once per subject. Grouped by the move they made, then by grade, "
    + "then by surname. Come here from Growth_Matrix by clicking a number.",
    C.warn, "#000000", 9, SW, 22, false);
  gs.header("ADMIN ONLY -- names every pupil on the campus, across every teacher. This tab must "
    + "not be copied into a sheet shared with staff.",
    C.alert, C.alertTxt, 9, SW, 20, false);

  var anchorRow = {};                       // "prior>current" -> 1-based row

  function writeGroup(key, title, list, ptsEach) {
    if (!list.length) return;
    // Subject first, so each subject forms one contiguous block inside the
    // group. That block start is what a subject matrix links to -- which is why
    // no pupil has to be written twice to serve three matrices.
    list.sort(function (a, b) {
      var sa = String(a.subject), sb = String(b.subject);
      if (sa !== sb) return sa < sb ? -1 : 1;
      var ga = String(a.grade), gb = String(b.grade);
      if (ga !== gb) return ga < gb ? -1 : 1;
      return String(a.name) < String(b.name) ? -1 : String(a.name) > String(b.name) ? 1 : 0;
    });
    var subjectsHere = {};
    for (var sq = 0; sq < list.length; sq++) subjectsHere[list[sq].subject] = true;
    var multiSubject = Object.keys(subjectsHere).length > 1;
    gs.row(8);
    // +1 because gs.v.length is a 0-based count and the header lands on the
    // NEXT row, while a sheet range like "A14" is 1-based. Without it every
    // link arrived one row above its own heading.
    anchorRow[key] = gs.v.length + 1;
    gs.header(title + "   --   " + list.length + " pupil(s)"
              + (ptsEach === null ? "" : "   |   " + ptsEach + " point(s) each"),
              ptsEach === null ? "#b71c1c" : cellPointBg(ptsEach),
              ptsEach !== null && ptsEach >= 1.25 ? "#ffffff" : "#000000", 12, SW, 24);
    var head = ["Student", "Local ID", "Grade", "Teacher", "Period", "Subject",
                "Last year", "This year", "Points"];
    var gsSubjects = {};
    for (var gh = 0; gh < trajTests.length; gh++) if (trajTests[gh].subject) gsSubjects[trajTests[gh].subject] = true;
    var gsMulti = Object.keys(gsSubjects).length > 1;
    for (var h = 0; h < trajTests.length; h++) head.push(trajTestLabel(trajTests[h], gsMulti));
    gs.headerRow(head, C.sectionBg, 30);

    var lastGrade = null, lastSubj = null;
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (String(e.subject) !== lastSubj) {
        lastSubj = String(e.subject);
        lastGrade = null;                       // restart grade banding per subject
        // Anchor for the subject matrices. Recorded BEFORE the heading row is
        // written, and +1 for the same 0-based/1-based reason as the group
        // anchor above -- without it every subject link lands one row high.
        anchorRow[key + "|" + lastSubj] = gs.v.length + 1;
        if (multiSubject) {
          gs.row(18);
          gs.set(0, lastSubj, { bg: "#37474f", fg: "#ffffff", bold: true, size: 10 });
        }
      }
      if (String(e.grade) !== lastGrade) {
        lastGrade = String(e.grade);
        gs.row(18);
        gs.set(0, "Grade " + lastGrade, { bg: C.subHdr, fg: C.subTxt, bold: true, size: 10 });
      }
      var bg = i % 2 === 0 ? C.white : C.zebra;
      gs.row(17);
      gs.set(0, e.name, { bg: bg, size: 9 });
      gs.set(1, e.stu.localId || "", { bg: bg, align: "center", size: 9, fmt: "@" });
      gs.set(2, e.grade, { bg: bg, align: "center", size: 9 });
      gs.set(3, e.instructor, { bg: bg, size: 9 });
      gs.set(4, e.period, { bg: bg, align: "center", size: 9 });
      gs.set(5, e.subject, { bg: bg, align: "center", size: 9 });
      gs.set(6, ENHANCED_BAND_SHORT[e.prior] || "",
             { bg: rampBg(e.prior, ""), fg: rampFg(e.prior, ""), align: "center", size: 9 });
      gs.set(7, ENHANCED_BAND_SHORT[e.current] || "",
             { bg: rampBg(e.current, ""), fg: rampFg(e.current, ""), align: "center", size: 9 });
      if (e.points === null) {
        gs.set(8, e.reason, { bg: C.warn, size: 8, wrap: true });
      } else {
        var tot = e.points + (e.accelerated ? 0.25 : 0);
        gs.set(8, tot, { bg: cellPointBg(tot), fg: cellPointFg(tot),
                         align: "center", bold: true, fmt: "0.00" });
      }
      // the pupil's whole history, oldest first
      for (var t = 0; t < trajTests.length; t++) {
        var band = "", took = false;
        var ks = Object.keys(e.stu.testScores), pick = null;
        for (var kk = 0; kk < ks.length; kk++) {
          var rz = e.stu.testScores[ks[kk]];
          if (rz.order !== trajTests[t].order) continue;
          if (!pick) pick = rz;
          if (rz.tookTest) { pick = rz; break; }
        }
        var coarse = "", scale = "";
        if (pick && pick.tookTest) {
          took = true;
          band = enhancedBandOf(pick.scaleScore,
                   cutGradeLabelFor(primaryQuestionsEx(trajTests[t], blockQuestions)),
                   trajTests[t].subject, pick.language, yearFromDate(trajTests[t].date));
          // We only hold TEA's six-band cut tables for recent years. For every
          // other year the export still carries the Approaches/Meets/Masters
          // flags and a scale score -- so show those rather than "sat", which
          // threw away the one thing this column exists for: whether a pupil
          // has always been at Did Not Meet or only fell away after Grade 5.
          if (pick.hasBands !== false) {
            coarse = masteryLevel(pick.approaches, pick.meets, pick.masters);
          }
          var sc9 = parseFloat(pick.scaleScore);
          if (sc9 && !isNaN(sc9)) scale = String(Math.round(sc9));
        }
        var label = band ? ENHANCED_BAND_SHORT[band] : (coarse ? bandShort(coarse) : "");
        var cellTxt = !took ? "\u2013"
                    : (label ? (scale ? label + "\n" + scale : label)
                             : (scale ? scale : "sat"));
        gs.set(9 + t, cellTxt, {
          bg: took ? (label ? rampBg(band, coarse) : C.zebra) : C.strandNone,
          fg: took ? (label ? rampFg(band, coarse) : "#616161") : "#9e9e9e",
          align: "center", size: 8, wrap: true });
      }
    }
  }

  for (var pi = 0; pi < B.length; pi++) {
    for (var ci = 0; ci < B.length; ci++) {
      var key = B[pi] + ">" + B[ci];
      writeGroup(key, ENHANCED_BAND_NAMES[B[pi]] + "  \u2192  " + ENHANCED_BAND_NAMES[B[ci]],
                 G.cells[key] || [], cellPoints(B[pi], B[ci]));
    }
  }
  writeGroup("__none", "NOT SCORED  --  no growth could be calculated", G.notScored, null);

  var widths = [190, 82, 55, 145, 55, 65, 76, 76, 66];
  for (var w = 0; w < trajTests.length; w++) widths.push(66);
  gs.flush(stuSheet, widths);
  var gid = stuSheet.getSheetId();

  // ---- the matrices -------------------------------------------------------
  var mSheet = getOrCreate(ss, "Growth_Matrix");
  var g = new Grid(GM_COLS);
  g.header("GROWTH MATRIX  --  campus, prior year against current year",
           C.hdr, C.hdrTxt, 14, GM_COLS, 30);
  g.header("Every pupil with a growth score, counted once per subject. Click any number to jump "
    + "to those pupils on Growth_Students, listed by grade then surname with their whole test "
    + "history. Cell colour is what the move is WORTH, not how many are in it.",
    C.warn, "#000000", 9, GM_COLS, 26, false);
  // The links address a sheet inside THIS workbook by its id. Copy this tab
  // into another spreadsheet and the numbers still read correctly but the
  // links point at nothing -- so say that here rather than let someone
  // discover it in front of a room.
  g.header("ADMIN ONLY. The numbers below link to Growth_Students in THIS workbook. If you copy "
    + "this tab into a sheet you are sharing, the counts still read correctly but the links stop "
    + "working -- and Growth_Students names every pupil on the campus, so it should not travel "
    + "with it.",
    C.alert, C.alertTxt, 9, GM_COLS, 24, false);

  /**
   * One 6x6 matrix for a scope, appended to the tab.
   *
   * `subj` is "" for the combined matrix, or a subject name. The link suffix is
   * what points a subject cell at that subject's block inside the group on
   * Growth_Students, rather than at the whole group.
   */
  function renderMatrix(sub, title, note) {
    var S = growthSubset(G, sub);
    var suffix = sub ? "|" + sub : "";

    g.row(8);
    g.header(title, sub ? C.subHdr : "#263238", "#ffffff", 12, GM_COLS, 26);
    if (note) g.header(note, C.warn, "#000000", 9, GM_COLS, 20, false);

    g.row(22);
    g.set(0, "", { bg: C.white });
    g.set(1, "CURRENT YEAR  \u2192", { bg: C.subHdr, fg: C.subTxt, bold: true, size: 10 });
    g.headerRow(["PRIOR YEAR  \u2193"].concat(B.map(function (b) { return ENHANCED_BAND_SHORT[b]; }))
                .concat(["Pupils", "Points"]), C.sectionBg, 24);

    var colTot = [0, 0, 0, 0, 0, 0];
    for (var r2 = 0; r2 < B.length; r2++) {
      var rowN = 0, rowP = 0;
      g.row(26);
      g.set(0, ENHANCED_BAND_NAMES[B[r2]], { bg: C.sectionBg, bold: true, size: 9 });
      for (var c2 = 0; c2 < B.length; c2++) {
        var k2 = B[r2] + ">" + B[c2];
        var list = S.cells[k2] || [];
        var val = cellPoints(B[r2], B[c2]);
        rowN += list.length; rowP += list.length * val; colTot[c2] += list.length;
        var anchor = anchorRow[k2 + suffix];
        if (list.length > 0 && anchor) {
          g.set(1 + c2, '=HYPERLINK("#gid=' + gid + '&range=A' + anchor + '","'
                        + list.length + '")',
                { bg: cellPointBg(val), fg: cellPointFg(val), align: "center",
                  bold: true, size: 12, fmt: "General" });
        } else {
          g.set(1 + c2, list.length, { bg: cellPointBg(val), fg: cellPointFg(val),
                                       align: "center", size: 11 });
        }
      }
      g.set(7, rowN, { bg: C.zebra, align: "center", bold: true });
      g.set(8, Math.round(rowP * 100) / 100, { bg: C.zebra, align: "center", fmt: "0.00" });
    }

    g.row(24);
    g.set(0, "Pupils", { bg: C.sectionBg, bold: true });
    for (var c3 = 0; c3 < B.length; c3++) {
      g.set(1 + c3, colTot[c3], { bg: C.zebra, align: "center", bold: true });
    }
    g.set(7, S.scored, { bg: C.subHdr, fg: C.subTxt, align: "center", bold: true });
    var earned = S.points + S.accelerated * 0.25;
    g.set(8, Math.round(earned * 100) / 100, { bg: C.subHdr, fg: C.subTxt,
                                               align: "center", bold: true, fmt: "0.00" });

    var pct = S.scored ? Math.round(earned / S.scored * 100) : 0;
    g.row(28);
    g.set(0, "Assessments scored", { bg: C.sectionBg, bold: true });
    g.set(1, S.scored, { bg: C.white, align: "center", bold: true });
    g.set(2, "Points earned", { bg: C.sectionBg, bold: true });
    g.set(3, Math.round(earned * 100) / 100, { bg: C.white, align: "center", bold: true, fmt: "0.00" });
    g.set(4, "Expected", { bg: C.sectionBg, bold: true });
    g.set(5, S.scored * GROWTH_EXPECTED_PER_PUPIL, { bg: C.white, align: "center" });
    g.set(6, "Of expected", { bg: C.sectionBg, bold: true });
    g.set(7, pct, { bg: pct >= 100 ? C.strandGood : pct >= 70 ? C.strandMid : C.strandBad,
                    align: "center", bold: true, fmt: "0\"%\"" });

    if (S.notScored.length > 0 && anchorRow["__none" + suffix]) {
      g.row(22);
      g.set(0, "Not scored", { bg: C.warn, bold: true });
      g.set(1, '=HYPERLINK("#gid=' + gid + '&range=A' + anchorRow["__none" + suffix] + '","'
               + S.notScored.length + '")',
            { bg: C.warn, align: "center", bold: true, fmt: "General" });
      g.set(2, "No growth could be calculated. Click to see who, and why.",
            { bg: C.warn, size: 9, wrap: true });
    }
    if (S.accelerated > 0) {
      g.row(20);
      g.set(0, "Accelerated", { bg: C.sectionBg, bold: true });
      g.set(1, S.accelerated, { bg: C.white, align: "center", bold: true });
      g.set(2, "Did Not Meet last year, Approaches or above this year. Each adds 0.25 on top.",
            { bg: C.white, size: 9, wrap: true, fg: "#555555" });
    }
  }

  // Combined first -- it is the one that matches what TEA scores. The subject
  // matrices follow only when there is more than one subject to split, because
  // with a single subject they would be a copy of the table above them.
  var subs = growthSubjects(G);
  renderMatrix("", "ALL SUBJECTS  --  " + (subs.length ? subs.join(" + ") : "no growth scored"),
    "This is the campus growth picture as TEA calculates it. Science and Social Studies earn no "
    + "growth points at all: School Progress Part A evaluates RLA and mathematics only, so they "
    + "are neither in the numerator nor the denominator.");

  if (subs.length > 1) {
    for (var sx = 0; sx < subs.length; sx++) {
      renderMatrix(subs[sx], subs[sx].toUpperCase() + " ONLY",
        "The same pupils as above, limited to " + subs[sx]
        + ". Every subject matrix adds up to the combined one.");
    }
  }

  g.flush(mSheet, [150, 78, 78, 78, 78, 78, 78, 80, 80]);
  return true;
}

/**
 * Needed_Info -- what the export did not carry, and what it costs.
 *
 * Built only when there is something to say. A tab that is always present and
 * usually empty becomes furniture, and people stop reading it.
 *
 * Three groups, because they call for three different responses:
 *   KEY COLUMNS MISSING   a named feature is off; fix it in the next pull
 *   YOU CAN FILL IN       test-level facts, a handful of rows, typeable here
 *   WORTH ADDING          per-pupil columns nobody can type; pull them instead
 *
 * Nothing here stops a run. The only things that stop a run are an export with
 * no test blocks, no Student Name column, or a test with no Order -- because
 * those make every number wrong rather than one feature absent.
 */
function generateNeededInfo(ss, scan, mergedTests) {
  var blocks = (scan && scan.allBlocks) ? scan.allBlocks : [];
  if (blocks.length === 0) return false;

  // Which key columns are absent, and from which tests.
  var KEY = [
    { k: "tek",   label: "TEK codes on the question row",
      cost: "No TEK ranking, no strand view, no state comparison, no vertical alignment. Scoring still works.",
      miss: function (b) { return !b.hasTEKRow; } },
    { k: "scale", label: "Scale Score",
      cost: "No growth scoring at all -- the six A-F bands are read from scale score.",
      miss: function (b) { return b.scalScoreCol < 0; } },
    { k: "bands", label: "Approaches / Meets / Masters",
      cost: "Trajectory and band grids read \"sat\" instead of a performance band.",
      miss: function (b) { return !b.bandColCount; } },
    { k: "raw",   label: "Raw Score",
      cost: "The reconciliation check cannot run -- that is the one that proves our arithmetic against Eduphoria's.",
      miss: function (b) { return b.rawScoreCol < 0; } },
    { k: "instr", label: "Current Instructor",
      cost: "Every pupil lands in one \"(No instructor listed)\" group. The PLC tab has nothing to section.",
      miss: function (b) { return b.instructorCol < 0; } },
    { k: "period", label: "Current Period",
      cost: "Grouping by class period is unavailable; sections only.",
      miss: function (b) { return b.periodCol < 0; } },
    { k: "date",  label: "Date Taken",
      cost: "Ordering falls back to reading the month and year out of the test title, so the title must keep them.",
      miss: function (b) { return b.dateTakenCol < 0; } }
  ];

  var rows = [];
  for (var k = 0; k < KEY.length; k++) {
    var hits = [];
    for (var b = 0; b < blocks.length; b++) {
      if (!blocks[b].include) continue;
      if (KEY[k].miss(blocks[b]) && hits.indexOf(blocks[b].testName) === -1) {
        hits.push(blocks[b].testName);
      }
    }
    if (hits.length) rows.push({ def: KEY[k], tests: hits });
  }
  if (rows.length === 0) return false;

  var sheet = getOrCreate(ss, "Needed_Info");
  var g = new Grid(NI_COLS);
  g.header("NEEDED INFO  --  what this export did not carry", C.hdr, C.hdrTxt, 14, NI_COLS, 30);
  g.header("None of this stopped the run. Each line names a column that was absent and the one "
    + "thing it switches off, so you can decide whether it is worth adding to the next pull. "
    + "This tab only appears when there is something on it.",
    C.warn, "#000000", 9, NI_COLS, 26, false);

  g.row(8);
  g.header("KEY COLUMNS MISSING", C.subHdr, C.subTxt, 12, NI_COLS, 24);
  g.headerRow(["Column", "Tests affected", "What it switches off"], C.sectionBg, 22);
  for (var r = 0; r < rows.length; r++) {
    var bg = r % 2 === 0 ? C.white : C.zebra;
    g.row(30);
    g.set(0, rows[r].def.label, { bg: bg, bold: true, size: 10 });
    g.set(1, rows[r].tests.length === blocks.length ? "every test"
            : rows[r].tests.slice(0, 3).join("; ") + (rows[r].tests.length > 3
              ? "  (+" + (rows[r].tests.length - 3) + " more)" : ""),
          { bg: bg, size: 9, wrap: true });
    g.set(2, rows[r].def.cost, { bg: bg, size: 9, wrap: true, fg: "#555555" });
  }

  g.row(8);
  g.header("WORTH ADDING TO YOUR NEXT PULL", C.subHdr, C.subTxt, 12, NI_COLS, 24);
  g.header("These carry per-pupil values, so they cannot be typed in here -- they have to come "
    + "from Eduphoria. Data_Check section 10 lists every column your export DID carry and how "
    + "many rows had a value, so you can see which of these are worth configuring.",
    C.warn, "#000000", 9, NI_COLS, 22, false);
  g.headerRow(["Column", "What it would unlock"], C.sectionBg, 22);
  var WANT = [
    ["Previous Year Scale Score",
     "Growth scores for pupils who transferred in from another Texas district - they currently show as \"not scored\"."],
    ["Score Code",
     "TEA excludes score codes A (Absent) and O (Other) from growth. Without it our number cannot match theirs."],
    ["School Snapshot / Testing Enrollment",
     "An accountability view that filters on real enrolment rather than inferring it from dates."],
    ["Previous Year STAAR Progress",
     "TEA's own growth answer per pupil, so our calculation can be checked against theirs one pupil at a time."],
    ["State ID (TSDS Unique ID)",
     "The identifier that follows a pupil across districts and years. We currently join on Local ID."],
    ["Grade Level",
     "Makes the cut-table grade a fact instead of something inferred from TEK prefixes."]
  ];
  for (var w = 0; w < WANT.length; w++) {
    var wbg = w % 2 === 0 ? C.white : C.zebra;
    g.row(26);
    g.set(0, WANT[w][0], { bg: wbg, bold: true, size: 10 });
    g.set(1, WANT[w][1], { bg: wbg, size: 9, wrap: true, fg: "#555555" });
  }

  g.flush(sheet, [210, 260, 430, 110, 110]);
  return true;
}


/**
 * Why a pupil on the roster has no row in this section's table.
 *
 * "No data" is not one thing, and the difference decides what a teacher does.
 * A pupil who sat a different paper is fine and appears under it. A pupil
 * sitting on this paper's roster with no responses is an absence to chase. A
 * pupil with nothing anywhere has just arrived. Showing a bare count told a
 * teacher none of that -- and the pupils who vanish are, by definition, the
 * ones nobody notices.
 */
function whyNoDataOnPaper(student, papers, testByOrder) {
  var keys = Object.keys(student.testScores || {});
  var shownOrders = {};
  for (var pi2 = 0; pi2 < papers.length; pi2++) shownOrders[papers[pi2].order] = true;
  var onThisPaper = false, elsewhereLabels = [], seen = {};
  for (var i = 0; i < keys.length; i++) {
    var r = student.testScores[keys[i]];
    if (shownOrders[r.order]) { onThisPaper = true; continue; }
    if (!r.tookTest) continue;
    var other = testByOrder[r.order];
    var lab = other ? other.label : r.testName;
    if (lab && !seen[lab]) { seen[lab] = true; elsewhereLabels.push(lab); }
  }
  // The parser writes a record for every pupil on the sheet, including a blank
  // one for a paper they did not sit, so "has a record here" is not the useful
  // fact -- what they DID sit is. Report that first.
  if (elsewhereLabels.length) {
    return (onThisPaper ? "no responses on this paper; " : "")
           + "sat " + elsewhereLabels.join("; ") + " instead";
  }
  if (onThisPaper) return "on the roster for this paper, but no responses recorded - check the absence";
  return "no test data anywhere in this workbook - new to the district?";
}

function generatePLCBySection(ss, mergedTests, allStudents, blockQuestions, allExcluded,
                              showAbsent, byPeriod, plcContent, teacherSubjCfg) {
  if (mergedTests.length === 0 || allStudents.length === 0) return 0;

  // Missing only when an older caller has not been updated; the defaults are
  // the behaviour this tab already had.
  var PC = plcContent || readPLCContent(null);
  function typeOf(t) { return "STAAR"; }          // public build: every paper is a STAAR paper
  // ONE table per class period. The paper is whichever the Config picked for
  // this subject, or the newest one the class actually sat. A PLC meeting needs
  // one test in front of it, not a stack; the rest of the year is the strip on
  // the right. A combined class spanning two grade-level papers in the SAME
  // administration still gets a second table through the coverage rule below,
  // because the alternative is dropping half the roster.
  var TABLE_BUDGET = 1;
  var pickMissed = "";          // set when the picked paper is one this class never sat

  /**
   * The paper Config picked for a subject, as an order number, or -1 for none.
   *
   * Matched on the merged test's own label first, then on any block title
   * inside it: the Config lists block titles, and two blocks of one paper merge
   * into a single test whose label is only one of them.
   */
  function pickedPaperFor(subject) {
    var want = (PC.paper && subject) ? String(PC.paper[subject] || "").trim() : "";
    if (!want) return -1;
    for (var pi = 0; pi < mergedTests.length; pi++) {
      var pt = mergedTests[pi];
      if (String(pt.label || "").trim() === want) return pt.order;
      var pbl = pt.blocks || [];
      for (var pb = 0; pb < pbl.length; pb++) {
        if (String(pbl[pb].testName || "").trim() === want) return pt.order;
      }
    }
    return -1;
  }

  /**
   * Whether a type belongs on the timeline strip.
   *
   * Unknown or unset means YES. Fail-open is right here: an unexpected extra
   * column is a smaller harm than silently dropping a pupil's history, and an
   * older Config that predates this setting must keep showing everything.
   * Anything explicitly falsy -- "No", false, 0 -- is a no.
   */
  function onTimeline(t) {
    var v = PC.timeline[typeOf(t)];
    return v === undefined || v === null ? true : !!v;
  }

  // EACH SECTION IS SCORED AGAINST THE PAPER ITS OWN PUPILS SAT.
  //
  // A teacher with a Maths 6 class and a Maths 7 class has pupils on two
  // different papers. Scoping the whole tab to one test made the other cohort
  // vanish -- 144 pupils on the roster, 41 on the tab. A section is almost
  // always one grade level, so the test is picked per section instead.
  /**
   * The one place that decides what a PLC group IS. The roster map and the
   * flattened score rows must agree exactly -- when they disagreed, every pupil
   * fell out of every table and the tab showed nothing but the absence list.
   */
  // Which subjects are in this run. With more than one, a period is a period
  // OF A SUBJECT -- "Period 3 -- Math" and "Period 3 -- ELA" are different
  // rooms with different teachers, and treating them as one group is exactly
  // what emptied the English tabs when both were loaded together.
  var subjectsInRun = [];
  for (var sj = 0; sj < mergedTests.length; sj++) {
    var sjs = mergedTests[sj].subject || "";
    if (sjs && subjectsInRun.indexOf(sjs) === -1) subjectsInRun.push(sjs);
  }
  var multiSubject = subjectsInRun.length > 1;

  function groupNameOf(rec, subject) {
    var base;
    if (byPeriod) {
      base = rec.period ? "Period " + rec.period
                        : (rec.section || "(No period listed)");
    } else {
      base = rec.section || "(No section listed)";
      // An export that names the class only by its period (DCBs; STAAR pulled with Current Period
      // alone) gives a bare "3". Say what it is.
      if (/^\d+$/.test(base)) base = "Period " + base;
    }
    return (multiSubject && subject) ? base + "  --  " + subject : base;
  }

  // A paper's results are grouped by the pupil's CURRENT placement -- the same rule that builds each
  // teacher's class list below -- not by the class label printed on that paper.
  //
  // Found 2026-10-10 on the STAAR + MAP + DCB showcase, and true of real exports: STAAR names a class
  // by Current Section or Course ("Math 8-01", "Math 8 - 1"), a DCB only by Current Period ("1").
  // Placement comes from the NEWEST paper, a DCB, so the class list said "1" while the STAAR results
  // said "Math 8-01"; they never met, and every period's TEK table came out empty -- "NOT IN THE
  // TABLE ABOVE, 22 of 22". Austin: the tool is for whoever has the pupils NOW, so the current
  // placement is the right key for every paper.
  // Keyed on idKey, not localId: two pupils sharing a Local ID are split by parseStudents into
  // "S9" and "S9#1", and a localId key would hand both the second one's class.
  var plcById = {};
  for (var pbi = 0; pbi < allStudents.length; pbi++) {
    var pbk = allStudents[pbi].idKey || allStudents[pbi].localId;
    if (pbk) plcById[pbk] = allStudents[pbi];
  }
  var flatByOrder = {};
  function flatFor(mtx) {
    if (!flatByOrder[mtx.order]) {
      var f = flattenStudentsForTest(mtx, allStudents, blockQuestions, allExcluded);
      var fSubj = subjectsInRun.length ? mtx.subject : "";
      for (var fi = 0; fi < f.length; fi++) {
        var fsk = f[fi].idKey || f[fi].localId;
        var fst = fsk ? plcById[fsk] : null;
        if (fst) {
          var fpl = placementFor(fst, fSubj, true);
          f[fi].__grp = (fpl.instructor || "(No instructor listed)") + "||" + groupNameOf(fpl, fSubj);
        } else {
          f[fi].__grp = (f[fi].instructor || "(No instructor listed)") + "||" +
                        groupNameOf(f[fi], mtx.subject);
        }
      }
      flatByOrder[mtx.order] = f;
    }
    return flatByOrder[mtx.order];
  }
  var testByOrder = {};
  for (var mo = 0; mo < mergedTests.length; mo++) testByOrder[mergedTests[mo].order] = mergedTests[mo];

  /**
   * Everyone who sat a STAAR paper anywhere in this workbook.
   *
   * The roster check a benchmark needs: a pupil NOT in here is new to the
   * campus, and this export is the first time the tool has seen their Local ID.
   * Their profile is built from the benchmark like anyone else's -- nobody is
   * dropped for being new -- and the tab says so rather than leaving a teacher
   * to notice a name they do not recognise.
   */
  var staarSeen = {};
  for (var ssi = 0; ssi < allStudents.length; ssi++) {
    var sKeys = Object.keys(allStudents[ssi].testScores);
    for (var sk2 = 0; sk2 < sKeys.length; sk2++) {
      var sRec = allStudents[ssi].testScores[sKeys[sk2]];
      if (!sRec.tookTest) continue;
      var sT = testByOrder[sRec.order];
      if (sT && ((sT.testType ? sT.testType : (sT.isSTAAR ? "STAAR" : "")) === "STAAR")) {
        staarSeen[allStudents[ssi].localId] = true; break;
      }
    }
  }

  /**
   * The SAME pupils on last year's STAAR, tallied by TEK.
   *
   * "Did this group grow" only means something against the standard this one
   * grows out of, and against the same children -- last year's pupils in this
   * grade are a different set of people. So: the newest STAAR paper in this
   * subject older than the one on the tab, restricted to the pupils in front of
   * us. Pupils who were not here last year are simply not in it, and n says so.
   *
   * THE PAPER THESE PUPILS SAT, NOT JUST THE NEWEST ONE. A workbook holding last May's
   * grade 5, 6, 7 and 8 papers has four candidates on the same date, and taking the
   * highest order handed a grade-6 class the GRADE-7 paper -- which none of them sat -- and
   * a grade-8 class THIS YEAR's grade-7 paper. On the demo workbook not one class got a
   * growth figure. So only papers these pupils actually took are candidates, and the newest
   * of those wins. Found 2026-10-06. The master has the same fault.
   */
  function prevYearStatsFor(pupils, mt) {
    var cand = {}, any = false;
    for (var pyi = 0; pyi < mergedTests.length; pyi++) {
      var pt = mergedTests[pyi];
      if (pt.order >= mt.order) continue;
      if (groupSubject && pt.subject !== groupSubject) continue;
      if (typeOf(pt) !== "STAAR") continue;
      cand[pt.order] = { test: pt, sat: 0 }; any = true;
    }
    if (!any) return null;
    var ids = {};
    for (var pu = 0; pu < pupils.length; pu++) if (pupils[pu].localId) ids[pupils[pu].localId] = true;
    // `pupils` are this paper's flattened rows, which carry no test history, so each candidate
    // is counted by matching ids against its own flattened rows (cached per paper per run).
    var maxSat = 0;
    for (var co in cand) {
      var cFlat = flattenStudentsForTest(cand[co].test, allStudents, blockQuestions, allExcluded);
      for (var cf = 0; cf < cFlat.length; cf++) if (ids[cFlat[cf].localId]) cand[co].sat++;
      if (cand[co].sat > maxSat) maxSat = cand[co].sat;
    }
    // Nobody in front of us sat ANY earlier STAAR in this subject: grade 3 (the first STAAR year),
    // a class of newcomers, or earlier papers not loaded. That is "no earlier STAAR" for THESE
    // pupils, not "nobody sat this particular paper", so it is reported as such.
    if (maxSat === 0) return null;
    // The NEWEST paper at least half as many of them sat as the best-attended one. "Most sat"
    // alone lets a paper from two years back win by a single pupil who missed last May.
    var best = null, floor = Math.max(1, Math.ceil(maxSat / 2));
    for (var co2 in cand) {
      var cc = cand[co2];
      if (cc.sat < floor) continue;
      if (!best || cc.test.order > best.order) best = cc.test;
    }
    var prevFlat = flattenStudentsForTest(best, allStudents, blockQuestions, allExcluded), rows = [];
    for (var pf = 0; pf < prevFlat.length; pf++) if (ids[prevFlat[pf].localId]) rows.push(prevFlat[pf]);
    if (rows.length === 0) return { test: best, stats: {}, n: 0, ids: {} };
    var had = {};
    for (var hr = 0; hr < rows.length; hr++) had[rows[hr].localId] = true;
    return { test: best, n: rows.length, ids: had,
             stats: tekStatsForGroup(rows, primaryQuestionsEx(best, blockQuestions),
                                     getExclNumsEx(best, allExcluded)) };
  }

  // teacher -> section -> full pupil records (every pupil, whatever they sat)
  var byTeacher = {}, teacherOrder = [], secSubject = {};
  var placeSubjects = subjectsInRun.length ? subjectsInRun : [""];
  for (var i = 0; i < allStudents.length; i++) {
    var s = allStudents[i];
    for (var ps = 0; ps < placeSubjects.length; ps++) {
      var subj = placeSubjects[ps];
      // A pupil joins a subject's roster only if they sat a paper in it. A
      // maths-only pupil must not appear on an English teacher's tab as
      // "no result".
      if (subj) {
        var satSubj = false, sks = Object.keys(s.testScores);
        for (var sk = 0; sk < sks.length && !satSubj; sk++) {
          var sr = s.testScores[sks[sk]];
          if (sr.tookTest && (testByOrder[sr.order] || {}).subject === subj) satSubj = true;
        }
        if (!satSubj) continue;
      }
      // STRICT: a pupil's maths teacher must come from a maths paper. See
      // placementFor -- the loose fallback handed English teachers maths
      // rosters whenever the maths export named no instructor.
      var pl  = placementFor(s, subj, true);
      var tch = pl.instructor || "(No instructor listed)";
      // Grouping by period merges the several sections a teacher may hold in
      // one period into the one class they actually teach. Falls back to
      // section when the export carries no Current Period.
      var sec = groupNameOf(pl, subj);
      if (!byTeacher[tch]) { byTeacher[tch] = {}; secSubject[tch] = {}; teacherOrder.push(tch); }
      if (!byTeacher[tch][sec]) { byTeacher[tch][sec] = []; secSubject[tch][sec] = subj; }
      byTeacher[tch][sec].push(s);
    }
  }
  teacherOrder.sort();

  // The subject the section being built belongs to. Every paper-selection
  // helper below reads it, so an English period can only ever be offered
  // English papers -- however many maths papers its pupils also sat.
  var groupSubject = "";
  function paperInScope(order) {
    if (!groupSubject) return true;
    var t0 = testByOrder[order];
    return !!t0 && t0.subject === groupSubject;
  }

  /**
   * Which paper this section's PLC table is built from.
   *
   * Ranked on three things, in order:
   *   1. Build Views? = Yes in the Test Registry -- this is the control. Tick
   *      the paper you want the PLC to show.
   *   2. How many of this section actually sat it.
   *   3. The newer paper.
   *
   * The old version used pupil count alone and stopped at the first order to
   * reach the top count, so a section that sat last year's STAAR AND this
   * year's benchmark -- the same pupils, the same count -- landed on whichever
   * happened to be visited first. That is a coin toss, and it is exactly the
   * case that arises once a current-year test is loaded beside a prior STAAR.
   *
   * Whatever wins, the section header reports how many of the roster sat it,
   * so a paper only half the class took cannot hide.
   */
  function testForSection(members, allow) {
    var tally = {};
    for (var mi = 0; mi < members.length; mi++) {
      var ks = Object.keys(members[mi].testScores);
      for (var ki = 0; ki < ks.length; ki++) {
        var r = members[mi].testScores[ks[ki]];
        if (!r.tookTest || !paperInScope(r.order)) continue;
        tally[r.order] = (tally[r.order] || 0) + 1;
      }
    }
    var best = null, bestKey = null;
    var orders = Object.keys(tally);
    for (var oi = 0; oi < orders.length; oi++) {
      var ord = parseInt(orders[oi], 10);
      var t   = testByOrder[ord];
      if (!t) continue;
      if (allow && !allow(t)) continue;
      var key = [t.buildViews ? 1 : 0, tally[ord], ord];
      if (bestKey === null ||
          key[0] > bestKey[0] ||
          (key[0] === bestKey[0] && key[1] > bestKey[1]) ||
          (key[0] === bestKey[0] && key[1] === bestKey[1] && key[2] > bestKey[2])) {
        bestKey = key; best = ord;
      }
    }
    return best === null ? null : testByOrder[best];
  }

  /** Did this pupil sit the paper on `order`? */
  function satPaper(stu, order) {
    var ks = Object.keys(stu.testScores);
    for (var i2 = 0; i2 < ks.length; i2++) {
      var r2 = stu.testScores[ks[i2]];
      if (r2.order === order && r2.tookTest && paperInScope(order)) return true;
    }
    return false;
  }

  /**
   * Every paper needed to cover this group, best first.
   *
   * Grouping by class period can put two grade levels in one group -- a teacher
   * with a combined class holds pupils on different papers at the same hour.
   * Showing only the biggest paper would hide the other cohort, which is the
   * same failure as the old whole-tab single test (144 on the roster, 41 on the
   * tab). So: pick the best paper, drop everyone it covers, and repeat on who
   * is left. A group whose pupils all sat one paper -- almost all of them --
   * yields exactly one, and nothing about that case changes.
   */
  /** How many of `members` sat each paper. */
  function paperTally(members) {
    var tally = {};
    for (var mt2 = 0; mt2 < members.length; mt2++) {
      var ks2 = Object.keys(members[mt2].testScores);
      for (var kt2 = 0; kt2 < ks2.length; kt2++) {
        var rr2 = members[mt2].testScores[ks2[kt2]];
        if (rr2.tookTest && paperInScope(rr2.order)) tally[rr2.order] = (tally[rr2.order] || 0) + 1;
      }
    }
    return tally;
  }

  function papersForGroup(members) {
    var tally = paperTally(members), i3;
    pickMissed = "";

    // THE TYPE IS HONOURED ABSOLUTELY. This is the fix for the fault Austin
    // reported: adding DCBs pushed STAAR off the teacher tabs. Each period gets
    // ONE TEK table, and the old rule gave it to whichever paper most of the
    // class had sat -- which, once unit tests arrive every few weeks, is a DCB.
    // Nothing about the tab looked wrong; it was simply answering a different
    // question from the one it was opened to answer.
    var wantType = PC.paperType || PLC_TYPE_DEFAULT;

    var orders = [];
    for (var o2 in tally) orders.push(parseInt(o2, 10));

    function eligible(ord) {
      var t = testByOrder[ord];
      if (!t || !paperInScope(ord)) return false;
      // The TYPE is the only gate. There used to be a second one -- a per-type
      // "Can be the TEK table? (0 = never)" column -- and two controls for one
      // decision is how a teacher ends up unable to say what the tab is showing.
      // Picking the type says it outright.
      return typeOf(t) === wantType;
    }
    var elig = [];
    for (i3 = 0; i3 < orders.length; i3++) if (eligible(orders[i3])) elig.push(orders[i3]);

    /**
     * Most of THIS class first, then the English form, then the newer paper.
     * Ranking on the order number alone once handed a period's only table to a
     * paper ONE held-back pupil had sat, because two papers from the same May
     * are ordered alphabetically and "Grade 7" sorts after "Grade 6".
     */
    function paperRankKey(ord) {
      var t = testByOrder[ord];
      var isES = t && /spanish/i.test(String(t.label || "")) ? 0 : 1;
      // Build Views leads, INSIDE the chosen type. Ticking a paper there is a
      // teacher saying "this one", and it has to outrank a head count or the
      // tick does nothing. It cannot cross the type line: picking STAAR and
      // ticking a benchmark still gets you the STAAR, which is the whole point
      // of the type being chosen first.
      return [t && t.buildViews ? 1 : 0, tally[ord] || 0, isES, ord];
    }
    function byPaperRank(a, b) {
      var ka = paperRankKey(a), kb = paperRankKey(b);
      for (var i = 0; i < ka.length; i++) if (ka[i] !== kb[i]) return kb[i] - ka[i];
      return 0;
    }
    elig.sort(byPaperRank);

    // A NAMED test wins outright, when this class actually sat it. Going back
    // to an older paper means looking at that paper; whoever has no row on it
    // is named under "no data on this paper" rather than quietly shown another.
    var wantName = String(PC.paperName || "").trim();
    if (wantName) {
      for (i3 = 0; i3 < elig.length; i3++) {
        if (String(testByOrder[elig[i3]].label || "").trim() === wantName) {
          return [testByOrder[elig[i3]]];
        }
      }
      pickMissed = wantName;           // named, but nobody in this class sat it
    }

    if (elig.length === 0) {
      // Nothing of the chosen type for this class. Say so on the table rather
      // than silently substituting another type -- substituting is the bug.
      pickMissed = pickMissed || ("no " + wantType + " paper");
      return [];
    }

    var out = [testByOrder[elig[0]]], chosen = {};
    chosen[elig[0]] = true;

    // COVERAGE, still within the chosen type and the same administration. A
    // combined class spanning two grade levels sat two papers in one year and
    // both belong here; an OLDER paper does not, or a single absence would
    // earn the period a second table from a previous year.
    var newestYear = 0;
    for (i3 = 0; i3 < elig.length; i3++) {
      var yy = yearFromDate(testByOrder[elig[i3]].date);
      if (yy > newestYear) newestYear = yy;
    }
    var left = [];
    for (var mi2 = 0; mi2 < members.length; mi2++) {
      if (!satPaper(members[mi2], out[0].order)) left.push(members[mi2]);
    }
    while (left.length > 0 && out.length < PLC_CONTENT_DEFAULT.maxTables) {
      var pick = null;
      var sub = paperTally(left);
      var cand = [];
      for (var c2 in sub) {
        var co = parseInt(c2, 10);
        if (chosen[co] || !eligible(co)) continue;
        if (yearFromDate(testByOrder[co].date) !== newestYear) continue;
        cand.push(co);
      }
      if (!cand.length) break;
      cand.sort(function (a, b) { return (sub[b] || 0) - (sub[a] || 0) || b - a; });
      pick = cand[0];
      out.push(testByOrder[pick]);
      chosen[pick] = true;
      var still = [];
      for (i3 = 0; i3 < left.length; i3++) if (!satPaper(left[i3], pick)) still.push(left[i3]);
      if (still.length === left.length) break;
      left = still;
    }

    out.sort(function (a, b) { return byPaperRank(a.order, b.order); });
    return out;
  }

  // The flattened rows carry no history, so keep a way back to the full record.
  var byId = {};
  for (var bx = 0; bx < allStudents.length; bx++) {
    byId[allStudents[bx].localId || allStudents[bx].name] = allStudents[bx];
  }

  // Year and cut-table grade label for every paper, worked out once. The grade
  // label comes from the TEK codes on the paper's own questions, not the title.
  var yearByOrder = {}, gradeByOrder = {};
  for (var yo = 0; yo < mergedTests.length; yo++) {
    var mtY = mergedTests[yo];
    yearByOrder[mtY.order]  = yearFromDate(mtY.date);
    gradeByOrder[mtY.order] = cutGradeLabelFor(primaryQuestionsEx(mtY, blockQuestions));
  }

  /**
   * Growth for one pupil into `mt`, against the paper they sat the year before.
   * Returns growthBetween()'s shape, so the reason travels with the null.
   */
  function pupilGrowth(full, mt) {
    if (!full) return { points: null, reason: "no pupil record" };
    var curYear = yearByOrder[mt.order];
    var keys = Object.keys(full.testScores), cur = null, prior = null;
    for (var i = 0; i < keys.length; i++) {
      var r = full.testScores[keys[i]];
      var ry = yearByOrder[r.order];
      if (!r.tookTest) continue;
      if (r.order === mt.order) cur = r;
      // Same subject only. With two subjects loaded the last prior-year paper
      // seen could be the OTHER subject, and growthBetween then reported
      // "different subject" for a pupil who had a perfectly good pair.
      else if (ry === curYear - 1 &&
               (testByOrder[r.order] || {}).subject === (mt.subject || "")) prior = r;
    }
    function shape(rec, mtx) {
      if (!rec) return null;
      var ord = rec.order;
      return { tookTest: rec.tookTest, year: yearByOrder[ord],
               gradeLabel: gradeByOrder[ord], subject: (testByOrder[ord] || {}).subject || "",
               scaleScore: rec.scaleScore, rawScore: rec.rawScore,
               hasRawScore: rec.hasRawScore, scoreCode: rec.scoreCode,
               language: rec.language };
    }
    return growthBetween(shape(prior), shape(cur));
  }

  var used = {}, built = 0;
  PLC_TABS_BUILT = {};

  // ONE TAB PER TEACHER PER SUBJECT.
  //
  // A teacher with one subject gets one tab named as before. A teacher with
  // two -- a special education teacher holding both English and maths is the
  // case that asked for this -- gets one tab per subject, so they read one
  // subject at a time instead of scrolling past the other. Each tab is then
  // single-subject by construction, which is why the column headings need no
  // M / E prefix on them any more.
  var plcTabs = [];
  for (var to = 0; to < teacherOrder.length; to++) {
    var tName = teacherOrder[to];
    var tSubs = teacherSubjectsOf(secSubject[tName]);
    // The Config wins. Its subject ticks are pre-filled from the export but a
    // teacher may have corrected them, and a correction is the whole point:
    // an automatic split gave a maths teacher a near-empty English tab off
    // two stray rows. Anything ticked that this teacher has no pupils in is
    // dropped rather than producing an empty tab.
    var picked = teacherSubjCfg ? teacherSubjCfg[tName] : null;
    if (picked) {
      var keep = [];
      for (var ks = 0; ks < tSubs.length; ks++) if (picked[tSubs[ks]]) keep.push(tSubs[ks]);
      if (keep.length > 0) tSubs = keep;
    }
    if (tSubs.length > 1) {
      for (var tsx = 0; tsx < tSubs.length; tsx++) plcTabs.push({ teacher: tName, subject: tSubs[tsx] });
    } else if (tSubs.length === 1) {
      // Carry the subject so the OTHER subject's sections are filtered out,
      // even though this teacher gets only one tab.
      plcTabs.push({ teacher: tName, subject: picked ? tSubs[0] : "" });
    } else {
      plcTabs.push({ teacher: tName, subject: "" });        // "" = every section they have
    }
  }
  // The subject belongs in the TAB NAME only where a teacher has two tabs to
  // tell apart. A teacher narrowed to one subject is still just their name --
  // "PLC_Reed, Ms - Math" on a teacher who only ever teaches maths is noise.
  var tabsPerTeacher = {};
  for (var tc0 = 0; tc0 < plcTabs.length; tc0++) {
    tabsPerTeacher[plcTabs[tc0].teacher] = (tabsPerTeacher[plcTabs[tc0].teacher] || 0) + 1;
  }
  for (var tc1 = 0; tc1 < plcTabs.length; tc1++) {
    plcTabs[tc1].nameSuffix = tabsPerTeacher[plcTabs[tc1].teacher] > 1 ? plcTabs[tc1].subject : "";
  }

  PROGRESS.begin(ss, "Building teacher tabs", plcTabs.length);
  for (var ti = 0; ti < plcTabs.length; ti++) {
    var teacher     = plcTabs[ti].teacher;
    var tabSubject  = plcTabs[ti].subject;
    var allSections = byTeacher[teacher];
    // One breadcrumb per tab: if Google kills the run at the six-minute limit,
    // the execution log says which tab it died on and how many were done.
    RUN_TRACE.at("PLC tab " + (ti + 1) + " of " + plcTabs.length,
                 teacher + (plcTabs[ti].nameSuffix ? "  --  " + plcTabs[ti].nameSuffix : ""));
    // Only this tab's subject, when the teacher was split across two.
    var sections = allSections;
    if (tabSubject) {
      sections = {};
      for (var asx in allSections) {
        if ((secSubject[teacher] || {})[asx] === tabSubject) sections[asx] = allSections[asx];
      }
    }
    var secNames = Object.keys(sections).sort(function (a, b) {
      var ka = sectionSortKey(a), kb = sectionSortKey(b);
      return ka !== kb ? ka - kb : (a < b ? -1 : a > b ? 1 : 0);
    });
    if (secNames.length === 0) continue;

    var teacherTotal = 0;
    for (var sc = 0; sc < secNames.length; sc++) teacherTotal += sections[secNames[sc]].length;

    // Tests oldest-first for the trajectory block down the right-hand side.
    //
    // SCOPED TO WHAT THIS TEACHER TEACHES. The strip used to carry every paper
    // in the run, so with maths and English loaded together a maths teacher's
    // "class over time" was half English columns -- and the cap of N newest
    // papers, applied across both subjects, then threw away the older years of
    // each. See trajTestsFor for both rules. The timeline shows only the types
    // ticked in PLC CONTENT.
    var teacherSubjects = tabSubject ? [tabSubject] : teacherSubjectsOf(secSubject[teacher]);
    // Every tab is one subject now, so a column heading never has to say which
    // subject it is -- the tab name and the banner already do.
    var stripMulti = false;
    // EACH GROUP'S STRIP SHOWS ITS OWN SUBJECT, AND ONLY ITS OWN.
    //
    // This was scoped to the union of the teacher's subjects, on a reading of
    // "put maths and English on the same one". That was the wrong reading: an
    // English period's strip is the English story, and a maths column in it is
    // noise whoever teaches the room. A teacher who holds both still sees both
    // on the tab -- one strip per period, each in its own subject.
    //
    // Within a group it is then narrowed again to the papers ITS OWN pupils
    // sat, so a Maths 6 class carries no Maths 7 or 8 paper, and capped per
    // subject. The grid is as wide as the widest group.
    var timelineTests = mergedTests.filter(onTimeline);
    var stripByGroup = {}, stripWidth = 0;
    for (var sg = 0; sg < secNames.length; sg++) {
      var sgSubj = (secSubject[teacher] || {})[secNames[sg]] || "";
      var sgSubjects = sgSubj ? [sgSubj] : teacherSubjects;
      var sgCand = trajTestsFor(timelineTests, sgSubjects, 0);
      var sgList = stripTestsFor(sgCand, sections[secNames[sg]], sgSubjects, PC.timelineMax);
      stripByGroup[secNames[sg]] = sgList;
      if (sgList.length > stripWidth) stripWidth = sgList.length;
    }
    // MAP checkpoints per group: the group's subject only, two columns per
    // term (RIT coloured by NWEA's projected STAAR level, then the growth
    // call). Off when PLC CONTENT unticks MAP on the strip.
    var mapColsByGroup = {}, mapWidth = 0;
    for (var mg = 0; mg < secNames.length; mg++) {
      var mgSubj = (secSubject[teacher] || {})[secNames[mg]] || "";
      var mgCols = (PC.timeline && PC.timeline.MAP === false) ? [] : mapCheckpointsFor(sections[secNames[mg]], mgSubj);
      mapColsByGroup[secNames[mg]] = mgCols;
      if (mgCols.length > mapWidth) mapWidth = mgCols.length;
    }
    // Interleave each group's STAAR papers and MAP checkpoints by date.
    var colsByGroup = {}, colsWidth = 0;
    for (var cg2 = 0; cg2 < secNames.length; cg2++) {
      // RENAMED from `built` (master 2026-09-24, ported 2026-10-06). `var` is function-scoped, so
      // this shared one variable with the tab counter above: `built++` ran on a columns object,
      // the function returned NaN, and "Per-teacher PLC tabs: N" fell out of the completion alert.
      var groupCols = stripColumnsFor(stripByGroup[secNames[cg2]] || [], mapColsByGroup[secNames[cg2]] || []);
      colsByGroup[secNames[cg2]] = groupCols;
      if (groupCols.width > colsWidth) colsWidth = groupCols.width;
    }
    var trajTests = [], mapCols = [], cols = [];
    // Everything this tab ends up using, gathered as it is drawn, for the
    // one note on the banner that says whether the run pulled the right tests.
    var tabPapers = [], tabPaperSeen = {}, tabMapCps = [], tabMapSeen = {};
    // ... then two blank columns, then the key.
    var keyCol = PLC_TRAJ_START + 1 + colsWidth + 2;
    var g = new Grid(keyCol + MAP_KEY_COLS);
    var keyDrawn = false;

    var plcBannerRow = g.header((byPeriod ? "PLC BY CLASS PERIOD  --  " : "PLC BY SECTION  --  ") + teacher
             + (teacherSubjects.length ? "  --  " + teacherSubjects.join(" + ") : "")
             + (plcTabs[ti].nameSuffix ? "   (this teacher has a separate tab for each subject)" : ""),
             C.hdr, C.hdrTxt, 14, PLC_SECTION_COLS, 30);
    g.header(secNames.length + (byPeriod ? " class period(s)   |   " : " section(s)   |   ")
      + teacherTotal + " pupils on roster"
      + "   |   each section is scored against the paper its own pupils sat, so a teacher "
      + "spanning two grades sees both",
      C.sectionBg, "#000000", 10, PLC_SECTION_COLS, 22, false);
    g.header("Ranked worst first by GAP -- how far this period sits below the benchmark. The "
      + "benchmark is named in the \"vs\" column. \"State avg\" is a MULTI-YEAR average across "
      + "released tests, NOT this year's state result -- TEA publishes that much later. "
      + "\"State '25\" is a real published figure for that year. \"All others\" means every other "
      + "pupil who sat this same test.   |   "
      + "\"This Period\" against \"My Other Periods\" is the column that decides what to do: low in "
      + "both is a whole-class reteach, low in one period only is a warm-up for that period.   |   "
      + "Every number is a real number, so click any column header to re-sort.",
      C.warn, "#000000", 9, PLC_SECTION_COLS, 38, false);
    g.row(6);

    for (var si2 = 0; si2 < secNames.length; si2++) {
      var secName = secNames[si2];
      var roster  = sections[secName];
      groupSubject = (secSubject[teacher] || {})[secName] || "";
      trajTests    = stripByGroup[secName] || [];
      mapCols      = mapColsByGroup[secName] || [];
      cols         = colsByGroup[secName].cols;

      var papers = papersForGroup(roster);
      var secStart = g.v.length;
      var shownIds = {};
      // The picked test is not one this class sat. Say so where the table is,
      // rather than showing a different paper under the name of the pick.
      if (pickMissed) {
        g.header(secName + "   --   nobody in this period sat \"" + pickMissed
                 + "\", the test picked on the Config tab, so this is "
                 + paperListLabel(papers) + " instead.",
                 C.warn, "#000000", 10, PLC_SECTION_COLS, 26, false);
      }
      if (papers.length > 1) {
        g.header(secName + "   --   this period sat " + papers.length + " papers in the same "
                 + "administration, which is two grade levels in one class, so there is a table "
                 + "each: " + paperListLabel(papers)
                 + ".   Papers nobody in this group sat are never shown.",
                 C.warn, "#000000", 10, PLC_SECTION_COLS, 26, false);
      }

      // Nobody in this group sat any paper. It used to vanish from the tab
      // entirely, which is the worst possible answer to "have we missed
      // anyone" -- a teacher cannot see an absence that was never drawn.
      if (papers.length === 0) {
        if (showAbsent) {
          g.header(secName + "      \u2014      no results for anyone in this group",
                   C.alert, C.alertTxt, 12, PLC_SECTION_COLS, 24);
          g.headerRow(["Student", "SpEd", "EB", "ED", "Why there is no data"],
                      C.sectionBg, 22);
          for (var nz = 0; nz < roster.length; nz++) {
            var nbg = nz % 2 === 0 ? C.white : C.zebra;
            g.row(18);
            g.set(0, roster[nz].name, { bg: nbg, size: 9 });
            g.set(1, roster[nz].sped === "Yes" ? "SpEd" : "", { bg: nbg, align: "center", size: 9 });
            g.set(2, shortEB(roster[nz].eb) === "EB" ? "EB" : "", { bg: nbg, align: "center", size: 9 });
            g.set(3, roster[nz].econDis === "Yes" ? "ED" : "", { bg: nbg, align: "center", size: 9 });
            g.set(4, "no test data anywhere in this workbook", { bg: nbg, size: 9 });
          }
          g.row(10);
        }
        continue;
      }

      for (var pgi = 0; pgi < papers.length; pgi++) {
        var mt = papers[pgi];

      // Everything below is relative to THIS section's paper.
      var qs        = primaryQuestionsEx(mt, blockQuestions);
      var exclNums  = getExclNumsEx(mt, allExcluded);
      var adjMaxAll = calcAdjMaxPtsEx(qs, exclNums);
      var testYr    = yearFromDate(mt.date);
      var flat      = flatFor(mt);
      var allStats  = tekStatsForGroup(flat, qs, exclNums);
      var thisGrp   = teacher + "||" + secName;

      var pupils = [];
      for (var fp = 0; fp < flat.length; fp++) {
        if (flat[fp].__grp === thisGrp) pupils.push(flat[fp]);
      }
      if (pupils.length === 0) continue;

      // This teacher's OTHER periods, but only those on the same paper --
      // comparing a Maths 6 class with a Maths 7 class compares two different
      // tests and means nothing.
      var othersAll = [];
      for (var oj = 0; oj < flat.length; oj++) {
        var og = flat[oj].__grp;
        if (og !== thisGrp && og.indexOf(teacher + "||") === 0) othersAll.push(flat[oj]);
      }

      // Everyone on this paper EXCEPT this period, whoever teaches them.
      // Including this period's own pupils would collapse every gap toward zero
      // for a teacher holding most of the cohort.
      var elsewhereAll = [];
      for (var ei = 0; ei < flat.length; ei++) {
        if (flat[ei].__grp !== thisGrp) elsewhereAll.push(flat[ei]);
      }

      var secHdrRow = g.header(secName + "      \u2014      " + mt.label, C.subHdr, C.subTxt, 12,
               PLC_SECTION_COLS, 24);

      var rosterN = roster.length;
      // Which paper this table is, on hover. papersForGroup now ranks by how
      // many of the group sat a paper, so the count is also the reason this
      // one is here rather than another -- which is what the held-back-pupil
      // fault turned on.
      var satHere = 0;
      for (var shq = 0; shq < roster.length; shq++) {
        var shk = Object.keys(roster[shq].testScores || {});
        for (var shr = 0; shr < shk.length; shr++) {
          var shrec = roster[shq].testScores[shk[shr]];
          if (shrec.order === mt.order && shrec.tookTest) { satHere++; break; }
        }
      }
      g.noteAt(secHdrRow, 0, testProvenance(mt, {
        grade: gradeByOrder[mt.order] || "",
        questions: primaryQuestionsEx(mt, blockQuestions).length,
        sat: satHere, of: rosterN,
        why: papers.length > 1
          ? ("This group has " + papers.length + " tables, one per paper, most-sat first.")
          : "This is the paper most of this group sat."
      }));
      if (!tabPaperSeen[mt.order]) { tabPaperSeen[mt.order] = true; tabPapers.push(mt); }

      // -- One block per FORM ------------------------------------------------
      // A period with English and Spanish testers in it gets two tables, one
      // under the other, never one merged average. The items are identical, so
      // the TEK rankings mean the same thing in both; the benchmark is not, so
      // each cohort is measured against pupils who sat the same form.
      var allPupilsInSec = pupils;
      var cohorts        = cohortsByForm(pupils);
      if (cohorts.length > 1) {
        g.header("This period sat BOTH forms of this paper, so it is reported twice below. "
                 + "Same items, same question numbers, same TEKs -- what a pupil got wrong "
                 + "means the same thing either way. The BENCHMARK differs: pupils who sit "
                 + "the Spanish paper score lower on 99% of items, about 13 points, so each "
                 + "cohort is compared with the pupils who actually sat their form.",
                 C.warn, "#000000", 9, PLC_SECTION_COLS, 30, false);
      }

      // Growth sits FIRST, above the TEK ranking.
      //
      // It used to be the last block on a very long tab, which in practice
      // meant it did not exist -- nobody scrolled that far. Diagnosis before
      // cause before action: did my pupils move, then why, then what to do.

        // -- Growth: what this group brought with them ------------------------
        // Deliberately framed as a description of the INCOMING pupils, not of the
        // teacher. It is last year's movement, computed the way the state does
        // it, so a teacher can see what the campus is carrying into this year.
        {
          var gMt = mt, gRows = [], gPts = 0, gN = 0, gAcc = 0, gSkip = [];
          // TEA's progress measure runs STAAR to STAAR. Under a benchmark it
          // filled a screen with "no prior-year STAAR in this workbook" for
          // pupils who plainly have one -- last May's, in the same school year,
          // which the rule cannot use because it needs consecutive years. So on
          // a benchmark the block is one sentence pointing at the column that
          // does answer the question, TEK by TEK.
          if (typeOf(mt) !== "STAAR") {
            g.row(8);
            g.header("GROWTH INTO THIS PAPER is not shown for a benchmark. The state's progress "
                     + "measure runs from one STAAR to the next, and a benchmark has no STAAR band "
                     + "to score. Growth for this paper is the \"Last year, same students\" column "
                     + "in the table above: each TEK against the standard it grows out of, for the "
                     + "pupils who were here last year.",
                     C.warn, "#000000", 9, PLC_SECTION_COLS, 26, false);
            gSkip = [];
          } else {
          for (var gi3 = 0; gi3 < roster.length; gi3++) {
            var gr = pupilGrowth(roster[gi3], gMt);
            if (gr.points === null) { gSkip.push({ stu: roster[gi3], why: gr.reason }); continue; }
            gPts += gr.points; gN++; if (gr.accelerated) gAcc++;
            gRows.push({ stu: roster[gi3], g: gr });
          }
          if (gN > 0 || gSkip.length > 0) {
            var expected = gN * GROWTH_EXPECTED_PER_PUPIL;
            var earned   = gPts + gAcc * 0.25;
            var pctG     = gN ? Math.round(earned / gN * 100) : 0;
            g.row(8);
            // Name the paper. The block used to sit after the paper loop and
            // always score papers[0], so with two papers it rendered underneath
            // the OLDER table while scoring the newer one -- and never said which.
            // It is now inside the loop, scoring the paper it sits under.
            g.header("GROWTH INTO THIS PAPER  --  " + secName + "   --   " + mt.label,
                     "#1a237e", "#ffffff", 12, PLC_SECTION_COLS, 24);
            g.header("This is last year's movement for the pupils you are RECEIVING, scored the "
                     + "way the state scores it. It describes the group, not the teaching -- nobody "
                     + "in this room taught these results. It is here so you know what the campus "
                     + "is carrying into this paper.   |   Expected is "
                     + GROWTH_EXPECTED_PER_PUPIL + " point per pupil.",
                     C.warn, "#000000", 9, PLC_SECTION_COLS, 26, false);
            g.row(20);
            g.set(0, "Pupils scored", { bg: C.sectionBg, bold: true });
            g.set(1, gN, { bg: C.white, align: "center", bold: true });
            g.set(2, "Points earned", { bg: C.sectionBg, bold: true });
            // 2dp, not 1: accelerated learning adds quarter points, and 6.75
            // rounded to 6.8 hides the very component it came from.
            g.set(3, Math.round(earned * 100) / 100, { bg: C.white, align: "center", bold: true });
            g.set(4, "Expected", { bg: C.sectionBg, bold: true });
            g.set(5, expected, { bg: C.white, align: "center" });
            g.set(6, "Of expected", { bg: C.sectionBg, bold: true });
            g.set(7, pctG, { bg: pctG >= 100 ? C.strandGood : pctG >= 70 ? C.strandMid : C.strandBad,
                             align: "center", bold: true, fmt: "0\"%\"" });
            if (gAcc > 0) {
              g.set(8, gAcc + " accelerated (Did Not Meet -> Approaches+)",
                    { bg: C.sectionBg, size: 9, wrap: true });
            }
            // Who could not be scored, and why -- new arrivals live here.
            if (gSkip.length > 0) {
              g.row(18);
              g.set(0, "Not scored", { bg: C.warn, bold: true });
              g.set(1, gSkip.length, { bg: C.warn, align: "center", bold: true });
              g.set(2, "why", { bg: C.sectionBg, bold: true });
              var whyTally = {};
              for (var wz = 0; wz < gSkip.length; wz++) {
                whyTally[gSkip[wz].why] = (whyTally[gSkip[wz].why] || 0) + 1;
              }
              var whyBits = [];
              for (var wk in whyTally) whyBits.push(whyTally[wk] + " " + wk);
              g.set(3, whyBits.join("   |   "), { bg: C.white, size: 9, wrap: true });
            }
            g.headerRow(["Student", "Last year", "This year", "Points", "Accelerated"],
                        C.sectionBg, 20);
            gRows.sort(function (a, b) { return a.g.points - b.g.points; });
            for (var gq = 0; gq < gRows.length; gq++) {
              var gbg2 = gq % 2 === 0 ? C.white : C.zebra;
              g.row(17);
              g.set(0, gRows[gq].stu.name, { bg: gbg2, size: 9 });
              g.set(1, ENHANCED_BAND_SHORT[gRows[gq].g.prior] || "",
                    { bg: rampBg(gRows[gq].g.prior, ""), fg: rampFg(gRows[gq].g.prior, ""),
                      size: 9, align: "center" });
              g.set(2, ENHANCED_BAND_SHORT[gRows[gq].g.current] || "",
                    { bg: rampBg(gRows[gq].g.current, ""), fg: rampFg(gRows[gq].g.current, ""),
                      size: 9, align: "center" });
              g.set(3, gRows[gq].g.points, { bg: gRows[gq].g.points >= 1 ? C.strandGood
                                               : gRows[gq].g.points > 0 ? C.strandMid : C.strandBad,
                                             align: "center", bold: true });
              g.set(4, gRows[gq].g.accelerated ? "yes" : "", { bg: gbg2, align: "center", size: 9 });
            }
            for (var gs2 = 0; gs2 < gSkip.length; gs2++) {
              var sbg = C.warn;
              g.row(17);
              g.set(0, gSkip[gs2].stu.name, { bg: sbg, size: 9 });
              g.set(1, "\u2013", { bg: sbg, align: "center" });
              g.set(2, "\u2013", { bg: sbg, align: "center" });
              g.set(3, "not scored", { bg: sbg, align: "center", size: 8 });
              g.set(4, gSkip[gs2].why, { bg: sbg, size: 8, wrap: true });
            }
          }
          }                                  // end: this paper is a STAAR paper
        }

        // -- PROJECTION: where they stood, where MAP says they are headed ----
        // Left: last STAAR beside MAP's projection for the NEXT one. Right, on
        // the same rows so a teacher reads straight across: the two growth
        // readings. Four bands, because four is all MAP can say -- the Low and
        // High halves are a TEA split and MAP does not attempt them.
        {
          var projRec = null, projYear = 0;
          for (var pj = 0; pj < roster.length && !projRec; pj++) {
            var pr0 = newestMAPFor(roster[pj], mt.subject);
            if (pr0 && mapLevelName(pr0.projectedProficiency)) { projRec = pr0; projYear = mapProjectionYear(pr0); }
          }
          if (projRec) {
            var wasN = {}, willN = {}, fb;
            for (var fb0 = 0; fb0 < FOUR_BANDS.length; fb0++) { wasN[FOUR_BANDS[fb0]] = 0; willN[FOUR_BANDS[fb0]] = 0; }
            // growth quadrants, counted over the same roster
            var q = { hh: [], hl: [], lh: [], ll: [] };
            for (var pk = 0; pk < roster.length; pk++) {
              var st0 = roster[pk];
              var bd  = pupilBandOn(st0, mt, blockQuestions);
              fb = fourBandOf(bd.fine, bd.coarse);
              if (fb) wasN[fb]++;
              var mr0 = newestMAPFor(st0, mt.subject);
              var lv0 = mr0 ? mapLevelName(mr0.projectedProficiency) : "";
              if (lv0) willN[lv0 === "Below" ? "Did Not Meet" : lv0]++;
              // TEA growth earned vs MAP conditional growth percentile
              var gr0 = pupilGrowth(st0, mt);
              var cgp = mr0 && mr0.condGrowthPercentile >= 0 ? mr0.condGrowthPercentile : -1;
              if (gr0.points === null || cgp < 0) continue;
              var teaOK = gr0.points >= 1, mapOK = cgp >= 50;
              (teaOK ? (mapOK ? q.hh : q.hl) : (mapOK ? q.lh : q.ll)).push(st0.name);
            }
            g.row(8);
            g.header("PROJECTION  --  " + secName + "   --   what they earned, and what MAP projects for the "
                     + (projYear ? "May " + projYear : "next") + " STAAR",
                     "#01579b", "#ffffff", 12, PLC_SECTION_COLS, 24);
            g.header("The right-hand figure is a PROJECTION, not a result: NWEA's, from this class's most recent MAP, "
                     + "for a test not yet sat. MAP reports four levels only -- the Low and High halves of Did Not Meet "
                     + "and Approaches are TEA's split and MAP does not attempt them, so this table is four rows deep "
                     + "while the strip on the right of this tab stays six.   |   "
                     + "On the right of this block, the same pupils counted two ways: TEA asks whether they moved a "
                     + "band, MAP asks whether they grew like similar pupils nationally. The two middle rows are the "
                     + "ones neither number finds alone.",
                     C.warn, "#000000", 9, PLC_SECTION_COLS, 40, false);
            g.headerRow(["Band", "STAAR " + (yearFromDate(mt.date) ? "May " + yearFromDate(mt.date) : "last"),
                         "MAP projects " + (projYear ? "May " + projYear : ""), "Change", "",
                         "Growth, two ways", "Pupils", "What it means"], C.sectionBg, 30);
            var qRows = [
              ["Earned TEA growth, MAP growth high", q.hh, ""],
              ["Earned TEA growth, MAP growth LOW",  q.hl, "coasting from a high start"],
              ["Missed TEA growth, MAP growth HIGH", q.lh, "growing fast from a low start"],
              ["Missed TEA growth, MAP growth low",  q.ll, ""]
            ];
            for (var fr = 0; fr < FOUR_BANDS.length; fr++) {
              var bn = FOUR_BANDS[fr], rk = fourBandRampKey(bn);
              var dlt = willN[bn] - wasN[bn];
              var rbg = fr % 2 === 0 ? C.white : C.zebra;
              g.row(20);
              g.set(0, bn, { bg: rampBg("", rk), fg: rampFg("", rk), bold: true, size: 9 });
              g.set(1, wasN[bn], { bg: rbg, align: "center", bold: true });
              g.set(2, willN[bn], { bg: rbg, align: "center", bold: true });
              g.set(3, (dlt > 0 ? "+" : "") + dlt,
                    { bg: rbg, fg: dlt > 0 ? "#1b5e20" : dlt < 0 ? "#b71c1c" : "#9e9e9e",
                      bold: dlt !== 0, align: "center" });
              g.set(5, qRows[fr][0], { bg: rbg, size: 9, bold: fr === 1 || fr === 2 });
              g.set(6, qRows[fr][1].length, { bg: rbg, align: "center", bold: true });
              g.set(7, qRows[fr][2] || (qRows[fr][1].length ? andMore(qRows[fr][1], 6, ", ") : ""),
                    { bg: rbg, size: 9, wrap: true, fg: qRows[fr][2] ? "#b26a00" : "#555555" });
            }
            var onTrackWas = wasN.Meets + wasN.Masters, onTrackWill = willN.Meets + willN.Masters;
            g.row(22);
            g.set(0, "On track for Meets or better", { bg: C.sectionBg, bold: true });
            g.set(1, onTrackWas,  { bg: C.white, align: "center", bold: true });
            g.set(2, onTrackWill, { bg: C.white, align: "center", bold: true });
            g.set(3, ((onTrackWill - onTrackWas) > 0 ? "+" : "") + (onTrackWill - onTrackWas),
                  { bg: C.white, bold: true, align: "center",
                    fg: onTrackWill >= onTrackWas ? "#1b5e20" : "#b71c1c" });
            g.set(5, "Named pupils behind each count are in the pull groups below.",
                  { bg: C.sectionBg, size: 9, fg: "#555555" });
            g.row(8);
          }
        }

        // -- TUTORING GROUPS FROM MAP ---------------------------------------
        // ONE ROW PER PUPIL, like the pull groups below. The first version put
        // a whole band's names in one cell: four pupils came to 118 characters
        // in a 130px column, about seven wrapped lines, which is not a list
        // anybody can read standing at a copier. The goal name gets its own
        // full-width heading so it is not squeezed into 140px either.
        {
          var tg = mapTutorGroups(roster, mt.subject);
          if (tg.length > 0) {
            var tgTerm = tg[0].term || "";
            g.row(8);
            g.header("TUTORING GROUPS FROM MAP  --  " + secName
                     + "   --   grouped by each goal area, weakest first",
                     "#6a1b9a", "#ffffff", 12, PLC_SECTION_COLS, 24);
            g.header("Grouped on the pupil's score IN THAT GOAL AREA, not on their overall MAP score. "
                     + "That is the point: the same child can be strong in one area and weak in "
                     + "another, and for a small group those are different children. One overall "
                     + "number would put them in the same group for everything.   |   "
                     + "Each area is THIS class sorted by that area's score and cut into groups of "
                     + "similar ability, because that is what you can teach in one sitting. Areas "
                     + "run weakest class average first, so the one worth pulling groups on is at "
                     + "the top.   |   "
                     + "The bands are cut from this class, not a national average; NWEA's own word "
                     + "(Lo, Avg, Hi) is beside each pupil so you can still see where they sit "
                     + "nationally."
                     + (tgTerm ? "   |   From the " + tgTerm + " MAP." : ""),
                     C.warn, "#000000", 9, PLC_SECTION_COLS, 40, false);

            for (var tgi = 0; tgi < tg.length; tgi++) {
              var G2 = tg[tgi];
              g.header(G2.name + "   --   class average " + G2.avg + " in this area"
                       + (tgi === 0 ? "   --   WEAKEST AREA, start here" : ""),
                       tgi === 0 ? "#4527a0" : "#7e57c2", "#ffffff", 11, PLC_SECTION_COLS, 22);
              g.headerRow(["Group", "Student", "RIT in this area", "NWEA", "Pull together"],
                          C.sectionBg, 22);
              for (var bi2 = 0; bi2 < G2.bands.length; bi2++) {
                var bd2 = G2.bands[bi2];
                var bandBg2 = bi2 === 0 ? C.strandBad
                            : bi2 === G2.bands.length - 1 ? C.strandGood : C.strandMid;
                for (var pz2 = 0; pz2 < bd2.pupils.length; pz2++) {
                  var pu = bd2.pupils[pz2], firstInBand = pz2 === 0;
                  var prow = (bi2 % 2 === 0) ? C.white : C.zebra;
                  g.row(19);
                  g.set(0, firstInBand ? bd2.label : "",
                        { bg: bandBg2, size: 9, bold: firstInBand && bi2 === 0 });
                  g.set(1, pu.name, { bg: prow, size: 9 });
                  g.set(2, pu.rit, { bg: prow, align: "center", bold: true });
                  g.set(3, pu.adj || "", { bg: prow, align: "center", size: 9, fg: "#555555" });
                  g.set(4, firstInBand
                            ? (bd2.pupils.length + " pupil(s), RIT " +
                               (bd2.lo === bd2.hi ? bd2.lo : bd2.lo + "-" + bd2.hi))
                            : "",
                        { bg: prow, size: 9, fg: "#555555" });
                }
              }
              g.row(6);
            }
            g.row(8);
          }
        }

      var others, elsewhere, secStats, otherStats, elsewhereStats, secPtsE, secAvg, allAvg;

      for (var ci = 0; ci < cohorts.length; ci++) {
        var cohLang  = cohorts[ci].lang;
        var split    = cohorts.length > 1;
        pupils    = cohorts[ci].pupils;
        others    = split ? sameForm(othersAll,    cohLang) : othersAll;
        elsewhere = split ? sameForm(elsewhereAll, cohLang) : elsewhereAll;
        var cohAll = split ? sameForm(flat, cohLang) : flat;

        secStats       = tekStatsForGroup(pupils, qs, exclNums);
        otherStats     = others.length    ? tekStatsForGroup(others, qs, exclNums)    : {};
        elsewhereStats = elsewhere.length ? tekStatsForGroup(elsewhere, qs, exclNums) : {};
        // These same pupils on last year's STAAR, for the growth column -- and
        // their figure on THIS paper too, because a class that has taken in new
        // students since is not the group that sat last year's test. Comparing
        // all twelve now against the nine who were here then would report
        // movement that belongs to the arrivals, not to anybody's teaching.
        var prevRef    = prevYearStatsFor(pupils, mt);
        var nowMatched = null;
        if (prevRef && prevRef.n > 0) {
          var matchedRows = [];
          for (var mri = 0; mri < pupils.length; mri++) {
            if (prevRef.ids[pupils[mri].localId]) matchedRows.push(pupils[mri]);
          }
          nowMatched = matchedRows.length ? tekStatsForGroup(matchedRows, qs, exclNums) : null;
        }

        secPtsE = 0;
        for (var pi = 0; pi < pupils.length; pi++) secPtsE += pupils[pi].adjScore;
        secAvg = pupils.length && adjMaxAll ? Math.round(secPtsE / pupils.length / adjMaxAll * 100) : 0;
        var allE = 0;
        for (var ai = 0; ai < cohAll.length; ai++) allE += cohAll[ai].adjScore;
        allAvg = cohAll.length && adjMaxAll ? Math.round(allE / cohAll.length / adjMaxAll * 100) : 0;

        if (split) {
          g.header((cohLang === "Spanish" ? "SPANISH FORM" : "ENGLISH FORM")
                   + "   --   " + pupils.length + " pupil(s) in this period",
                   cohLang === "Spanish" ? C.spanishTxt : "#37474f", "#ffffff",
                   11, PLC_SECTION_COLS, 22);
        }

      g.row(20);
      g.set(0, "Students with data", { bg: C.sectionBg, bold: true });
      g.set(1, pupils.length, { bg: C.white, align: "center", bold: true });
      g.set(2, "Period average", { bg: C.sectionBg, bold: true });
      g.set(3, secAvg, { bg: strandBg(secAvg), align: "center", bold: true, fmt: "0\"%\"" });
      g.set(4, split ? "All same-form students" : "All students",
            { bg: C.sectionBg, bold: true, size: split ? 9 : 10 });
      g.set(5, allAvg, { bg: C.white, align: "center", fmt: "0\"%\"" });
      g.set(6, "Difference", { bg: C.sectionBg, bold: true });
      g.set(7, secAvg - allAvg, {
        bg: (secAvg - allAvg) >= 0 ? C.strandGood : C.strandBad,
        align: "center", bold: true, fmt: "+0\"%\";-0\"%\";0\"%\""
      });
      if (split) {
        g.set(8, pupils.length + " of this period's " + rosterN + " pupils sat the "
                 + (cohLang === "Spanish" ? "Spanish" : "English") + " form"
                 + "; the rest are in the other block",
              { bg: C.sectionBg, size: 9, wrap: true });
      } else if (rosterN > pupils.length) {
        g.set(8, papers.length > 1
                 ? (pupils.length + " of this group's " + rosterN + " pupils sat this paper; "
                    + "the others are in the table(s) for their own paper")
                 : ("Section has " + rosterN + " pupils; " + (rosterN - pupils.length)
                    + " sat a different paper - they appear under their own test"),
              { bg: papers.length > 1 ? C.sectionBg : C.warn,
                fg: papers.length > 1 ? "#000000" : "#b71c1c", size: 9, wrap: true });
      } else if (pupils.length < MIN_GROUP_N) {
        g.set(8, "small group (n<" + MIN_GROUP_N + ") -- read with care",
              { bg: C.warn, fg: "#b71c1c", size: 9, wrap: true });
      }

      // lead4ward, linked not copied. One row per paper, because the documents
      // are per grade and subject rather than per TEK -- a link on every TEK
      // row would be thirty copies of the same three. Public URLs on
      // lead4ward.com, no login. The table lives in Ref_Lead4ward_Links.gs.
      var l4w = lead4wardLinksFor(mt.subject, gradeByOrder[mt.order],
                                  typeof cohLang === "string" ? cohLang : "");
      if (l4w) {
        // A light-blue row, blue underlined link text, and a label that says
        // what opens: "8th Grade Math Academic Vocab", not "Academic Vocabulary".
        var l4wWho = l4wLabel(mt.subject, gradeByOrder[mt.order],
                              typeof cohLang === "string" ? cohLang : "");
        g.row(22);
        for (var lc = 0; lc < PLC_SECTION_COLS; lc++) g.set(lc, "", { bg: L4W_ROW_BG });
        g.set(0, "lead4ward links", { bg: L4W_ROW_BG, fg: L4W_LINK_FG, bold: true, size: 10 });
        if (l4w.snapshot)   g.set(1, l4wLink(l4w.snapshot,   l4wWho + " TEKS Snapshot"),         L4W_LINK_OPTS);
        if (l4w.vocabulary) g.set(2, l4wLink(l4w.vocabulary, l4wWho + " Academic Vocab"),         L4W_LINK_OPTS);
        if (l4w.scaffold)   g.set(4, l4wLink(l4w.scaffold,   l4wWho + " TEKS Scaffold (Excel)"),  L4W_LINK_OPTS);
        g.set(8, typeof LEAD4WARD_CREDIT === "string" ? LEAD4WARD_CREDIT : "lead4ward.com",
              { bg: L4W_ROW_BG, fg: "#555555", size: 9 });
      }
      // TEA's released test for THIS paper: the questions themselves, the key,
      // and TEA's own rationale for every answer choice. This is what turns a
      // dominant wrong answer from a letter into something a teacher can read.
      var relYr = yearFromDate(mt.date);
      var rel   = releasedTestFor(relYr, gradeByOrder[mt.order], mt.subject,
                                  typeof cohLang === "string" ? cohLang : "");
      if (rel) {
        var relWho = relYr + " " + l4wLabel(mt.subject, gradeByOrder[mt.order],
                                            typeof cohLang === "string" ? cohLang : "");
        g.row(22);
        for (var rc = 0; rc < PLC_SECTION_COLS; rc++) g.set(rc, "", { bg: L4W_ROW_BG });
        g.set(0, "TEA released test", { bg: L4W_ROW_BG, fg: L4W_LINK_FG, bold: true, size: 10 });
        if (rel.form)      g.set(1, l4wLink(rel.form,      relWho + " STAAR: the questions"),        L4W_LINK_OPTS);
        if (rel.rationale) g.set(2, l4wLink(rel.rationale, relWho + " item rationales (why each answer is right or wrong)"), L4W_LINK_OPTS);
        if (rel.key)       g.set(6, l4wLink(rel.key,       relWho + " answer key"),                  L4W_LINK_OPTS);
        g.set(8, "TEA's own documents, public. Question numbers in this table match the released test.",
              { bg: L4W_ROW_BG, fg: "#555555", size: 9 });
      }

      var tekHeadRow = g.v.length;
      g.headerRow(["#", "TEK", "Was / becomes", "R/S", "Questions", "This Period",
                   "My Other Periods", "All Other Students", "State", "Gap", "vs",
                   "Priority", "Not yet mastered", "Last year, same students"],
                  C.sectionBg, 34);
      // A blank "Was / becomes" column has two causes and the cell cannot say which. Said once,
      // here, when the reason is that we hold no chart for this subject at all -- otherwise a
      // teacher reads an empty column as "TEA lists nothing". Ported from the master 2026-10-06.
      if (!haveVertAlignChart(mt.subject)) {
        g.noteAt(tekHeadRow, 2,
          "Blank all the way down because this workbook holds no vertical alignment chart for "
          + (mt.subject || "this subject") + " -- not because TEA lists no earlier or later "
          + "standard.\n\nMath and ELA have the chart loaded; Science and History do not yet.");
      }

      // Rank the TEKs this period is weakest on.
      var rows = [];
      for (var k in secStats) {
        var info = secStats[k];
        if (info.possible === 0) continue;
        var secPct   = info.earned / info.possible;
        var oInfo    = otherStats[k];
        var otherPct = (oInfo && oInfo.possible > 0) ? oInfo.earned / oInfo.possible : null;
        var aInfo    = allStats[k];
        var allPct   = (aInfo && aInfo.possible > 0) ? aInfo.earned / aInfo.possible : null;
        // Not a STAAR paper -> no state figure, so the benchmark falls through
        // to "All others", which is the honest comparator for a local test.
        var statePct = mt.isSTAAR
                     ? getStateTEKPctEx(info.tek, mt.subject, testYr, cohLang) : null;

        // A Spanish-form cohort measured against ENGLISH state figures is not a
        // small bias, it is a false alarm. Grade 5 Maths: the English figure runs
        // a median 15 points above the Spanish one, and the priority bands are
        // 10-20 points wide. Simulated on a cohort sitting EXACTLY at the Spanish
        // state average -- a perfectly typical class -- English figures relabel
        // 34 of 36 TEKs as "URGENT RETEACH" or "Strategic Reteach" instead of the
        // "Monitor" all 36 deserve. So when we hold no Spanish figure we show
        // none, and the benchmark falls through to pupils who sat the same form.
        // That is the rule Midlo already chose for a paper with no state data.
        if (statePct !== null && cohLang === "Spanish" &&
            !getStateTEKIsESEx(info.tek, mt.subject, testYr, cohLang)) {
          statePct = null;
        }
        var eInfo    = elsewhereStats[k];
        var elsePct  = (eInfo && eInfo.possible > 0)
                       ? Math.round(eInfo.earned / eInfo.possible * 100) : null;

        // Severity = how far below the benchmark this period sits, in points.
        //
        // State average first: a class at 30% on a TEK the state also gets 30%
        // on has no gap to close, while a class at 55% where the state gets 75%
        // plainly does. A newly released STAAR has no published state figures
        // for a year or more, so the fallback carries most of the weight --
        // every other pupil who sat the same test. That is what makes the gap a
        // real number instead of a hunch, which is the whole point.
        //
        // Last resort, when this period is the only one: the period's own
        // average across the test, so a lone class still gets a ranking.
        var benchmark, benchSrc;
        if (statePct !== null) {
          benchmark = statePct;
          var ssrc  = getStateTEKSrcEx(info.tek, mt.subject, testYr, cohLang);
          var isES  = getStateTEKIsESEx(info.tek, mt.subject, testYr, cohLang);
          // "State avg" when it is the multi-year blend, "State '25" when TEA
          // actually published a figure for a year. Never let a blend read as
          // if it were this test's own state result.
          // Name the form as well as the year. A Spanish-form cohort measured
          // against English figures would read about 13 points worse than it is,
          // so when that fallback happens the column has to admit it.
          benchSrc = (ssrc === STATE_SRC_BLEND || !ssrc)
                     ? "State avg" : "State '" + String(ssrc).substring(2);
          if (isES) benchSrc = "Spanish '" + String(ssrc).substring(2);
        }
        else if (elsePct !== null) { benchmark = elsePct;  benchSrc = "All others"; }
        else                       { benchmark = secAvg;   benchSrc = "Test avg"; }

        rows.push({
          info: info, secPct: secPct, otherPct: otherPct,
          allPct: (elsePct === null ? null : elsePct / 100),
          statePct: statePct, benchSrc: benchSrc, benchmark: benchmark,
          stateN: mt.isSTAAR ? getStateTEKNEx(info.tek, mt.subject, testYr, cohLang) : null,
          shortfall: benchmark - Math.round(secPct * 100),
          missing: studentsMissingTEK(pupils, info, qs)
        });
      }
      // Worst shortfall first; ties broken by raw score, lowest first.
      rows.sort(function (a, b) {
        if (b.shortfall !== a.shortfall) return b.shortfall - a.shortfall;
        return a.secPct - b.secPct;
      });

      if (rows.length === 0) {
        g.row(20);
        g.set(0, "(No TEK-tagged questions on this test)", { bg: C.white, fg: "#757575" });
      }

      for (var ri = 0; ri < rows.length; ri++) {
        var r    = rows[ri];
        var sPct = Math.round(r.secPct * 100);
        var bg   = ri % 2 === 0 ? C.white : C.zebra;

        g.row(18);
        g.set(0, ri + 1, { bg: ri < 5 ? "#ffe0b2" : bg, align: "center",
                           bold: ri < 5, fmt: "0" });
        // Code AND what it says. A ranked list of bare codes is the single
        // biggest reason a teacher cannot act on this tab -- "6.3.D" means
        // nothing without "add, subtract, multiply, and divide integers".
        var tdesc = tekDescriptor(r.info.tek, mt.subject, cohLang);
        g.set(1, tdesc.text ? (r.info.tek + "\n" + tdesc.text) : r.info.tek,
              { bg: bg, bold: true, size: 9, wrap: true });
        // What this standard was a grade below and becomes a grade above. Blank
        // when TEA's chart shows no counterpart -- that is an answer, not a gap.
        g.set(2, verticalAlignmentLabel(r.info.tek, mt.subject),
              { bg: bg, fg: "#555555", size: 8, wrap: true });
        // r.info.assessed is always "" -- buildSubjectTEKMaps sets it and
        // nothing ever fills it -- so this column has been empty on every tab
        // ever produced. The descriptor tables carry TEA's designation.
        var tType = tekTypeLabel(tdesc.type)
                 || (r.info.assessed ? String(r.info.assessed).charAt(0) : "");
        g.set(3, tType, { bg: tType === "R" ? "#e3f2fd" : bg, align: "center",
                          bold: tType === "R" });
        g.set(4, "Q" + r.info.qNums.join(", Q"), { bg: bg, fg: "#555555", size: 9 });
        g.set(5, sPct, { bg: strandBg(sPct), align: "center", bold: true, fmt: "0\"%\"" });

        if (r.otherPct === null) {
          g.set(6, "", { bg: C.strandNone });
        } else {
          var oPct = Math.round(r.otherPct * 100);
          // The whole point of the tab: is this period alone, or everyone?
          var gap = sPct - oPct;
          g.set(6, oPct, {
            bg: gap <= -15 ? C.strandBad : gap >= 15 ? C.strandGood : bg,
            align: "center", fmt: "0\"%\""
          });
        }

        g.set(7, r.allPct === null ? "" : Math.round(r.allPct * 100),
              { bg: bg, align: "center", fmt: "0\"%\"" });
        // State percentage AND how many items the TEK is worth. The percentage
        // says how hard it is; the item count says whether fixing it is worth a
        // lesson. A one-item TEK at 40% moves fewer points than a four-item TEK
        // at 60%, and ranking by gap alone hides that completely.
        g.set(8, r.statePct === null ? ""
                 : (r.stateN > 0 ? r.statePct + "%\n" + r.stateN + (r.stateN === 1 ? " item" : " items")
                                 : r.statePct + "%"),
              { bg: bg, fg: "#555555", align: "center", size: 9, wrap: true, fmt: "@" });
        // Gap is never blank -- that is what makes it actionable.
        g.set(9, -r.shortfall, {
          bg: r.shortfall <= 0 ? C.strandGood
              : r.shortfall >= 15 ? C.strandBad : C.strandMid,
          align: "center", bold: r.shortfall >= 15,
          fmt: "+0\"%\";-0\"%\";0\"%\""
        });
        g.set(10, r.benchSrc, { bg: bg, fg: "#757575", align: "center", size: 8 });
        // Judge the priority against the SAME benchmark the gap and the ranking
        // used. Passing statePct here instead would make a row ranked #1 on a
        // 20-point gap read "Strong (no state avg)" whenever the state figure
        // is missing -- the label contradicting the order it sits in.
        g.set(11, priorityLabelEx(r.secPct, r.benchmark).label, { bg: bg, size: 9 });
        g.set(12, r.missing.length, { bg: bg, align: "center" });
        // Growth against the standard this one grows out of, same pupils.
        var ly = lastYearTEKCell(prevRef, nowMatched, r.info.tek, mt.subject, sPct);
        g.set(13, ly.text, { bg: ly.bg || bg, fg: ly.fg || "#000000", align: "center",
                             size: 9, wrap: true, note: ly.note });
      }

      // -- New to the campus: on this paper, nowhere in the STAAR data ---
      var newIn = [];
      for (var nwi = 0; nwi < pupils.length; nwi++) {
        if (!staarSeen[pupils[nwi].localId]) newIn.push(pupils[nwi].name);
      }
      if (newIn.length > 0) {
        newIn.sort();
        g.row(6);
        g.header("NEW TO THIS CAMPUS  --  " + newIn.length + " student(s) on this paper have no STAAR "
                 + "record in this workbook", "#4e342e", "#ffffff", 11, PLC_SECTION_COLS, 22);
        g.header(newIn.join(",   ") + "   |   They are counted in everything above: their profile was "
                 + "built from this paper. What they do not have is STAAR history, which is why their "
                 + "strip on the right is short and why \"last year, same students\" leaves them out.",
                 C.white, "#000000", 9, PLC_SECTION_COLS, 30, false);
      }

      // -- Support groups within this period ----------------------------
      // Compared against the SAME group among everyone else, not against the
      // whole cohort. A class's EB pupils being below the class average tells
      // you little on its own; being below other EB pupils on the same test is
      // the comparison that says whether the support is landing.
      var groups = supportGroupsOf(pupils);
      if (groups.length > 0) {
        g.row(8);
        g.header("SUPPORT GROUPS  --  " + secName
                 + "   |   each group compared with the SAME group among all other students",
                 "#00695c", "#ffffff", 12, PLC_SECTION_COLS, 24);
        g.headerRow(["Group", "Students", "Avg", "vs Period", "vs Same Group Elsewhere",
                     "Weakest TEK for this group"], C.sectionBg, 30);

        var elseGroups = supportGroupsOf(elsewhere);
        var elseByLabel = {};
        for (var eg = 0; eg < elseGroups.length; eg++) {
          elseByLabel[elseGroups[eg].label] = elseGroups[eg].members;
        }

        g.row(18);
        g.set(0, "Everyone in this period", { bg: C.zebra, bold: true });
        g.set(1, pupils.length, { bg: C.zebra, align: "center" });
        g.set(2, secAvg, { bg: C.zebra, align: "center", bold: true, fmt: "0\"%\"" });

        for (var gi2 = 0; gi2 < groups.length; gi2++) {
          var grp    = groups[gi2];
          var gAvg   = groupAvgPct(grp.members, adjMaxAll);
          var peers  = elseByLabel[grp.label] || [];
          var pAvg   = groupAvgPct(peers, adjMaxAll);
          var gbg    = gi2 % 2 === 0 ? C.white : C.zebra;

          g.row(18);
          g.set(0, grp.label, { bg: gbg, bold: true });
          g.set(1, grp.members.length, { bg: gbg, align: "center" });
          g.set(2, gAvg, { bg: strandBg(gAvg), align: "center", bold: true, fmt: "0\"%\"" });
          g.set(3, gAvg - secAvg, {
            bg: (gAvg - secAvg) <= -10 ? C.strandBad : (gAvg - secAvg) >= 0 ? C.strandGood : C.strandMid,
            align: "center", fmt: "+0\"%\";-0\"%\";0\"%\""
          });
          if (pAvg === null) {
            g.set(4, "no peers on this test", { bg: gbg, fg: "#757575", size: 8, align: "center" });
          } else {
            g.set(4, gAvg - pAvg, {
              bg: (gAvg - pAvg) <= -10 ? C.strandBad : (gAvg - pAvg) >= 0 ? C.strandGood : C.strandMid,
              align: "center", bold: true, fmt: "+0\"%\";-0\"%\";0\"%\""
            });
          }
          g.set(5, weakestTEKFor(grp.members, qs, exclNums), { bg: gbg, size: 9 });
        }
      }

      // Names for the weakest few, so a pull group can be formed straight away.
      var pullable = [];
      for (var pj = 0; pj < rows.length && pullable.length < PLC_PULL_TEK_LIMIT; pj++) {
        if (rows[pj].missing.length > 0) pullable.push(rows[pj]);
      }
      // -- REPORTING CATEGORY: this class against its benchmark, STAAR only --
      // Every subject. Nothing here reads MAP, which is why it can run where
      // the MAP bridge below cannot.
      var cats = plcCategoryRollup(rows, mt.subject);
      if (cats.length > 0) {
        g.row(8);
        g.header("REPORTING CATEGORY  --  " + secName + "   --   where this class stands, worst first",
                 "#00695c", "#ffffff", 12, PLC_SECTION_COLS, 24);
        g.header("The same numbers as the TEK table above, added up per reporting category, so you "
                 + "can see whether a weakness is one standard or a whole category.   |   "
                 + "Weighted by marks available, so a four-mark standard counts for more than a "
                 + "one-mark one.   |   \"This Period\" against \"My Other Periods\" is the column "
                 + "that decides what to do: low in both is a whole-class reteach, low here only is "
                 + "a warm-up for this class.",
                 C.warn, "#000000", 9, PLC_SECTION_COLS, 38, false);
        // "Comparison", never "Benchmark". In this workbook a Benchmark is a
        // KIND OF TEST (BOY/MOY), and the presentation build has no such thing
        // -- a column headed Benchmark beside STAAR percentages would read as
        // "your benchmark test result". "Comparison" is already the workbook's
        // own word for this, in "no state comparison".
        g.headerRow(["Reporting category", "Questions", "This Period", "My Other Periods",
                     "All Other Students", "Comparison", "Gap", "vs", "What it means"],
                    C.sectionBg, 26);
        // rci, not ci: this loop sits INSIDE the cohort loop, which already uses ci. With one
        // function-scoped var, the cohort loop ended after English and every Spanish cohort's
        // tables were silently never drawn. Fixed in the master 2026-09-27; ported 2026-10-06.
        for (var rci = 0; rci < cats.length; rci++) {
          var c0 = cats[rci], cbg = rci % 2 === 0 ? C.white : C.zebra;
          g.row(20);
          g.set(0, c0.name, { bg: cbg, size: 9 });
          g.set(1, c0.questions, { bg: cbg, align: "center", size: 9 });
          g.set(2, c0.pct, { bg: strandBg(c0.pct), align: "center", bold: true, fmt: "0\"%\"" });
          g.set(3, c0.otherPct === null ? "\u2013" : c0.otherPct,
                { bg: cbg, align: "center", size: 9, fmt: c0.otherPct === null ? "" : "0\"%\"" });
          g.set(4, c0.allPct === null ? "\u2013" : c0.allPct,
                { bg: cbg, align: "center", size: 9, fmt: c0.allPct === null ? "" : "0\"%\"" });
          g.set(5, c0.benchmark, { bg: cbg, align: "center", size: 9, fmt: "0\"%\"" });
          // Gap then source, the same order as the per-TEK table above, so the
          // two tables teach one convention rather than two.
          g.set(6, c0.gap, { bg: cbg, align: "center", size: 9, bold: c0.gap >= 5,
                             fg: c0.gap >= 5 ? "#b71c1c" : c0.gap <= -5 ? "#1b5e20" : "#000000",
                             fmt: "+0;-0;0" });
          g.set(7, c0.benchSrc, { bg: cbg, align: "center", size: 9, fg: "#555555" });
          var saying = plcCategorySay(c0);
          g.set(8, saying, { bg: cbg, size: 9, wrap: true,
                             bold: saying.indexOf("reteach") !== -1,
                             fg: saying.indexOf("reteach") !== -1 ? "#b71c1c" : "#555555" });
        }
        g.row(8);
      }

      // -- REPORTING CATEGORY: MAP in the autumn beside STAAR in the spring --
      // Maths only. See MAP_GOAL_ALIASES: our ELA categories are Reading and
      // Writing, MAP gives three reading goals, and three onto two is a guess.
      var bridgeBy = bridgeGroupBy(mt.subject);
      if (bridgeBy) {
        var bridgeCfg = MAP_GOAL_BRIDGE[mt.subject];
        var rcAgg = {}, rcOrder = [];
        for (var rk2 = 0; rk2 < rows.length; rk2++) {
          var nm = "";
          if (bridgeBy === "rc") {
            var rcInf = (typeof TEK_RC_MAP !== "undefined") ? TEK_RC_MAP[rows[rk2].info.tek] : null;
            nm = rcInf && rcInf.rcName ? rcInf.rcName : "";
          } else {
            nm = rows[rk2].info.strand || "";
          }
          if (!nm) continue;
          if (!rcAgg[nm]) { rcAgg[nm] = { name: nm, e: 0, p: 0, key: bridgeGroupKeyOf(mt.subject, nm) }; rcOrder.push(nm); }
          rcAgg[nm].e += rows[rk2].info.earned;
          rcAgg[nm].p += rows[rk2].info.possible;
        }
        var goalAgg = {};
        for (var gp = 0; gp < pupils.length; gp++) {
          var full2 = byId[pupils[gp].localId || pupils[gp].name];
          var mr2 = newestMAPFor(full2, mt.subject);
          if (!mr2) continue;
          for (var gq = 0; gq < mr2.goals.length; gq++) {
            var gk2 = rcKey(mr2.goals[gq].name, mt.subject);
            if (!goalAgg[gk2]) goalAgg[gk2] = { sum: 0, n: 0, name: mr2.goals[gq].name };
            goalAgg[gk2].sum += mr2.goals[gq].rit; goalAgg[gk2].n++;
          }
        }
        var rcShown = [];
        for (var ro = 0; ro < rcOrder.length; ro++) {
          var a2 = rcAgg[rcOrder[ro]];
          if (a2.p === 0) continue;
          var ga = a2.key ? (goalAgg[a2.key] || null) : null;
          rcShown.push({ name: a2.name, pct: Math.round(a2.e / a2.p * 100),
                         rit: ga && ga.n ? Math.round(ga.sum / ga.n) : null,
                         goal: ga ? ga.name : "" });
        }
        var anyRit = false;
        for (var ar = 0; ar < rcShown.length; ar++) if (rcShown[ar].rit !== null) anyRit = true;
        // anyRit, not just rcShown.length. This block is the MAP bridge: with
        // no MAP goal data every row read "MAP does not assess this" under a
        // column headed "MAP goal (autumn)", which is all the presentation
        // build ever showed. The STAAR-only rollup above now carries the
        // category view, so this one only earns its place when MAP is present.
        if (anyRit && rcShown.length > 0) {
          var ritAvg = 0, ritN = 0;
          for (var ar2 = 0; ar2 < rcShown.length; ar2++) if (rcShown[ar2].rit !== null) { ritAvg += rcShown[ar2].rit; ritN++; }
          ritAvg = ritN ? ritAvg / ritN : 0;
          var pctAvg = 0;
          for (var ap = 0; ap < rcShown.length; ap++) pctAvg += rcShown[ap].pct;
          pctAvg = rcShown.length ? pctAvg / rcShown.length : 0;
          g.row(8);
          var bLabel = bridgeCfg.label.toUpperCase();
          g.header(bLabel + "  --  " + secName + "   --   what MAP said in the autumn, what STAAR said in the spring",
                   "#00695c", "#ffffff", 12, PLC_SECTION_COLS, 24);
          g.header(bridgeCfg.note + "   |   "
                   + "Both columns are this class against ITSELF: a goal RIT is high or low against this "
                   + "class's other goals, a percentage against this class's other " + bridgeCfg.label
                   + "s. The last column is the whole reading.",
                   C.warn, "#000000", 9, PLC_SECTION_COLS, 34, false);
          g.headerRow([bridgeCfg.label.charAt(0).toUpperCase() + bridgeCfg.label.slice(1),
                       "MAP goal (autumn)", "STAAR " + (yearFromDate(mt.date) || ""),
                       "What it means for this class"], C.sectionBg, 26);
          for (var rs = 0; rs < rcShown.length; rs++) {
            var it = rcShown[rs], rbg2 = rs % 2 === 0 ? C.white : C.zebra;
            var mapLow = it.rit !== null && it.rit < ritAvg - 1.5;
            var mapHigh = it.rit !== null && it.rit > ritAvg + 1.5;
            var stLow = it.pct < pctAvg - 5, stHigh = it.pct > pctAvg + 5;
            var say = "";
            if (it.rit === null)      say = "MAP does not assess this";
            else if (mapLow && stLow) say = "weak on both  ->  reteach";
            else if (mapHigh && stHigh) say = "strong on both  ->  keep moving";
            else if (stLow && !mapLow)  say = "STAAR worse than MAP expected";
            else if (stHigh && !mapHigh) say = "STAAR better than MAP expected";
            else say = "middling on both";
            g.row(20);
            g.set(0, it.name, { bg: rbg2, size: 9 });
            g.set(1, it.rit === null ? "\u2013" : (it.rit + (mapLow ? "  low" : mapHigh ? "  high" : "  avg")),
                  { bg: rbg2, align: "center", size: 9,
                    fg: mapLow ? "#b71c1c" : mapHigh ? "#1b5e20" : "#000000", bold: mapLow || mapHigh });
            g.set(2, it.pct, { bg: strandBg(it.pct), align: "center", bold: true, fmt: "0\"%\"" });
            g.set(3, say, { bg: rbg2, size: 9, wrap: true,
                            bold: say.indexOf("reteach") !== -1,
                            fg: say.indexOf("reteach") !== -1 ? "#b71c1c" : "#555555" });
          }
          g.row(8);
        }
      }

      // -- WORTH A SECOND LOOK: MAP and STAAR disagreed sharply --------------
      {
        var dis = [];
        var ORD = { "Did Not Meet": 0, "Approaches": 1, "Meets": 2, "Masters": 3 };
        for (var dz = 0; dz < roster.length; dz++) {
          var stD = roster[dz];
          var bdD = pupilBandOn(stD, mt, blockQuestions);
          var actual = fourBandOf(bdD.fine, bdD.coarse);
          var mrD = newestMAPFor(stD, mt.subject);
          var projD = mrD ? mapLevelName(mrD.projectedProficiency) : "";
          if (projD === "Below") projD = "Did Not Meet";
          if (!actual || !projD) continue;
          var gap = ORD[projD] - ORD[actual];
          if (Math.abs(gap) < 2) continue;
          dis.push({ name: stD.name, proj: projD, actual: actual, gap: gap,
                     rapid: mrD.rapidGuess ? (mrD.rapidGuessPct + "%") : "" });
        }
        dis.sort(function (a, b) { return Math.abs(b.gap) - Math.abs(a.gap); });
        if (dis.length > 0) {
          g.row(8);
          g.header("WORTH A SECOND LOOK  --  " + secName + "   --   MAP and STAAR disagreed by two bands or more",
                   "#4a148c", "#ffffff", 12, PLC_SECTION_COLS, 24);
          g.header("A short list on purpose. Each of these is a conversation, not a number: a pupil who knows more "
                   + "than one of the two tests measured. Rapid guessing on MAP frequently explains it outright.",
                   C.warn, "#000000", 9, PLC_SECTION_COLS, 22, false);
          g.headerRow(["Student", "MAP projected", "STAAR actual", "Rapid guessing", "What it might mean"],
                      C.sectionBg, 22);
          for (var dd = 0; dd < dis.length; dd++) {
            var d2 = dis[dd], dbg = dd % 2 === 0 ? C.white : C.zebra;
            g.row(20);
            g.set(0, d2.name, { bg: dbg, size: 9 });
            g.set(1, d2.proj,   { bg: rampBg("", fourBandRampKey(d2.proj)),   fg: rampFg("", fourBandRampKey(d2.proj)),   align: "center", size: 9 });
            g.set(2, d2.actual, { bg: rampBg("", fourBandRampKey(d2.actual)), fg: rampFg("", fourBandRampKey(d2.actual)), align: "center", size: 9 });
            g.set(3, d2.rapid, { bg: d2.rapid ? "#ff8f00" : dbg, fg: d2.rapid ? "#ffffff" : "#000000",
                                 align: "center", size: 9, bold: !!d2.rapid });
            g.set(4, d2.rapid ? "MAP was not a fair read of this pupil"
                     : d2.gap > 0 ? "MAP expected more than STAAR showed  --  ask about the test day"
                                  : "knows more than MAP measured",
                  { bg: dbg, size: 9, wrap: true });
          }
          g.row(8);
        }
      }

      if (pullable.length > 0) {
        g.row(8);
        g.header("PULL GROUPS  --  " + secName, "#4a148c", "#ffffff", 12, PLC_SECTION_COLS, 24);
        g.header("One row per pupil, worst first. \"Missed\" is the actual question numbers to look "
                 + "at with them. Service flags are here so you can tell an accommodation question "
                 + "from a Tier 2 one at a glance.",
                 C.warn, "#000000", 9, PLC_SECTION_COLS, 22, false);
        // `mt` is the paper the pull list was ranked on (the last one the loop
        // above built), so the link opens that paper's grade, not papers[0].
        var l4wPull = mt ? lead4wardLinksFor(mt.subject, gradeByOrder[mt.order], "") : null;
        if (l4wPull && (l4wPull.scaffold || l4wPull.snapshot)) {
          var l4wPullWho = l4wLabel(mt.subject, gradeByOrder[mt.order], "");
          g.row(22);
          for (var lp = 0; lp < PLC_SECTION_COLS; lp++) g.set(lp, "", { bg: L4W_ROW_BG });
          g.set(0, "lead4ward links", { bg: L4W_ROW_BG, fg: L4W_LINK_FG, bold: true, size: 10 });
          g.set(2, l4wLink(l4wPull.scaffold || l4wPull.snapshot,
                           l4wPull.scaffold
                             ? l4wPullWho + " TEKS Scaffold (Excel): split a TEK into the sub-skills a small group needs"
                             : l4wPullWho + " TEKS Snapshot: what each standard asks for"),
                L4W_LINK_OPTS);
        }
        g.headerRow(["TEK", "Rank", "Student", "SpEd", "EB", "ED", "Got", "Missed"],
                    C.sectionBg, 22);

        // Who is otherwise solid? A pupil at or above this period's average who
        // still missed this TEK is a one-lesson fix. A pupil below it missed
        // this TEK and much else besides, and pulling them for this alone
        // treats a symptom. Same list, separated -- never silently merged.
        var solidCut = secAvg;

        for (var pk = 0; pk < pullable.length; pk++) {
          var pr = pullable[pk];

          // Per-pupil detail on this TEK: what they earned and which questions
          // they actually got wrong. A name on its own tells a teacher nothing
          // they can act on; a question number does.
          var detail = [];
          for (var mi = 0; mi < pr.missing.length; mi++) {
            var stu = pr.missing[mi], earned = 0, poss = 0, missedQ = [];
            for (var dj = 0; dj < pr.info.qIdx.length; dj++) {
              var dq = pr.info.qIdx[dj];
              var got = stu.scores[dq] || 0;
              earned += got;
              poss   += qs[dq].maxPts;
              if (got < qs[dq].maxPts) missedQ.push("Q" + qs[dq].number);
            }
            detail.push({ stu: stu, earned: earned, poss: poss, missedQ: missedQ });
          }
          for (var dg = 0; dg < detail.length; dg++) {
            var dstu = detail[dg].stu;
            var dfull = byId[dstu.localId || dstu.name];
            // adjPctScore is a FRACTION (0-1); secAvg is a PERCENTAGE (0-100).
            // Comparing them directly makes every pupil look below average and
            // the split silently does nothing.
            var dpct = dstu.adjPctScore;
            detail[dg].overall = dpct;
            detail[dg].solid   = (dpct !== null && dpct !== undefined
                                  && solidCut > 0 && dpct * 100 >= solidCut);
            var pg = dfull ? pupilGrowth(dfull, mt) : null;
            detail[dg].growth  = (pg && pg.points !== null)
              ? (pg.points + (pg.accelerated ? 0.25 : 0)) : null;
          }
          // Solid-but-missed first, then by how little they got on this TEK.
          detail.sort(function (a, b) {
            if (a.solid !== b.solid) return a.solid ? -1 : 1;
            return a.earned - b.earned;
          });

          var bandBg = "#ede7f6";
          g.row(20);
          g.set(0, pr.info.tek + (pr.info.assessed ? " [" + pr.info.assessed + "]" : ""),
                { bg: bandBg, bold: true });
          g.set(1, "#" + (pk + 1), { bg: bandBg, align: "center", bold: true });
          g.set(2, pr.info.strand, { bg: bandBg, size: 9 });
          g.set(6, Math.round(pr.secPct * 100), { bg: bandBg, align: "center",
                                                  bold: true, fmt: "0\"%\"" });
          g.set(7, detail.length + " pupil(s) to pull", { bg: bandBg, size: 9 });

          var wroteSplit = false;
          for (var di = 0; di < detail.length; di++) {
            var d    = detail[di];
            // One divider, once, where the group changes character.
            if (!wroteSplit && !d.solid && di > 0) {
              wroteSplit = true;
              g.row(16);
              g.set(2, "-- below the period average: this TEK is not their only gap --",
                    { bg: C.warn, fg: "#555555", size: 8, italic: true });
            }
            var rowBg = d.solid ? "#e8f5e9" : (di % 2 === 0 ? C.white : C.zebra);
            g.row(19);
            g.set(2, d.stu.name
                     + (d.growth !== null && d.growth < 1 ? "   (0 growth)" : ""),
                  { bg: rowBg });
            g.set(3, d.stu.sped === "Yes" ? "SpEd" : "",
                  { bg: d.stu.sped === "Yes" ? "#fff3e0" : rowBg, align: "center", size: 9 });
            g.set(4, shortEB(d.stu.eb) === "EB" ? "EB" : "",
                  { bg: shortEB(d.stu.eb) === "EB" ? "#e3f2fd" : rowBg, align: "center", size: 9 });
            g.set(5, d.stu.econDis === "Yes" ? "ED" : "",
                  { bg: d.stu.econDis === "Yes" ? "#f1f8e9" : rowBg, align: "center", size: 9 });
            g.set(6, d.earned + " / " + d.poss,
                  { bg: d.earned === 0 ? C.strandBad : C.strandMid, align: "center", size: 9 });
            g.set(7, d.missedQ.join(", "), { bg: rowBg, size: 9 });
          }
          g.row(6);
        }
      }

      // -- Proximity list: who is sitting on a cut --------------------------
      //
      // A different list from the one above and it answers a different
      // question. The reteach group is about ONE standard this term; this is
      // about pupils a handful of scale points from a performance cut, which is
      // stable all year and belongs with tutorials rather than an in-class pull.
      //
      // Points ABOVE a cut are listed too. A pupil four points above Meets is
      // exactly as fragile as one four points below, and naming only the ones
      // below is how a slide back gets noticed in June instead of October.
      {
        var bubbles = [];
        for (var bz = 0; bz < pupils.length; bz++) {
          var bstu = pupils[bz];
          var bfull = byId[bstu.localId || bstu.name];
          var brec = null;
          if (bfull) {
            var bks = Object.keys(bfull.testScores);
            for (var bk = 0; bk < bks.length; bk++) {
              var br = bfull.testScores[bks[bk]];
              if (br.order !== mt.order) continue;
              if (!brec) brec = br;
              if (br.tookTest) { brec = br; break; }
            }
          }
          if (!brec || !brec.tookTest) continue;
          var bb = bubbleFor(brec.scaleScore, cutGradeLabelFor(qs), mt.subject,
                             brec.language, yearFromDate(mt.date));
          if (!bb) continue;
          var bg2 = bfull ? pupilGrowth(bfull, mt) : null;
          bubbles.push({ stu: bstu, b: bb,
                         growth: (bg2 && bg2.points !== null)
                                   ? (bg2.points + (bg2.accelerated ? 0.25 : 0)) : null });
        }
        if (bubbles.length > 0) {
          // Closest to a cut first -- those are the ones a term of tutorials
          // actually moves.
          bubbles.sort(function (a, b) { return Math.abs(a.b.delta) - Math.abs(b.b.delta); });
          g.row(8);
          g.header("ON THE EDGE  --  " + secName + "   --   within " + BUBBLE_WINDOW
                   + " scale points of a cut", "#00695c", "#ffffff", 12, PLC_SECTION_COLS, 24);
          g.header("These pupils sit either side of a performance cut on " + mt.label
                   + ". The ones ABOVE a cut are here on purpose: they are as close to slipping "
                   + "back as the others are to moving up. This list barely changes all year, so "
                   + "it suits tutorials and progress monitoring rather than a lesson-time pull.",
                   C.warn, "#000000", 9, PLC_SECTION_COLS, 26, false);
          g.headerRow(["Student", "Scale", "Nearest cut", "Points away", "Side",
                       "Growth", "SpEd", "EB"], C.sectionBg, 22);
          for (var bi2 = 0; bi2 < bubbles.length; bi2++) {
            var bu = bubbles[bi2], brow = bi2 % 2 === 0 ? C.white : C.zebra;
            var above = bu.b.delta >= 0;
            g.row(19);
            g.set(0, bu.stu.name, { bg: brow, size: 9 });
            g.set(1, bu.b.scale, { bg: brow, align: "center", size: 9 });
            g.set(2, bu.b.cut + " (" + bu.b.cutScore + ")", { bg: brow, align: "center", size: 9 });
            g.set(3, Math.abs(bu.b.delta), { bg: brow, align: "center", bold: true, size: 9 });
            g.set(4, above ? "above" : "below",
                  { bg: above ? "#e8f5e9" : "#ffebee",
                    fg: above ? "#1b5e20" : "#b71c1c", align: "center", size: 9, bold: true });
            g.set(5, bu.growth === null ? "\u2013" : bu.growth,
                  { bg: bu.growth === null ? C.strandNone
                        : bu.growth >= 1 ? C.strandGood : C.strandBad,
                    align: "center", size: 9, fmt: "0.00" });
            g.set(6, bu.stu.sped === "Yes" ? "SpEd" : "", { bg: brow, align: "center", size: 9 });
            g.set(7, shortEB(bu.stu.eb) === "EB" ? "EB" : "", { bg: brow, align: "center", size: 9 });
          }
        }
      }
      }   // end cohort loop
      pupils = allPupilsInSec;
      for (var shx = 0; shx < allPupilsInSec.length; shx++) {
        shownIds[allPupilsInSec[shx].localId || allPupilsInSec[shx].name] = true;
      }


      }   // end paper loop

      // -- Roster check: who is on this group's list but not in a table -------
      // The count in the summary said "4 sat a different paper" without saying
      // WHO, so a teacher could see that somebody was missing but not which
      // pupil, and had no way to tell an absence from a transfer.
      if (showAbsent) {
        var inTable = shownIds;
        var absent = [];
        for (var rr = 0; rr < roster.length; rr++) {
          if (inTable[roster[rr].localId || roster[rr].name]) continue;
          absent.push(roster[rr]);
        }
        if (absent.length > 0) {
          g.row(8);
          g.header("NOT IN THE TABLE ABOVE  --  " + absent.length + " of " + roster.length
                   + " pupil(s) in " + secName,
                   C.alert, C.alertTxt, 12, PLC_SECTION_COLS, 24);
          var paperNames = [];
          for (var pnx = 0; pnx < papers.length; pnx++) paperNames.push(papers[pnx].label);
          g.header("These pupils are on this group's roster but have no result on "
                   + paperNames.join(" / ") + ". They are listed so an absence cannot hide "
                   + "behind a count. "
                   + "Untick \"Name pupils with no data on the paper\" in Config to drop this block.",
                   C.warn, "#000000", 9, PLC_SECTION_COLS, 22, false);
          g.headerRow(["Student", "SpEd", "EB", "ED", "Why there is no data"], C.sectionBg, 22);
          for (var az = 0; az < absent.length; az++) {
            var abg = az % 2 === 0 ? C.white : C.zebra;
            g.row(18);
            g.set(0, absent[az].name, { bg: abg, size: 9 });
            g.set(1, absent[az].sped === "Yes" ? "SpEd" : "", { bg: abg, align: "center", size: 9 });
            g.set(2, shortEB(absent[az].eb) === "EB" ? "EB" : "", { bg: abg, align: "center", size: 9 });
            g.set(3, absent[az].econDis === "Yes" ? "ED" : "", { bg: abg, align: "center", size: 9 });
            g.set(4, whyNoDataOnPaper(absent[az], papers, testByOrder), { bg: abg, size: 9, wrap: true });
          }
        }
      }

      // -- Trajectory, beside the table from column N ---------------------
      // Where each pupil in this class has been, band by band, oldest test
      // first. It sits alongside rather than below so a teacher reading the TEK
      // ranking can see who they are talking about without scrolling away.
      var TS = PLC_TRAJ_START, tRow = secStart;
      var stripCols = colsByGroup[secName].width;
      if (!keyDrawn) { drawMAPKey(g, secStart, keyCol, mapWidth > 0); keyDrawn = true; }
      g.setAt(tRow, TS, "THIS CLASS OVER TIME  --  every paper this class sat, in the order they sat them.  \"S\" = sat the Spanish form that year"
                        + (mapCols.length ? "   |   MAP: RIT coloured by NWEA's projected STAAR level; \"vs target\" = RIT points above or below the growth NWEA projected" : ""),
              { bg: "#37474f", fg: "#ffffff", bold: true, size: 11 });
      for (var hh = 1; hh <= stripCols; hh++) g.setAt(tRow, TS + hh, "", { bg: "#37474f" });
      tRow++;

      g.setAt(tRow, TS, "Student", { bg: C.sectionBg, bold: true });
      for (var ch = 0; ch < cols.length; ch++) {
        var hc = TS + 1 + cols[ch].at;
        if (cols[ch].kind === "staar") {
          g.setAt(tRow, hc, trajTestLabel(cols[ch].mt, stripMulti),
                  { bg: C.sectionBg, bold: true, size: 8, align: "center", wrap: true });
          // The strip labels are deliberately tiny -- "M STAAR '26" -- so the
          // full identity of each column lives in its note.
          g.noteAt(tRow, hc, testProvenance(cols[ch].mt,
                   { grade: gradeByOrder[cols[ch].mt.order] || "" }));
          if (!tabPaperSeen[cols[ch].mt.order]) {
            tabPaperSeen[cols[ch].mt.order] = true; tabPapers.push(cols[ch].mt);
          }
        } else {
          g.setAt(tRow, hc,     cols[ch].cp.label, { bg: "#e0f2f1", bold: true, size: 8, align: "center", wrap: true });
          g.setAt(tRow, hc + 1, "vs target",       { bg: "#e0f2f1", bold: true, size: 8, align: "center", wrap: true });
          var cpRec = cols[ch].cp.rec;
          var cpSeen = 0;
          for (var cpq = 0; cpq < roster.length; cpq++) if (mapRecordFor(roster[cpq], cols[ch].cp)) cpSeen++;
          var cpNote = mapProvenance(cpRec, { grade: cpRec ? cpRec.grade : "", pupils: cpSeen });
          g.noteAt(tRow, hc,     cpNote);
          g.noteAt(tRow, hc + 1, cpNote);
          if (cpRec && !tabMapSeen[cols[ch].cp.key]) {
            tabMapSeen[cols[ch].cp.key] = true; tabMapCps.push(cols[ch].cp);
          }
        }
      }
      tRow++;

      // Everyone on the group's roster, not just whoever appeared in the last
      // table. A pupil with no current result still has a history worth seeing,
      // and leaving them out is how people go missing.
      var ordered = roster.slice().sort(function (x, y) {
        return String(x.name) < String(y.name) ? -1 : String(x.name) > String(y.name) ? 1 : 0;
      });
      for (var pz = 0; pz < ordered.length; pz++) {
        var full = ordered[pz];
        var zbg  = pz % 2 === 0 ? C.white : C.zebra;
        g.setAt(tRow, TS, ordered[pz].name, { bg: zbg, size: 9 });
        for (var cz = 0; cz < cols.length; cz++) {
          var colAt = TS + 1 + cols[cz].at;

          // -- a MAP checkpoint: RIT filled by projected level, then growth ----
          if (cols[cz].kind === "map") {
            var mrec = mapRecordFor(full, cols[cz].cp);
            if (!mrec) {
              g.setAt(tRow, colAt,     "\u2013", { bg: C.strandNone, fg: "#9e9e9e", align: "center", size: 8 });
              g.setAt(tRow, colAt + 1, "\u2013", { bg: C.strandNone, fg: "#9e9e9e", align: "center", size: 8 });
              continue;
            }
            var lvl = mapLevelName(mrec.projectedProficiency);
            g.setAt(tRow, colAt, mrec.rit, {
              bg: lvl ? rampBg("", lvl) : zbg, fg: lvl ? rampFg("", lvl) : "#000000",
              align: "center", size: 8, bold: !!lvl
            });
            var gst = mapGrowthStyle(mrec.growthCall, zbg);
            g.setAt(tRow, colAt + 1, mapGrowthText(mrec),
                    { bg: gst.bg, fg: gst.fg, bold: gst.bold, align: "center", size: 8 });
            continue;
          }

          // -- a STAAR paper: the band the pupil earned, six-way where TEA's cuts exist --
          var mtz = cols[cz].mt;
          var band = "", fine = "", took = false, wasES = false, noBand = false;
          if (full) {
            var kz = Object.keys(full.testScores), pickR = null;
            for (var kk = 0; kk < kz.length; kk++) {
              var rz = full.testScores[kz[kk]];
              if (rz.order !== mtz.order) continue;
              if (!pickR) pickR = rz;
              if (rz.tookTest) { pickR = rz; break; }   // the form they really sat
            }
            if (pickR) {
              took  = pickR.tookTest;
              wasES = pickR.language === "Spanish";
              // No band columns on this paper (a local benchmark has none), so
              // there is no band to report. Saying "Below" would invent one.
              noBand = took && pickR.hasBands === false;
              if (took && !noBand) band = masteryLevel(pickR.approaches, pickR.meets, pickR.masters);
              // Split the band into its Low/High halves when we hold TEA's cut
              // table for that year. This is the whole point of the strip: a
              // pupil sitting at High Approaches two years running is a very
              // different conversation from one sliding Low Approaches to High
              // Did Not Meet, and plain "Approaches" hides both.
              // Guarded on !noBand: a local benchmark's scale score is not a
              // STAAR scale score, so running it through TEA's cut table would
              // invent a band out of an unrelated number.
              if (took && !noBand) {
                fine = enhancedBandOf(pickR.scaleScore,
                         cutGradeLabelFor(primaryQuestionsEx(mtz, blockQuestions)),
                         mtz.subject, pickR.language, yearFromDate(mtz.date));
              }
            }
          }
          // "S" marks a year this pupil sat the SPANISH form. English and
          // Spanish forms are merged into one test so the trajectory lines up,
          // which means the column heading cannot say which one a given pupil
          // sat -- only the cell can. A pupil who moves from S to no-S between
          // two years has changed test language, and a dip across that line is
          // usually the language, not the mathematics.
          // Prefer the six-band label; fall back to the four-band one for a
          // year with no cut table, so an older column still reads rather than
          // going blank.
          var tLab = fine ? ENHANCED_BAND_SHORT[fine] : band ? bandShort(band) : "";
          g.setAt(tRow, colAt,
            !took ? "\u2013" : (!tLab ? ("sat" + (wasES ? " S" : ""))
                                      : (tLab + (wasES ? " S" : ""))), {
            bg: !took ? C.strandNone : !tLab ? C.zebra : rampBg(fine, band),
            fg: !took ? "#9e9e9e"    : !tLab ? "#616161" : rampFg(fine, band),
            align: "center", size: 8,
            bold: took && wasES
          });
        }
        tRow++;
      }

      g.row(10);
    }

    var tabName = safeTabName("PLC_", teacher + (plcTabs[ti].nameSuffix ? " - " + plcTabs[ti].nameSuffix : ""), used);
    var sheet = getOrCreate(ss, tabName);
    // Written last, because the list is only complete once every section is
    // drawn. noteAt reaches back up the grid, which is the whole reason it
    // takes a row index.
    g.noteAt(plcBannerRow, 0, pulledTestsNote(tabPapers, tabMapCps,
             "EVERY TEST BEHIND THIS TAB  --  " + teacher));
    // Widths by column ROLE, because several blocks share these columns. A
    // pupil's name lands in column A (growth, on-the-edge and no-data lists),
    // in column C (pull groups), in column M (not yet mastered) and in the
    // strip's first column. The old array was one entry short and misaligned,
    // so those four columns got 20 to 55 px -- three letters of a surname --
    // while the blank gap column got 170.
    var w = [
      140,   // A  rank # / pupil name in the growth, edge and no-data lists
      300,   // B  TEK code + wording
      150,   // C  was/becomes / pupil name in pull groups / band
      60,    // D  R/S / points / SpEd
      130,   // E  question numbers / accelerated / why there is no data
      110,   // F  this period
      110,   // G  my other periods
      120,   // H  all other students / "n pupil(s) to pull"
      80,    // I  state % + item count
      70,    // J  gap
      120,   // K  vs
      105,   // L  priority
      240,   // M  not yet mastered (names)
      150,   // N  last year, same students
      20     // O  blank gap before the strip
    ];
    w.push(170);                                          // O  strip: pupil name
    for (var wq = 0; wq < colsWidth; wq++) w.push(56);    // one per STAAR paper, two per MAP checkpoint
    w.push(20); w.push(20);                                // the gap before the key
    w.push(90); w.push(20); w.push(330);                   // swatch, spacer, meaning
    // Written only now, with the widths in hand: a wrapped cell's height
    // depends on how wide its column is, so they go on before rows are sized.
    g.flush(sheet, w);
    sheet.setFrozenRows(1);
    built++;
    PLC_TABS_BUILT[teacher] = PLC_TABS_BUILT[teacher]
                                ? PLC_TABS_BUILT[teacher] + " | " + tabName : tabName;
    PROGRESS.step(teacher + (plcTabs[ti].nameSuffix ? " (" + plcTabs[ti].nameSuffix + ")" : ""));
    console.log(tabName + " written -- " + secNames.length + " section(s), "
                + teacherTotal + " students.");
  }

  return built;
}


// === PART 30: DATA CHECK ================================================
// Tab: Data_Check -- an audit you can put in front of someone before you share
// anything. Every figure here is a comparison against something the script did
// NOT compute: Eduphoria's own Raw Score, its own performance-level flags, the
// TEK tags on the paper.
//
// Read it as a challenge to the output, not a summary of it. A clean run means
// the arithmetic agrees with Eduphoria on every pupil; anything else is listed
// by name so it can be checked by hand.

var DC_COLS = 8;

/**
 * The built-in state figures (Ref_State_Averages, from lead4ward) against TEA_STATE_TEK_PCT (TEA's own
 * item analysis joined to TEA's item keys). Pure: reads only the two tables, so a test can call it.
 *
 * Agreement = within one point after rounding both sides, the same tolerance the Ref_State_Avg check
 * has always used. Figures the built-in table rolls up from sub-standards ("roll") are skipped: they are
 * not one TEK's items. Returns counts overall and per subject/form, and every disagreement with the
 * likeliest cause, largest first.
 */
function checkStateFiguresAgainstTEA() {
  var out = { compared: 0, agree: 0, differ: 0, uncheckable: 0, notOnTEA: 0, noKey: 0, offYears: 0, teaOnly: 0,
              teaYears: [], otherYears: [], bySubject: [], diffs: [] };
  var teaYearSet = {}, otherYearSet = {}, allTeaYears = {};
  for (var sj in TEA_STATE_TEK_PCT) {
    for (var fj in TEA_STATE_TEK_PCT[sj]) {
      for (var tj in TEA_STATE_TEK_PCT[sj][fj]) {
        for (var yj in TEA_STATE_TEK_PCT[sj][fj][tj]) allTeaYears[yj] = true;
      }
    }
  }
  var forms = [["EN", "English", "stateTEKAvg"], ["ES", "Spanish", "stateTEKAvgES"]];
  var reg = subjectRegistry();
  for (var ri = 0; ri < reg.length; ri++) {
    for (var fi = 0; fi < forms.length; fi++) {
      var built = reg[ri][forms[fi][2]] || {};
      var teaRaw = (TEA_STATE_TEK_PCT[reg[ri].subject] || {})[forms[fi][0]] || {};
      var tea = {}, k;
      for (k in teaRaw) { if (teaRaw.hasOwnProperty(k)) tea[normalizeTEK(k) || k] = teaRaw[k]; }
      // Which TESTS TEA keyed: year + the TEK's grade/course prefix ("7", "A", "E1"). Grouping by year
      // alone wrongly blamed TEA's key for Algebra I 2022 and Grade 3 RLA 2021, which TEA never keyed.
      var years = {}, keyed = {};
      for (k in tea) {
        for (var yk in tea[k]) {
          if (tea[k].hasOwnProperty(yk)) { years[yk] = true; keyed[yk + "|" + k.split(".")[0]] = true; }
        }
      }
      var row = { subject: reg[ri].subject, form: forms[fi][1], compared: 0, agree: 0, differ: 0, uncheckable: 0 };
      for (var tek in built) {
        if (!built.hasOwnProperty(tek) || typeof built[tek] !== "object") continue;
        for (var y in built[tek]) {
          if (!built[tek].hasOwnProperty(y)) continue;
          var b = built[tek][y];
          if (!b || typeof b !== "object" || b.roll) continue;
          // Three reasons a figure cannot be checked, kept apart so the message says which:
          // a year TEA has posted nothing for; a year TEA posted, but not this subject/form's item key;
          // or TEA's key has no item on this TEK that year.
          if (!allTeaYears[y]) { row.uncheckable++; out.offYears++; otherYearSet[y] = true; continue; }
          if (!years[y] || !keyed[y + "|" + tek.split(".")[0]]) { row.uncheckable++; out.noKey++; continue; }
          var t = tea[tek] && tea[tek][y];
          if (!t) { row.uncheckable++; out.notOnTEA++; continue; }   // TEA's key has no item on it that year
          teaYearSet[y] = true;
          row.compared++;
          var d = Math.round(b.pct) - Math.round(t.pct);
          if (Math.abs(d) <= 1) { row.agree++; continue; }
          row.differ++;
          var bn = b.n || (b.q ? 1 : 0), why;
          if (bn && t.n && bn !== t.n) {
            why = "Item count: built-in averages " + bn + " item(s), TEA's key puts " + t.n + " on this TEK";
          } else if (t.p2) {
            why = "2-point item: built-in looks like full credit only; TEA counts partial credit as half";
          } else if (b.q && t.q && b.q === t.q) {
            why = "Same item (Q" + t.q + "), different figure: built-in transcription";
          } else {
            why = "Different figure for the same TEK";
          }
          out.diffs.push({ tek: tek, subject: reg[ri].subject, form: forms[fi][1], year: parseInt(y, 10),
                           builtIn: b.pct, tea: t.pct, diff: d, why: why });
        }
      }
      for (k in tea) {
        for (var y2 in tea[k]) {
          if (tea[k].hasOwnProperty(y2) && !(built[k] && typeof built[k] === "object" && built[k][y2])) out.teaOnly++;
        }
      }
      if (row.compared || row.uncheckable) out.bySubject.push(row);
      out.compared += row.compared; out.agree += row.agree; out.differ += row.differ;
      out.uncheckable += row.uncheckable;
    }
  }
  out.diffs.sort(function (a, b) { return Math.abs(b.diff) - Math.abs(a.diff); });
  out.teaYears = Object.keys(teaYearSet).sort();
  out.otherYears = Object.keys(otherYearSet).sort();
  return out;
}

function dcSection(g, title) {
  g.row(6);
  g.header(title, C.subHdr, C.subTxt, 12, DC_COLS, 24);
}

/**
 * Join a list for a message, saying plainly when it has been cut short.
 *
 * A truncated list that does not admit it reads as a contradiction -- "10
 * block(s) ..." followed by six names looks like the count is wrong, and the
 * first thing anyone does is go hunting for a bug that is not there.
 */
function andMore(list, max, sep) {
  sep = sep || " | ";
  if (list.length <= max) return list.join(sep);
  return list.slice(0, max).join(sep) + sep + "...and " + (list.length - max) + " more";
}

/** An information row: says something true about the data that is not a pass or a fail. */
function dcNote(g, label, detail) {
  g.row(20);
  g.set(0, label, { bg: C.sectionBg, bold: true });
  g.set(1, "NOTE", { bg: C.zebra, fg: "#555555", bold: true, align: "center" });
  g.set(2, detail, { bg: C.white, size: 9, wrap: true });
}

function dcVerdict(g, label, ok, detail) {
  g.row(20);
  g.set(0, label, { bg: C.sectionBg, bold: true });
  g.set(1, ok ? "PASS" : "CHECK", {
    bg: ok ? C.strandGood : C.strandBad,
    fg: ok ? "#000000" : "#ffffff", bold: true, align: "center"
  });
  g.set(2, detail, { bg: C.white, size: 9, wrap: true });
}

function generateDataCheck(ss, mergedTests, allStudents, blockQuestions, allExcluded, scan,
                           target) {
  var sheet = getOrCreate(ss, "Data_Check");
  var g = new Grid(DC_COLS);

  g.header("DATA CHECK  --  every figure below is checked against something the script did not compute",
    C.hdr, C.hdrTxt, 14, DC_COLS, 30);
  g.header("Run this before sharing anything. PASS means our arithmetic agrees with Eduphoria's own "
    + "columns. CHECK means it does not, and the rows are named so you can look.",
    C.warn, "#000000", 9, DC_COLS, 24, false);

  // -- 1. Raw score, ours vs Eduphoria's ---------------------------------
  dcSection(g, "1. SCORING  --  our total against Eduphoria's Raw Score, per pupil per test");
  g.headerRow(["Test", "Pupils", "Agree", "Differ", "Worst diff", "Ambiguous items", "Not checked", ""],
              C.sectionBg, 22);

  var totAgree = 0, totDiff = 0, totNoRaw = 0, mismatchRows = [], totZeroRaw = 0;
  for (var mi = 0; mi < mergedTests.length; mi++) {
    var mt = mergedTests[mi];
    var agree = 0, differ = 0, worst = 0, ambig = 0, n = 0, noRaw = 0, zeroRaw = 0;
    for (var si = 0; si < allStudents.length; si++) {
      var keys = Object.keys(allStudents[si].testScores);
      for (var ki = 0; ki < keys.length; ki++) {
        var res = allStudents[si].testScores[keys[ki]];
        if (res.order !== mt.order || !res.tookTest) continue;
        n++;
        if (res.ambiguousCount) ambig++;
        if (!res.hasRawScore) { noRaw++; continue; }
        // A COLUMN HEADED "AGREE" MUST NOT HOLD RECORDS NOBODY COMPARED.
        //
        // This read `if (rawScore > 0 && d !== 0) differ; else agree;` -- so
        // every record whose Eduphoria Raw Score was 0 was counted as AGREEING
        // without being compared to anything. `hasRawScore` only says the
        // COLUMN exists, and `parseFloat(val) || 0` turns a blank, a dash and a
        // genuine zero into the same 0. At 58% agreement that hid in the noise.
        // At 99.8% it becomes the headline claim of the workbook, and it would
        // be false: the first question a sceptical principal asks is "did you
        // check the children who scored nothing", and the honest answer was no.
        var d = (res.preRecon || 0) - (res.rawScore || 0);
        var ours = res.preRecon || 0;
        if (res.rawScore > 0) {
          if (d !== 0) {
            differ++;
            if (Math.abs(d) > Math.abs(worst)) worst = d;
            if (mismatchRows.length < 40) {
              mismatchRows.push([mt.label, allStudents[si].name, res.preRecon, res.rawScore, d,
                                 res.ambiguousCount, "", ""]);
            }
          } else { agree++; }
        } else if (ours === 0) {
          // Eduphoria zero and our zero. That IS a comparison, and it passes.
          agree++;
        } else {
          // Eduphoria zero, ours above zero. Either they scored the child zero
          // and we are wrong, or the cell is blank and there was nothing to
          // compare. The cell cannot tell those apart, so neither will this --
          // it is counted, named, and kept out of both verdicts.
          zeroRaw++;
        }
      }
    }
    totAgree += agree; totDiff += differ; totZeroRaw += zeroRaw;
    var rbg = mi % 2 === 0 ? C.white : C.zebra;
    g.row(19);
    g.set(0, mt.label, { bg: rbg, size: 9 });
    g.set(1, n, { bg: rbg, align: "center" });
    g.set(2, agree, { bg: agree === n ? C.strandGood : rbg, align: "center" });
    g.set(3, differ, { bg: differ > 0 ? C.strandBad : rbg, align: "center" });
    g.set(4, worst, { bg: rbg, align: "center" });
    g.set(5, ambig, { bg: rbg, align: "center" });
    var notes = [];
    if (noRaw > 0)   { totNoRaw += noRaw; notes.push(noRaw + " unchecked - no Raw Score column"); }
    if (zeroRaw > 0) { notes.push(zeroRaw + " not compared - Eduphoria's Raw Score is blank or "
                                  + "zero while ours is not, and the cell cannot say which"); }
    if (notes.length) {
      g.set(6, notes.join("   |   "), { bg: C.warn, fg: "#b71c1c", size: 8, wrap: true });
    }
  }
  // A check that could not run is not a pass. With no Raw Score column every
  // record is skipped, and reporting "0 differ" would have been a green light
  // on the one figure that proves our arithmetic against Eduphoria's.
  if (totAgree + totDiff === 0 && totNoRaw > 0) {
    dcVerdict(g, "Scoring agrees with Eduphoria", false,
      "COULD NOT RUN. This export has no Raw Score column, so " + totNoRaw + " records were "
      + "skipped and nothing was verified. This is the check that proves our totals against "
      + "Eduphoria's own figure -- add Raw Score to the export and it comes back.");
  } else
  dcVerdict(g, "Scoring agrees with Eduphoria", totDiff === 0,
    totDiff === 0
      // SAY WHAT WAS CHECKED, AND WHAT WAS NOT. "Every one matching" is only
      // true of the records that were actually compared, and until 2026-09-24
      // this sentence silently included every pupil Eduphoria scored zero.
      ? totAgree + " pupil-test records compared against Eduphoria's Raw Score, every one "
        + "matching before the run corrected anything."
        + (totZeroRaw ? "   " + totZeroRaw + " further record(s) were NOT compared: Eduphoria's "
             + "Raw Score is blank or zero while ours is not, and the cell cannot say which of "
             + "those it means. They are counted on the rows above, not in this figure." : "")
      // STATE THE PROPORTION, NOT JUST THE COUNT. "10 of 4,647 differ" and
      // "1,628 of 4,990 differ" are the same shape and opposite situations, and
      // this tab is the one a person reads while deciding whether to share.
      //
      // The old excuse clause named "ambiguous multi-select items", and the
      // 2026-09-24 colour fix made it obsolete: a cell is only ambiguous now
      // when its COLOUR could not be read at all. Left as it was, this sentence
      // would have called every remaining difference "a real scoring
      // disagreement" on the day agreement went from 55.7% to 99.8%.
      : totDiff + " of " + (totAgree + totDiff) + " records differ -- "
        + Math.round(totAgree / Math.max(1, totAgree + totDiff) * 1000) / 10
        + "% agree. Listed below by name. A difference where the answer cell's COLOUR could not "
        + "be read is expected and is corrected at run time -- the text alone cannot tell a "
        + "fully correct multi-select from a near-miss. Any other difference is a real scoring "
        + "disagreement and needs a look.");

  if (mismatchRows.length > 0) {
    g.row(6);
    g.header("Records where our total differed from Eduphoria before reconciliation",
             C.sectionBg, "#000000", 10, DC_COLS, 20);
    g.headerRow(["Test", "Pupil", "Ours", "Eduphoria", "Diff", "Ambiguous items", "", ""],
                C.sectionBg, 20);
    for (var mr = 0; mr < mismatchRows.length; mr++) {
      var row = mismatchRows[mr];
      g.row(18);
      for (var c = 0; c < row.length; c++) {
        g.set(c, row[c], { bg: mr % 2 === 0 ? C.white : C.zebra,
                           size: 9, align: c >= 2 ? "center" : "left" });
      }
    }
  }

  // -- 2. Performance flags ----------------------------------------------
  dcSection(g, "2. PERFORMANCE LEVELS  --  Eduphoria's own flags, checked for internal consistency");
  var badLadder = 0, ladderEg = [];
  for (var s2 = 0; s2 < allStudents.length; s2++) {
    var k2 = Object.keys(allStudents[s2].testScores);
    for (var i2 = 0; i2 < k2.length; i2++) {
      var r2 = allStudents[s2].testScores[k2[i2]];
      if (!r2.tookTest) continue;
      // Masters implies Meets implies Approaches. Anything else is the export
      // contradicting itself, and every mastery count downstream inherits it.
      if ((r2.masters === "Yes" && r2.meets !== "Yes") ||
          (r2.meets === "Yes" && r2.approaches !== "Yes")) {
        badLadder++;
        if (ladderEg.length < 10) {
          ladderEg.push(allStudents[s2].name + " -- " + r2.testName + "  (A:" +
            (r2.approaches || "-") + " M:" + (r2.meets || "-") + " Ma:" + (r2.masters || "-") + ")");
        }
      }
    }
  }
  dcVerdict(g, "Approaches / Meets / Masters ladder", badLadder === 0,
    badLadder === 0 ? "No record claims a higher level without the ones beneath it."
                    : badLadder + " record(s) break the ladder: " + ladderEg.join(" | "));

  // -- 3. TEK coverage ---------------------------------------------------
  dcSection(g, "3. TEK COVERAGE  --  every question tagged, every tag resolved to a strand");
  var qTotal = 0, qNoTek = 0, qNoStrand = 0, unresolved = {};
  for (var mt2 = 0; mt2 < mergedTests.length; mt2++) {
    var qs = primaryQuestionsEx(mergedTests[mt2], blockQuestions);
    for (var qi = 0; qi < qs.length; qi++) {
      qTotal++;
      if (!qs[qi].tek) { qNoTek++; continue; }
      if (!qs[qi].strand || qs[qi].strand === "Other Standards") {
        qNoStrand++; unresolved[qs[qi].tek] = true;
      }
    }
  }
  var unresolvedList = Object.keys(unresolved).sort();
  dcVerdict(g, "Every question carries a TEK", qNoTek === 0,
    qNoTek === 0 ? qTotal + " questions, all tagged."
                 : qNoTek + " of " + qTotal + " questions have no TEK on the paper. Those questions "
                   + "score normally but appear in no TEK or strand view.");
  dcVerdict(g, "Every TEK resolves to a strand", qNoStrand === 0,
    qNoStrand === 0 ? "All tagged questions mapped to a named strand."
                    : qNoStrand + " question(s) on " + unresolvedList.length
                      + " unmapped TEK(s): " + andMore(unresolvedList, 25, ", "));

  // -- 4. State comparison figures ---------------------------------------
  dcSection(g, "4. STATE COMPARISONS  --  what the 'State' column is actually made of");
  g.headerRow(["Test", "TEKs", "Multi-year blend", "Published year", "No state figure",
               "Single-item figures", "Wrong side of redesign", ""], C.sectionBg, 22);
  var anyBlend = 0;
  for (var mt3 = 0; mt3 < mergedTests.length; mt3++) {
    var m3 = mergedTests[mt3];
    var qs3 = primaryQuestionsEx(m3, blockQuestions);
    var yr3 = yearFromDate(m3.date);
    var seen = {}, blend = 0, dated = 0, none = 0, thin = 0, crossed = 0;
    for (var q3 = 0; q3 < qs3.length; q3++) {
      var t3 = qs3[q3].tek;
      if (!t3 || seen[t3]) continue;
      seen[t3] = true;
      var src = getStateTEKSrcEx(t3, m3.subject, yr3);
      if (src === STATE_SRC_BLEND) blend++;
      else if (src) {
        dated++;
        // A figure from one released question is not a stable average.
        var e3 = _stateTEKLookup(t3, m3.subject, yr3, "n");
        if (e3 === 1) thin++;
        // Did the fallback have to cross the redesign to find anything?
        if (yr3 && ((Number(src) >= STAAR_REDESIGN_YEAR) !== (yr3 >= STAAR_REDESIGN_YEAR))) crossed++;
      }
      else                        none++;
    }
    anyBlend += blend;
    var bg3 = mt3 % 2 === 0 ? C.white : C.zebra;
    g.row(19);
    g.set(0, m3.label, { bg: bg3, size: 9 });
    g.set(1, blend + dated + none, { bg: bg3, align: "center" });
    g.set(2, blend, { bg: blend > 0 ? C.warn : bg3, align: "center" });
    g.set(3, dated, { bg: bg3, align: "center" });
    g.set(4, none, { bg: none > 0 ? C.strandNone : bg3, align: "center" });
    g.set(5, thin, { bg: bg3, align: "center" });
    g.set(6, crossed, { bg: crossed > 0 ? C.warn : bg3, align: "center" });
  }
  dcVerdict(g, "State figures are what they claim to be", true,
    anyBlend > 0
      ? anyBlend + " TEK comparisons use the MULTI-YEAR BLEND (" + STATE_SRC_BLEND
        + "), not that test's own state result. TEA publishes year-specific figures long after the "
        + "test. This is not an error, but do not describe those numbers as 'the state average for "
        + "this test' when sharing. The 'vs' column on each view says which was used."
      : "Every state comparison uses a year-specific published figure.");

  // -- 5. Roster ---------------------------------------------------------
  dcSection(g, "5. ROSTER  --  who came through the parse");
  var noResults = 0, noId = 0, ids = {}, dupIds = 0;
  for (var s5 = 0; s5 < allStudents.length; s5++) {
    var st = allStudents[s5];
    if (Object.keys(st.testScores).length === 0) noResults++;
    if (!st.localId) noId++;
    else {
      var base = String(st.localId).split("#")[0];
      if (ids[base]) dupIds++; else ids[base] = true;
    }
  }
  dcVerdict(g, "Pupils parsed", true, allStudents.length + " pupils across "
    + mergedTests.length + " test(s) in this run.");
  dcVerdict(g, "Every pupil has a Local ID", noId === 0,
    noId === 0 ? "All pupils keyed on Local ID."
               : noId + " pupil(s) have no Local ID and were keyed on name instead. They will not "
                 + "join across tabs or years.");
  dcVerdict(g, "Local IDs are unique", dupIds === 0,
    dupIds === 0 ? "No Local ID used by more than one pupil."
                 : dupIds + " Local ID(s) used by more than one pupil on the same tab. They were "
                   + "kept separate, but the export should be checked -- one pupil's scores would "
                   + "otherwise overwrite another's.");
  dcVerdict(g, "Every pupil has at least one result", noResults === 0,
    noResults === 0 ? "No orphaned pupils."
                    : noResults + " pupil(s) parsed with no test result at all.");

  // -- 6. Reference data, per subject ------------------------------------
  dcSection(g, "6. REFERENCE DATA  --  what the built-in TEK, category and state tables actually hold");
  // WHICH reference data this workbook carries. Since 2026-10-10 it is ONE file, STAAR_Reference_Data,
  // which defines REFERENCE_DATA_VERSION; a workbook still on the separate Ref_* files has no version.
  var refVer = (typeof REFERENCE_DATA_VERSION !== "undefined") ? String(REFERENCE_DATA_VERSION) : "";
  dcVerdict(g, "Reference data file", !!refVer, refVer
    ? "STAAR_Reference_Data, version " + refVer + "."
    : "No STAAR_Reference_Data file found: this workbook still uses the older separate reference files. "
      + "They still work. When you next update, add STAAR_Reference_Data.gs and DELETE the old Ref_* and "
      + "TEK_Text files, so the project does not hold two copies of every table.");
  g.headerRow(["Subject", "TEKs", "Reporting cats", "State figures", "Form", "Years held", "", ""],
              C.sectionBg, 22);

  for (var ri6 = 0; ri6 < subjectRegistry().length; ri6++) {
    var sd6 = subjectRegistry()[ri6];
    var rcN = 0; for (var rk in sd6.tekRCMap) rcN++;
    var blend6 = 0, dated6 = 0, yrs6 = {};
    for (var sk6 in sd6.stateTEKAvg) {
      var e6 = sd6.stateTEKAvg[sk6];
      if (typeof e6 === "number") blend6++;
      else { dated6++; for (var y6 in e6) yrs6[y6] = true; }
    }
    var yrList = Object.keys(yrs6).sort();
    var bg6 = ri6 % 2 === 0 ? C.white : C.zebra;
    g.row(19);
    g.set(0, sd6.subject, { bg: bg6, bold: true });
    g.set(1, sd6.tekData.length, { bg: bg6, align: "center" });
    g.set(2, rcN, { bg: rcN === 0 ? C.strandBad : bg6, align: "center" });
    g.set(3, blend6 + dated6, { bg: bg6, align: "center" });
    g.set(4, blend6 && !dated6 ? "multi-year blend" : dated6 && !blend6 ? "by year" : "mixed",
          { bg: blend6 && !dated6 ? C.warn : bg6, size: 9, align: "center" });
    g.set(5, yrList.length ? (yrList[0] + "-" + yrList[yrList.length - 1]) : STATE_SRC_BLEND,
          { bg: bg6, size: 9, align: "center" });
  }

  var missingRC = [];
  for (var ri7 = 0; ri7 < subjectRegistry().length; ri7++) {
    var n7 = 0; for (var rk7 in subjectRegistry()[ri7].tekRCMap) n7++;
    if (n7 === 0) missingRC.push(subjectRegistry()[ri7].subject);
  }
  dcVerdict(g, "Every subject has reporting categories", missingRC.length === 0,
    missingRC.length === 0
      ? "All subjects map TEKs to a STAAR reporting category."
      : missingRC.join(", ") + " has an EMPTY reporting-category map. Tests in that subject still "
        + "score correctly, but Strand_Timeline groups every strand under \"Other Strands\" and the "
        + "reporting-category rows are absent. Needs the TEA blueprint loading before that subject "
        + "is used in anger.");

  // -- 7. State averages checked against TEA's own item analysis -----------
  // The built-in State figures (Ref_State_Averages) were transcribed from lead4ward IQ exports. Since
  // 2026-10-10 the reference data also carries TEA_STATE_TEK_PCT: the same measure rebuilt from TEA's
  // public files alone (item analysis reports + TEA's item keys; tools_tea_item_analysis.py). This
  // section compares the two, figure by figure, so the check runs on every workbook with nothing to
  // paste. TEA's data covers 2019 and 2021-2026 (2019-23 from TEA's public PDFs, 2024-26 from TEA's
  // Research Portal); figures from other years are counted as "not checkable", never as passed.
  dcSection(g, "7. STATE AVERAGES  --  the built-in figures checked against TEA's own item analysis");
  if (typeof TEA_STATE_TEK_PCT === "undefined") {
    dcVerdict(g, "Independent check of state figures", false,
      "This workbook's STAAR_Reference_Data is older than 2026-10-10 and has no TEA item-analysis table. "
      + "Replace it with the current STAAR_Reference_Data.gs to turn this check on. The State column "
      + "still works; it just has not been checked.");
  } else {
    var sc7 = checkStateFiguresAgainstTEA();
    var yrs7 = sc7.teaYears.join(", ");
    dcVerdict(g, "Independent check of state figures", sc7.differ === 0 && sc7.compared > 0,
      sc7.compared === 0
        ? "No built-in figure falls in a year TEA has published item analysis for (" + yrs7 + ")."
        : (sc7.differ === 0
            ? "All " + sc7.compared + " built-in state figures that TEA also publishes agree with TEA's own "
              + "item analysis within a point (" + yrs7 + "). Verified against TEA."
            : sc7.agree + " of " + sc7.compared + " built-in state figures agree with TEA's own item analysis "
              + "within a point (" + yrs7 + "); " + sc7.differ + " differ, listed below, largest first. "
              + "The State column still uses the built-in figure; TEA's is the one to trust."));
    g.row(18);
    g.set(0, "Not checkable", { bg: C.sectionBg, bold: true });
    g.set(2, sc7.uncheckable + " built-in figures cannot be checked this way, and are neither passed nor "
          + "failed: " + sc7.offYears + " are from years with no TEA item analysis in the reference data ("
          + sc7.otherYears.join(", ") + "); " + sc7.noKey + " are from a test TEA published no item key "
          + "for, or whose key uses an earlier TEKS edition than the built-in table (2019 RLA); " + sc7.notOnTEA + " are TEKs that TEA's key does not place on "
          + "that year's paper. TEA has "
          + sc7.teaOnly + " figures the built-in table does not hold.",
          { bg: C.white, size: 9, wrap: true });
    g.headerRow(["Subject", "Form", "Compared", "Agree", "Differ", "Not checkable", "", ""], C.sectionBg, 20);
    for (var s7 = 0; s7 < sc7.bySubject.length; s7++) {
      var b7 = sc7.bySubject[s7];
      g.row(18);
      var cells7 = [b7.subject, b7.form, b7.compared, b7.agree, b7.differ, b7.uncheckable];
      for (var c7 = 0; c7 < cells7.length; c7++) {
        g.set(c7, cells7[c7], { bg: (c7 === 4 && b7.differ) ? C.warn : (s7 % 2 ? C.zebra : C.white),
                                size: 9, align: c7 >= 2 ? "center" : "left" });
      }
    }
    if (sc7.diffs.length) {
      g.headerRow(["TEK", "Subject", "Form", "Year", "Built-in", "TEA", "Diff", "Likely cause"], C.sectionBg, 20);
      var show7 = Math.min(sc7.diffs.length, 40);
      for (var d7 = 0; d7 < show7; d7++) {
        var r7 = sc7.diffs[d7];
        g.row(18);
        var vals7 = [r7.tek, r7.subject, r7.form, r7.year, r7.builtIn, r7.tea, r7.diff, r7.why];
        for (var v7 = 0; v7 < vals7.length; v7++) {
          g.set(v7, vals7[v7], { bg: d7 % 2 === 0 ? C.white : C.zebra, size: 9,
                                 wrap: v7 === 7, align: (v7 >= 3 && v7 <= 6) ? "center" : "left" });
        }
      }
      if (sc7.diffs.length > show7) {
        g.row(18);
        g.set(0, "... and " + (sc7.diffs.length - show7) + " more", { bg: C.white, size: 9 });
      }
    }
  }

  // OPTIONAL: your own lead4ward IQ export, on a tab called Ref_State_Avg (TEK | Subject | Year | State %).
  // Before 2026-10-10 this was the only check, so a missing tab was a CHECK; the TEA comparison above
  // has replaced that, and this now runs only when the tab is there.
  var refSheet = ss.getSheetByName("Ref_State_Avg");
  if (refSheet && refSheet.getLastRow() >= 2) {
    var ref = refSheet.getDataRange().getValues();
    var hdrR = {}, i7;
    for (i7 = 0; i7 < ref[0].length; i7++) hdrR[cellStr(ref[0][i7]).toLowerCase()] = i7;
    var cT = hdrR["tek"], cS = hdrR["subject"], cY = hdrR["year"];
    var cP = hdrR["state %"] !== undefined ? hdrR["state %"] : hdrR["pct"];
    if (cT === undefined || cP === undefined) {
      dcVerdict(g, "Your own export (Ref_State_Avg)", false,
        "Ref_State_Avg needs at least a TEK column and a State % column.");
    } else {
      var same = 0, diff = 0, absent = 0, diffRows = [];
      for (i7 = 1; i7 < ref.length; i7++) {
        var tRef = normalizeTEK(cellStr(ref[i7][cT]));
        if (!tRef) continue;
        var subjRef = cS !== undefined ? cellStr(ref[i7][cS]) : "";
        var yrRef   = cY !== undefined ? parseInt(cellStr(ref[i7][cY]), 10) : 0;
        var pRef    = parseFloat(cellStr(ref[i7][cP]).replace("%", ""));
        if (isNaN(pRef)) continue;
        var ours = getStateTEKPctEx(tRef, subjRef || undefined, yrRef || 0);
        if (ours === null) { absent++; continue; }
        // Round both sides: the built-in Maths figures are whole numbers.
        if (Math.abs(Math.round(ours) - Math.round(pRef)) <= 1) { same++; }
        else {
          diff++;
          if (diffRows.length < 40) {
            diffRows.push([tRef, subjRef, yrRef || "", ours, Math.round(pRef * 10) / 10,
                           Math.round((ours - pRef) * 10) / 10, "", ""]);
          }
        }
      }
      dcVerdict(g, "Your own export (Ref_State_Avg)", diff === 0,
        same + " matched within a point, " + diff + " differ, " + absent
        + " in your export but absent from the built-in table."
        + (diff === 0 ? "  Matches your export." : "  Differences listed below."));
      if (diffRows.length > 0) {
        g.headerRow(["TEK", "Subject", "Year", "Script uses", "Your export", "Diff", "", ""],
                    C.sectionBg, 20);
        for (var dr = 0; dr < diffRows.length; dr++) {
          g.row(18);
          for (var dc2 = 0; dc2 < diffRows[dr].length; dc2++) {
            g.set(dc2, diffRows[dr][dc2],
                  { bg: dr % 2 === 0 ? C.white : C.zebra, size: 9,
                    align: dc2 >= 2 ? "center" : "left" });
          }
        }
      }
    }
  }

  // -- 8. Block inventory -------------------------------------------------
  // Which trailer columns each test block actually exposes. `summaryStart` is
  // fixed by the Raw Score header, and the trailer scan begins there -- so a
  // block missing that header skips its ENTIRE trailer: scores, bands, section
  // and instructor alike. Pupils on such a block land with no section and
  // disappear from the per-teacher view, which is exactly what a "my section
  // has 15 pupils but only 4 show" report looks like.
  dcSection(g, "8. TEST BLOCKS  --  which columns each block exposes, and who it yields");
  g.headerRow(["Test", "Cols", "Qs", "Raw Score", "Section", "Instructor",
               "Pupils w/ section", "Pupils w/ data"], C.sectionBg, 22);

  var blocks8 = (scan && scan.allBlocks) ? scan.allBlocks : [];
  var noTrailer = [], noSection = [], noSectionPrior = [];
  // Only the CURRENT year's papers are used to group pupils into classes. A
  // prior-year STAAR pull has no Current Section and never will -- the pupils
  // were not in this year's classes when they sat it -- so listing those as a
  // fault sends people looking for a missing column that cannot exist.
  var maxYear8 = 0;
  for (var my = 0; my < blocks8.length; my++) {
    var yr8 = yearFromDate(blocks8[my].autoDate);
    if (yr8 > maxYear8) maxYear8 = yr8;
  }
  for (var b8 = 0; b8 < blocks8.length; b8++) {
    var blk = blocks8[b8];
    var data8 = (scan.cache && scan.cache[blk.sheetName]) ? scan.cache[blk.sheetName] : null;
    var withSec = 0, withData = 0;
    if (data8) {
      var demo8 = detectDemoCols(data8);
      for (var r8 = DATA_START_ROW - 1; r8 < data8.length; r8++) {
        var row8 = data8[r8];
        if (!row8 || !cellStr(row8[demo8.name])) continue;
        // Current Period alone places a pupil too (2026-10-10): real DCB exports carry only it.
        var sc8 = blk.sectionCol >= 0 ? cellStr(row8[blk.sectionCol])
                : blk.courseCol  >= 0 ? cellStr(row8[blk.courseCol])
                : blk.periodCol  >= 0 ? cellStr(row8[blk.periodCol]) : "";
        if (sc8 && sc8 !== "-") withSec++;
        if (blk.summaryStartCol >= 0) {
          var rv = cellStr(row8[blk.summaryStartCol]);
          if (rv && rv !== "-") withData++;
        }
      }
    }
    var hasRaw = blk.summaryStartCol < blk.startCol + blk.questionCount + 2;
    var bg8 = b8 % 2 === 0 ? C.white : C.zebra;
    g.row(19);
    g.set(0, blk.testName, { bg: bg8, size: 9 });
    g.set(1, blk.startCol + "-" + blk.summaryStartCol, { bg: bg8, size: 9, align: "center" });
    g.set(2, blk.questionCount, { bg: bg8, align: "center" });
    g.set(3, hasRaw ? "yes" : "MISSING", { bg: hasRaw ? bg8 : C.strandBad,
                                           fg: hasRaw ? "#000000" : "#ffffff",
                                           align: "center", size: 9 });
    var noClassCol = blk.sectionCol < 0 && blk.courseCol < 0 && blk.periodCol < 0;
    g.set(4, blk.sectionCol >= 0 ? "Section" : (blk.courseCol >= 0 ? "Course"
             : (blk.periodCol >= 0 ? "Period" : "none")),
          { bg: noClassCol ? C.strandBad : bg8,
            fg: noClassCol ? "#ffffff" : "#000000",
            align: "center", size: 9 });
    g.set(5, blk.instructorCol >= 0 ? "yes" : "MISSING",
          { bg: blk.instructorCol >= 0 ? bg8 : C.strandBad,
            fg: blk.instructorCol >= 0 ? "#000000" : "#ffffff", align: "center", size: 9 });
    g.set(6, withSec, { bg: withSec === 0 && withData > 0 ? C.strandBad : bg8, align: "center" });
    g.set(7, withData, { bg: bg8, align: "center" });

    if (!hasRaw) noTrailer.push(blk.testName);
    if (noClassCol) {
      if (maxYear8 > 0 && yearFromDate(blk.autoDate) < maxYear8) noSectionPrior.push(blk.testName);
      else noSection.push(blk.testName);
    }
  }

  dcVerdict(g, "Every block exposes its trailer", noTrailer.length === 0,
    noTrailer.length === 0
      ? blocks8.length + " block(s), all with a Raw Score header, so the whole trailer is read."
      : noTrailer.length + " block(s) have NO Raw Score header, so their entire trailer is "
        + "skipped -- scores, performance bands, Current Section and Current Instructor all. "
        + "Pupils whose only data is on such a block get no section and vanish from the "
        + "per-teacher view: " + andMore(noTrailer, 6));
  dcVerdict(g, "Every CURRENT-year block identifies the class", noSection.length === 0,
    noSection.length === 0
      ? "Every " + (maxYear8 || "current") + " block carries Current Section, Course or Period."
        + (noSectionPrior.length
            ? "  " + noSectionPrior.length + " older block(s) carry none of them, which is normal -- "
              + "they are used for growth and the timeline, not for grouping."
            : "")
      : noSection.length + " CURRENT-year block(s) carry no Current Section, Current Period or Current "
        + "Course, so pupils whose only result is on them cannot be grouped by class: "
        + andMore(noSection, 6)
        + (noSectionPrior.length
            ? "   (" + noSectionPrior.length + " older block(s) also lack it, which is expected "
              + "and not a problem.)"
            : ""));

  // -- 9. Roster reconciliation ------------------------------------------
  // The question this answers: "Config says this teacher has 86 pupils, the PLC
  // tabs add up to 77 -- where did nine go?" Every pupil is accounted for here,
  // section by section, and the last column names the paper the missing ones
  // actually sat. Nothing is lost silently.
  if (target) {
    dcSection(g, "9. ROSTER RECONCILIATION  --  every pupil accounted for, against \""
                 + target.label + "\"");
    g.headerRow(["Teacher", "Section", "On roster", "With data", "Missing",
                 "Where the missing ones are", "", ""], C.sectionBg, 22);

    var onTarget = {};
    var flat9 = flattenStudentsForTest(target, allStudents, blockQuestions, allExcluded);
    for (var f9 = 0; f9 < flat9.length; f9++) {
      onTarget[(flat9[f9].localId || flat9[f9].name)] = true;
    }
    var labelByOrder = {};
    for (var lo = 0; lo < mergedTests.length; lo++) labelByOrder[mergedTests[lo].order] = mergedTests[lo].label;

    var grp9 = {}, keys9 = [];
    for (var s9 = 0; s9 < allStudents.length; s9++) {
      var st9 = allStudents[s9];
      var k9  = (st9.instructor || "(No instructor listed)") + "\u0001" +
                (st9.section    || "(No section listed)");
      if (!grp9[k9]) { grp9[k9] = []; keys9.push(k9); }
      grp9[k9].push(st9);
    }
    keys9.sort();

    var tRoster = 0, tData = 0, tMissing = 0;
    for (var g9 = 0; g9 < keys9.length; g9++) {
      var parts9 = keys9[g9].split("\u0001");
      var members = grp9[keys9[g9]];
      var have = 0, elsewhereTests = {}, noneAtAll = 0;
      for (var mm = 0; mm < members.length; mm++) {
        var id9 = members[mm].localId || members[mm].name;
        if (onTarget[id9]) { have++; continue; }
        // Not on the target paper -- so which one did they sit?
        var sat = [], tk9 = Object.keys(members[mm].testScores);
        for (var q9 = 0; q9 < tk9.length; q9++) {
          var r9 = members[mm].testScores[tk9[q9]];
          if (r9.tookTest) sat.push(labelByOrder[r9.order] || r9.testName);
        }
        if (sat.length === 0) noneAtAll++;
        else elsewhereTests[sat[sat.length - 1]] = (elsewhereTests[sat[sat.length - 1]] || 0) + 1;
      }
      var miss = members.length - have;
      var where = [];
      for (var wk in elsewhereTests) where.push(elsewhereTests[wk] + " sat " + wk);
      if (noneAtAll) where.push(noneAtAll + " have no test data at all");

      tRoster += members.length; tData += have; tMissing += miss;
      var bg9 = g9 % 2 === 0 ? C.white : C.zebra;
      g.row(19);
      g.set(0, parts9[0], { bg: bg9, size: 9 });
      g.set(1, parts9[1], { bg: bg9, size: 9 });
      g.set(2, members.length, { bg: bg9, align: "center", bold: true });
      g.set(3, have, { bg: bg9, align: "center" });
      g.set(4, miss, { bg: miss > 0 ? C.warn : bg9, align: "center" });
      g.set(5, where.join("; "), { bg: bg9, size: 9, wrap: true });
    }

    g.row(20);
    g.set(0, "TOTAL", { bg: C.sectionBg, bold: true });
    g.set(2, tRoster,  { bg: C.sectionBg, align: "center", bold: true });
    g.set(3, tData,    { bg: C.sectionBg, align: "center", bold: true });
    g.set(4, tMissing, { bg: C.sectionBg, align: "center", bold: true });

    dcVerdict(g, "Every pupil accounted for", true,
      tRoster + " pupils parsed in this run. " + tData + " sat \"" + target.label
      + "\" and appear in the per-teacher tabs; " + tMissing + " did not, and the row above "
      + "names the paper each of them sat instead. A pupil on your SIS roster who sat none of "
      + "the loaded tests is not in the export at all and cannot be counted here -- that gap is "
      + "between your roster and Eduphoria, not inside this script.");
  }


  // -- 10. Column census -------------------------------------------------
  // Which columns the export actually carries, and how many rows have anything
  // in them. Midlothian can add a long list of optional columns in Eduphoria
  // but cannot tell which are populated -- several exist only at certain grade
  // levels, or are simply empty. Rather than guess which are worth configuring
  // on every download, pull them all once and let this count decide.
  dcSection(g, "10. COLUMN CENSUS  --  which columns carry data, so you can stop pulling the empty ones");
  g.headerRow(["Column", "Sheet", "Rows with a value", "Fill", "Distinct", "Values (if few)"],
              C.sectionBg, 22);

  var censusSheets = (scan && scan.sheetInfos) ? scan.sheetInfos : [];
  var anyCensus = false;
  for (var cs = 0; cs < censusSheets.length; cs++) {
    var csName = censusSheets[cs].sheetName;
    if (!censusSheets[cs].include) continue;
    var dataC = (scan.cache && scan.cache[csName]) ? scan.cache[csName] : null;
    if (!dataC || dataC.length < 3) continue;

    // The header row is wherever "Student Name" sits.
    var hdrRow = -1;
    for (var hr = 0; hr < Math.min(5, dataC.length); hr++) {
      for (var hc = 0; hc < Math.min(12, (dataC[hr] || []).length); hc++) {
        if (cellStr(dataC[hr][hc]).toLowerCase() === "student name") { hdrRow = hr; break; }
      }
      if (hdrRow >= 0) break;
    }
    if (hdrRow < 0) continue;
    anyCensus = true;

    // Question columns are unlabelled and there are hundreds; skip them.
    var seenCol = {};
    for (var cc = 0; cc < dataC[hdrRow].length; cc++) {
      var label = cellStr(dataC[hdrRow][cc]).trim();
      if (!label || label.toLowerCase() === "all responses") continue;
      if (seenCol[label]) continue;              // same column in every block
      seenCol[label] = true;

      var filled = 0, total = 0, vals = {}, nVals = 0, wide = false;
      for (var rr = hdrRow + 1; rr < dataC.length; rr++) {
        var rowC = dataC[rr];
        if (!rowC) continue;
        // count only real pupil rows
        var anyName = false;
        for (var nc = 0; nc < Math.min(12, rowC.length); nc++) {
          if (cellStr(rowC[nc])) { anyName = true; break; }
        }
        if (!anyName) continue;
        total++;
        var v = cellStr(rowC[cc]).trim();
        if (!v || v === "-" || v.toUpperCase() === "N/A") continue;
        filled++;
        if (nVals <= 9 && !vals[v]) { vals[v] = true; nVals++; }
        if (v.length > 24) wide = true;
      }
      if (total === 0) continue;

      var pct = Math.round(filled / total * 100);
      var bgC = filled === 0 ? C.strandBad : pct >= 90 ? C.strandGood : C.warn;
      g.row(17);
      g.set(0, label, { bg: C.white, size: 9, bold: filled === 0 ? false : true });
      g.set(1, csName, { bg: C.white, size: 8, fg: "#757575" });
      g.set(2, filled + " of " + total, { bg: C.white, align: "center", size: 9 });
      g.set(3, pct, { bg: bgC, align: "center", bold: true, fmt: "0\"%\"" });
      g.set(4, nVals > 9 ? "10+" : String(nVals), { bg: C.white, align: "center", size: 9 });
      // Only list values when there are few and they are short -- that catches
      // flags and codes. Cardinality alone is not enough of a guard: a class of
      // six would have listed six pupil names, and "Current Instructor" listed
      // the teacher. Anything whose header names a person or an identifier
      // reports its fill rate and nothing else.
      var lcLabel = label.toLowerCase();
      var identifying = lcLabel.indexOf("name") !== -1 || lcLabel.indexOf("id") !== -1 ||
                        lcLabel.indexOf("instructor") !== -1 || lcLabel.indexOf("teacher") !== -1 ||
                        lcLabel.indexOf("student") !== -1;
      if (filled > 0 && nVals <= 8 && !wide && !identifying) {
        var vl = [];
        for (var vk in vals) vl.push(vk);
        g.set(5, vl.join(" | "), { bg: C.white, size: 8, fg: "#555555", wrap: true });
      } else if (filled === 0) {
        g.set(5, "empty - not worth pulling", { bg: C.warn, size: 8, fg: "#b71c1c" });
      }
    }
  }
  if (!anyCensus) {
    g.row(18);
    g.set(0, "(No sheet with a Student Name header row was readable)",
          { bg: C.white, fg: "#757575" });
  }
  g.row(8);


  // -- 11. Prev Year Scale Score, checked against the paper we hold ---------
  // Midlo asked for this by name: they do not yet trust the Eduphoria column.
  // Wherever a pupil has BOTH the exported prev-year figure AND the actual
  // prior-year paper in this workbook, the two can be compared -- and if they
  // agree everywhere, the column can be trusted for the pupils where we have
  // nothing else, which is the whole point of pulling it.
  var pvYearByOrder = {};
  for (var pv = 0; pv < mergedTests.length; pv++) {
    pvYearByOrder[mergedTests[pv].order] = yearFromDate(mergedTests[pv].date);
  }
  var pvBoth = 0, pvAgree = 0, pvDiff = [], pvOnlyCol = 0, pvNoCol = 0;
  for (var ps = 0; ps < allStudents.length; ps++) {
    var stu = allStudents[ps];
    var ks = Object.keys(stu.testScores);
    for (var kk2 = 0; kk2 < ks.length; kk2++) {
      var rec = stu.testScores[ks[kk2]];
      if (!rec.tookTest) continue;
      var yr = pvYearByOrder[rec.order];
      if (!yr) continue;
      var exported = parseFloat(rec.prevScale);
      if (!exported || isNaN(exported)) { pvNoCol++; continue; }
      // the prior-year paper we actually hold for this pupil
      var held = null;
      for (var k3 = 0; k3 < ks.length; k3++) {
        var r3 = stu.testScores[ks[k3]];
        if (!r3.tookTest) continue;
        if (pvYearByOrder[r3.order] === yr - 1) { held = r3; break; }
      }
      if (!held) { pvOnlyCol++; continue; }
      pvBoth++;
      var ours = parseFloat(held.scaleScore);
      if (!isNaN(ours) && Math.abs(ours - exported) < 0.5) pvAgree++;
      else pvDiff.push({ name: stu.name, yr: yr, exported: exported, ours: ours });
    }
  }

  if (pvBoth > 0 || pvOnlyCol > 0) {
    dcSection(g, "11. PREV YEAR SCALE SCORE  --  Eduphoria's column against the paper we hold");
    g.headerRow(["Check", "Count", "What it means"], C.sectionBg, 22);
    var pvRows = [
      ["Both available, and they agree", pvAgree,
       "The exported figure matched the prior-year paper in this workbook exactly."],
      ["Both available, and they differ", pvDiff.length,
       pvDiff.length ? "Listed below. Until these are explained the column cannot be trusted."
                     : "None."],
      ["Column only - no prior paper held", pvOnlyCol,
       "These are the pupils the column exists for: transfers we could not otherwise score."],
      ["No value in the column", pvNoCol,
       "Either the column is absent, or blank for that pupil."]
    ];
    for (var pr2 = 0; pr2 < pvRows.length; pr2++) {
      var pbg = pr2 % 2 === 0 ? C.white : C.zebra;
      g.row(19);
      g.set(0, pvRows[pr2][0], { bg: pbg, size: 9, bold: true });
      g.set(1, pvRows[pr2][1], { bg: pvRows[pr2][1] > 0 && pr2 === 1 ? C.strandBad : pbg,
                                 align: "center", bold: true });
      g.set(2, pvRows[pr2][2], { bg: pbg, size: 9, wrap: true, fg: "#555555" });
    }
    dcVerdict(g, "Prev Year Scale Score agrees with the paper we hold",
      pvBoth > 0 && pvDiff.length === 0,
      pvBoth === 0
        ? "Could not be checked: no pupil has both the exported figure and the prior-year paper "
          + "in this workbook. Load a year with overlap and this check becomes meaningful."
        : (pvDiff.length === 0
            ? pvAgree + " of " + pvBoth + " matched exactly, so the column can be trusted for the "
              + pvOnlyCol + " pupil(s) where it is the only prior-year figure we have."
            : pvDiff.length + " of " + pvBoth + " disagree. Named below."));
    if (pvDiff.length > 0) {
      g.headerRow(["Student", "Test year", "Column says", "Paper says", "Difference"],
                  C.sectionBg, 20);
      for (var pd = 0; pd < Math.min(pvDiff.length, 40); pd++) {
        var d2 = pvDiff[pd], dbg = pd % 2 === 0 ? C.white : C.zebra;
        g.row(17);
        g.set(0, d2.name, { bg: dbg, size: 9 });
        g.set(1, d2.yr, { bg: dbg, align: "center", size: 9 });
        g.set(2, d2.exported, { bg: dbg, align: "center" });
        g.set(3, isNaN(d2.ours) ? "(blank)" : d2.ours, { bg: dbg, align: "center" });
        g.set(4, isNaN(d2.ours) ? "" : Math.round(d2.exported - d2.ours),
              { bg: C.strandBad, align: "center", bold: true });
      }
    }
    g.row(8);
  }


  // -- 12. Is last year's teacher already in the export? --------------------
  // Midlo wants to attribute growth to whoever taught the pupil that year, for
  // coaching. That needs the teacher AT THE TIME of the prior paper, and the
  // export's only instructor column is called "Current". But the columns are
  // written per BLOCK, and in Midlo's own sample they disagreed across blocks
  // for the same pupil -- which would mean the historical placement is already
  // here and nobody has to go hunting in Eduphoria for it.
  //
  // This settles it: compare the instructor recorded on a pupil's prior-year
  // block against the one on their current block. If they never differ, the
  // column is just today's teacher stamped on every block and the history is
  // genuinely absent. If they differ for a meaningful share, it is real.
  var tiYearBy = {};
  for (var ti2 = 0; ti2 < mergedTests.length; ti2++) {
    tiYearBy[mergedTests[ti2].order] = yearFromDate(mergedTests[ti2].date);
  }
  var tiPairs = 0, tiDiffer = 0, tiSame = 0, tiBlank = 0, tiExamples = 0;
  for (var ts = 0; ts < allStudents.length; ts++) {
    var st2 = allStudents[ts], kz2 = Object.keys(st2.testScores);
    var newest = null;
    for (var k5 = 0; k5 < kz2.length; k5++) {
      var r5 = st2.testScores[kz2[k5]];
      if (!r5.tookTest || !tiYearBy[r5.order]) continue;
      if (!newest || tiYearBy[r5.order] > tiYearBy[newest.order]) newest = r5;
    }
    if (!newest) continue;
    var want = tiYearBy[newest.order] - 1, prev = null;
    for (var k6 = 0; k6 < kz2.length; k6++) {
      var r6 = st2.testScores[kz2[k6]];
      if (r6.tookTest && tiYearBy[r6.order] === want) { prev = r6; break; }
    }
    if (!prev) continue;
    tiPairs++;
    var a = String(prev.instructor || "").trim(), b2 = String(newest.instructor || "").trim();
    if (!a || !b2) tiBlank++;
    else if (a === b2) tiSame++;
    else tiDiffer++;
  }

  if (tiPairs > 0) {
    dcSection(g, "12. PRIOR-YEAR TEACHER  --  is last year's teacher already in this export?");
    g.headerRow(["Check", "Count", "What it means"], C.sectionBg, 22);
    var tiRows = [
      ["Prior and current teacher DIFFER", tiDiffer,
       "The instructor column is written per test block, so it records who had the pupil THAT year. Growth can be attributed to the teacher who taught it."],
      ["Prior and current teacher the same", tiSame,
       "Either the pupil genuinely kept the same teacher, or the column is today's placement stamped on every block."],
      ["One of them blank", tiBlank,
       "No instructor recorded on one of the two papers."],
      ["Pupils with both years", tiPairs, "The population this check could look at."]
    ];
    for (var tr2 = 0; tr2 < tiRows.length; tr2++) {
      var tbg2 = tr2 % 2 === 0 ? C.white : C.zebra;
      g.row(19);
      g.set(0, tiRows[tr2][0], { bg: tbg2, size: 9, bold: true });
      g.set(1, tiRows[tr2][1], { bg: tbg2, align: "center", bold: true });
      g.set(2, tiRows[tr2][2], { bg: tbg2, size: 9, wrap: true, fg: "#555555" });
    }
    // A NOTE, not a verdict. Austin, 2026-10-10: the tool is for the teachers who have the pupils NOW --
    // "this is not evaluating last year's teachers". Eduphoria's Current Instructor stamps today's teacher
    // on every year's paper, which is exactly what the teacher tabs want, so it is never a CHECK.
    dcNote(g, "Teacher on each year's test",
      tiDiffer > 0
        ? tiDiffer + " of " + tiPairs + " pupils show a different teacher on last year's test than on "
          + "this year's, so this export also records who taught them then. Teacher tabs still use "
          + "each pupil's CURRENT teacher."
        : "Every pupil shows their current teacher on every year's test, because Eduphoria's Current "
          + "Instructor is today's placement. That is what this tool wants: each teacher sees the pupils "
          + "they have now. It does not say who taught them last year, and nothing here needs that.");
    g.row(8);
  }

  // -- 13. Teacher tabs ----------------------------------------------------
  // The completion dialog names ticked teachers who got no tab, but a dialog is
  // gone the moment it is clicked. This is the same answer, kept.
  var tabsBuilt = Object.keys(PLC_TABS_BUILT).length;
  if (tabsBuilt > 0 || PLC_TICKED_N > 0 || PLC_NO_TAB.length > 0) {
    dcSection(g, "13. TEACHER TABS  --  who got a tab, and why anyone ticked did not");
    g.headerRow(["Teacher", "Why there is no tab", ""], C.sectionBg, 22);
    g.row(19);
    g.set(0, "Tabs built", { bg: C.white, size: 9, bold: true });
    g.set(1, tabsBuilt + (PLC_TICKED_N ? " of " + PLC_TICKED_N + " ticked" : " (no teacher filter: everybody)"),
          { bg: C.white, size: 9 });
    for (var nt = 0; nt < PLC_NO_TAB.length; nt++) {
      var ntbg = nt % 2 === 0 ? C.zebra : C.white;
      g.row(48);
      g.set(0, PLC_NO_TAB[nt].name, { bg: ntbg, size: 9, bold: true, fg: "#b71c1c" });
      g.set(1, PLC_NO_TAB[nt].reason, { bg: ntbg, size: 9, wrap: true });
    }
    dcVerdict(g, "Every ticked teacher has a tab", PLC_NO_TAB.length === 0,
      PLC_NO_TAB.length === 0
        ? (PLC_TICKED_N ? "All " + PLC_TICKED_N + " ticked teachers were built." : tabsBuilt + " tabs, one per teacher found.")
        : PLC_NO_TAB.length + " ticked teacher(s) have no tab. The reason beside each name is read "
          + "from the export itself, not guessed.");
    g.row(8);
  }

  g.flush(sheet, [200, 220, 90, 85, 80, 300, 90, 90]);
  sheet.setFrozenRows(1);
  console.log("Data_Check written -- scoring diffs: " + totDiff + ", ladder breaks: " + badLadder
              + ", unmapped TEKs: " + unresolvedList.length);
}


// === PART 31: DIAGNOSTICS ===============================================
// Tab: Diagnostics -- built to be SHARED. No pupil names, no staff names, no
// Local IDs, no scores. Teachers appear as T01, T02; sections as S1, S2.
//
// It exists to answer one question without anybody having to hunt: when a
// teacher's PLC totals do not match the number beside them on Config, where did
// the difference go and what could cause it.

var DIAG_COLS = 10;

function diagRow(g, label, value, note, warn) {
  g.row(19);
  g.set(0, label, { bg: C.sectionBg, size: 9 });
  g.set(1, value, { bg: warn ? C.warn : C.white, align: "center", bold: true });
  g.set(2, note, { bg: C.white, size: 9, wrap: true });
}

function runDiagnostics() {
  var ss  = SpreadsheetApp.getActiveSpreadsheet();
  var ui  = SpreadsheetApp.getUi();
  var scan = scanWorkbook(ss);
  // A missing Student Name column is the one failure that looks like success:
  // parseStudents skips every row without a name, so the run completes, every
  // tab builds, and not one pupil is in any of them. Catch it up front.
  var noNameSheets = [];
  for (var nsi = 0; nsi < scan.sheetInfos.length; nsi++) {
    var nsName = scan.sheetInfos[nsi].sheetName;
    if (!scan.sheetInfos[nsi].include) continue;
    var nsData = scan.cache && scan.cache[nsName];
    if (!nsData) continue;
    var foundName = false;
    for (var nr = 0; nr < Math.min(5, nsData.length) && !foundName; nr++) {
      for (var nc = 0; nc < Math.min(12, (nsData[nr] || []).length); nc++) {
        if (cellStr(nsData[nr][nc]).toLowerCase() === "student name") { foundName = true; break; }
      }
    }
    if (!foundName) noNameSheets.push(nsName);
  }
  if (noNameSheets.length > 0 && noNameSheets.length === scan.sheetInfos.length) {
    ui.alert("No Student Name column found",
      "These sheets have no \"Student Name\" header:\n\n  " + noNameSheets.join("\n  ") +
      "\n\nEvery row is keyed on that column, so the run would finish with zero " +
      "pupils and no error. Add the column to the export and pull again.",
      ui.ButtonSet.OK);
    return;
  }

  if (scan.allBlocks.length === 0) {
    ui.alert("Nothing to diagnose", "No test data found on any tab.", ui.ButtonSet.OK);
    return;
  }
  autoOrderBlocks(scan.allBlocks);

  var cfg           = getConfigValues(ss);
  var teacherFilter = readTeacherFilter(cfg);
  readConfig(cfg, scan.sheetInfos, scan.allBlocks);

var subjectTEKMaps = buildSubjectTEKMaps();
  // Same ordering rule as the main pipeline -- this path parses questions too,
  // so it had the identical flat-map bug.
  resolveBlockSubjects(scan.allBlocks, scan.cache, subjectTEKMaps);
  var blockQuestions = {}, bi;
  for (bi = 0; bi < scan.allBlocks.length; bi++) {
    var blk = scan.allBlocks[bi];
    if (!blk.include || blk.order === 0) continue;
    var d = scan.cache[blk.sheetName];
    if (d) blockQuestions[blk.testName] = parseQuestions(blk, d, scan.tekMap, subjectTEKMaps);
  }

  // Parse twice: once unfiltered, once as the run would, so the filter's own
  // contribution to any shortfall is visible rather than guessed at.
  function parseAll(filter) {
    var map = {};
    for (var si = 0; si < scan.sheetInfos.length; si++) {
      var info = scan.sheetInfos[si];
      if (!info.include) continue;
      var sd = scan.cache[info.sheetName];
      if (!sd) continue;
      var sb2 = [];
      for (var b2 = 0; b2 < scan.allBlocks.length; b2++) {
        if (scan.allBlocks[b2].sheetName === info.sheetName) sb2.push(scan.allBlocks[b2]);
      }
      parseStudents(info.sheetName, sd, info.format, sb2, blockQuestions, map,
                    scan.formulaCache[info.sheetName], filter,
                    scan.bgCache ? scan.bgCache[info.sheetName] : null);
    }
    var out = [];
    for (var k in map) out.push(map[k]);
    return out;
  }
  var everyone = parseAll(null);
  var inRun    = parseAll(teacherFilter);

  var sheet = getOrCreate(ss, "Diagnostics");
  var g = new Grid(DIAG_COLS);

  g.header("DIAGNOSTICS  --  safe to share: no pupil names, no staff names, no IDs, no scores",
    C.hdr, C.hdrTxt, 14, DIAG_COLS, 30);
  g.header("Built to answer one question: when a teacher's PLC totals do not match the number "
    + "beside them on Config, where did the difference go?",
    C.warn, "#000000", 9, DIAG_COLS, 22, false);

  // -- workbook shape --
  g.row(6);
  g.header("WORKBOOK", C.subHdr, C.subTxt, 12, DIAG_COLS, 24);
  var tabsIncluded = 0;
  for (var t1 = 0; t1 < scan.sheetInfos.length; t1++) if (scan.sheetInfos[t1].include) tabsIncluded++;
  var orders = {}, nOrders = 0;
  for (var o1 = 0; o1 < scan.allBlocks.length; o1++) {
    if (!orders[scan.allBlocks[o1].order]) { orders[scan.allBlocks[o1].order] = true; nOrders++; }
  }
  diagRow(g, "Tabs scanned", scan.sheetInfos.length, "");
  diagRow(g, "Tabs included in the run", tabsIncluded,
    tabsIncluded < scan.sheetInfos.length
      ? "A tab set to No in the Sheet Registry contributes NO pupils at all." : "",
    tabsIncluded < scan.sheetInfos.length);
  diagRow(g, "Test blocks found", scan.allBlocks.length, "");
  diagRow(g, "Distinct tests after merging", nOrders,
    "Blocks sharing a test name across tabs, and the English/Spanish forms of one paper, merge.");
  diagRow(g, "Pupils parsed, no filter", everyone.length, "");
  diagRow(g, "Pupils parsed, as this run", inRun.length,
    teacherFilter ? "The teacher filter is ON, so only ticked teachers' pupils were kept."
                  : "No teacher filter, so every pupil was kept.",
    teacherFilter && inRun.length < everyone.length);

  // -- per teacher, anonymised --
  g.row(6);
  g.header("PER TEACHER  --  Config census against what the views actually grouped",
    C.subHdr, C.subTxt, 12, DIAG_COLS, 24);
  g.headerRow(["Teacher", "Config census", "In this run", "Difference", "Sections", "Periods",
               "Rows sharing a Local ID", "Pupils w/ 2+ instructors", "Pupils w/o a section",
               "Pupils w/o test data"], C.sectionBg, 30);

  var runByTeacher = {};
  for (var r1 = 0; r1 < inRun.length; r1++) {
    var tn = inRun[r1].instructor || NO_TEACHER;
    if (!runByTeacher[tn]) runByTeacher[tn] = [];
    runByTeacher[tn].push(inRun[r1]);
  }
  var names = [];
  for (var cn in scan.teacherCensus) names.push(cn);
  for (var rn in runByTeacher) if (names.indexOf(rn) === -1) names.push(rn);
  names.sort();

  var anyAmbig = 0, anyNoSec = 0, anyDup = 0, totalDiff = 0;
  for (var ti = 0; ti < names.length; ti++) {
    var nm  = names[ti];
    var ent = scan.teacherCensus[nm];
    var mine = runByTeacher[nm] || [];
    var censusN = ent ? Object.keys(ent.students).length : 0;
    var ambig = 0, noSec = 0, noData = 0;
    for (var mi = 0; mi < mine.length; mi++) {
      var pk = mine[mi].localId || mine[mi].name;
      var px = scan.pupilIndex[pk];
      if (px && px.instructorsSeen > 1) ambig++;
      if (!mine[mi].section) noSec++;
      var took = false, kz = Object.keys(mine[mi].testScores);
      for (var kk = 0; kk < kz.length; kk++) if (mine[mi].testScores[kz[kk]].tookTest) { took = true; break; }
      if (!took) noData++;
    }
    anyAmbig += ambig; anyNoSec += noSec;
    var diff = censusN - mine.length;
    totalDiff += Math.abs(diff);
    var bg = ti % 2 === 0 ? C.white : C.zebra;
    g.row(19);
    g.set(0, "T" + (ti + 1 < 10 ? "0" : "") + (ti + 1), { bg: bg, bold: true, align: "center" });
    g.set(1, censusN, { bg: bg, align: "center" });
    g.set(2, mine.length, { bg: bg, align: "center" });
    g.set(3, diff, { bg: diff !== 0 ? C.warn : bg, align: "center", bold: diff !== 0 });
    g.set(4, ent ? Object.keys(ent.sections).length : 0, { bg: bg, align: "center" });
    // Periods as well as sections: once a run is grouped by class period, the
    // section count is not the number a teacher is reconciling against.
    g.set(5, ent ? teacherPeriodLabel(ent) : "", { bg: bg, align: "center", size: 9 });
    var dupIds = ent ? (ent.rows - censusN) : 0;
    anyDup += dupIds;
    g.set(6, dupIds, { bg: dupIds > 0 ? C.warn : bg, align: "center" });
    g.set(7, ambig,  { bg: ambig  > 0 ? C.warn : bg, align: "center" });
    g.set(8, noSec,  { bg: noSec  > 0 ? C.warn : bg, align: "center" });
    g.set(9, noData, { bg: noData > 0 ? C.warn : bg, align: "center" });
  }

  // -- what a difference means --
  g.row(6);
  g.header("IF A DIFFERENCE IS NOT ZERO, IT IS ONE OF THESE",
    C.subHdr, C.subTxt, 12, DIAG_COLS, 24);
  var causes = [
    ["Teacher filter is on", teacherFilter
      ? "ON - pupils of unticked teachers were never parsed, so their rows read 0 here."
      : "off - not a factor in this run."],
    ["A tab is excluded", tabsIncluded < scan.sheetInfos.length
      ? "YES - " + (scan.sheetInfos.length - tabsIncluded) + " tab(s) set to No in the Sheet "
        + "Registry. Every pupil on them is absent from both counts."
      : "no - every tab is included."],
    ["Rows sharing a Local ID", anyDup > 0
      ? anyDup + " row(s) repeat a Local ID already used on the same tab. The Config census "
        + "counts DISTINCT ids, the views keep the rows apart as separate pupils -- so the run "
        + "total is higher by exactly that many. Two pupils sharing an id is worth fixing at the "
        + "export: otherwise one pupil's scores would overwrite another's."
      : "none - every Local ID is used once."],
    ["Pupils with two or more instructors", anyAmbig > 0
      ? anyAmbig + " pupil(s) carry a DIFFERENT instructor in different test blocks. Both the "
        + "census and the views now take the newest paper, so they should agree -- but if a "
        + "pupil changed teacher mid-year, they count once, under the newer one."
      : "none - every pupil has one instructor throughout."],
    ["Pupils with no section", anyNoSec > 0
      ? anyNoSec + " pupil(s) have a teacher but no Current Section or Current Course. They are "
        + "counted for the teacher but grouped under \"(No section listed)\"."
      : "none."],
    ["Pupils who sat nothing", "Counted on the roster, absent from every TEK table, because "
      + "there is no paper to rank them on. Data_Check section 9 names the paper each pupil sat."],
    ["Pupils not in the export at all", "If your SIS says 120 and this says 86, the other 34 sat "
      + "none of the loaded tests and Eduphoria never wrote them a row. Nothing downstream can "
      + "see them; that gap is between your roster and the export."]
  ];
  for (var ci = 0; ci < causes.length; ci++) {
    g.row(20);
    g.set(0, causes[ci][0], { bg: C.sectionBg, bold: true, size: 9 });
    g.set(2, causes[ci][1], { bg: C.white, size: 9, wrap: true });
  }

  g.row(6);
  g.header(totalDiff === 0
    ? "Every teacher's Config census matches what the views grouped. No discrepancy to chase."
    : "Total discrepancy across all teachers: " + totalDiff + " pupil(s). Read the causes above, "
      + "then Data_Check section 9 for the pupil-by-pupil account.",
    totalDiff === 0 ? C.strandGood : C.warn, "#000000", 11, DIAG_COLS, 26);

  g.flush(sheet, [230, 105, 90, 85, 70, 130, 130, 125, 120]);
  sheet.setFrozenRows(1);
  ss.setActiveSheet(sheet);
  console.log("Diagnostics written -- total teacher discrepancy: " + totalDiff);
}
/**
 * STAAR REFERENCE DATA  --  everything the analyzer looks up, in ONE file.
 *
 * Paste this file once, next to the analyzer. It holds no logic and never needs editing by hand.
 * Replace it as a whole when a new version is issued (new cut scores each fall, new state
 * figures each summer). Data_Check shows which version a workbook carries.
 *
 * Version: 2026-10-12 52a10606
 * Built by tools_build_reference.py from reference_src/ -- do not edit this file; edit the
 * source part and rebuild.
 *
 * Contents:
 *   PART 1  Ref_TEK_Structure        TEKS lists, reporting categories, strands and vertical alignment (TEA)
 *   PART 2  TEK_Text                 TEA wording for every standard, English and Spanish
 *   PART 3  Ref_Cut_Scores           TEA performance-level cut scores, by year
 *   PART 4  Ref_Released_Tests       TEA released-test links
 *   PART 5  Ref_Lead4ward_Links      lead4ward resource links
 *   PART 6  Ref_State_Averages       State percent correct per TEK (derived from lead4ward exports)
 *   PART 7  Ref_TEA_Item_Stats       TEA's own state percent per TEK, from TEA item analysis (checks PART 6)
 *
 * If an older workbook still has the separate files (Ref_TEK_Structure, TEK_Text, Ref_Cut_Scores,
 * Ref_Released_Tests, Ref_Lead4ward_Links, Ref_State_Averages, Ref_TEKS_Midschool), DELETE
 * them when you add this one. Apps Script would otherwise hold two copies of every table, and
 * whichever loads last wins -- silently.
 */
var REFERENCE_DATA_VERSION = "2026-10-12 52a10606";
var REFERENCE_DATA_PARTS = ["Ref_TEK_Structure", "TEK_Text", "Ref_Cut_Scores", "Ref_Released_Tests", "Ref_Lead4ward_Links", "Ref_State_Averages", "Ref_TEA_Item_Stats"];


